/* HSK grammar (official 2025 syllabus) + Vietnamese — generated by tools/build-grammar.cjs, do not edit */
window.GRAMMAR={"1":[{"n":1,"c":["语素","前缀",""],"z":"小—、第—","t":"Tiền tố 小 và 第","d":"小 + họ: gọi thân mật người nhỏ tuổi hơn (小高 = cậu Cao). 第 + số: chỉ thứ tự (第一 = thứ nhất).","e":[["小高去哪儿了？","xiǎo gāo qù nǎ r le","Tiểu Cao đi đâu rồi?"],["今天我们学习第一课。","jīn tiān wǒ men xué xí dì yī kè","Hôm nay chúng ta học bài thứ nhất."]]},{"n":2,"c":["语素","后缀",""],"z":"—们、—边","t":"Hậu tố 们 và 边","d":"Danh từ chỉ người + 们 = số nhiều (同学们 = các bạn học). Từ chỉ phương hướng + 边 = phía, bên (里边 = bên trong).","e":[["同学们，你们好！","tóng xué men nǐ men hǎo","Các bạn học sinh, chào các em!"],["学校里边有超市。","xué xiào lǐ biān yǒu chāo shì","Trong trường có siêu thị."],["外边正在下雨呢。","wài biān zhèng zài xià yǔ ne","Bên ngoài đang mưa đấy."],["电影院在医院的后边。","diàn yǐng yuàn zài yī yuàn de hòu biān","Rạp chiếu phim ở phía sau bệnh viện."]]},{"n":3,"c":["词类","名词","方位名词"],"z":"上、下、里、外、前、后","t":"Danh từ chỉ phương vị","d":"Đặt SAU danh từ để chỉ vị trí: 桌子上 (trên bàn), 书店里 (trong hiệu sách). Khác tiếng Việt: tiếng Trung nói \"bàn trên\" chứ không phải \"trên bàn\".","e":[["桌子上有几本书？","zhuō zi shàng yǒu jǐ běn shū","Trên bàn có mấy quyển sách?"],["书店里的人很多。","shū diàn lǐ de rén hěn duō","Trong hiệu sách rất đông người."],["他们都在国外。","tā men dōu zài guó wài","Họ đều ở nước ngoài."]]},{"n":4,"c":["词类","动词","能愿动词"],"z":"会、能","t":"Động từ năng nguyện 会, 能","d":"会 = biết (kỹ năng học được). 能 = có thể (có khả năng, điều kiện cho phép). Phủ định: 不会, 不能.","e":[["我会说中文。","wǒ huì shuō zhōng wén","Tôi biết nói tiếng Trung."],["他不会开车。","tā bú huì kāi chē","Anh ấy không biết lái xe."],["你明天能不能去？","nǐ míng tiān néng bu néng qù","Ngày mai bạn có đi được không?"],["她生病了，不能来上课。","tā shēng bìng le bù néng lái shàng kè","Cô ấy bị ốm rồi, không thể đến lớp."]]},{"n":5,"c":["词类","动词","能愿动词"],"z":"想、要","t":"Động từ năng nguyện 想, 要","d":"想 = muốn, nghĩ đến việc (mong muốn nhẹ). 要 = muốn, sẽ, cần (ý chí mạnh hơn). Đứng trước động từ.","e":[["我想买一些水果。","wǒ xiǎng mǎi yì xiē shuǐ guǒ","Tôi muốn mua một ít hoa quả."],["你想喝茶吗？","nǐ xiǎng hē chá ma","Bạn muốn uống trà không?"],["他们要去书店。","tā men yào qù shū diàn","Họ sẽ đi hiệu sách."],["我要学习汉语。","wǒ yào xué xí hàn yǔ","Tôi muốn học tiếng Hán."]]},{"n":6,"c":["词类","动词","能愿动词"],"z":"可以","t":"Động từ năng nguyện 可以","d":"可以 + động từ = được phép, có thể. 不可以 = không được (cấm). Hỏi xin phép: 我可以……吗？","e":[["这儿不可以吃东西。","zhè r bù kě yǐ chī dōng xi","Ở đây không được ăn đồ."],["我可以问一个问题吗？","wǒ kě yǐ wèn yí gè wèn tí ma","Tôi có thể hỏi một câu được không?"]]},{"n":7,"c":["词类","动词","离合词"],"z":"看病、睡觉、说话、上课、下课、上班、下班、生病","t":"Từ ly hợp","d":"Từ gồm động từ + tân ngữ, có thể tách ra để chèn 了, 一下, số lượng… vào giữa: 睡觉 → 睡一觉, 下课 → 下了课. Từ ly hợp không mang thêm tân ngữ phía sau.","e":[["他去医院看病了。","tā qù yī yuàn kàn bìng le","Anh ấy đi bệnh viện khám bệnh rồi."],["我想睡一觉，休息一下（儿）。","wǒ xiǎng shuì yí jiào xiū xi yí xià r","Tôi muốn ngủ một giấc, nghỉ ngơi một chút."],["上课不要说话。","shàng kè bú yào shuō huà","Trong giờ học không được nói chuyện."],["今天我上中文课。","jīn tiān wǒ shàng zhōng wén kè","Hôm nay tôi học tiết tiếng Trung."],["我下了课要去食堂。","wǒ xià le kè yào qù shí táng","Tan học xong tôi sẽ đi nhà ăn."],["下了班你做什么？","xià le bān nǐ zuò shén me","Tan làm xong bạn làm gì?"],["她昨天生病了。","tā zuó tiān shēng bìng le","Hôm qua cô ấy bị ốm."]]},{"n":8,"c":["词类","代词","疑问代词"],"z":"多、多少、几、哪、哪儿、哪里、哪些、什么、谁、怎么、怎么样","t":"Đại từ nghi vấn","d":"Dùng để hỏi, đặt đúng vị trí của thông tin cần hỏi (không đảo lên đầu câu). 几 hỏi số nhỏ (thường dưới 10), 多少 hỏi số bất kỳ, 多 + tính từ hỏi mức độ (多大 = bao nhiêu tuổi).","e":[["你弟弟多大？","nǐ dì di duō dà","Em trai bạn bao nhiêu tuổi?"],["这件衣服多少钱？","zhè jiàn yī fu duō shǎo qián","Bộ quần áo này bao nhiêu tiền?"],["现在几点？","xiàn zài jǐ diǎn","Bây giờ là mấy giờ?"],["她是哪国人？","tā shì nǎ guó rén","Cô ấy là người nước nào?"],["你去哪儿？","nǐ qù nǎ r","Bạn đi đâu?"],["你住在哪里？","nǐ zhù zài nǎ lǐ","Bạn sống ở đâu?"],["哪些是汉语书？","nǎ xiē shì hàn yǔ shū","Những quyển nào là sách tiếng Hán?"],["那是什么？","nà shì shén me","Kia là cái gì?"],["那个人是谁？","nà ge rén shì shuí","Người kia là ai?"],["你怎么去学校？","nǐ zěn me qù xué xiào","Bạn đến trường bằng cách nào?"],["明天天气怎么样？","míng tiān tiān qì zěn me yàng","Thời tiết ngày mai thế nào?"]]},{"n":9,"c":["词类","代词","人称代词"],"z":"我、你、您、他、她、我们、你们、他们、她们、它、它们、大家","t":"Đại từ nhân xưng","d":"我 tôi, 你 bạn, 您 ngài/ông/bà (lịch sự), 他 anh ấy, 她 cô ấy, 它 nó (con vật, đồ vật). Thêm 们 thành số nhiều. 大家 = mọi người.","e":[["我是学生。","wǒ shì xué shēng","Tôi là học sinh."],["你是哪国人？","nǐ shì nǎ guó rén","Bạn là người nước nào?"],["老师，您好！","lǎo shī nín hǎo","Em chào thầy/cô ạ!"],["他会开车吗？","tā huì kāi chē ma","Anh ấy biết lái xe không?"],["她是不是老师？","tā shì bu shì lǎo shī","Cô ấy có phải là giáo viên không?"],["我们都是大学生。","wǒ men dōu shì dà xué shēng","Chúng tôi đều là sinh viên."],["你们是学生吗？","nǐ men shì xué shēng ma","Các bạn là học sinh à?"],["他们去哪儿了？","tā men qù nǎ r le","Họ đi đâu rồi?"],["她们都是我的朋友。","tā men dōu shì wǒ de péng you","Các cô ấy đều là bạn của tôi."],["你看，它正在吃饭呢。","nǐ kàn tā zhèng zài chī fàn ne","Bạn xem, nó đang ăn kìa."],["这些小狗真漂亮，它们叫什么名字？","zhè xiē xiǎo gǒu zhēn piào liang tā men jiào shén me míng zi","Mấy chú chó con này đẹp thật, chúng tên là gì?"],["大家都喜欢学习汉语。","dà jiā dōu xǐ huan xué xí hàn yǔ","Mọi người đều thích học tiếng Hán."]]},{"n":10,"c":["词类","代词","指示代词"],"z":"这、那、这儿、那儿、这里、那里、这些、那些、有的、这个、那个、有些","t":"Đại từ chỉ thị","d":"这 (này, gần) – 那 (kia, xa). 这儿/这里 = ở đây, 那儿/那里 = ở đó. 这些/那些 = những… này/kia. 有的…有的… = có người…, có người….","e":[["这是谁的书？","zhè shì shuí de shū","Đây là sách của ai?"],["那个手机多少钱？","nà ge shǒu jī duō shǎo qián","Cái điện thoại kia bao nhiêu tiền?"],["我在这儿学习中文。","wǒ zài zhè r xué xí zhōng wén","Tôi học tiếng Trung ở đây."],["那儿有一家书店。","nà r yǒu yì jiā shū diàn","Ở đó có một hiệu sách."],["这里是我的家。","zhè lǐ shì wǒ de jiā","Đây là nhà tôi."],["那里有一家饭店。","nà lǐ yǒu yì jiā fàn diàn","Ở đó có một nhà hàng."],["这些是老师的书。","zhè xiē shì lǎo shī de shū","Đây là sách của thầy giáo."],["我不认识那些人。","wǒ bú rèn shi nà xiē rén","Tôi không quen những người đó."],["到了饭店，大家有的想吃米饭，有的想吃面条。","dào le fàn diàn dà jiā yǒu de xiǎng chī mǐ fàn yǒu de xiǎng chī miàn tiáo","Đến nhà hàng rồi, mọi người có người muốn ăn cơm, có người muốn ăn mì."],["这个杯子多少钱？","zhè ge bēi zi duō shǎo qián","Cái cốc này bao nhiêu tiền?"],["她在那个房间。","tā zài nà ge fáng jiān","Cô ấy ở phòng kia."],["有些学生不在学校住。","yǒu xiē xué shēng bú zài xué xiào zhù","Có một số học sinh không ở trong trường."]]},{"n":11,"c":["词类","数词",""],"z":"一、二/两、三、四、五、六、七、八、九、零、十、百、半、千","t":"Số từ","d":"Đếm số dùng 二, trước lượng từ dùng 两 (两个, 两百). Số 0 ở giữa đọc 零 (一百零六 = 106). 半 = rưỡi, nửa: 九点半 (9 giờ rưỡi), 半个小时 (nửa tiếng).","e":[["一个、两百、五十八、一百零六、两千三百五十、九点半、半个小时","yí gè liǎng bǎi wǔ shí bā yì bǎi líng liù liǎng qiān sān bǎi wǔ shí jiǔ diǎn bàn bàn gè xiǎo shí","một cái, hai trăm, năm mươi tám, một trăm linh sáu, hai nghìn ba trăm năm mươi, chín giờ rưỡi, nửa tiếng"]]},{"n":12,"c":["词类","量词","名量词"],"z":"专用名量词：本、个、家、口、块、件、只、元","t":"Lượng từ chuyên dùng","d":"Số + lượng từ + danh từ: 一本书 (một quyển sách). 本 sách vở, 个 chung, 家 cửa hàng/công ty, 口 người trong nhà, 块 tiền (đồng), 件 quần áo/sự việc, 只 con vật nhỏ, 元 đồng (văn viết).","e":[["这本书是中文书。","zhè běn shū shì zhōng wén shū","Quyển sách này là sách tiếng Trung."],["我吃了两个包子。","wǒ chī le liǎng gè bāo zi","Tôi đã ăn hai cái bánh bao."],["前边有一家书店。","qián biān yǒu yì jiā shū diàn","Phía trước có một hiệu sách."],["你家有几口人？","nǐ jiā yǒu jǐ kǒu rén","Nhà bạn có mấy người?"],["我有十块钱。","wǒ yǒu shí kuài qián","Tôi có mười đồng."],["这只小猫真漂亮。","zhè zhī xiǎo māo zhēn piào liang","Chú mèo con này đẹp thật."],["这件衣服三百元。","zhè jiàn yī fu sān bǎi yuán","Bộ quần áo này ba trăm tệ."]]},{"n":13,"c":["词类","量词","名量词"],"z":"借用名量词：杯","t":"Lượng từ mượn từ danh từ: 杯","d":"Mượn đồ đựng làm lượng từ: 一杯茶 (một cốc trà). Khi số là 一 có thể lược: 喝杯茶 = uống cốc trà.","e":[["喝杯茶吧。","hē bēi chá ba","Uống cốc trà đi."]]},{"n":14,"c":["词类","量词","时量词"],"z":"日、号、岁、点、分、年、天","t":"Lượng từ thời gian","d":"日/号 ngày (号 dùng trong khẩu ngữ), 岁 tuổi, 点 giờ, 分 phút, 年 năm, 天 ngày. Các từ này đi thẳng sau số, không cần 个 (一年, 一天; nhưng 一个月).","e":[["今天几月几日（号）？","jīn tiān jǐ yuè jǐ rì hào","Hôm nay là ngày mấy tháng mấy?"],["她今年几岁？","tā jīn nián jǐ suì","Năm nay cô ấy mấy tuổi?"],["现在八点二十分。","xiàn zài bā diǎn èr shí fēn","Bây giờ là tám giờ hai mươi phút."],["一年有十二个月。","yì nián yǒu shí èr gè yuè","Một năm có mười hai tháng."],["你一天学习几个汉字？","nǐ yì tiān xué xí jǐ gè hàn zì","Một ngày bạn học mấy chữ Hán?"]]},{"n":15,"c":["词类","副词","程度副词"],"z":"非常、很、太、真、有（一）点儿","t":"Phó từ chỉ mức độ","d":"Đứng trước tính từ / động từ tâm lý. 很 rất (trung tính), 非常 vô cùng, 太…了 quá…, 真 thật là, 有点儿 hơi (thường mang ý không hài lòng).","e":[["我非常喜欢学中文。","wǒ fēi cháng xǐ huan xué zhōng wén","Tôi vô cùng thích học tiếng Trung."],["这里的水果很便宜。","zhè lǐ de shuǐ guǒ hěn pián yi","Hoa quả ở đây rất rẻ."],["房间里太热了。","fáng jiān lǐ tài rè le","Trong phòng nóng quá."],["这儿的菜真好吃。","zhè r de cài zhēn hǎo chī","Món ăn ở đây ngon thật."],["今天天气有点儿冷。","jīn tiān tiān qì yǒu diǎn r lěng","Hôm nay trời hơi lạnh."]]},{"n":16,"c":["词类","副词","范围副词"],"z":"都¹","t":"Phó từ phạm vi 都","d":"都 = đều, tất cả. Đứng trước động từ, tổng hợp những người/vật đã nêu ở phía TRƯỚC nó.","e":[["我们都学习汉语。","wǒ men dōu xué xí hàn yǔ","Chúng tôi đều học tiếng Hán."],["他们都是中国学生。","tā men dōu shì zhōng guó xué shēng","Họ đều là sinh viên Trung Quốc."]]},{"n":17,"c":["词类","副词","时间副词"],"z":"在、正在","t":"Phó từ thời gian 在, 正在","d":"在 / 正在 + động từ = đang làm gì. 正在 nhấn mạnh \"ngay lúc này\".","e":[["他们在做什么？","tā men zài zuò shén me","Họ đang làm gì?"],["学生们正在上课。","xué shēng men zhèng zài shàng kè","Các học sinh đang học."]]},{"n":18,"c":["词类","副词","频率副词"],"z":"再¹","t":"Phó từ tần suất 再","d":"再 + động từ = lại, thêm lần nữa (việc chưa xảy ra, ở tương lai).","e":[["我想再买一本。","wǒ xiǎng zài mǎi yì běn","Tôi muốn mua thêm một quyển nữa."],["我再问一个问题，可以吗？","wǒ zài wèn yí gè wèn tí kě yǐ ma","Tôi hỏi thêm một câu nữa, được không?"]]},{"n":19,"c":["词类","副词","关联副词"],"z":"还¹、也","t":"Phó từ liên kết 还, 也","d":"还 = còn, ngoài ra còn (bổ sung thêm). 也 = cũng (giống nhau). Cả hai đứng trước động từ, không đứng đầu câu.","e":[["我想吃面条儿，还想吃包子。","wǒ xiǎng chī miàn tiáo r hái xiǎng chī bāo zi","Tôi muốn ăn mì, còn muốn ăn bánh bao nữa."],["我有两个姐姐，还有一个哥哥。","wǒ yǒu liǎng gè jiě jie hái yǒu yí gè gē ge","Tôi có hai chị gái, còn có một anh trai."],["他是学生，我也是学生。","tā shì xué shēng wǒ yě shì xué shēng","Anh ấy là học sinh, tôi cũng là học sinh."],["我学习汉语，我弟弟也学习汉语。","wǒ xué xí hàn yǔ wǒ dì di yě xué xí hàn yǔ","Tôi học tiếng Hán, em trai tôi cũng học tiếng Hán."]]},{"n":20,"c":["词类","副词","否定副词"],"z":"不、没（有）、不要","t":"Phó từ phủ định 不, 没(有), 不要","d":"不 phủ định hiện tại, tương lai, thói quen, và 是. 没(有) phủ định việc đã xảy ra (không dùng kèm 了). 不要 = đừng (cấm, khuyên).","e":[["她不是老师。","tā bú shì lǎo shī","Cô ấy không phải là giáo viên."],["我没看电视。","wǒ méi kàn diàn shì","Tôi không xem tivi."],["她去超市了，我没有去。","tā qù chāo shì le wǒ méi yǒu qù","Cô ấy đi siêu thị rồi, tôi không đi."],["请大家不要说话。","qǐng dà jiā bú yào shuō huà","Mọi người đừng nói chuyện."]]},{"n":21,"c":["词类","介词","引出时间、处所"],"z":"在","t":"Giới từ 在 (chỉ nơi chốn)","d":"在 + nơi chốn + động từ = làm gì ở đâu. Cụm 在… đứng TRƯỚC động từ (khác tiếng Việt).","e":[["我想在中国工作。","wǒ xiǎng zài zhōng guó gōng zuò","Tôi muốn làm việc ở Trung Quốc."],["你在哪儿学习中文？","nǐ zài nǎ r xué xí zhōng wén","Bạn học tiếng Trung ở đâu?"]]},{"n":22,"c":["词类","介词","引出对象"],"z":"和¹、对","t":"Giới từ 和, 对 (chỉ đối tượng)","d":"和 + người + 一起 + động từ = cùng ai làm gì. 对 + người + 说 = nói với ai. Phủ định đặt trước giới từ: 没和…一起.","e":[["我没和她一起去超市。","wǒ méi hé tā yì qǐ qù chāo shì","Tôi không cùng cô ấy đi siêu thị."],["我对老师说“谢谢”。","wǒ duì lǎo shī shuō xiè xie","Tôi nói \"cảm ơn\" với thầy giáo."]]},{"n":23,"c":["词类","连词","连接词语或短语"],"z":"和²","t":"Liên từ 和","d":"和 = và, nối hai danh từ / cụm danh từ. Không dùng 和 để nối hai câu hay hai động từ.","e":[["我和姐姐都喜欢唱歌。","wǒ hé jiě jie dōu xǐ huan chàng gē","Tôi và chị gái đều thích hát."],["今天和明天都下雨。","jīn tiān hé míng tiān dōu xià yǔ","Hôm nay và ngày mai đều mưa."]]},{"n":24,"c":["词类","助词","结构助词"],"z":"的¹","t":"Trợ từ kết cấu 的","d":"Định ngữ + 的 + danh từ = … của… (我的手机 = điện thoại của tôi). Quan hệ thân thiết có thể bỏ 的: 我妈妈.","e":[["这是你的手机吗？","zhè shì nǐ de shǒu jī ma","Đây là điện thoại của bạn à?"],["她是我的好朋友。","tā shì wǒ de hǎo péng you","Cô ấy là bạn thân của tôi."]]},{"n":25,"c":["词类","助词","动态助词"],"z":"了¹","t":"Trợ từ động thái 了 (了1)","d":"Động từ + 了 = hành động đã hoàn thành. Thường có số lượng hoặc định ngữ sau: 学了十个汉字.","e":[["今天我们学了十个汉字。","jīn tiān wǒ men xué le shí gè hàn zì","Hôm nay chúng tôi đã học mười chữ Hán."],["我买了一些苹果。","wǒ mǎi le yì xiē píng guǒ","Tôi đã mua một ít táo."]]},{"n":26,"c":["词类","助词","语气助词"],"z":"吧¹、了²、吗、呢¹、呢²、呢³","t":"Trợ từ ngữ khí 吧, 了, 吗, 呢","d":"吧: đề nghị (…đi, nhé). 了 (了2) cuối câu: tình huống đã thay đổi. 吗: câu hỏi có/không. 呢: ① đang làm gì (正在…呢); ② còn… thì sao? (你呢？); ③ … đâu? (你的手机呢？).","e":[["我们走吧。","wǒ men zǒu ba","Chúng ta đi thôi."],["八点了，起床吧。","bā diǎn le qǐ chuáng ba","Tám giờ rồi, dậy đi."],["她病了，在家休息呢。","tā bìng le zài jiā xiū xi ne","Cô ấy ốm rồi, đang nghỉ ở nhà đấy."],["他是中国人吗？","tā shì zhōng guó rén ma","Anh ấy là người Trung Quốc à?"],["这个电影好看吗？","zhè ge diàn yǐng hǎo kàn ma","Bộ phim này hay không?"],["她正在学习呢。","tā zhèng zài xué xí ne","Cô ấy đang học bài đấy."],["我是中国人，你呢？","wǒ shì zhōng guó rén nǐ ne","Tôi là người Trung Quốc, còn bạn?"],["A：你的手机呢？","nǐ de shǒu jī ne","A: Điện thoại của bạn đâu?"],["B：我的手机在房间里。","wǒ de shǒu jī zài fáng jiān lǐ","B: Điện thoại của tôi ở trong phòng."]]},{"n":27,"c":["词类","叹词",""],"z":"喂","t":"Thán từ 喂","d":"喂 (wèi) = alô (gọi điện thoại), hoặc \"này\" để gọi người khác.","e":[["喂，请问，李老师在吗？","wèi qǐng wèn lǐ lǎo shī zài ma","Alô, xin hỏi thầy Lý có ở đó không ạ?"],["喂，你去哪儿？","wèi nǐ qù nǎ r","Này, bạn đi đâu đấy?"]]},{"n":28,"c":["短语","结构类型","基本结构类型"],"z":"联合短语","t":"Cụm từ liên hợp","d":"Hai thành phần ngang hàng ghép lại (có hoặc không có 和).","e":[["哥哥姐姐、今天和明天、有没有","gē ge jiě jie jīn tiān hé míng tiān yǒu méi yǒu","anh trai và chị gái, hôm nay và ngày mai, có hay không"]]},{"n":29,"c":["短语","结构类型","基本结构类型"],"z":"偏正短语","t":"Cụm từ chính phụ","d":"Thành phần bổ nghĩa đứng TRƯỚC thành phần chính: 好朋友 (bạn tốt), 很喜欢 (rất thích).","e":[["好朋友、我的书包、很喜欢","hǎo péng you wǒ de shū bāo hěn xǐ huan","bạn tốt, cặp sách của tôi, rất thích"]]},{"n":30,"c":["短语","结构类型","基本结构类型"],"z":"动宾短语","t":"Cụm động – tân","d":"Động từ + tân ngữ.","e":[["买东西、回学校、去公司","mǎi dōng xi huí xué xiào qù gōng sī","mua đồ, về trường, đến công ty"]]},{"n":31,"c":["短语","结构类型","基本结构类型"],"z":"主谓短语","t":"Cụm chủ – vị","d":"Chủ ngữ + vị ngữ tạo thành một cụm.","e":[["我们学习、孩子高兴、房间很大","wǒ men xué xí hái zi gāo xìng fáng jiān hěn dà","chúng tôi học, đứa trẻ vui, căn phòng rất rộng"]]},{"n":32,"c":["短语","结构类型","其他结构类型"],"z":"数量短语","t":"Cụm số lượng","d":"Số từ + lượng từ.","e":[["一杯、两个","yì bēi liǎng gè","một cốc, hai cái"]]},{"n":33,"c":["短语","结构类型","其他结构类型"],"z":"介宾短语","t":"Cụm giới – tân","d":"Giới từ + danh từ, đứng trước động từ.","e":[["在学校（学习）、对老师（说）、和朋友（说汉语）","zài xué xiào xué xí duì lǎo shī shuō hé péng you shuō hàn yǔ","học ở trường, nói với thầy giáo, nói tiếng Hán với bạn"]]},{"n":34,"c":["短语","结构类型","其他结构类型"],"z":"方位短语","t":"Cụm phương vị","d":"Danh từ + từ chỉ phương vị.","e":[["桌子上、饭店里、椅子下边","zhuō zi shàng fàn diàn lǐ yǐ zi xià biān","trên bàn, trong nhà hàng, dưới gầm ghế"]]},{"n":35,"c":["句子成分","主语",""],"z":"名词、代词或名词性短语作主语","t":"Chủ ngữ là danh từ, đại từ","d":"Chủ ngữ thường là danh từ, đại từ hoặc cụm danh từ, đứng đầu câu.","e":[["电影很好看。","diàn yǐng hěn hǎo kàn","Bộ phim rất hay."],["她是老师。","tā shì lǎo shī","Cô ấy là giáo viên."],["这本书多少钱？","zhè běn shū duō shǎo qián","Quyển sách này bao nhiêu tiền?"]]},{"n":36,"c":["句子成分","谓语",""],"z":"名词、代词、数词或数量短语作谓语","t":"Vị ngữ là danh từ, số từ, cụm số lượng","d":"Khi nói ngày tháng, thứ, tuổi, giá tiền… có thể bỏ 是: 明天星期三 (Ngày mai thứ Tư). Phủ định thì phải dùng 不是.","e":[["明天星期三。","míng tiān xīng qī sān","Ngày mai là thứ Tư."],["那个饭店怎么样？","nà ge fàn diàn zěn me yàng","Nhà hàng kia thế nào?"],["我今年十二，我哥哥十五。","wǒ jīn nián shí èr wǒ gē ge shí wǔ","Năm nay tôi mười hai tuổi, anh trai tôi mười lăm."],["这本书二十八块。","zhè běn shū èr shí bā kuài","Quyển sách này hai mươi tám đồng."]]},{"n":37,"c":["句子成分","谓语",""],"z":"动词或动词性短语、形容词或形容词性短语作谓语","t":"Vị ngữ là động từ, tính từ","d":"Tính từ làm vị ngữ trực tiếp, không cần 是, thường có 很: 我很好. Không nói 我是很好.","e":[["老师来了。","lǎo shī lái le","Thầy giáo đến rồi."],["哥哥去学校了。","gē ge qù xué xiào le","Anh trai đi đến trường rồi."],["我的房间不大。","wǒ de fáng jiān bú dà","Phòng của tôi không rộng."],["这个菜很好吃。","zhè ge cài hěn hǎo chī","Món này rất ngon."]]},{"n":38,"c":["句子成分","宾语",""],"z":"名词、代词或名词性短语作宾语","t":"Tân ngữ là danh từ, đại từ","d":"Tân ngữ đứng sau động từ.","e":[["我喝茶。","wǒ hē chá","Tôi uống trà."],["明天我去找你。","míng tiān wǒ qù zhǎo nǐ","Ngày mai tôi đi tìm bạn."],["我吃了二十个饺子。","wǒ chī le èr shí gè jiǎo zi","Tôi đã ăn hai mươi cái sủi cảo."]]},{"n":39,"c":["句子成分","定语",""],"z":"名词性词语、形容词性短语、数量短语作定语","t":"Định ngữ","d":"Định ngữ (thành phần bổ nghĩa cho danh từ) luôn đứng TRƯỚC danh từ: 中文歌 (bài hát tiếng Trung), 便宜的手机 (điện thoại rẻ). Tính từ 2 âm tiết thường thêm 的.","e":[["她不会唱中文歌。","tā bú huì chàng zhōng wén gē","Cô ấy không biết hát bài hát tiếng Trung."],["我的中文老师是中国人。","wǒ de zhōng wén lǎo shī shì zhōng guó rén","Thầy giáo tiếng Trung của tôi là người Trung Quốc."],["我想买便宜的手机。","wǒ xiǎng mǎi pián yi de shǒu jī","Tôi muốn mua chiếc điện thoại rẻ."],["桌子下边有一只小狗。","zhuō zi xià biān yǒu yì zhī xiǎo gǒu","Dưới gầm bàn có một chú chó con."]]},{"n":40,"c":["句子成分","状语",""],"z":"副词、形容词作状语","t":"Trạng ngữ: phó từ, tính từ, từ chỉ thời gian – nơi chốn","d":"Trạng ngữ đứng TRƯỚC động từ: thời gian (十点), nơi chốn (在网上), phó từ (不, 非常). Thứ tự hay gặp: chủ ngữ + thời gian + nơi chốn + động từ.","e":[["他不吃包子。","tā bù chī bāo zi","Anh ấy không ăn bánh bao."],["这个房间非常干净。","zhè ge fáng jiān fēi cháng gān jìng","Căn phòng này vô cùng sạch sẽ."],["你认真写！","nǐ rèn zhēn xiě","Bạn viết cẩn thận vào!"],["他十点睡觉。","tā shí diǎn shuì jiào","Anh ấy mười giờ đi ngủ."],["我们下午去吧。","wǒ men xià wǔ qù ba","Chiều chúng ta đi nhé."],["她在网上买了两本书。","tā zài wǎng shàng mǎi le liǎng běn shū","Cô ấy đã mua hai quyển sách trên mạng."]]},{"n":41,"c":["句子成分","补语","数量补语1"],"z":"动词+动量补语","t":"Bổ ngữ động lượng 一下","d":"Động từ + 一下 = làm thử, làm một chút (giọng nhẹ nhàng, lịch sự).","e":[["休息一下吧。","xiū xi yí xià ba","Nghỉ một chút đi."],["请问一下，医院在哪儿？","qǐng wèn yí xià yī yuàn zài nǎ r","Cho hỏi một chút, bệnh viện ở đâu?"],["我想看一下那件衣服。","wǒ xiǎng kàn yí xià nà jiàn yī fu","Tôi muốn xem thử bộ quần áo kia."],["请写一下你的名字。","qǐng xiě yí xià nǐ de míng zi","Mời viết tên của bạn vào."]]},{"n":42,"c":["句子的类型","句型","单句"],"z":"主谓句1：动词谓语句","t":"Câu vị ngữ động từ","d":"Chủ ngữ + động từ (+ tân ngữ).","e":[["我买了一个面包。","wǒ mǎi le yí gè miàn bāo","Tôi đã mua một cái bánh mì."],["他今天不休息。","tā jīn tiān bù xiū xi","Hôm nay anh ấy không nghỉ."]]},{"n":43,"c":["句子的类型","句型","单句"],"z":"主谓句2：形容词谓语句","t":"Câu vị ngữ tính từ","d":"Chủ ngữ + (很/真…) + tính từ. Không dùng 是 trước tính từ.","e":[["今天天气很热。","jīn tiān tiān qì hěn rè","Hôm nay trời rất nóng."],["你女儿真漂亮！","nǐ nǚ ér zhēn piào liang","Con gái bạn xinh thật!"]]},{"n":44,"c":["句子的类型","句型","单句"],"z":"主谓句3：名词谓语句","t":"Câu vị ngữ danh từ","d":"Dùng cho thứ, ngày, giờ, tuổi, giá cả; không cần 是.","e":[["今天星期一。","jīn tiān xīng qī yī","Hôm nay là thứ Hai."],["现在十二点半。","xiàn zài shí èr diǎn bàn","Bây giờ là mười hai giờ rưỡi."]]},{"n":45,"c":["句子的类型","句型","单句"],"z":"非主谓句","t":"Câu không chủ ngữ","d":"Câu không có (không cần) chủ ngữ: chào hỏi, hiện tượng tự nhiên.","e":[["对不起！","duì bù qǐ","Xin lỗi!"],["下雨了。","xià yǔ le","Trời mưa rồi."]]},{"n":46,"c":["句子的类型","句类","陈述句"],"z":"","t":"Câu trần thuật","d":"Câu kể, nói về một sự việc (khẳng định hoặc phủ định).","e":[["她是我的朋友。","tā shì wǒ de péng you","Cô ấy là bạn của tôi."],["我不想吃面条儿。","wǒ bù xiǎng chī miàn tiáo r","Tôi không muốn ăn mì."]]},{"n":47,"c":["句子的类型","句类","疑问句"],"z":"是非问句","t":"Câu hỏi có/không (dùng 吗)","d":"Câu trần thuật + 吗？ Trả lời: 是/对/不是….","e":[["他是中国人吗？","tā shì zhōng guó rén ma","Anh ấy là người Trung Quốc à?"]]},{"n":48,"c":["句子的类型","句类","疑问句"],"z":"特指问句","t":"Câu hỏi có từ để hỏi","d":"Dùng 谁, 什么, 哪, 哪儿… đặt đúng chỗ thông tin cần hỏi; KHÔNG thêm 吗.","e":[["他是哪国人？","tā shì nǎ guó rén","Anh ấy là người nước nào?"]]},{"n":49,"c":["句子的类型","句类","疑问句"],"z":"正反问句","t":"Câu hỏi chính phản","d":"Động từ/tính từ + 不/没 + động từ/tính từ: 想不想, 冷不冷. Hoặc …了没有？ cho việc đã xảy ra. Không thêm 吗.","e":[["你想不想学中文？","nǐ xiǎng bu xiǎng xué zhōng wén","Bạn có muốn học tiếng Trung không?"],["你吃没吃晚饭？","nǐ chī méi chī wǎn fàn","Bạn đã ăn tối chưa?"],["同学们都来了没有？","tóng xué men dōu lái le méi yǒu","Các bạn học sinh đến đủ chưa?"],["今天冷不冷？","jīn tiān lěng bu lěng","Hôm nay có lạnh không?"]]},{"n":50,"c":["句子的类型","句类","祈使句"],"z":"","t":"Câu cầu khiến","d":"Yêu cầu, mời, khuyên, cấm: 请…, …吧, 不要/别….","e":[["您请坐。","nín qǐng zuò","Mời ông/bà ngồi."],["走吧！","zǒu ba","Đi thôi!"],["请大家不要说话！","qǐng dà jiā bú yào shuō huà","Mọi người đừng nói chuyện!"]]},{"n":51,"c":["句子的类型","句类","感叹句"],"z":"","t":"Câu cảm thán","d":"Bày tỏ cảm xúc: 真…啊！, 太…了！","e":[["今天真冷啊！","jīn tiān zhēn lěng a","Hôm nay lạnh thật đấy!"],["太贵了！","tài guì le","Đắt quá!"]]},{"n":52,"c":["句子的类型","特殊句型","“是”字句1"],"z":"表示等同或类属","t":"Câu chữ 是 (đồng nhất, phân loại)","d":"A 是 B = A là B. Phủ định: 不是.","e":[["我哥哥是大学生。","wǒ gē ge shì dà xué shēng","Anh trai tôi là sinh viên."]]},{"n":53,"c":["句子的类型","特殊句型","“有”字句1"],"z":"表示领有","t":"Câu chữ 有 (sở hữu)","d":"A 有 B = A có B. Phủ định chỉ dùng 没有 (không nói 不有).","e":[["我有哥哥，没有姐姐。","wǒ yǒu gē ge méi yǒu jiě jie","Tôi có anh trai, không có chị gái."]]},{"n":54,"c":["句子的类型","特殊句型","存现句1"],"z":"所处+是+名词","t":"Câu tồn hiện: nơi chốn + 是 + danh từ","d":"Nói ở chỗ đó là cái gì (người nói biết rõ chỗ đó là gì).","e":[["前边是不是电影院？","qián biān shì bu shì diàn yǐng yuàn","Phía trước có phải là rạp chiếu phim không?"],["超市后边是一家饭店。","chāo shì hòu biān shì yì jiā fàn diàn","Phía sau siêu thị là một nhà hàng."]]},{"n":55,"c":["句子的类型","特殊句型","存现句1"],"z":"处所+有+数量短语+名词","t":"Câu tồn hiện: nơi chốn + 有 + số lượng + danh từ","d":"Ở đâu có cái gì. Nơi chốn đứng đầu câu, không cần 在.","e":[["学校外边有一家书店。","xué xiào wài biān yǒu yì jiā shū diàn","Bên ngoài trường có một hiệu sách."],["桌子上有一本中文书。","zhuō zi shàng yǒu yì běn zhōng wén shū","Trên bàn có một quyển sách tiếng Trung."]]},{"n":56,"c":["句子的类型","特殊句型","连动句1"],"z":"前后动作先后发生，后一动作是前一动作的目的","t":"Câu liên động (hành động sau là mục đích)","d":"Chủ ngữ + động từ 1 (đi/đến…) + động từ 2 (để làm gì). Thứ tự theo trình tự thời gian.","e":[["我来中国学汉语。","wǒ lái zhōng guó xué hàn yǔ","Tôi đến Trung Quốc học tiếng Hán."],["晚上我们去电影院看电影。","wǎn shang wǒ men qù diàn yǐng yuàn kàn diàn yǐng","Buổi tối chúng tôi đến rạp xem phim."]]},{"n":57,"c":["句子的类型","特殊句型","连动句1"],"z":"前一动作是后一动作的方式","t":"Câu liên động (hành động trước là phương thức)","d":"坐/开/骑 + phương tiện + 去/来/上班… = đi bằng phương tiện gì.","e":[["我坐飞机去上海。","wǒ zuò fēi jī qù shàng hǎi","Tôi đi máy bay đến Thượng Hải."],["爸爸每天开车上班。","bà ba měi tiān kāi chē shàng bān","Bố ngày nào cũng lái xe đi làm."]]},{"n":58,"c":["句子的类型","特殊句型","双宾语句1"],"z":"主语+动词+宾语1+宾语2","t":"Câu hai tân ngữ","d":"Chủ ngữ + động từ (给, 问, 教, 送…) + tân ngữ người + tân ngữ vật.","e":[["老师给我一本书。","lǎo shī gěi wǒ yì běn shū","Thầy giáo đưa cho tôi một quyển sách."],["我问你一个问题。","wǒ wèn nǐ yí gè wèn tí","Tôi hỏi bạn một câu hỏi."]]},{"n":59,"c":["句子的类型","复句","不用关联词语的复句"],"z":"","t":"Câu phức không dùng từ nối","d":"Các vế đặt cạnh nhau, quan hệ hiểu qua ngữ cảnh.","e":[["这是我哥哥，他学习中文。","zhè shì wǒ gē ge tā xué xí zhōng wén","Đây là anh trai tôi, anh ấy học tiếng Trung."],["我有一个姐姐，没有妹妹。","wǒ yǒu yí gè jiě jie méi yǒu mèi mei","Tôi có một chị gái, không có em gái."],["她今天生病了，不能上课。","tā jīn tiān shēng bìng le bù néng shàng kè","Hôm nay cô ấy bị ốm, không đi học được."],["上午去，下午去？你说。","shàng wǔ qù xià wǔ qù nǐ shuō","Sáng đi hay chiều đi? Bạn nói đi."]]},{"n":60,"c":["句子的类型","复句","并列复句"],"z":"……，也……","t":"Câu phức đẳng lập: ……，也……","d":"Vế sau dùng 也 = cũng, nói hai điều giống nhau.","e":[["我喜欢唱歌，我弟弟也喜欢唱歌。","wǒ xǐ huan chàng gē wǒ dì di yě xǐ huan chàng gē","Tôi thích hát, em trai tôi cũng thích hát."],["这家饭店的饺子很好吃，也很便宜。","zhè jiā fàn diàn de jiǎo zi hěn hǎo chī yě hěn pián yi","Sủi cảo của nhà hàng này rất ngon, cũng rất rẻ."]]},{"n":61,"c":["句子的类型","复句","并列复句"],"z":"……，还……","t":"Câu phức đẳng lập: ……，还……","d":"Vế sau dùng 还 = còn, bổ sung thêm thông tin.","e":[["这个房间很大，还很漂亮。","zhè ge fáng jiān hěn dà hái hěn piào liang","Căn phòng này rất rộng, lại còn rất đẹp."],["我会说英语，还会说汉语。","wǒ huì shuō yīng yǔ hái huì shuō hàn yǔ","Tôi biết nói tiếng Anh, còn biết nói tiếng Hán."]]},{"n":62,"c":["动作的态","","完成态"],"z":"用动态助词“了¹”表示","t":"Thể hoàn thành (了1)","d":"Động từ + 了 + số lượng/tân ngữ: hành động đã xong. Phủ định: 没 + động từ (bỏ 了).","e":[["你学了多少个汉字？","nǐ xué le duō shǎo gè hàn zì","Bạn đã học được bao nhiêu chữ Hán?"],["我买了一些苹果。","wǒ mǎi le yì xiē píng guǒ","Tôi đã mua một ít táo."]]},{"n":63,"c":["动作的态","","变化态"],"z":"用语气助词“了²”表示","t":"Thể biến đổi (了2)","d":"了 cuối câu báo hiệu tình hình mới, đã thay đổi: 八点了 (đã tám giờ rồi), 病了 (ốm rồi).","e":[["八点了，起床吧。","bā diǎn le qǐ chuáng ba","Tám giờ rồi, dậy đi."],["她病了，在家休息呢。","tā bìng le zài jiā xiū xi ne","Cô ấy ốm rồi, đang nghỉ ở nhà."]]},{"n":64,"c":["动作的态","","进行态"],"z":"……在/正在+动词","t":"Thể tiếp diễn: 在/正在 + động từ","d":"Hành động đang diễn ra.","e":[["同学们在/正在上课。","tóng xué men zài zhèng zài shàng kè","Các bạn học sinh đang học."]]},{"n":65,"c":["动作的态","","进行态"],"z":"……在/正在+动词……+呢","t":"Thể tiếp diễn: 在/正在 + động từ + 呢","d":"Thêm 呢 cuối câu làm câu tự nhiên, nhấn mạnh \"đang\".","e":[["王老师在/正在打电话呢。","wáng lǎo shī zài zhèng zài dǎ diàn huà ne","Thầy Vương đang gọi điện thoại đấy."]]},{"n":66,"c":["动作的态","","进行态"],"z":"……呢","t":"Thể tiếp diễn: ……呢","d":"Chỉ dùng 呢 cuối câu cũng diễn tả \"đang\".","e":[["我没看电视，学习呢。","wǒ méi kàn diàn shì xué xí ne","Tôi không xem tivi, tôi đang học bài."]]},{"n":67,"c":["特殊表达法","数的表达法",""],"z":"钱数表示法","t":"Cách nói số tiền","d":"Khẩu ngữ: 块 (đồng) – 毛 (hào) – 分 (xu); văn viết: 元 – 角 – 分. Giá theo đơn vị: 三块一个 = ba đồng một cái.","e":[["这本书二十四块（钱）。","zhè běn shū èr shí sì kuài qián","Quyển sách này hai mươi bốn đồng."],["包子三块（钱）一个。","bāo zi sān kuài qián yí gè","Bánh bao ba đồng một cái."]]},{"n":68,"c":["特殊表达法","数的表达法",""],"z":"序数表达法1：第+数词","t":"Số thứ tự: 第 + số","d":"第 + số (+ lượng từ) = thứ…: 第一本 (quyển thứ nhất), 第六课 (bài thứ sáu).","e":[["今天我们学习第六课。","jīn tiān wǒ men xué xí dì liù kè","Hôm nay chúng ta học bài thứ sáu."],["第一本是我的书，第二本是她的书。","dì yī běn shì wǒ de shū dì èr běn shì tā de shū","Quyển thứ nhất là sách của tôi, quyển thứ hai là sách của cô ấy."]]},{"n":69,"c":["特殊表达法","时间表示法",""],"z":"年、月、日、星期表示法","t":"Cách nói năm, tháng, ngày, thứ","d":"Thứ tự từ lớn đến nhỏ: năm → tháng → ngày → thứ. Năm đọc từng số: 2022年 = èr líng èr èr nián. Thứ Hai đến thứ Bảy: 星期一 … 星期六; Chủ nhật: 星期日/星期天.","e":[["2022年2月4日","nián yuè rì","ngày 4 tháng 2 năm 2022"],["九月十五号、五月一日","jiǔ yuè shí wǔ hào wǔ yuè yī rì","ngày 15 tháng 9, ngày 1 tháng 5"],["星期一、星期二、星期三、星期四、星期五、星期六、星期日/星期天","xīng qī yī xīng qī èr xīng qī sān xīng qī sì xīng qī wǔ xīng qī liù xīng qī rì xīng qī tiān","thứ Hai, thứ Ba, thứ Tư, thứ Năm, thứ Sáu, thứ Bảy, Chủ nhật"]]},{"n":70,"c":["特殊表达法","时间表示法",""],"z":"钟点表示法","t":"Cách nói giờ","d":"点 giờ, 分 phút, 半 rưỡi. Phút dưới 10 thêm 零: 七点零五 (7:05).","e":[["两点、七点零五、九点二十（分）、十点半","liǎng diǎn qī diǎn líng wǔ jiǔ diǎn èr shí fēn shí diǎn bàn","hai giờ, bảy giờ năm phút, chín giờ hai mươi (phút), mười giờ rưỡi"]]}],"2":[{"n":1,"c":["语素","后缀",""],"z":"面","t":"Hậu tố 面","d":"Từ phương vị + 面 = phía, mặt: 前面 (phía trước), 里面 (bên trong), 后面 (phía sau). Nghĩa giống 前边, 里边.","e":[["我想坐在教室前面。","wǒ xiǎng zuò zài jiào shì qián miàn","Tôi muốn ngồi ở phía trước lớp học."],["你的书包里面有什么？","nǐ de shū bāo lǐ miàn yǒu shén me","Trong cặp sách của bạn có gì?"],["学校后面有一家超市。","xué xiào hòu miàn yǒu yì jiā chāo shì","Phía sau trường có một siêu thị."]]},{"n":2,"c":["词类","名词","方位名词"],"z":"左、右","t":"Danh từ phương vị 左, 右","d":"左边 bên trái, 右边 bên phải. Hay đứng trước danh từ làm định ngữ: 左边那件 (cái bên trái kia).","e":[["左边那件多少钱？","zuǒ biān nà jiàn duō shǎo qián","Cái bên trái kia bao nhiêu tiền?"],["你右边那个人是谁？","nǐ yòu biān nà ge rén shì shuí","Người bên phải bạn là ai?"]]},{"n":3,"c":["词类","动词","动词重叠"],"z":"AA、A一A、A了A、ABAB","t":"Lặp lại động từ","d":"Động từ đơn: AA, A一A, A了A (đã làm). Động từ 2 âm tiết: ABAB. Ý nghĩa: làm thử, làm một chút, giọng nhẹ nhàng. Âm lặp lại thường đọc thanh nhẹ.","e":[["那本书能给我看看吗？","nà běn shū néng gěi wǒ kàn kàn ma","Quyển sách kia có thể cho tôi xem một chút không?"],["请大家说一说自己的爱好。","qǐng dà jiā shuō yi shuō zì jǐ de ài hào","Mời mọi người nói thử về sở thích của mình."],["我尝了尝，觉得很好吃。","wǒ cháng le cháng jué de hěn hǎo chī","Tôi nếm thử một chút, thấy rất ngon."],["喝杯茶，休息休息吧。","hē bēi chá xiū xi xiū xi ba","Uống cốc trà, nghỉ ngơi một chút đi."]]},{"n":4,"c":["词类","动词","能愿动词"],"z":"可能","t":"Động từ năng nguyện 可能","d":"可能 + động từ = có lẽ, có thể (phỏng đoán).","e":[["她可能回家了。","tā kě néng huí jiā le","Có lẽ cô ấy về nhà rồi."],["小猫可能在房间里。","xiǎo māo kě néng zài fáng jiān lǐ","Có lẽ con mèo ở trong phòng."]]},{"n":5,"c":["词类","动词","离合词"],"z":"帮忙、游泳、跳舞、跑步","t":"Từ ly hợp 帮忙, 游泳, 跳舞, 跑步","d":"Có thể tách: 帮我一个忙 (giúp tôi một việc). Lặp lại theo kiểu AAB: 游游泳, 跳跳舞, 跑跑步. Không nói 帮忙我 – phải nói 帮我的忙 / 帮我一个忙.","e":[["你能帮我一个忙吗？","nǐ néng bāng wǒ yí gè máng ma","Bạn có thể giúp tôi một việc không?"],["晚上一起去游游泳，运动一下吧。","wǎn shang yì qǐ qù yóu yóu yǒng yùn dòng yí xià ba","Tối cùng đi bơi một chút, vận động một chút nhé."],["星期六的晚上，我喜欢和朋友们一起唱唱歌，跳跳舞。","xīng qī liù de wǎn shang wǒ xǐ huan hé péng you men yì qǐ chàng chàng gē tiào tiào wǔ","Tối thứ Bảy, tôi thích cùng các bạn hát hò, nhảy nhót."],["有时间你可以去外面跑跑步。","yǒu shí jiān nǐ kě yǐ qù wài miàn pǎo pǎo bù","Có thời gian bạn có thể ra ngoài chạy bộ một chút."]]},{"n":6,"c":["词类","代词","疑问代词"],"z":"为什么","t":"Đại từ nghi vấn 为什么","d":"为什么 = tại sao, đứng sau chủ ngữ, trước động từ.","e":[["他昨天为什么没来上课？","tā zuó tiān wèi shén me méi lái shàng kè","Hôm qua tại sao anh ấy không đi học?"],["你为什么想学中文？","nǐ wèi shén me xiǎng xué zhōng wén","Tại sao bạn muốn học tiếng Trung?"]]},{"n":7,"c":["词类","代词","人称代词"],"z":"自己","t":"Đại từ nhân xưng 自己","d":"自己 = tự mình, bản thân. 你自己去 = bạn tự đi.","e":[["下午我有事，你自己去，可以吗？","xià wǔ wǒ yǒu shì nǐ zì jǐ qù kě yǐ ma","Chiều nay tôi có việc, bạn tự đi được không?"]]},{"n":8,"c":["词类","代词","指示代词"],"z":"那么、那样、这么、这样、每","t":"Đại từ chỉ thị 那么, 那样, 这么, 这样, 每","d":"这么/那么 + tính từ = như thế này/như thế kia (nhấn mức độ). 这样/那样 = như thế này/kia (cách thức, tính chất). 每 + lượng từ = mỗi (每天, 每个人), thường đi với 都.","e":[["他为什么学得那么好？","tā wèi shén me xué de nà me hǎo","Tại sao anh ấy học giỏi như thế?"],["那样的事情经常有。","nà yàng de shì qing jīng cháng yǒu","Chuyện như vậy thường hay có."],["这么多人，我们明天再来吧。","zhè me duō rén wǒ men míng tiān zài lái ba","Đông người thế này, mai chúng ta lại đến nhé."],["这个字这样写，对吗？","zhè ge zì zhè yàng xiě duì ma","Chữ này viết như thế này, đúng không?"],["你每天怎么去学校？","nǐ měi tiān zěn me qù xué xiào","Mỗi ngày bạn đến trường bằng cách nào?"]]},{"n":9,"c":["词类","形容词","形容词重叠"],"z":"AA、AABB","t":"Lặp lại tính từ","d":"AA (高高的), AABB (高高兴兴). Lặp lại để miêu tả sinh động, nhấn mạnh. Sau khi lặp lại thì không dùng 很, 非常 nữa; làm trạng ngữ thì thêm 地.","e":[["她高高的个子，大大的眼睛，非常漂亮。","tā gāo gāo de gè zi dà dà de yǎn jing fēi cháng piào liang","Cô ấy dáng cao cao, mắt to to, vô cùng xinh đẹp."],["大家高高兴兴地回家了。","dà jiā gāo gāo xìng xìng de huí jiā le","Mọi người vui vui vẻ vẻ về nhà."]]},{"n":10,"c":["词类","数词",""],"z":"万、好多、多","t":"Số từ 万, 好多, 多","d":"万 = vạn (10.000): 两万三千 = 23.000. 好多 = rất nhiều. Số + 多 = hơn (số ước lượng): 二十多年 = hơn hai mươi năm.","e":[["两万三千、五万零八百、好多东西、好多人、二十多年、五十多人","liǎng wàn sān qiān wǔ wàn líng bā bǎi hǎo duō dōng xi hǎo duō rén èr shí duō nián wǔ shí duō rén","hai vạn ba nghìn (23.000), năm vạn lẻ tám trăm (50.800), rất nhiều đồ, rất nhiều người, hơn hai mươi năm, hơn năm mươi người"]]},{"n":11,"c":["词类","量词","名量词"],"z":"专用名量词：条、位、间、名","t":"Lượng từ chuyên dùng 条, 位, 间, 名","d":"条 vật dài (quần, đường, cá), 位 người (kính trọng), 间 phòng, 名 người (trang trọng, theo danh sách).","e":[["一条裤子、一位老师、一间教室、一名学生","yì tiáo kù zi yí wèi lǎo shī yì jiān jiào shì yì míng xué shēng","một chiếc quần, một vị giáo viên, một phòng học, một học sinh"]]},{"n":12,"c":["词类","量词","名量词"],"z":"借用名量词：包","t":"Lượng từ mượn 包","d":"包 = gói, túi, bọc.","e":[["一包衣服、一包书","yì bāo yī fu yì bāo shū","một túi quần áo, một gói sách"]]},{"n":13,"c":["词类","量词","动量词"],"z":"次","t":"Động lượng từ 次","d":"Động từ + số + 次 = làm mấy lần.","e":[["去一次、看一次","qù yí cì kàn yí cì","đi một lần, xem một lần"]]},{"n":14,"c":["词类","副词","程度副词"],"z":"多、好、最","t":"Phó từ mức độ 多, 好, 最","d":"多 + tính từ + 啊！ = …biết bao (cảm thán). 好 + tính từ = thật là, rất (khẩu ngữ). 最 = nhất.","e":[["这只小狗多可爱啊！","zhè zhī xiǎo gǒu duō kě ài a","Chú chó con này đáng yêu biết bao!"],["这个教室好大啊！","zhè ge jiào shì hǎo dà a","Phòng học này to thật đấy!"],["我最喜欢打篮球。","wǒ zuì xǐ huan dǎ lán qiú","Tôi thích chơi bóng rổ nhất."]]},{"n":15,"c":["词类","副词","范围副词"],"z":"一起","t":"Phó từ phạm vi 一起","d":"一起 + động từ = cùng nhau làm gì. Hay đi với 和/跟: 和你一起去.","e":[["晚上我们一起吃饭吧。","wǎn shang wǒ men yì qǐ chī fàn ba","Tối nay chúng ta cùng ăn cơm nhé."],["一起去看电影，怎么样？","yì qǐ qù kàn diàn yǐng zěn me yàng","Cùng đi xem phim, thế nào?"]]},{"n":16,"c":["词类","副词","时间副词"],"z":"还²、已经、有时（候）、快、快要、正","t":"Phó từ thời gian 还, 已经, 有时(候), 快, 快要, 正","d":"还 = vẫn (còn) chưa; 已经 = đã (rồi), hay đi với 了; 有时候 = có lúc; 快 = mau, nhanh lên; 快要…了 = sắp…rồi; 正 = đúng lúc đang.","e":[["他还没有起床呢。","tā hái méi yǒu qǐ chuáng ne","Anh ấy vẫn chưa ngủ dậy."],["张老师已经下班了。","zhāng lǎo shī yǐ jīng xià bān le","Thầy Trương đã tan làm rồi."],["我有时（候）去超市买东西。","wǒ yǒu shí hòu qù chāo shì mǎi dōng xi","Tôi có lúc đi siêu thị mua đồ."],["下雨了，快回家吧。","xià yǔ le kuài huí jiā ba","Trời mưa rồi, mau về nhà đi."],["新年快要到了。","xīn nián kuài yào dào le","Năm mới sắp đến rồi."],["我出来的时候，他正睡觉呢。","wǒ chū lái de shí hou tā zhèng shuì jiào ne","Lúc tôi ra ngoài, anh ấy đang ngủ."]]},{"n":17,"c":["词类","副词","频率副词"],"z":"常、经常","t":"Phó từ tần suất 常, 经常","d":"常/经常 = thường, thường xuyên. Phủ định hay dùng 不常.","e":[["我不常坐地铁。","wǒ bù cháng zuò dì tiě","Tôi không hay đi tàu điện ngầm."],["你经常上网买东西吗？","nǐ jīng cháng shàng wǎng mǎi dōng xi ma","Bạn có thường mua đồ trên mạng không?"]]},{"n":18,"c":["词类","副词","否定副词"],"z":"别","t":"Phó từ phủ định 别","d":"别 + động từ = đừng (cấm, khuyên). Giống 不要 nhưng khẩu ngữ hơn.","e":[["下雨了，别出去了。","xià yǔ le bié chū qù le","Trời mưa rồi, đừng ra ngoài nữa."],["别忘了，明天有考试。","bié wàng le míng tiān yǒu kǎo shì","Đừng quên, ngày mai có bài kiểm tra."]]},{"n":19,"c":["词类","副词","关联副词"],"z":"再²、就¹","t":"Phó từ liên kết 再, 就","d":"先…再… = trước tiên…rồi mới… (việc chưa làm). 就 = thì, liền (kết quả, nối tiếp ngay): 一…就… = vừa…là….","e":[["我先休息一会儿再工作。","wǒ xiān xiū xi yí huì r zài gōng zuò","Tôi nghỉ một lát trước rồi mới làm việc."],["你洗完手再吃水果。","nǐ xǐ wán shǒu zài chī shuǐ guǒ","Bạn rửa tay xong rồi hãy ăn hoa quả."],["因为身体不舒服，我就没去上课。","yīn wèi shēn tǐ bù shū fu wǒ jiù méi qù shàng kè","Vì người không khỏe nên tôi đã không đi học."],["他一到北京就去了长城。","tā yí dào běi jīng jiù qù le cháng chéng","Anh ấy vừa đến Bắc Kinh là đi Trường Thành ngay."]]},{"n":20,"c":["词类","副词","语气副词"],"z":"都²、就²、还是¹","t":"Phó từ ngữ khí 都, 就, 还是","d":"都…了 = đã…rồi (nhấn mạnh muộn, nhiều). 就 = chính là, ngay (khẳng định): 就在旁边 = ngay bên cạnh; 就买这件 = mua luôn cái này. 还是 = tốt hơn là, vẫn nên (khuyên, lựa chọn sau khi cân nhắc).","e":[["都十二点了，快睡觉吧。","dōu shí èr diǎn le kuài shuì jiào ba","Đã mười hai giờ rồi, mau đi ngủ đi."],["车站就在那个饭馆旁边。","chē zhàn jiù zài nà ge fàn guǎn páng biān","Bến xe ở ngay cạnh quán ăn kia."],["就买这件白色的吧。","jiù mǎi zhè jiàn bái sè de ba","Mua luôn cái màu trắng này đi."],["外边很冷，还是多穿一点儿吧。","wài biān hěn lěng hái shì duō chuān yì diǎn r ba","Bên ngoài rất lạnh, tốt hơn là mặc thêm chút áo đi."]]},{"n":21,"c":["词类","介词","引出时间、处所"],"z":"从¹","t":"Giới từ 从 (thời gian, nơi chốn)","d":"从 = từ. 从…到… = từ…đến….","e":[["我们从八点到十二点上课。","wǒ men cóng bā diǎn dào shí èr diǎn shàng kè","Chúng tôi học từ tám giờ đến mười hai giờ."],["你从哪儿来？","nǐ cóng nǎ r lái","Bạn từ đâu đến?"]]},{"n":22,"c":["词类","介词","引出方向、路径"],"z":"往","t":"Giới từ 往 (phương hướng)","d":"往 + phương hướng + động từ = đi/nhìn về phía…: 往前走 = đi thẳng về phía trước.","e":[["你从这儿往前走。","nǐ cóng zhè r wǎng qián zǒu","Bạn đi thẳng về phía trước từ đây."],["从这儿往下看，真漂亮啊！","cóng zhè r wǎng xià kàn zhēn piào liang a","Từ đây nhìn xuống, đẹp thật đấy!"]]},{"n":23,"c":["词类","介词","引出方向、路径"],"z":"从²","t":"Giới từ 从 (đường đi qua)","d":"从 + nơi chốn + 过/进/出… = đi qua/vào/ra từ chỗ nào.","e":[["这路公交车不从学校门口过。","zhè lù gōng jiāo chē bù cóng xué xiào mén kǒu guò","Tuyến xe buýt này không đi qua cổng trường."],["前门没开，咱们从后门进去吧。","qián mén méi kāi zán men cóng hòu mén jìn qù ba","Cửa trước không mở, chúng ta đi vào từ cửa sau đi."]]},{"n":24,"c":["词类","介词","引出对象"],"z":"给","t":"Giới từ 给","d":"给 + người + động từ = làm gì cho ai / đối với ai: 给妈妈打电话 = gọi điện cho mẹ.","e":[["我经常给爸爸妈妈打电话。","wǒ jīng cháng gěi bà ba mā ma dǎ diàn huà","Tôi thường gọi điện thoại cho bố mẹ."],["我给老师买了一杯咖啡。","wǒ gěi lǎo shī mǎi le yì bēi kā fēi","Tôi mua cho thầy giáo một cốc cà phê."]]},{"n":25,"c":["词类","介词","引出对象"],"z":"比","t":"Giới từ 比","d":"A 比 B + tính từ = A … hơn B. Không dùng 很, 非常 trước tính từ trong câu 比.","e":[["今天比昨天热。","jīn tiān bǐ zuó tiān rè","Hôm nay nóng hơn hôm qua."],["我觉得红色的比黑色的好看。","wǒ jué de hóng sè de bǐ hēi sè de hǎo kàn","Tôi thấy cái màu đỏ đẹp hơn cái màu đen."]]},{"n":26,"c":["词类","介词","引出对象"],"z":"跟¹","t":"Giới từ 跟","d":"跟 + người + động từ = với ai, cùng ai: 跟我说 = nói với tôi.","e":[["跟我说说你的爱好吧。","gēn wǒ shuō shuō nǐ de ài hào ba","Kể cho tôi nghe về sở thích của bạn đi."],["我跟他见过一次。","wǒ gēn tā jiàn guò yí cì","Tôi đã gặp anh ấy một lần."]]},{"n":27,"c":["词类","介词","引出原因"],"z":"因为¹","t":"Giới từ 因为 (nguyên nhân)","d":"因为 + danh từ = vì, do…","e":[["因为中国电影，我开始学习中文。","yīn wèi zhōng guó diàn yǐng wǒ kāi shǐ xué xí zhōng wén","Vì phim Trung Quốc mà tôi bắt đầu học tiếng Trung."]]},{"n":28,"c":["词类","连词","连接词或短语"],"z":"跟²","t":"Liên từ 跟","d":"A 跟 B = A và B (khẩu ngữ, giống 和).","e":[["爸爸跟妈妈都不在家。","bà ba gēn mā ma dōu bú zài jiā","Bố và mẹ đều không có nhà."],["我跟哥哥都在中国上学。","wǒ gēn gē ge dōu zài zhōng guó shàng xué","Tôi và anh trai đều đi học ở Trung Quốc."]]},{"n":29,"c":["词类","连词","连接分句或者句子"],"z":"但、但是、那、虽然、还是²、因为²、所以","t":"Liên từ nối câu: 但(是), 那, 虽然, 还是, 因为, 所以","d":"但是 = nhưng; 那 = vậy thì; 虽然…但是… = tuy…nhưng…; 还是 = hay là (câu hỏi lựa chọn); 因为…所以… = vì…nên….","e":[["这家饭馆的菜很好吃，但/但是有点儿贵。","zhè jiā fàn guǎn de cài hěn hǎo chī dàn dàn shì yǒu diǎn r guì","Món ăn của quán này rất ngon, nhưng hơi đắt."],["你不舒服，那就别去了。","nǐ bù shū fu nà jiù bié qù le","Bạn không khỏe, vậy thì đừng đi nữa."],["手机虽然不大，但/但是能帮我们做很多事。","shǒu jī suī rán bú dà dàn dàn shì néng bāng wǒ men zuò hěn duō shì","Điện thoại tuy không to nhưng có thể giúp chúng ta làm rất nhiều việc."],["你想喝茶还是喝咖啡？","nǐ xiǎng hē chá hái shì hē kā fēi","Bạn muốn uống trà hay uống cà phê?"],["因为我最近每天看手机，所以眼睛有点儿不舒服。","yīn wèi wǒ zuì jìn měi tiān kàn shǒu jī suǒ yǐ yǎn jing yǒu diǎn r bù shū fu","Vì dạo này ngày nào tôi cũng xem điện thoại nên mắt hơi khó chịu."]]},{"n":30,"c":["词类","助词","结构助词"],"z":"得、地","t":"Trợ từ kết cấu 得, 地","d":"Động từ + 得 + bổ ngữ (đánh giá kết quả, mức độ): 说得很好 = nói rất giỏi. Tính từ/trạng từ + 地 + động từ (cách thức): 高兴地唱歌 = vui vẻ hát.","e":[["他汉语说得很好。","tā hàn yǔ shuō de hěn hǎo","Anh ấy nói tiếng Hán rất giỏi."],["大家正在高兴地唱歌。","dà jiā zhèng zài gāo xìng de chàng gē","Mọi người đang vui vẻ ca hát."]]},{"n":31,"c":["词类","助词","动态助词"],"z":"过","t":"Trợ từ động thái 过","d":"Động từ + 过 = đã từng (trải nghiệm). Phủ định: 没 + động từ + 过.","e":[["你学过中文吗？","nǐ xué guò zhōng wén ma","Bạn đã từng học tiếng Trung chưa?"],["我没去过北京。","wǒ méi qù guò běi jīng","Tôi chưa từng đến Bắc Kinh."]]},{"n":32,"c":["词类","助词","动态助词"],"z":"着","t":"Trợ từ động thái 着","d":"Động từ + 着 = đang (trong trạng thái), …sẵn. Diễn tả trạng thái kéo dài hoặc cách thức đi kèm hành động khác.","e":[["他穿着一条黑色的裤子。","tā chuān zhe yì tiáo hēi sè de kù zi","Anh ấy đang mặc một chiếc quần màu đen."],["教室的门开着。","jiào shì de mén kāi zhe","Cửa lớp học đang mở."],["他们唱着歌，跳着舞，非常高兴。","tā men chàng zhe gē tiào zhe wǔ fēi cháng gāo xìng","Họ vừa hát vừa nhảy, rất vui vẻ."]]},{"n":33,"c":["词类","助词","语气助词"],"z":"呢⁴、吧²、的²、啊¹","t":"Trợ từ ngữ khí 呢, 吧, 的, 啊","d":"呢 trong câu hỏi có từ để hỏi: làm câu nhẹ nhàng hơn. 吧 = chắc là…phải không (đoán, cần xác nhận). 的 trong câu 是…的: nhấn mạnh thời gian, nơi chốn, cách thức. 啊 = cảm thán.","e":[["她怎么不在家呢？","tā zěn me bú zài jiā ne","Sao cô ấy lại không ở nhà nhỉ?"],["明天你想去哪儿呢？","míng tiān nǐ xiǎng qù nǎ r ne","Ngày mai bạn muốn đi đâu?"],["这是你的手机吧？","zhè shì nǐ de shǒu jī ba","Đây là điện thoại của bạn phải không?"],["这么晚了，超市已经关门了吧？","zhè me wǎn le chāo shì yǐ jīng guān mén le ba","Muộn thế này rồi, siêu thị chắc đã đóng cửa rồi nhỉ?"],["我是去年九月来中国的。","wǒ shì qù nián jiǔ yuè lái zhōng guó de","Tôi đến Trung Quốc vào tháng 9 năm ngoái."],["我们是在北京认识的。","wǒ men shì zài běi jīng rèn shi de","Chúng tôi quen nhau ở Bắc Kinh."],["他们是坐飞机去上海的。","tā men shì zuò fēi jī qù shàng hǎi de","Họ đi máy bay đến Thượng Hải."],["今天的晚饭是我做的。","jīn tiān de wǎn fàn shì wǒ zuò de","Bữa tối hôm nay là do tôi nấu."],["你汉语说得真好啊！","nǐ hàn yǔ shuō de zhēn hǎo a","Bạn nói tiếng Hán giỏi thật đấy!"]]},{"n":34,"c":["短语","结构类型","基本结构类型"],"z":"动补短语1","t":"Cụm động – bổ","d":"Động từ + bổ ngữ (kết quả, xu hướng, trạng thái, số lượng).","e":[["听懂、回去、跑得很快、等一下","tīng dǒng huí qù pǎo de hěn kuài děng yí xià","nghe hiểu, quay về, chạy rất nhanh, đợi một chút"]]},{"n":35,"c":["短语","结构类型","其他结构类型"],"z":"“的”字短语","t":"Cụm chữ 的","d":"… + 的 thay cho danh từ đã biết: 白色的 = cái màu trắng, 妈妈做的 = món mẹ nấu.","e":[["老师的、白色的、便宜的、妈妈做的","lǎo shī de bái sè de pián yi de mā ma zuò de","của thầy giáo, cái màu trắng, cái rẻ, món mẹ nấu"]]},{"n":36,"c":["短语","结构类型","其他结构类型"],"z":"连谓短语","t":"Cụm liên vị","d":"Hai động từ nối tiếp cùng một chủ ngữ.","e":[["来上课、去上海旅游、坐地铁去学校","lái shàng kè qù shàng hǎi lǚ yóu zuò dì tiě qù xué xiào","đến học, đi Thượng Hải du lịch, đi tàu điện ngầm đến trường"]]},{"n":37,"c":["短语","结构类型","其他结构类型"],"z":"兼语短语","t":"Cụm kiêm ngữ","d":"Tân ngữ của động từ trước đồng thời là chủ ngữ của động từ sau: 请他来 = mời anh ấy đến.","e":[["请他来、叫朋友帮忙、让妈妈洗衣服","qǐng tā lái jiào péng you bāng máng ràng mā ma xǐ yī fu","mời anh ấy đến, gọi bạn giúp đỡ, bảo mẹ giặt quần áo"]]},{"n":38,"c":["短语","功能类型","名词性短语"],"z":"","t":"Cụm danh từ","d":"Cụm có chức năng như một danh từ.","e":[["新电脑、老师的书、火车票、一个男孩、两条、这间","xīn diàn nǎo lǎo shī de shū huǒ chē piào yí gè nán hái liǎng tiáo zhè jiān","máy tính mới, sách của thầy giáo, vé tàu hỏa, một cậu bé, hai cái (vật dài), căn phòng này"]]},{"n":39,"c":["短语","功能类型","动词性短语"],"z":"","t":"Cụm động từ","d":"Cụm có chức năng như một động từ.","e":[["写汉字、听懂、回去、经常上网、可以进去","xiě hàn zì tīng dǒng huí qù jīng cháng shàng wǎng kě yǐ jìn qù","viết chữ Hán, nghe hiểu, quay về, thường xuyên lên mạng, có thể đi vào"]]},{"n":40,"c":["短语","功能类型","形容词性短语"],"z":"","t":"Cụm tính từ","d":"Cụm có chức năng như một tính từ.","e":[["很累、非常忙、慢一点儿","hěn lèi fēi cháng máng màn yì diǎn r","rất mệt, vô cùng bận, chậm một chút"]]},{"n":41,"c":["短语","固定短语","其他"],"z":"什么的","t":"Cụm cố định 什么的","d":"Liệt kê + 什么的 = …vân vân, …các thứ.","e":[["他喜欢唱歌、跳舞什么的。","tā xǐ huan chàng gē tiào wǔ shén me de","Anh ấy thích hát, nhảy các thứ."],["足球、篮球什么的，我都喜欢。","zú qiú lán qiú shén me de wǒ dōu xǐ huan","Bóng đá, bóng rổ các kiểu, tôi đều thích."]]},{"n":42,"c":["固定格式","",""],"z":"还是……吧","t":"Cấu trúc 还是……吧","d":"= tốt hơn là…, vẫn nên… đi (đưa ra lời khuyên/lựa chọn sau khi cân nhắc).","e":[["这些菜我都没吃过，还是你点吧。","zhè xiē cài wǒ dōu méi chī guò hái shì nǐ diǎn ba","Những món này tôi đều chưa ăn bao giờ, tốt hơn là bạn gọi đi."],["你还是去医院看看吧。","nǐ hái shì qù yī yuàn kàn kàn ba","Tốt hơn là bạn đi bệnh viện khám đi."]]},{"n":43,"c":["固定格式","",""],"z":"要/快要/就要……了","t":"Cấu trúc 要/快要/就要……了","d":"= sắp…rồi. 就要…了 có thể đi với thời gian cụ thể (下星期就要…了); 快要…了 thì KHÔNG đi với thời gian cụ thể.","e":[["电影要开始了。","diàn yǐng yào kāi shǐ le","Phim sắp bắt đầu rồi."],["我们快要开学了。","wǒ men kuài yào kāi xué le","Chúng tôi sắp khai giảng rồi."],["下星期就要考试了。","xià xīng qī jiù yào kǎo shì le","Tuần sau là thi rồi."]]},{"n":44,"c":["固定格式","",""],"z":"都……了","t":"Cấu trúc 都……了","d":"= đã…rồi (nhấn mạnh đã muộn/đã nhiều, thường kèm ý trách, giục).","e":[["都这么晚了，你怎么还不睡觉？","dōu zhè me wǎn le nǐ zěn me hái bú shuì jiào","Đã muộn thế này rồi, sao bạn vẫn chưa ngủ?"],["都十一点了，别看电视了。","dōu shí yī diǎn le bié kàn diàn shì le","Đã mười một giờ rồi, đừng xem tivi nữa."]]},{"n":45,"c":["句子成分","主语",""],"z":"受事主语","t":"Chủ ngữ bị động (chủ ngữ là đối tượng chịu tác động)","d":"Đưa vật chịu tác động lên đầu câu, không cần 被: 水果都吃完了 = Hoa quả ăn hết rồi.","e":[["水果都吃完了。","shuǐ guǒ dōu chī wán le","Hoa quả ăn hết rồi."],["那本书我看过了。","nà běn shū wǒ kàn guò le","Quyển sách đó tôi đọc rồi."]]},{"n":46,"c":["句子成分","谓语",""],"z":"名词性短语作谓语","t":"Cụm danh từ làm vị ngữ","d":"Miêu tả ngoại hình, quê quán, tuổi tác… không cần 是.","e":[["她高个子、大眼睛，很漂亮。","tā gāo gè zi dà yǎn jing hěn piào liang","Cô ấy dáng cao, mắt to, rất xinh."],["王老师上海人，四十多岁。","wáng lǎo shī shàng hǎi rén sì shí duō suì","Thầy Vương người Thượng Hải, hơn bốn mươi tuổi."]]},{"n":47,"c":["句子成分","定语",""],"z":"动词或动词性短语、主谓短语作定语","t":"Động từ, cụm chủ – vị làm định ngữ","d":"Cụm động từ/chủ vị + 的 + danh từ: 唱歌的女孩儿 = cô gái đang hát. Bắt buộc có 的.","e":[["那个唱歌的女孩儿是谁？","nà ge chàng gē de nǚ hái r shì shuí","Cô bé đang hát kia là ai?"],["这就是我儿子学习汉语的学校。","zhè jiù shì wǒ ér zi xué xí hàn yǔ de xué xiào","Đây chính là ngôi trường con trai tôi học tiếng Hán."],["我还不知道电影开始的时间。","wǒ hái bù zhī dao diàn yǐng kāi shǐ de shí jiān","Tôi vẫn chưa biết thời gian bắt đầu chiếu phim."]]},{"n":48,"c":["句子成分","补语","结果补语1"],"z":"动词+错/懂/好/会/完","t":"Bổ ngữ kết quả: 错, 懂, 好, 会, 完","d":"Động từ + bổ ngữ kết quả: 写错 (viết sai), 听懂 (nghe hiểu), 洗好 (giặt xong xuôi), 学会 (học được, biết rồi), 做完 (làm xong). Phủ định: 没 + động từ + bổ ngữ.","e":[["这个字你写错了。","zhè ge zì nǐ xiě cuò le","Chữ này bạn viết sai rồi."],["老师的话你听懂了吗？","lǎo shī de huà nǐ tīng dǒng le ma","Lời thầy giáo bạn nghe hiểu chưa?"],["衣服已经洗好了。","yī fu yǐ jīng xǐ hǎo le","Quần áo đã giặt xong rồi."],["我学会游泳了。","wǒ xué huì yóu yǒng le","Tôi đã học được bơi rồi."],["题太多了，我没做完。","tí tài duō le wǒ méi zuò wán","Bài nhiều quá, tôi làm không xong."]]},{"n":49,"c":["句子成分","补语","趋向补语1"],"z":"简单趋向补语的趋向意义用法：动词+来/去","t":"Bổ ngữ xu hướng đơn: 来/去","d":"Động từ + 来 (hướng về phía người nói) / 去 (rời xa người nói): 上来 (đi lên đây), 回去 (quay về đó).","e":[["你上来吧，我在楼上等你。","nǐ shàng lái ba wǒ zài lóu shàng děng nǐ","Bạn lên đây đi, tôi đợi bạn ở trên lầu."],["太晚了，你快回去吧。","tài wǎn le nǐ kuài huí qù ba","Muộn quá rồi, bạn mau về đi."]]},{"n":50,"c":["句子成分","补语","趋向补语1"],"z":"简单趋向补语的趋向意义用法：动词+上/下/进/出/过/回","t":"Bổ ngữ xu hướng đơn: 上/下/进/出/过/回","d":"Động từ + 上 (lên), 下 (xuống), 进 (vào), 出 (ra), 过 (qua), 回 (về).","e":[["飞机飞上天了。","fēi jī fēi shàng tiān le","Máy bay bay lên trời rồi."],["弟弟跑下楼了。","dì di pǎo xià lóu le","Em trai chạy xuống lầu rồi."],["老师走进办公室了。","lǎo shī zǒu jìn bàn gōng shì le","Thầy giáo đi vào văn phòng rồi."],["他从包里拿出一本书。","tā cóng bāo lǐ ná chū yì běn shū","Anh ấy lấy ra một quyển sách từ trong túi."],["我们一起走回学校吧。","wǒ men yì qǐ zǒu huí xué xiào ba","Chúng ta cùng đi bộ về trường nhé."]]},{"n":51,"c":["句子成分","补语","趋向补语1"],"z":"复合趋向补语的趋向意义用法：动词+出来/出去/过来/过去/回来/回去/进来/进去/起来/上来/上去/下来/下去","t":"Bổ ngữ xu hướng kép","d":"Động từ + 上/下/进/出/回/过/起 + 来/去. Tân ngữ chỉ nơi chốn phải đặt trước 来/去: 走进教室来. Tân ngữ chỉ vật có thể đặt trước hoặc sau 来/去.","e":[["车开过来了，大家快上车。","chē kāi guò lái le dà jiā kuài shàng chē","Xe chạy tới rồi, mọi người mau lên xe."],["她在那边等着呢，咱们走过去吧。","tā zài nà biān děng zhe ne zán men zǒu guò qù ba","Cô ấy đang đợi ở bên kia, chúng ta đi qua đó đi."],["他从书包里拿出来一本中文书。","tā cóng shū bāo lǐ ná chū lái yì běn zhōng wén shū","Anh ấy lấy ra một quyển sách tiếng Trung từ trong cặp."],["妈妈从超市买回来一些水果。","mā ma cóng chāo shì mǎi huí lái yì xiē shuǐ guǒ","Mẹ mua một ít hoa quả từ siêu thị về."],["王老师走进教室来了。","wáng lǎo shī zǒu jìn jiào shì lái le","Thầy Vương đi vào lớp học rồi."],["咱们的车能开进学校去吗？","zán men de chē néng kāi jìn xué xiào qù ma","Xe của chúng ta có lái vào trong trường được không?"],["你可以站起来吗？","nǐ kě yǐ zhàn qǐ lái ma","Bạn có thể đứng dậy được không?"],["他们怎么还没有走上来？","tā men zěn me hái méi yǒu zǒu shàng lái","Sao họ vẫn chưa đi lên đây nhỉ?"],["你在楼上等我，我给你送上去。","nǐ zài lóu shàng děng wǒ wǒ gěi nǐ sòng shàng qù","Bạn đợi tôi trên lầu, tôi mang lên cho bạn."],["他们从山上走下来了。","tā men cóng shān shàng zǒu xià lái le","Họ từ trên núi đi xuống rồi."],["这些东西你帮我拿下去吧。","zhè xiē dōng xi nǐ bāng wǒ ná xià qù ba","Những đồ này bạn giúp tôi mang xuống nhé."]]},{"n":52,"c":["句子成分","补语","状态补语1"],"z":"动词+得+形容词性短语","t":"Bổ ngữ trạng thái: động từ + 得 + tính từ","d":"Đánh giá, miêu tả kết quả của hành động. Có tân ngữ thì lặp lại động từ hoặc đưa tân ngữ lên trước: (打)篮球打得很好.","e":[["大家玩儿得很高兴。","dà jiā wán r de hěn gāo xìng","Mọi người chơi rất vui."],["他篮球打得很好。","tā lán qiú dǎ de hěn hǎo","Anh ấy chơi bóng rổ rất giỏi."]]},{"n":53,"c":["句子成分","补语","数量补语2"],"z":"表示动作持续的时间","t":"Bổ ngữ thời lượng","d":"Động từ + 了 + khoảng thời gian = làm trong bao lâu. Thêm 了 cuối câu = đến giờ vẫn còn tiếp tục.","e":[["我学了两年中文了。","wǒ xué le liǎng nián zhōng wén le","Tôi đã học tiếng Trung được hai năm rồi."],["我等了她一个多小时。","wǒ děng le tā yí gè duō xiǎo shí","Tôi đã đợi cô ấy hơn một tiếng đồng hồ."],["他们昨天看了一晚上的电视。","tā men zuó tiān kàn le yì wǎn shang de diàn shì","Hôm qua họ xem tivi suốt cả buổi tối."]]},{"n":54,"c":["句子成分","补语","数量补语2"],"z":"形容词+数量补语","t":"Tính từ + bổ ngữ số lượng","d":"Tính từ + 一些/一点儿/两岁… = hơn bao nhiêu (dùng trong so sánh).","e":[["坐地铁比坐公交车快一些。","zuò dì tiě bǐ zuò gōng jiāo chē kuài yì xiē","Đi tàu điện ngầm nhanh hơn đi xe buýt một chút."],["我哥哥比我大两岁。","wǒ gē ge bǐ wǒ dà liǎng suì","Anh trai tôi lớn hơn tôi hai tuổi."]]},{"n":55,"c":["句子的类型","句型","单句"],"z":"主谓句4：主谓谓语句","t":"Câu vị ngữ chủ – vị","d":"Vị ngữ là cả một cụm chủ – vị: 她 | 个子很高 (Cô ấy | dáng rất cao).","e":[["她个子很高。","tā gè zi hěn gāo","Cô ấy dáng người rất cao."],["这件事我知道。","zhè jiàn shì wǒ zhī dao","Việc này tôi biết."]]},{"n":56,"c":["句子的类型","句类","疑问句"],"z":"用“还是”连接的选择问句","t":"Câu hỏi lựa chọn với 还是","d":"A 还是 B？ = A hay B? Không thêm 吗.","e":[["是我自己去，还是你跟我一起去？","shì wǒ zì jǐ qù hái shì nǐ gēn wǒ yì qǐ qù","Là tôi tự đi, hay bạn đi cùng tôi?"],["你喜欢打篮球，还是喜欢踢足球？","nǐ xǐ huan dǎ lán qiú hái shì xǐ huan tī zú qiú","Bạn thích chơi bóng rổ hay thích đá bóng?"]]},{"n":57,"c":["句子的类型","句类","祈使句"],"z":"用“别”的祈使句","t":"Câu cầu khiến với 别","d":"别 + động từ (+ 了) = đừng…(nữa).","e":[["下雨了，别出去了。","xià yǔ le bié chū qù le","Trời mưa rồi, đừng ra ngoài nữa."],["别忘了，明天有考试。","bié wàng le míng tiān yǒu kǎo shì","Đừng quên, ngày mai có bài kiểm tra."]]},{"n":58,"c":["句子的类型","特殊句式","“是”字句2"],"z":"表示说明或特征","t":"Câu chữ 是: giải thích, đặc điểm","d":"是 + … + 的 = nói rõ đặc điểm, tính chất: 是新的 = là đồ mới.","e":[["那件衣服是新的。","nà jiàn yī fu shì xīn de","Bộ quần áo đó là đồ mới."],["这个手机是坏的，不能用。","zhè ge shǒu jī shì huài de bù néng yòng","Cái điện thoại này bị hỏng, không dùng được."]]},{"n":59,"c":["句子的类型","特殊句式","“有”字句2"],"z":"表示达到","t":"Câu chữ 有: đạt tới (mức độ)","d":"有 + số lượng = có tới, đạt tới…(không). Thường dùng để hỏi ước lượng.","e":[["王老师有三十岁吗？","wáng lǎo shī yǒu sān shí suì ma","Thầy Vương có tới ba mươi tuổi không?"],["这些水果有一百块钱吗？","zhè xiē shuǐ guǒ yǒu yì bǎi kuài qián ma","Chỗ hoa quả này có tới một trăm đồng không?"]]},{"n":60,"c":["句子的类型","特殊句式","存现句2"],"z":"处所+动词+着(+数量短语)+名词","t":"Câu tồn hiện: nơi chốn + động từ + 着 + danh từ","d":"Miêu tả ở đâu có ai/cái gì đang ở trạng thái nào: 门口站着一个人 = Ở cửa có một người đang đứng.","e":[["门口站着一个人。","mén kǒu zhàn zhe yí gè rén","Ở cửa có một người đang đứng."],["教室里坐着十几个学生。","jiào shì lǐ zuò zhe shí jǐ gè xué shēng","Trong lớp có hơn mười học sinh đang ngồi."]]},{"n":61,"c":["句子的类型","特殊句式","比较句1"],"z":"A比B+形容词","t":"Câu so sánh: A 比 B + tính từ","d":"A hơn B về tính chất nào đó.","e":[["姐姐比我高。","jiě jie bǐ wǒ gāo","Chị gái cao hơn tôi."],["公交车比地铁便宜。","gōng jiāo chē bǐ dì tiě pián yi","Xe buýt rẻ hơn tàu điện ngầm."]]},{"n":62,"c":["句子的类型","特殊句式","比较句1"],"z":"A比B+形容词+数量补语/程度补语","t":"Câu so sánh: A 比 B + tính từ + chênh lệch","d":"Sau tính từ thêm mức chênh: 两岁 (hai tuổi), 一点儿 (một chút), 多了/得多 (hơn nhiều). Không dùng 很/非常/太.","e":[["哥哥比我大两岁。","gē ge bǐ wǒ dà liǎng suì","Anh trai lớn hơn tôi hai tuổi."],["咖啡比奶茶贵一点儿。","kā fēi bǐ nǎi chá guì yì diǎn r","Cà phê đắt hơn trà sữa một chút."],["今天比昨天冷多了。","jīn tiān bǐ zuó tiān lěng duō le","Hôm nay lạnh hơn hôm qua nhiều."],["姐姐的个子比妹妹高得多。","jiě jie de gè zi bǐ mèi mei gāo de duō","Chiều cao của chị cao hơn em gái nhiều."]]},{"n":63,"c":["句子的类型","特殊句式","比较句1"],"z":"A有/没有B（+这么/那么）+形容词","t":"Câu so sánh: A 有/没有 B (这么/那么) + tính từ","d":"A 有 B … 吗？= A có … bằng B không? A 没有 B (那么) … = A không … bằng B.","e":[["你有他高吗？","nǐ yǒu tā gāo ma","Bạn có cao bằng anh ấy không?"],["今天没有昨天（那么）冷。","jīn tiān méi yǒu zuó tiān nà me lěng","Hôm nay không lạnh bằng hôm qua."],["我的汉语没有你（这么）好。","wǒ de hàn yǔ méi yǒu nǐ zhè me hǎo","Tiếng Hán của tôi không giỏi bằng bạn."]]},{"n":64,"c":["句子的类型","特殊句式","比较句1"],"z":"A比B+动词+得+形容词/A+动词+得+比+B+形容词","t":"Câu so sánh có bổ ngữ trạng thái","d":"A 比 B + động từ + 得 + tính từ, hoặc A + động từ + 得 + 比 B + tính từ. Hai cách cùng nghĩa.","e":[["她比我说得好。","tā bǐ wǒ shuō de hǎo","Cô ấy nói giỏi hơn tôi."],["我跑得比弟弟快。","wǒ pǎo de bǐ dì di kuài","Tôi chạy nhanh hơn em trai."]]},{"n":65,"c":["句子的类型","特殊句式","“是……的”句1"],"z":"强调时间、地点、方式、动作者","t":"Câu 是……的: nhấn mạnh thời gian, nơi chốn, cách thức, người làm","d":"Dùng cho việc ĐÃ xảy ra. 是 đặt trước phần cần nhấn mạnh (có thể lược), 的 ở cuối câu.","e":[["我是去年九月来中国的。","wǒ shì qù nián jiǔ yuè lái zhōng guó de","Tôi đến Trung Quốc vào tháng 9 năm ngoái."],["我们是在北京认识的。","wǒ men shì zài běi jīng rèn shi de","Chúng tôi quen nhau ở Bắc Kinh."],["他们是坐飞机去上海的。","tā men shì zuò fēi jī qù shàng hǎi de","Họ đi Thượng Hải bằng máy bay."],["今天的晚饭是我做的。","jīn tiān de wǎn fàn shì wǒ zuò de","Bữa tối hôm nay là do tôi nấu."]]},{"n":66,"c":["句子的类型","特殊句式","兼语句1"],"z":"表使令：主语+请/叫/让……+宾语1+动词+宾语2","t":"Câu kiêm ngữ: 请/叫/让","d":"Chủ ngữ + 请 (mời)/叫 (gọi, bảo)/让 (để, bảo) + người + động từ.","e":[["妈妈叫我去超市买水果。","mā ma jiào wǒ qù chāo shì mǎi shuǐ guǒ","Mẹ bảo tôi đi siêu thị mua hoa quả."],["我想请老师教我中文。","wǒ xiǎng qǐng lǎo shī jiāo wǒ zhōng wén","Tôi muốn mời thầy giáo dạy tôi tiếng Trung."],["老师让我们介绍一下自己的爱好。","lǎo shī ràng wǒ men jiè shào yí xià zì jǐ de ài hào","Thầy giáo bảo chúng tôi giới thiệu sở thích của bản thân."]]},{"n":67,"c":["句子的类型","特殊句式","双宾语句2"],"z":"主语+动词+给+宾语1+宾语2","t":"Câu hai tân ngữ với 给","d":"Động từ (送, 卖, 借, 还…) + 给 + người + vật.","e":[["爸爸送给我一个新手机。","bà ba sòng gěi wǒ yí gè xīn shǒu jī","Bố tặng cho tôi một chiếc điện thoại mới."],["他卖给我一本中文书。","tā mài gěi wǒ yì běn zhōng wén shū","Anh ấy bán cho tôi một quyển sách tiếng Trung."]]},{"n":68,"c":["句子的类型","复句","选择复句"],"z":"（是）……，还是……","t":"Câu phức lựa chọn: (是)……，还是……","d":"= …hay là…? (câu hỏi lựa chọn).","e":[["你（是）喝茶，还是喝咖啡？","nǐ shì hē chá hái shì hē kā fēi","Bạn uống trà hay uống cà phê?"],["你（是）喜欢白色的，还是黑色的？","nǐ shì xǐ huan bái sè de hái shì hēi sè de","Bạn thích cái màu trắng hay cái màu đen?"]]},{"n":69,"c":["句子的类型","复句","转折复句"],"z":"虽然……，但是……","t":"Câu phức chuyển ngoặt: 虽然……，但是……","d":"= Tuy…nhưng…. 虽然 có thể đứng trước hoặc sau chủ ngữ.","e":[["虽然学习的时间不长，但是他汉语说得很好。","suī rán xué xí de shí jiān bù cháng dàn shì tā hàn yǔ shuō de hěn hǎo","Tuy thời gian học không dài, nhưng anh ấy nói tiếng Hán rất giỏi."],["学汉语虽然难，但是很有意思。","xué hàn yǔ suī rán nán dàn shì hěn yǒu yì si","Học tiếng Hán tuy khó nhưng rất thú vị."]]},{"n":70,"c":["句子的类型","复句","因果复句"],"z":"因为……，所以……","t":"Câu phức nhân quả: 因为……，所以……","d":"= Vì…nên….","e":[["因为机票太贵了，所以我准备坐火车去。","yīn wèi jī piào tài guì le suǒ yǐ wǒ zhǔn bèi zuò huǒ chē qù","Vì vé máy bay đắt quá nên tôi định đi tàu hỏa."],["因为我爸爸在中国工作，所以我来这儿学习中文。","yīn wèi wǒ bà ba zài zhōng guó gōng zuò suǒ yǐ wǒ lái zhè r xué xí zhōng wén","Vì bố tôi làm việc ở Trung Quốc nên tôi đến đây học tiếng Trung."]]},{"n":71,"c":["句子的类型","复句","紧缩复句"],"z":"一……就……","t":"Câu rút gọn: 一……就……","d":"= Vừa…là…/ hễ…là…. 一 và 就 đều đứng trước động từ.","e":[["他一下课就去打篮球了。","tā yí xià kè jiù qù dǎ lán qiú le","Anh ấy vừa tan học là đi chơi bóng rổ."],["我一到商场就想买东西。","wǒ yí dào shāng chǎng jiù xiǎng mǎi dōng xi","Tôi cứ đến trung tâm thương mại là muốn mua sắm."]]},{"n":72,"c":["动作的态","","持续态"],"z":"动词+着：表示状态的持续","t":"Thể duy trì: 着 (trạng thái kéo dài)","d":"Động từ + 着: trạng thái tiếp tục tồn tại (cửa đang mở, đang đứng).","e":[["门开着，你进去吧。","mén kāi zhe nǐ jìn qù ba","Cửa đang mở, bạn vào đi."],["别站着，快请坐。","bié zhàn zhe kuài qǐng zuò","Đừng đứng nữa, mời ngồi đi."]]},{"n":73,"c":["动作的态","","持续态"],"z":"动词+着：表示动作的持续","t":"Thể duy trì: 着 (hành động kéo dài)","d":"正 + động từ + 着 + … + 呢: hành động đang tiếp diễn.","e":[["他们正吃着饭呢。","tā men zhèng chī zhe fàn ne","Họ đang ăn cơm."],["教室里正上着课呢。","jiào shì lǐ zhèng shàng zhe kè ne","Trong lớp đang có tiết học."]]},{"n":74,"c":["动作的态","","经历态"],"z":"用动态助词“过”表示","t":"Thể kinh nghiệm: 过","d":"Động từ + 过 = đã từng. Phủ định: 没 + động từ + 过.","e":[["你学过中文吗？","nǐ xué guò zhōng wén ma","Bạn đã từng học tiếng Trung chưa?"],["我没去过北京。","wǒ méi qù guò běi jīng","Tôi chưa từng đến Bắc Kinh."]]},{"n":75,"c":["特殊表达法","数的表达法",""],"z":"序数表示法2：数词+量词","t":"Số thứ tự: số + lượng từ","d":"Không cần 第: 三楼 = tầng 3, 304路 = tuyến (xe buýt) 304 (đọc từng số: sān líng sì).","e":[["我的房间在三楼。","wǒ de fáng jiān zài sān lóu","Phòng của tôi ở tầng ba."],["你可以坐304路公交车。","nǐ kě yǐ zuò lù gōng jiāo chē","Bạn có thể đi xe buýt tuyến 304."]]},{"n":76,"c":["特殊表达法","数的表达法",""],"z":"概数表达法1：用“几”表示概数","t":"Số ước lượng với 几","d":"几 trong câu trần thuật = vài, mấy: 几件 = mấy cái, 几百 = vài trăm.","e":[["这几件衣服你帮我洗一下。","zhè jǐ jiàn yī fu nǐ bāng wǒ xǐ yí xià","Mấy bộ quần áo này bạn giặt giúp tôi nhé."],["我们学校有几百名外国学生。","wǒ men xué xiào yǒu jǐ bǎi míng wài guó xué shēng","Trường chúng tôi có vài trăm học sinh nước ngoài."]]},{"n":77,"c":["特殊表达法","数的表达法",""],"z":"概数表达法1：数词+多+量词","t":"Số ước lượng: số + 多 + lượng từ","d":"Dùng với số tròn chục, trăm (20, 5000…): 二十多个 = hơn hai mươi cái.","e":[["教室里有二十多个学生。","jiào shì lǐ yǒu èr shí duō gè xué shēng","Trong lớp có hơn hai mươi học sinh."],["那个手机五千多块钱。","nà ge shǒu jī wǔ qiān duō kuài qián","Cái điện thoại kia hơn năm nghìn đồng."]]},{"n":78,"c":["特殊表达法","数的表达法",""],"z":"概数表达法1：数词+量词+多","t":"Số ước lượng: số + lượng từ + 多","d":"Dùng với số lẻ (1–9) hoặc đơn vị liên tục: 三年多 = hơn ba năm (3 năm và vài tháng).","e":[["我来中国已经三年多了。","wǒ lái zhōng guó yǐ jīng sān nián duō le","Tôi đến Trung Quốc đã hơn ba năm rồi."],["王老师的儿子今年六岁多了。","wáng lǎo shī de ér zi jīn nián liù suì duō le","Con trai thầy Vương năm nay hơn sáu tuổi rồi."]]}],"3":[{"n":1,"c":["语素","前缀",""],"z":"老—","t":"Tiền tố 老","d":"老 + họ: cách gọi thân mật người lớn tuổi hơn hoặc ngang hàng (老李 = anh Lý / ông Lý). 老 ở đây không có nghĩa là \"già\".","e":[["这家饭店的经理老李是我的朋友。","zhè jiā fàn diàn de jīng lǐ lǎo lǐ shì wǒ de péng you","Quản lý của nhà hàng này, anh Lý, là bạn của tôi."]]},{"n":2,"c":["语素","后缀",""],"z":"—家、—子、—员","t":"Hậu tố 家, 子, 员","d":"家 = nhà… (chuyên gia một lĩnh vực: 画家 họa sĩ). 子 = hậu tố danh từ, đọc thanh nhẹ (屋子 căn phòng). 员 = người làm một công việc (运动员 vận động viên).","e":[["你听说过这个画家吗？","nǐ tīng shuō guò zhè ge huà jiā ma","Bạn đã nghe nói về họa sĩ này chưa?"],["屋子有点儿小，可是很干净。","wū zi yǒu diǎn r xiǎo kě shì hěn gān jìng","Căn phòng hơi nhỏ, nhưng rất sạch sẽ."],["她以前是一名羽毛球运动员。","tā yǐ qián shì yì míng yǔ máo qiú yùn dòng yuán","Trước đây cô ấy là một vận động viên cầu lông."]]},{"n":3,"c":["词类","名词","方位名词"],"z":"东、南、西、北、北方、东方、南方、西方、中间","t":"Danh từ phương vị 东, 南, 西, 北, 中间…","d":"东 đông, 南 nam, 西 tây, 北 bắc (thứ tự hay nói: 东南西北). 北方 miền Bắc, 南方 miền Nam, 东方 phương Đông, 西方 phương Tây, 中间 ở giữa.","e":[["我听说北方的冬天很冷。","wǒ tīng shuō běi fāng de dōng tiān hěn lěng","Tôi nghe nói mùa đông ở miền Bắc rất lạnh."],["中国的北方和南方我都去过。","zhōng guó de běi fāng hé nán fāng wǒ dōu qù guò","Miền Bắc và miền Nam Trung Quốc tôi đều đã đến rồi."],["你们两个人中间的那个人是谁？","nǐ men liǎng gè rén zhōng jiān de nà ge rén shì shuí","Người đứng giữa hai bạn là ai?"],["东方人和西方人的生活习惯不太一样。","dōng fāng rén hé xī fāng rén de shēng huó xí guàn bú tài yí yàng","Thói quen sinh hoạt của người phương Đông và người phương Tây không giống nhau lắm."]]},{"n":4,"c":["词类","动词","能愿动词"],"z":"需要、该、应该、愿意、得","t":"Động từ năng nguyện 需要, 该, 应该, 愿意, 得","d":"需要 = cần; 该/应该 = nên, phải (theo lẽ thường); 愿意 = bằng lòng, sẵn lòng; 得 (děi) = phải (khẩu ngữ, phủ định dùng 不用 chứ không nói 不得).","e":[["从这儿过去，大概需要多长时间？","cóng zhè r guò qù dà gài xū yào duō cháng shí jiān","Từ đây đi qua đó, khoảng mất bao lâu?"],["医生说我感冒了，需要吃药。","yī shēng shuō wǒ gǎn mào le xū yào chī yào","Bác sĩ nói tôi bị cảm, cần uống thuốc."],["已经十一点了，你该睡觉了。","yǐ jīng shí yī diǎn le nǐ gāi shuì jiào le","Đã mười một giờ rồi, bạn nên đi ngủ rồi."],["你学了一天了，该休息休息了。","nǐ xué le yì tiān le gāi xiū xi xiū xi le","Bạn học cả ngày rồi, nên nghỉ ngơi một chút."],["我们应该多练习说中文。","wǒ men yīng gāi duō liàn xí shuō zhōng wén","Chúng ta nên luyện nói tiếng Trung nhiều hơn."],["我要去动物园，应该怎么坐车呢？","wǒ yào qù dòng wù yuán yīng gāi zěn me zuò chē ne","Tôi muốn đi vườn bách thú, nên đi xe thế nào nhỉ?"],["你愿意帮我学习汉语吗？","nǐ yuàn yì bāng wǒ xué xí hàn yǔ ma","Bạn có sẵn lòng giúp tôi học tiếng Hán không?"],["我很愿意参加这次汉语比赛。","wǒ hěn yuàn yì cān jiā zhè cì hàn yǔ bǐ sài","Tôi rất sẵn lòng tham gia cuộc thi tiếng Hán lần này."],["要上课了，咱们得快点儿走。","yào shàng kè le zán men děi kuài diǎn r zǒu","Sắp vào học rồi, chúng ta phải đi nhanh lên."],["我明天有考试，今天得认真复习。","wǒ míng tiān yǒu kǎo shì jīn tiān děi rèn zhēn fù xí","Ngày mai tôi có bài thi, hôm nay phải ôn tập chăm chỉ."]]},{"n":5,"c":["词类","动词","离合词"],"z":"动宾式离合词：放假、见面、结婚、洗澡","t":"Từ ly hợp kiểu động – tân: 放假, 见面, 结婚, 洗澡","d":"Có thể chèn 了, 过, 个… vào giữa: 放了假, 见过面, 洗个澡. Không mang tân ngữ phía sau: nói 跟他见面, không nói 见面他.","e":[["我放了假就准备去旅游。","wǒ fàng le jià jiù zhǔn bèi qù lǚ yóu","Được nghỉ là tôi chuẩn bị đi du lịch."],["我们已经很长时间没见过面了。","wǒ men yǐ jīng hěn cháng shí jiān méi jiàn guò miàn le","Chúng tôi đã lâu lắm rồi không gặp nhau."],["结了婚以后，你还打算工作吗？","jié le hūn yǐ hòu nǐ hái dǎ suàn gōng zuò ma","Kết hôn rồi bạn vẫn định đi làm chứ?"],["你先去洗个澡，休息一会儿。","nǐ xiān qù xǐ gè zǎo xiū xi yí huì r","Bạn đi tắm trước đi, nghỉ ngơi một lát."]]},{"n":6,"c":["词类","动词","离合词"],"z":"动补式离合词：打开、看见、离开、完成、分开","t":"Từ ly hợp kiểu động – bổ: 打开, 看见, 离开, 完成, 分开","d":"Chèn 得/不 vào giữa để tạo bổ ngữ khả năng: 打不开 (không mở được), 看得见 (nhìn thấy được), 分不开 (không tách rời được).","e":[["我打不开这瓶水，你能帮帮我吗？","wǒ dǎ bù kāi zhè píng shuǐ nǐ néng bāng bāng wǒ ma","Tôi không mở được chai nước này, bạn giúp tôi được không?"],["黑板上的字你看得见吗？","hēi bǎn shàng de zì nǐ kàn de jiàn ma","Chữ trên bảng bạn có nhìn thấy không?"],["他已经离不开这个地方了。","tā yǐ jīng lí bù kāi zhè ge dì fang le","Anh ấy đã không thể rời xa nơi này nữa rồi."],["今天的作业我可能完不成了。","jīn tiān de zuò yè wǒ kě néng wán bù chéng le","Bài tập hôm nay có lẽ tôi không làm xong được rồi."],["我的中文越来越好，跟老师的帮助是分不开的。","wǒ de zhōng wén yuè lái yuè hǎo gēn lǎo shī de bāng zhù shì fēn bù kāi de","Tiếng Trung của tôi ngày càng tốt, không thể tách rời sự giúp đỡ của thầy cô."]]},{"n":7,"c":["词类","代词","疑问代词"],"z":"怎样","t":"Đại từ nghi vấn 怎样","d":"怎样 = thế nào, như thế nào (giống 怎么样, hơi trang trọng). 怎样 + động từ: hỏi cách thức.","e":[["怎样才能学好中文呢？","zěn yàng cái néng xué hǎo zhōng wén ne","Làm thế nào mới học giỏi tiếng Trung được nhỉ?"],["他是怎样一个人？","tā shì zěn yàng yí gè rén","Anh ấy là người như thế nào?"]]},{"n":8,"c":["词类","代词","疑问代词"],"z":"疑问代词的非疑问用法：任指用法：①疑问代词+都……    ②疑问代词+疑问代词","t":"Đại từ nghi vấn chỉ \"bất kỳ\"","d":"① Từ để hỏi + 都/也 = ai cũng, đâu cũng, gì cũng: 谁都可以 = ai cũng được. ② Từ để hỏi lặp lại ở hai vế: 谁…谁… = ai…thì người đó…; 什么…什么… = …gì thì…nấy.","e":[["这次旅行谁都可以参加。","zhè cì lǚ xíng shuí dōu kě yǐ cān jiā","Chuyến du lịch lần này ai cũng có thể tham gia."],["我最近感冒了，哪儿都没去。","wǒ zuì jìn gǎn mào le nǎ r dōu méi qù","Dạo này tôi bị cảm, chẳng đi đâu cả."],["谁感兴趣谁就去参加。","shuí gǎn xìng qù shuí jiù qù cān jiā","Ai có hứng thú thì người đó đi tham gia."],["你想吃什么就点什么吧。","nǐ xiǎng chī shén me jiù diǎn shén me ba","Bạn muốn ăn gì thì gọi nấy nhé."]]},{"n":9,"c":["词类","代词","疑问代词"],"z":"疑问代词的非疑问用法：不定指用法","t":"Đại từ nghi vấn chỉ \"không xác định\"","d":"Từ để hỏi không dùng để hỏi mà mang nghĩa \"nào đó\": 在哪儿 = ở đâu đó, 什么 = cái gì đó, 谁 = ai đó, 哪天 = hôm nào đó.","e":[["我好像在哪儿见过她。","wǒ hǎo xiàng zài nǎ r jiàn guò tā","Hình như tôi đã gặp cô ấy ở đâu đó."],["你先吃点儿什么再走吧。","nǐ xiān chī diǎn r shén me zài zǒu ba","Bạn ăn chút gì đó rồi hãy đi."],["我下周搬家，想请谁来帮帮忙。","wǒ xià zhōu bān jiā xiǎng qǐng shuí lái bāng bāng máng","Tuần sau tôi chuyển nhà, muốn nhờ ai đó đến giúp một tay."],["咱们哪天一起去踢足球吧。","zán men nǎ tiān yì qǐ qù tī zú qiú ba","Hôm nào đó chúng ta cùng đi đá bóng nhé."]]},{"n":10,"c":["词类","代词","人称代词"],"z":"别人、咱们","t":"Đại từ nhân xưng 别人, 咱们","d":"别人 = người khác. 咱们 = chúng ta (bao gồm cả người nghe), còn 我们 có thể không bao gồm người nghe.","e":[["我不太清楚，你问问别人吧。","wǒ bú tài qīng chu nǐ wèn wèn bié rén ba","Tôi không rõ lắm, bạn hỏi người khác xem."],["别人能学好，我也一定能学好。","bié rén néng xué hǎo wǒ yě yí dìng néng xué hǎo","Người khác học giỏi được thì tôi cũng nhất định học giỏi được."],["咱们明天一起去动物园，怎么样？","zán men míng tiān yì qǐ qù dòng wù yuán zěn me yàng","Ngày mai chúng ta cùng đi vườn bách thú, thế nào?"],["要迟到了，咱们快走吧。","yào chí dào le zán men kuài zǒu ba","Sắp muộn rồi, chúng ta đi nhanh lên."]]},{"n":11,"c":["词类","代词","指示代词"],"z":"别的、其他","t":"Đại từ chỉ thị 别的, 其他","d":"别的 = khác (cái khác ngoài cái đã nói). 其他 = khác, còn lại (những cái khác trong cùng phạm vi).","e":[["除了北京，你还去过别的城市吗？","chú le běi jīng nǐ hái qù guò bié de chéng shì ma","Ngoài Bắc Kinh ra, bạn còn đến thành phố nào khác chưa?"],["我喜欢学习别的国家的语言和文化。","wǒ xǐ huan xué xí bié de guó jiā de yǔ yán hé wén huà","Tôi thích học ngôn ngữ và văn hóa của các nước khác."],["其他同学都回国了，只有我还在中国。","qí tā tóng xué dōu huí guó le zhǐ yǒu wǒ hái zài zhōng guó","Các bạn khác đều về nước rồi, chỉ có tôi vẫn ở Trung Quốc."],["除了看足球比赛，你还有其他爱好吗？","chú le kàn zú qiú bǐ sài nǐ hái yǒu qí tā ài hào ma","Ngoài xem thi đấu bóng đá ra, bạn còn sở thích nào khác không?"]]},{"n":12,"c":["词类","量词","名量词"],"z":"专用名量词：把、双、张、种、层、封、页、辆、节、所、班、段、头、句、公斤、斤、角、毛、刻、米","t":"Lượng từ chuyên dùng (nhóm 3)","d":"把 vật có tay cầm (ô, ghế), 双 đôi, 张 vật phẳng (ảnh, bàn, giấy), 种 loại, 层 tầng, 封 bức (thư), 页 trang, 辆 chiếc (xe), 节 tiết (học), 所 ngôi (trường, bệnh viện), 班 chuyến (xe, tàu), 段 đoạn, 头 con (trâu bò, lợn), 句 câu; đơn vị: 公斤 kg, 斤 cân (0,5 kg), 角/毛 hào, 刻 khắc (15 phút), 米 mét.","e":[["下雨了，记得带一把伞。","xià yǔ le jì de dài yì bǎ sǎn","Trời mưa rồi, nhớ mang một chiếc ô."],["我在网上买了两双鞋。","wǒ zài wǎng shàng mǎi le liǎng shuāng xié","Tôi đã mua hai đôi giày trên mạng."],["桌子上放着几张照片。","zhuō zi shàng fàng zhe jǐ zhāng zhào piàn","Trên bàn đặt mấy tấm ảnh."],["这里有多少种水果？","zhè lǐ yǒu duō shǎo zhǒng shuǐ guǒ","Ở đây có bao nhiêu loại hoa quả?"],["我们的教室在四层。","wǒ men de jiào shì zài sì céng","Phòng học của chúng tôi ở tầng bốn."],["我想给我的爸爸妈妈写一封信。","wǒ xiǎng gěi wǒ de bà ba mā ma xiě yì fēng xìn","Tôi muốn viết cho bố mẹ một bức thư."],["请大家打开书，第五页。","qǐng dà jiā dǎ kāi shū dì wǔ yè","Mời mọi người mở sách, trang năm."],["那辆黑色的自行车是我的。","nà liàng hēi sè de zì xíng chē shì wǒ de","Chiếc xe đạp màu đen kia là của tôi."],["我每周都有一节中文课。","wǒ měi zhōu dōu yǒu yì jié zhōng wén kè","Tuần nào tôi cũng có một tiết tiếng Trung."],["这个城市一共有三所大学。","zhè ge chéng shì yí gòng yǒu sān suǒ dà xué","Thành phố này có tổng cộng ba trường đại học."],["咱们坐下一班地铁走吧。","zán men zuò xià yì bān dì tiě zǒu ba","Chúng ta đi chuyến tàu điện ngầm sau nhé."],["请大家用这些词写一段话。","qǐng dà jiā yòng zhè xiē cí xiě yí duàn huà","Mời mọi người dùng những từ này viết một đoạn văn."],["爷爷家里养了十几头牛。","yé ye jiā lǐ yǎng le shí jǐ tóu niú","Nhà ông nội nuôi hơn mười con bò."],["这句话是什么意思？","zhè jù huà shì shén me yì si","Câu này có nghĩa là gì?"],["苹果多少钱一斤/公斤？","píng guǒ duō shǎo qián yì jīn gōng jīn","Táo bao nhiêu tiền một cân/một kg?"],["这些一共八块五角（毛）钱。","zhè xiē yí gòng bā kuài wǔ jiǎo máo qián","Chỗ này tổng cộng tám đồng năm hào."],["现在八点一刻。","xiàn zài bā diǎn yí kè","Bây giờ là tám giờ mười lăm."],["我哥哥身高一米八五。","wǒ gē ge shēn gāo yì mǐ bā wǔ","Anh trai tôi cao một mét tám mươi lăm."]]},{"n":13,"c":["词类","量词","名量词"],"z":"借用名量词：碗、盘","t":"Lượng từ mượn 碗, 盘","d":"碗 = bát, 盘 = đĩa: 一碗米饭 (một bát cơm), 一盘饺子 (một đĩa sủi cảo).","e":[["我要一碗面条和一碗米饭。","wǒ yào yì wǎn miàn tiáo hé yì wǎn mǐ fàn","Tôi muốn một bát mì và một bát cơm."],["中午我在食堂吃了一盘饺子。","zhōng wǔ wǒ zài shí táng chī le yì pán jiǎo zi","Trưa nay tôi ăn một đĩa sủi cảo ở nhà ăn."]]},{"n":14,"c":["词类","量词","动量词"],"z":"口、回、遍、声","t":"Động lượng từ 口, 回, 遍, 声","d":"口 = ngụm, miếng; 回 = lần (khẩu ngữ, giống 次); 遍 = lượt (từ đầu đến cuối); 声 = tiếng (âm thanh, lời nói).","e":[["他喝了一口茶，然后开始工作。","tā hē le yì kǒu chá rán hòu kāi shǐ gōng zuò","Anh ấy uống một ngụm trà rồi bắt đầu làm việc."],["我已经说过好几回了，但他还是不记得。","wǒ yǐ jīng shuō guò hǎo jǐ huí le dàn tā hái shì bú jì de","Tôi đã nói mấy lần rồi mà anh ấy vẫn không nhớ."],["对不起，我没听懂，请再说一遍。","duì bù qǐ wǒ méi tīng dǒng qǐng zài shuō yí biàn","Xin lỗi, tôi nghe chưa hiểu, xin nói lại một lượt."],["她跟我说了一声“谢谢”就走了。","tā gēn wǒ shuō le yì shēng xiè xie jiù zǒu le","Cô ấy nói với tôi một tiếng \"cảm ơn\" rồi đi."]]},{"n":15,"c":["词类","量词","量词重叠"],"z":"个个、张张","t":"Lặp lại lượng từ","d":"Lượng từ lặp lại = mỗi…đều, tất cả: 个个 = cái nào cũng, 张张 = tấm nào cũng. Thường đi với 都.","e":[["这些苹果个个都很大。","zhè xiē píng guǒ gè gè dōu hěn dà","Những quả táo này quả nào cũng to."],["他画的画，张张都很漂亮。","tā huà de huà zhāng zhāng dōu hěn piào liang","Tranh anh ấy vẽ, bức nào cũng rất đẹp."]]},{"n":16,"c":["词类","副词","程度副词"],"z":"比较、还³、更、特别、挺、有些、越、极","t":"Phó từ mức độ 比较, 还, 更, 特别, 挺, 有些, 越, 极","d":"比较 khá, tương đối; 还 còn (khá hơn, tạm được); 更 càng, hơn nữa; 特别 đặc biệt; 挺…的 khá là, rất (khẩu ngữ); 有些 hơi, có phần; 越来越 càng ngày càng; 极 cực kỳ.","e":[["这本书的内容比较简单，我读得很快。","zhè běn shū de nèi róng bǐ jiào jiǎn dān wǒ dú de hěn kuài","Nội dung quyển sách này khá đơn giản, tôi đọc rất nhanh."],["外面太热了，屋子里还凉快一些。","wài miàn tài rè le wū zi lǐ hái liáng kuai yì xiē","Bên ngoài nóng quá, trong nhà còn mát hơn một chút."],["搬家以后，我们的生活更方便了。","bān jiā yǐ hòu wǒ men de shēng huó gèng fāng biàn le","Sau khi chuyển nhà, cuộc sống của chúng tôi càng thuận tiện hơn."],["我弟弟特别喜欢看足球比赛。","wǒ dì di tè bié xǐ huan kàn zú qiú bǐ sài","Em trai tôi đặc biệt thích xem thi đấu bóng đá."],["多穿点儿衣服，外面挺冷的。","duō chuān diǎn r yī fu wài miàn tǐng lěng de","Mặc thêm áo vào, bên ngoài khá lạnh đấy."],["孩子这么晚还没回来，妈妈心里有些着急。","hái zi zhè me wǎn hái méi huí lái mā ma xīn lǐ yǒu xiē zháo jí","Muộn thế này con vẫn chưa về, trong lòng mẹ có phần sốt ruột."],["冬天快要到了，天气越来越冷了。","dōng tiān kuài yào dào le tiān qì yuè lái yuè lěng le","Mùa đông sắp đến rồi, thời tiết càng ngày càng lạnh."],["我对中国历史极有兴趣。","wǒ duì zhōng guó lì shǐ jí yǒu xìng qù","Tôi cực kỳ hứng thú với lịch sử Trung Quốc."],["他工作特别忙，周末极少休息。","tā gōng zuò tè bié máng zhōu mò jí shǎo xiū xi","Công việc của anh ấy đặc biệt bận, cuối tuần rất hiếm khi được nghỉ."]]},{"n":17,"c":["词类","副词","范围副词"],"z":"就³、一块儿、一共、只、到处、只是","t":"Phó từ phạm vi 就, 一块儿, 一共, 只, 到处, 只是","d":"就 = chỉ (khẩu ngữ): 就要两斤 = chỉ lấy hai cân; 一块儿 = cùng nhau; 一共 = tổng cộng; 只 = chỉ; 到处 = khắp nơi; 只是 = chỉ là.","e":[["我就要两斤苹果，不要别的。","wǒ jiù yào liǎng jīn píng guǒ bú yào bié de","Tôi chỉ lấy hai cân táo, không lấy thứ khác."],["办公室里就张老师一个人。","bàn gōng shì lǐ jiù zhāng lǎo shī yí gè rén","Trong văn phòng chỉ có một mình thầy Trương."],["你跟我一块儿去图书馆，好吗？","nǐ gēn wǒ yí kuài r qù tú shū guǎn hǎo ma","Bạn đi thư viện cùng tôi, được không?"],["我们经常一块儿踢足球。","wǒ men jīng cháng yí kuài r tī zú qiú","Chúng tôi thường cùng nhau đá bóng."],["你们班一共有多少留学生？","nǐ men bān yí gòng yǒu duō shǎo liú xué shēng","Lớp các bạn tổng cộng có bao nhiêu lưu học sinh?"],["这些水果一共多少钱？","zhè xiē shuǐ guǒ yí gòng duō shǎo qián","Chỗ hoa quả này tổng cộng bao nhiêu tiền?"],["我只有一个哥哥，没有弟弟妹妹。","wǒ zhǐ yǒu yí gè gē ge méi yǒu dì di mèi mei","Tôi chỉ có một anh trai, không có em trai em gái."],["她只说了自己的名字，没说别的。","tā zhǐ shuō le zì jǐ de míng zi méi shuō bié de","Cô ấy chỉ nói tên của mình, không nói gì khác."],["公园里到处都是锻炼身体的老人。","gōng yuán lǐ dào chù dōu shì duàn liàn shēn tǐ de lǎo rén","Trong công viên khắp nơi đều là người già tập thể dục."],["她只是笑了笑，一句话也没说。","tā zhǐ shì xiào le xiào yí jù huà yě méi shuō","Cô ấy chỉ cười cười, chẳng nói câu nào."]]},{"n":18,"c":["词类","副词","时间副词"],"z":"才¹、马上、先、一会儿、刚、刚刚、一直","t":"Phó từ thời gian 才, 马上, 先, 一会儿, 刚, 刚刚, 一直","d":"才 = vừa mới; 马上 = ngay lập tức; 先 = trước (tiên); 一会儿…一会儿… = lúc thì…lúc thì…; 刚/刚刚 = vừa mới; 一直 = luôn luôn, suốt.","e":[["他才到家，还没有吃饭呢。","tā cái dào jiā hái méi yǒu chī fàn ne","Anh ấy vừa mới về đến nhà, vẫn chưa ăn cơm."],["我才搬来北京，还不太习惯这里的生活","wǒ cái bān lái běi jīng hái bú tài xí guàn zhè lǐ de shēng huó","Tôi vừa mới chuyển đến Bắc Kinh, vẫn chưa quen lắm với cuộc sống ở đây."],["请等一下，我马上来。","qǐng děng yí xià wǒ mǎ shàng lái","Xin đợi một chút, tôi đến ngay."],["接了电话，她马上就跑出去了。","jiē le diàn huà tā mǎ shàng jiù pǎo chū qù le","Nghe điện thoại xong, cô ấy lập tức chạy ra ngoài."],["你先走吧，我还有工作要做。","nǐ xiān zǒu ba wǒ hái yǒu gōng zuò yào zuò","Bạn đi trước đi, tôi còn có việc phải làm."],["我想先洗个澡，然后再写作业。","wǒ xiǎng xiān xǐ gè zǎo rán hòu zài xiě zuò yè","Tôi muốn tắm trước, sau đó mới làm bài tập."],["最近天气变化很快，一会儿阴，一会儿晴。","zuì jìn tiān qì biàn huà hěn kuài yí huì r yīn yí huì r qíng","Dạo này thời tiết thay đổi rất nhanh, lúc thì âm u, lúc thì nắng."],["他刚开始学汉语，说得还不太好。","tā gāng kāi shǐ xué hàn yǔ shuō de hái bú tài hǎo","Anh ấy vừa mới bắt đầu học tiếng Hán, nói vẫn chưa giỏi lắm."],["报纸是早上刚送来的。","bào zhǐ shì zǎo shang gāng sòng lái de","Báo là sáng nay vừa mới đưa đến."],["刚刚还是晴天，怎么突然下雨了？","gāng gāng hái shì qíng tiān zěn me tū rán xià yǔ le","Vừa nãy trời còn nắng, sao tự nhiên lại mưa thế?"],["他不在，刚刚出去。","tā bú zài gāng gāng chū qù","Anh ấy không có ở đây, vừa mới ra ngoài."],["我一直都住在北京。","wǒ yì zhí dōu zhù zài běi jīng","Tôi luôn sống ở Bắc Kinh."],["别出去了，外面一直在下雨。","bié chū qù le wài miàn yì zhí zài xià yǔ","Đừng ra ngoài nữa, bên ngoài mưa suốt."]]},{"n":19,"c":["词类","副词","频率副词"],"z":"总、总是、又、常常","t":"Phó từ tần suất 总, 总是, 又, 常常","d":"总/总是 = luôn luôn, lúc nào cũng; 又 = lại (việc đã lặp lại, quá khứ); 常常 = thường thường.","e":[["一到冬天，孩子就总生病。","yí dào dōng tiān hái zi jiù zǒng shēng bìng","Cứ đến mùa đông là đứa trẻ lại hay ốm."],["上学的时候，我总是让爸爸开车送我。","shàng xué de shí hou wǒ zǒng shì ràng bà ba kāi chē sòng wǒ","Hồi đi học, tôi lúc nào cũng nhờ bố lái xe đưa đi."],["那个电影太有意思了，我昨天又看了一遍。","nà ge diàn yǐng tài yǒu yì si le wǒ zuó tiān yòu kàn le yí biàn","Bộ phim đó hay quá, hôm qua tôi lại xem thêm một lần nữa."],["下课以后，我常常去体育馆打篮球。","xià kè yǐ hòu wǒ cháng cháng qù tǐ yù guǎn dǎ lán qiú","Sau giờ học, tôi thường đến nhà thi đấu chơi bóng rổ."]]},{"n":20,"c":["词类","副词","关联副词"],"z":"一边","t":"Phó từ liên kết 一边","d":"一边 A 一边 B = vừa A vừa B (hai hành động cùng lúc).","e":[["孩子们高兴地一边唱歌一边跳舞。","hái zi men gāo xìng de yì biān chàng gē yì biān tiào wǔ","Bọn trẻ vui vẻ vừa hát vừa nhảy."],["我想找一个工作，一边工作一边学习。","wǒ xiǎng zhǎo yí gè gōng zuò yì biān gōng zuò yì biān xué xí","Tôi muốn tìm một công việc, vừa làm vừa học."]]},{"n":21,"c":["词类","副词","情态副词"],"z":"大概、必须、差不多、一定、好像、几乎","t":"Phó từ tình thái 大概, 必须, 差不多, 一定, 好像, 几乎","d":"大概 = có lẽ, khoảng; 必须 = bắt buộc phải (phủ định: 不必); 差不多 = gần như, xấp xỉ; 一定 = nhất định (不一定 = chưa chắc); 好像 = hình như; 几乎 = hầu như.","e":[["他大概已经回家了。","tā dà gài yǐ jīng huí jiā le","Có lẽ anh ấy đã về nhà rồi."],["你们学校大概有多少留学生？","nǐ men xué xiào dà gài yǒu duō shǎo liú xué shēng","Trường các bạn có khoảng bao nhiêu lưu học sinh?"],["我必须做完才能下班。","wǒ bì xū zuò wán cái néng xià bān","Tôi phải làm xong mới được tan làm."],["老师要求我们必须每天复习。","lǎo shī yāo qiú wǒ men bì xū měi tiān fù xí","Thầy giáo yêu cầu chúng tôi bắt buộc phải ôn bài mỗi ngày."],["我学习中文差不多三年了。","wǒ xué xí zhōng wén chà bù duō sān nián le","Tôi học tiếng Trung được gần ba năm rồi."],["我跟哥哥差不多高。","wǒ gēn gē ge chà bù duō gāo","Tôi và anh trai cao xấp xỉ nhau."],["放心，我一定不会迟到。","fàng xīn wǒ yí dìng bú huì chí dào","Yên tâm, tôi nhất định không đến muộn."],["我明天不一定有时间。","wǒ míng tiān bù yí dìng yǒu shí jiān","Ngày mai tôi chưa chắc đã có thời gian."],["她好像没有明白我的意思。","tā hǎo xiàng méi yǒu míng bai wǒ de yì si","Hình như cô ấy chưa hiểu ý tôi."],["我好像在哪里见过她。","wǒ hǎo xiàng zài nǎ lǐ jiàn guò tā","Hình như tôi đã gặp cô ấy ở đâu đó."],["他几乎每天都去图书馆学习。","tā jī hū měi tiān dōu qù tú shū guǎn xué xí","Anh ấy hầu như ngày nào cũng đến thư viện học."],["他太忙了，几乎没有时间休息。","tā tài máng le jī hū méi yǒu shí jiān xiū xi","Anh ấy bận quá, hầu như không có thời gian nghỉ ngơi."]]},{"n":22,"c":["词类","副词","语气副词"],"z":"当然、其实、终于、才²、才³、就⁴","t":"Phó từ ngữ khí 当然, 其实, 终于, 才, 就","d":"当然 = đương nhiên; 其实 = thực ra; 终于 = cuối cùng thì; 才 = mới (muộn, khó, hoặc ít hơn mong đợi); 就 = đã, ngay (sớm, dễ, nhanh hơn mong đợi). 才 và 就 là cặp đối lập hay thi.","e":[["我当然愿意帮助你。","wǒ dāng rán yuàn yì bāng zhù nǐ","Tôi đương nhiên sẵn lòng giúp bạn."],["当然没问题，欢迎你参加。","dāng rán méi wèn tí huān yíng nǐ cān jiā","Đương nhiên không vấn đề gì, hoan nghênh bạn tham gia."],["这个问题其实不难。","zhè ge wèn tí qí shí bù nán","Câu hỏi này thực ra không khó."],["我以为他回国了，其实他一直在中国。","wǒ yǐ wéi tā huí guó le qí shí tā yì zhí zài zhōng guó","Tôi tưởng anh ấy về nước rồi, thực ra anh ấy vẫn luôn ở Trung Quốc."],["经过一年多的努力，工作终于完成了。","jīng guò yì nián duō de nǔ lì gōng zuò zhōng yú wán chéng le","Sau hơn một năm nỗ lực, công việc cuối cùng đã hoàn thành."],["考试终于都结束了，我太开心了。","kǎo shì zhōng yú dōu jié shù le wǒ tài kāi xīn le","Các bài thi cuối cùng cũng kết thúc hết rồi, tôi vui quá."],["课文有点儿难，我读了三遍才明白。","kè wén yǒu diǎn r nán wǒ dú le sān biàn cái míng bai","Bài khóa hơi khó, tôi đọc ba lượt mới hiểu."],["这些旧书才卖了二十多块钱。","zhè xiē jiù shū cái mài le èr shí duō kuài qián","Chỗ sách cũ này chỉ bán được có hơn hai mươi đồng."],["她今天六点半就起床了。","tā jīn tiān liù diǎn bàn jiù qǐ chuáng le","Hôm nay cô ấy sáu rưỡi đã dậy rồi."],["这个句子不难，我听一遍就懂了。","zhè ge jù zi bù nán wǒ tīng yí biàn jiù dǒng le","Câu này không khó, tôi nghe một lần là hiểu ngay."]]},{"n":23,"c":["词类","副词","否定副词"],"z":"不必、不用","t":"Phó từ phủ định 不必, 不用","d":"不必/不用 + động từ = không cần, không phải.","e":[["你可以用手机买票，不必去车站，非常方便。","nǐ kě yǐ yòng shǒu jī mǎi piào bú bì qù chē zhàn fēi cháng fāng biàn","Bạn có thể mua vé bằng điện thoại, không cần ra ga, rất tiện."],["不用担心，我们帮你一起准备。","bú yòng dān xīn wǒ men bāng nǐ yì qǐ zhǔn bèi","Đừng lo, chúng tôi cùng giúp bạn chuẩn bị."]]},{"n":24,"c":["词类","介词","引出对象"],"z":"为¹、向¹、关于","t":"Giới từ 为, 向, 关于 (dẫn đối tượng)","d":"为 + người = vì, cho ai; 向 + người = với, hướng về ai (向老师请假 = xin phép thầy); 关于 = về (chủ đề), thường đứng đầu câu.","e":[["生日快乐，这是我为你做的蛋糕。","shēng rì kuài lè zhè shì wǒ wèi nǐ zuò de dàn gāo","Chúc mừng sinh nhật, đây là bánh kem tớ làm cho cậu."],["大家为这次比赛做了很多准备。","dà jiā wèi zhè cì bǐ sài zuò le hěn duō zhǔn bèi","Mọi người đã chuẩn bị rất nhiều cho cuộc thi lần này."],["如果你不能去上课，应该向老师请假。","rú guǒ nǐ bù néng qù shàng kè yīng gāi xiàng lǎo shī qǐng jià","Nếu bạn không thể đi học, nên xin phép thầy cô."],["老师让我们向她学习。","lǎo shī ràng wǒ men xiàng tā xué xí","Thầy giáo bảo chúng tôi học tập cô ấy."],["关于这个问题，我们还需要认真讨论。","guān yú zhè ge wèn tí wǒ men hái xū yào rèn zhēn tǎo lùn","Về vấn đề này, chúng ta còn cần thảo luận kỹ."],["关于比赛的时间，我明天一定告诉大家。","guān yú bǐ sài de shí jiān wǒ míng tiān yí dìng gào su dà jiā","Về thời gian thi đấu, ngày mai tôi nhất định sẽ báo cho mọi người."]]},{"n":25,"c":["词类","介词","引出方向、路径"],"z":"向²","t":"Giới từ 向 (phương hướng)","d":"向 + phương hướng/nơi chốn + động từ = về phía…: 向门口走去 = đi về phía cửa.","e":[["他向门口走去，好像准备离开。","tā xiàng mén kǒu zǒu qù hǎo xiàng zhǔn bèi lí kāi","Anh ấy đi về phía cửa, hình như chuẩn bị rời đi."],["老师让大家看向前边。","lǎo shī ràng dà jiā kàn xiàng qián biān","Thầy giáo bảo mọi người nhìn về phía trước."]]},{"n":26,"c":["词类","介词","引出目的、原因"],"z":"为了、为²","t":"Giới từ 为了, 为 (mục đích, nguyên nhân)","d":"为了 + mục đích = để, vì (mục đích). 为 + sự việc + cảm xúc = vì…mà (nguyên nhân): 为…感到高兴 = vui vì….","e":[["为了身体健康，我们应该坚持锻炼。","wèi le shēn tǐ jiàn kāng wǒ men yīng gāi jiān chí duàn liàn","Vì sức khỏe, chúng ta nên kiên trì tập luyện."],["妈妈经常为了工作睡得很晚。","mā ma jīng cháng wèi le gōng zuò shuì de hěn wǎn","Mẹ thường vì công việc mà ngủ rất muộn."],["大家都为我的好成绩感到高兴。","dà jiā dōu wèi wǒ de hǎo chéng jì gǎn dào gāo xìng","Mọi người đều vui vì thành tích tốt của tôi."],["同学们都在为下个星期的考试做准备。","tóng xué men dōu zài wèi xià gè xīng qī de kǎo shì zuò zhǔn bèi","Các bạn học sinh đều đang chuẩn bị cho kỳ thi tuần sau."]]},{"n":27,"c":["词类","介词","引出施事、受事"],"z":"把、被","t":"Giới từ 把, 被","d":"把 đưa tân ngữ lên trước động từ để nói xử lý nó thế nào (câu chữ 把). 被 = bị, được (câu bị động): 被 + người làm + động từ.","e":[["你把箱子放在这儿吧。","nǐ bǎ xiāng zi fàng zài zhè r ba","Bạn để cái vali ở đây nhé."],["我的自行车被朋友借走了。","wǒ de zì xíng chē bèi péng you jiè zǒu le","Xe đạp của tôi bị bạn mượn đi rồi."]]},{"n":28,"c":["词类","介词","引出凭借、依据"],"z":"根据","t":"Giới từ 根据","d":"根据 = căn cứ vào, dựa theo.","e":[["大家可以根据兴趣选择自己喜欢的运动。","dà jiā kě yǐ gēn jù xìng qù xuǎn zé zì jǐ xǐ huan de yùn dòng","Mọi người có thể dựa theo sở thích để chọn môn thể thao mình thích."],["根据要求，我们必须参加明天的会议。","gēn jù yāo qiú wǒ men bì xū cān jiā míng tiān de huì yì","Theo yêu cầu, chúng tôi bắt buộc phải tham dự cuộc họp ngày mai."]]},{"n":29,"c":["词类","连词","连接词或者短语"],"z":"或、或者","t":"Liên từ 或, 或者","d":"或/或者 = hoặc (dùng trong câu trần thuật). Câu hỏi lựa chọn thì dùng 还是.","e":[["我喝茶或/或者咖啡都可以。","wǒ hē chá huò huò zhě kā fēi dōu kě yǐ","Tôi uống trà hoặc cà phê đều được."],["我们可以打车或/或者坐地铁去。","wǒ men kě yǐ dǎ chē huò huò zhě zuò dì tiě qù","Chúng ta có thể bắt taxi hoặc đi tàu điện ngầm."]]},{"n":30,"c":["词类","连词","连接分句或句子"],"z":"只有、只要、不但、而且、如果、可¹、可是、然后","t":"Liên từ nối câu: 只有, 只要, 不但, 而且, 如果, 可, 可是, 然后","d":"只有…才… = chỉ có…mới…; 只要…就… = chỉ cần…là…; 不但…而且… = không những…mà còn…; 如果 = nếu; 可/可是 = nhưng; 然后 = sau đó.","e":[["只有大家一起想办法，才能解决这个问题。","zhǐ yǒu dà jiā yì qǐ xiǎng bàn fǎ cái néng jiě jué zhè ge wèn tí","Chỉ có mọi người cùng nghĩ cách mới giải quyết được vấn đề này."],["只要你想学，就一定能学好。","zhǐ yào nǐ xiǎng xué jiù yí dìng néng xué hǎo","Chỉ cần bạn muốn học thì nhất định sẽ học giỏi."],["我不但学习了中文，而且认识了很多新朋友。","wǒ bú dàn xué xí le zhōng wén ér qiě rèn shi le hěn duō xīn péng you","Tôi không những học được tiếng Trung mà còn quen được rất nhiều bạn mới."],["如果你有时间，我想请你参加我的生日晚会。","rú guǒ nǐ yǒu shí jiān wǒ xiǎng qǐng nǐ cān jiā wǒ de shēng rì wǎn huì","Nếu bạn có thời gian, tôi muốn mời bạn dự tiệc sinh nhật của tôi."],["她特别想来中国看看，可一直没有合适的机会。","tā tè bié xiǎng lái zhōng guó kàn kàn kě yì zhí méi yǒu hé shì de jī huì","Cô ấy rất muốn đến Trung Quốc xem thử, nhưng mãi không có cơ hội thích hợp."],["我很早就到了机场，可是没想到飞机晚点了。","wǒ hěn zǎo jiù dào le jī chǎng kě shì méi xiǎng dào fēi jī wǎn diǎn le","Tôi đến sân bay từ rất sớm, nhưng không ngờ máy bay bị trễ."],["你先去那边买票，然后过来找我。","nǐ xiān qù nà biān mǎi piào rán hòu guò lái zhǎo wǒ","Bạn đến bên kia mua vé trước, sau đó qua đây tìm tôi."]]},{"n":31,"c":["词类","助词","其他助词"],"z":"的话","t":"Trợ từ 的话","d":"…的话 = nếu…(thì). Có thể dùng một mình hoặc kết hợp 如果…的话.","e":[["你喜欢的话，就送给你吧。","nǐ xǐ huan de huà jiù sòng gěi nǐ ba","Nếu bạn thích thì tặng bạn luôn."],["如果明天下雨的话，我们就不去爬山了。","rú guǒ míng tiān xià yǔ de huà wǒ men jiù bú qù pá shān le","Nếu ngày mai trời mưa thì chúng ta không đi leo núi nữa."]]},{"n":32,"c":["短语","结构类型","其他结构类型"],"z":"同位短语","t":"Cụm đồng vị","d":"Hai thành phần chỉ cùng một đối tượng đứng cạnh nhau: 首都北京 = thủ đô Bắc Kinh.","e":[["首都北京、她一个人、我们学生","shǒu dū běi jīng tā yí gè rén wǒ men xué shēng","thủ đô Bắc Kinh, một mình cô ấy, chúng tôi những người học sinh"]]},{"n":33,"c":["短语","结构类型","其他结构类型"],"z":"动补短语2","t":"Cụm động – bổ (mức độ, khả năng)","d":"Tính từ + 极了/坏了 (cực kỳ); động từ + 得/不 + bổ ngữ (có thể / không thể).","e":[["漂亮极了、累坏了、看不懂、写得完","piào liang jí le lèi huài le kàn bù dǒng xiě de wán","đẹp cực kỳ, mệt rã rời, xem không hiểu, viết xong được"]]},{"n":34,"c":["短语","结构类型","其他结构类型"],"z":"数量重叠：数词+量词+数词+量词","t":"Lặp lại số lượng: số + lượng + số + lượng","d":"一步一步 = từng bước một, 一句一句 = từng câu một; thường thêm 地 làm trạng ngữ.","e":[["工作要一步一步地做。","gōng zuò yào yí bù yí bù de zuò","Công việc phải làm từng bước một."],["老师一句一句地教我们读课文。","lǎo shī yí jù yí jù de jiāo wǒ men dú kè wén","Thầy giáo dạy chúng tôi đọc bài khóa từng câu một."]]},{"n":35,"c":["短语","固定短语","四字格"],"z":"不A 不 B","t":"Cấu trúc 不A不B","d":"A, B là hai tính từ trái nghĩa: không…không… = vừa vặn, đúng mức: 不大不小 = không to không nhỏ, vừa.","e":[["这件衣服不大不小，特别合适。","zhè jiàn yī fu bú dà bù xiǎo tè bié hé shì","Bộ quần áo này không rộng không chật, cực kỳ vừa."],["最近天气不冷不热，很舒服。","zuì jìn tiān qì bù lěng bú rè hěn shū fu","Dạo này thời tiết không lạnh không nóng, rất dễ chịu."]]},{"n":36,"c":["短语","固定短语","其他"],"z":"不一会儿","t":"Cụm cố định 不一会儿","d":"= chẳng mấy chốc, một lát sau.","e":[["不一会儿，张校长就来了。","bù yí huì r zhāng xiào zhǎng jiù lái le","Chẳng mấy chốc, hiệu trưởng Trương đã đến."],["时间不一会儿就过去了。","shí jiān bù yí huì r jiù guò qù le","Thời gian chẳng mấy chốc đã trôi qua."]]},{"n":37,"c":["短语","固定短语","其他"],"z":"看来","t":"Cụm cố định 看来","d":"= xem ra, có vẻ như (rút ra kết luận từ tình hình).","e":[["电梯坏了，看来咱们只能走楼梯了。","diàn tī huài le kàn lái zán men zhǐ néng zǒu lóu tī le","Thang máy hỏng rồi, xem ra chúng ta chỉ có thể đi cầu thang bộ."],["这么晚了，看来他今天不会来了。","zhè me wǎn le kàn lái tā jīn tiān bú huì lái le","Muộn thế này rồi, xem ra hôm nay anh ấy sẽ không đến."]]},{"n":38,"c":["短语","固定短语","其他"],"z":"在……看来","t":"Cấu trúc 在……看来","d":"在 + người + 看来 = theo ý kiến của ai, theo ai thấy.","e":[["在同事们看来，她对工作非常认真。","zài tóng shì men kàn lái tā duì gōng zuò fēi cháng rèn zhēn","Theo các đồng nghiệp thấy, cô ấy làm việc rất nghiêm túc."],["在我看来，坚持读书是一种很好的习惯。","zài wǒ kàn lái jiān chí dú shū shì yì zhǒng hěn hǎo de xí guàn","Theo tôi, kiên trì đọc sách là một thói quen rất tốt."]]},{"n":39,"c":["短语","固定短语","其他"],"z":"越来越","t":"Cụm cố định 越来越","d":"越来越 + tính từ/động từ tâm lý = càng ngày càng.","e":[["听说学习中文的年轻人越来越多。","tīng shuō xué xí zhōng wén de nián qīng rén yuè lái yuè duō","Nghe nói người trẻ học tiếng Trung càng ngày càng nhiều."],["我越来越习惯这里的生活了。","wǒ yuè lái yuè xí guàn zhè lǐ de shēng huó le","Tôi càng ngày càng quen với cuộc sống ở đây."]]},{"n":40,"c":["短语","固定短语","其他"],"z":"看起来","t":"Cụm cố định 看起来","d":"= trông có vẻ, nhìn có vẻ (đánh giá qua vẻ bề ngoài).","e":[["这些菜看起来都很好吃。","zhè xiē cài kàn qǐ lái dōu hěn hǎo chī","Những món này trông đều rất ngon."],["那个新来的老师看起来很年轻。","nà ge xīn lái de lǎo shī kàn qǐ lái hěn nián qīng","Thầy giáo mới đến kia trông rất trẻ."]]},{"n":41,"c":["短语","固定短语","其他"],"z":"看上去","t":"Cụm cố định 看上去","d":"= nhìn qua thì, trông (giống 看起来).","e":[["这道题看上去很难，其实很简单。","zhè dào tí kàn shàng qù hěn nán qí shí hěn jiǎn dān","Bài này nhìn qua thì rất khó, thực ra rất đơn giản."],["她看上去不像五十多岁的人。","tā kàn shàng qù bú xiàng wǔ shí duō suì de rén","Bà ấy trông không giống người hơn năm mươi tuổi."]]},{"n":42,"c":["短语","固定短语","其他"],"z":"一般来说","t":"Cụm cố định 一般来说","d":"= nói chung, thông thường.","e":[["一般来说，早上锻炼身体比较好。","yì bān lái shuō zǎo shang duàn liàn shēn tǐ bǐ jiào hǎo","Nói chung, buổi sáng tập thể dục thì tốt hơn."],["一般来说，学习外语需要多练习。","yì bān lái shuō xué xí wài yǔ xū yào duō liàn xí","Nói chung, học ngoại ngữ cần luyện tập nhiều."]]},{"n":43,"c":["短语","固定短语","其他"],"z":"不怎么样","t":"Cụm cố định 不怎么样","d":"= chẳng ra sao, không tốt lắm.","e":[["我觉得这些照片照得不怎么样。","wǒ jué de zhè xiē zhào piàn zhào de bù zěn me yàng","Tôi thấy những bức ảnh này chụp chẳng ra sao."],["虽然考试前我复习了很长时间，但是成绩不怎么样。","suī rán kǎo shì qián wǒ fù xí le hěn cháng shí jiān dàn shì chéng jì bù zěn me yàng","Tuy trước khi thi tôi ôn tập rất lâu nhưng kết quả chẳng ra sao."]]},{"n":44,"c":["固定格式","",""],"z":"除了 ……（以外），……还/也/都……","t":"Cấu trúc 除了……(以外)，……还/也/都……","d":"除了 A，还/也 B = ngoài A ra còn B (bao gồm cả A). 除了 A，都 B = ngoài A ra thì đều B (loại trừ A).","e":[["除了看新闻（以外），人们还/也可以在网上看电影、买东西。","chú le kàn xīn wén yǐ wài rén men hái yě kě yǐ zài wǎng shàng kàn diàn yǐng mǎi dōng xi","Ngoài xem tin tức ra, mọi người còn có thể xem phim, mua đồ trên mạng."],["除了北京（以外），别的城市我都没去过。","chú le běi jīng yǐ wài bié de chéng shì wǒ dōu méi qù guò","Ngoài Bắc Kinh ra, các thành phố khác tôi đều chưa đến."]]},{"n":45,"c":["固定格式","",""],"z":"从……起","t":"Cấu trúc 从……起","d":"= kể từ…: 从现在起 = kể từ bây giờ.","e":[["从那天起，我们就变成了好朋友。","cóng nà tiān qǐ wǒ men jiù biàn chéng le hǎo péng you","Kể từ hôm đó, chúng tôi trở thành bạn tốt."],["从现在起，我一定要努力学习。","cóng xiàn zài qǐ wǒ yí dìng yào nǔ lì xué xí","Kể từ bây giờ, tôi nhất định phải học hành chăm chỉ."]]},{"n":46,"c":["固定格式","",""],"z":"对……来说","t":"Cấu trúc 对……来说","d":"= đối với…mà nói.","e":[["对他来说，这个机会非常重要。","duì tā lái shuō zhè ge jī huì fēi cháng zhòng yào","Đối với anh ấy, cơ hội này vô cùng quan trọng."],["对我来说，学习汉语很有意思。","duì wǒ lái shuō xué xí hàn yǔ hěn yǒu yì si","Đối với tôi, học tiếng Hán rất thú vị."]]},{"n":47,"c":["固定格式","",""],"z":"一……也/都+不/没……","t":"Cấu trúc 一……也/都 + 不/没……","d":"一 + lượng từ + danh từ + 也/都 + 不/没 = một…cũng không (phủ định tuyệt đối).","e":[["来中国以前，我一句汉语也不会说。","lái zhōng guó yǐ qián wǒ yí jù hàn yǔ yě bú huì shuō","Trước khi đến Trung Quốc, tôi một câu tiếng Hán cũng không biết nói."],["你说的这些地方我一个都没去过。","nǐ shuō de zhè xiē dì fang wǒ yí gè dōu méi qù guò","Những nơi bạn nói tôi chưa đến nơi nào cả."]]},{"n":48,"c":["固定格式","",""],"z":"一点儿也不","t":"Cấu trúc 一点儿也不","d":"一点儿也/都 + 不/没 + tính từ/động từ = không…chút nào.","e":[["快要考试了，你怎么一点儿也不着急？","kuài yào kǎo shì le nǐ zěn me yì diǎn r yě bù zháo jí","Sắp thi rồi, sao bạn chẳng sốt ruột chút nào thế?"],["今天天气很好，一点儿也不冷。","jīn tiān tiān qì hěn hǎo yì diǎn r yě bù lěng","Hôm nay thời tiết rất đẹp, không lạnh chút nào."]]},{"n":49,"c":["固定格式","",""],"z":"越……越……","t":"Cấu trúc 越……越……","d":"= càng…càng….","e":[["我想认识中国朋友，越多越好。","wǒ xiǎng rèn shi zhōng guó péng you yuè duō yuè hǎo","Tôi muốn quen bạn bè Trung Quốc, càng nhiều càng tốt."],["医生让我多休息，休息得越多，好得越快。","yī shēng ràng wǒ duō xiū xi xiū xi de yuè duō hǎo de yuè kuài","Bác sĩ bảo tôi nghỉ ngơi nhiều, nghỉ càng nhiều thì khỏi càng nhanh."]]},{"n":50,"c":["固定格式","",""],"z":"（在）……以前/以后/前/后","t":"Cấu trúc (在)……以前/以后/前/后","d":"Sự việc + 以前/前 = trước khi…; sự việc + 以后/后 = sau khi…. Đặt cuối cụm (khác tiếng Việt).","e":[["考试以前，你一定要认真复习。","kǎo shì yǐ qián nǐ yí dìng yào rèn zhēn fù xí","Trước khi thi, bạn nhất định phải ôn tập kỹ."],["来到中国以后，我慢慢习惯了这里的生活。","lái dào zhōng guó yǐ hòu wǒ màn màn xí guàn le zhè lǐ de shēng huó","Sau khi đến Trung Quốc, tôi dần quen với cuộc sống ở đây."],["睡觉前别忘记吃药。","shuì jiào qián bié wàng jì chī yào","Trước khi đi ngủ đừng quên uống thuốc."],["放学后，我要参加留学生篮球比赛。","fàng xué hòu wǒ yào cān jiā liú xué shēng lán qiú bǐ sài","Tan học xong, tôi phải tham gia trận bóng rổ của lưu học sinh."],["在离开中国以前，我一定要去长城看看。","zài lí kāi zhōng guó yǐ qián wǒ yí dìng yào qù cháng chéng kàn kàn","Trước khi rời Trung Quốc, tôi nhất định phải đi Trường Thành một chuyến."]]},{"n":51,"c":["固定格式","",""],"z":"X什么(啊)","t":"Cấu trúc X 什么(啊)","d":"Tính từ/động từ + 什么啊 = phản bác: có gì mà…, …gì chứ!","e":[["难过什么啊，你的成绩不是挺好的吗？","nán guò shén me a nǐ de chéng jì bú shì tǐng hǎo de ma","Buồn gì chứ, thành tích của bạn chẳng phải khá tốt sao?"],["方便什么啊，附近一个超市都没有。","fāng biàn shén me a fù jìn yí gè chāo shì dōu méi yǒu","Tiện gì mà tiện, gần đây một cái siêu thị cũng không có."]]},{"n":52,"c":["固定格式","",""],"z":"该……了","t":"Cấu trúc 该……了","d":"= đến lúc phải…rồi.","e":[["八点了，该上课了。","bā diǎn le gāi shàng kè le","Tám giờ rồi, đến giờ vào học rồi."],["下周要考试，我该复习了。","xià zhōu yào kǎo shì wǒ gāi fù xí le","Tuần sau thi rồi, tôi phải ôn bài thôi."]]},{"n":53,"c":["固定格式","",""],"z":"在……上/下/中","t":"Cấu trúc 在……上/下/中","d":"在…上 = về mặt…; 在…下 = dưới (sự giúp đỡ, ảnh hưởng)…; 在…中 = trong (quá trình)….","e":[["在学习上，老师和同学给了我许多帮助。","zài xué xí shàng lǎo shī hé tóng xué gěi le wǒ xǔ duō bāng zhù","Về mặt học tập, thầy cô và bạn bè đã giúp tôi rất nhiều."],["在父母的影响下，我从小就对中文很感兴趣。","zài fù mǔ de yǐng xiǎng xià wǒ cóng xiǎo jiù duì zhōng wén hěn gǎn xìng qù","Dưới ảnh hưởng của bố mẹ, từ nhỏ tôi đã rất hứng thú với tiếng Trung."],["在这次比赛中，我认识了一些新朋友。","zài zhè cì bǐ sài zhōng wǒ rèn shi le yì xiē xīn péng you","Trong cuộc thi lần này, tôi đã quen được một số bạn mới."]]},{"n":54,"c":["句子成分","主语",""],"z":"动词或动词性短语、形容词或形容词性短语作主语","t":"Động từ, tính từ làm chủ ngữ","d":"Động từ/tính từ (hoặc cụm) đứng đầu câu làm chủ ngữ, không cần biến đổi.","e":[["哭没有用。","kū méi yǒu yòng","Khóc cũng chẳng có ích gì."],["多穿一点儿比较好。","duō chuān yì diǎn r bǐ jiào hǎo","Mặc thêm chút áo thì tốt hơn."],["太胖了不好，太瘦了也不好。","tài pàng le bù hǎo tài shòu le yě bù hǎo","Béo quá không tốt, gầy quá cũng không tốt."]]},{"n":55,"c":["句子成分","主语",""],"z":"主谓短语作主语","t":"Cụm chủ – vị làm chủ ngữ","d":"Cả một cụm chủ – vị làm chủ ngữ của câu.","e":[["你来也可以。","nǐ lái yě kě yǐ","Bạn đến cũng được."],["身体健康最重要。","shēn tǐ jiàn kāng zuì zhòng yào","Cơ thể khỏe mạnh là quan trọng nhất."]]},{"n":56,"c":["句子成分","定语",""],"z":"多项定语","t":"Định ngữ nhiều tầng","d":"Thứ tự thường gặp: sở hữu → thời gian/nơi chốn → chỉ thị + số lượng → cụm động từ → tính từ → danh từ chính. Ví dụ: 我 / 昨天新买的 / 那条 / 黑色的 / 裤子.","e":[["我昨天新买的那条黑色的裤子你放在哪儿了？","wǒ zuó tiān xīn mǎi de nà tiáo hēi sè de kù zi nǐ fàng zài nǎ r le","Cái quần màu đen tôi mới mua hôm qua bạn để ở đâu rồi?"],["前面那个穿着蓝衬衫的短头发高个子的老人就是我的中文老师。","qián miàn nà ge chuān zhe lán chèn shān de duǎn tóu fa gāo gè zi de lǎo rén jiù shì wǒ de zhōng wén lǎo shī","Ông cụ cao, tóc ngắn, mặc áo sơ mi xanh lam ở phía trước kia chính là thầy giáo tiếng Trung của tôi."]]},{"n":57,"c":["句子成分","补语","结果补语2"],"z":"动词+到/住/走/上","t":"Bổ ngữ kết quả: 到, 住, 走, 上","d":"买到 (mua được, đạt mục đích), 记住 (nhớ kỹ, cố định lại), 骑走 (đi mất, rời khỏi), 关上 (đóng lại, khép vào).","e":[["火车票你买到了没有？","huǒ chē piào nǐ mǎi dào le méi yǒu","Vé tàu bạn mua được chưa?"],["老师说的话我都记住了。","lǎo shī shuō de huà wǒ dōu jì zhù le","Lời thầy giáo nói tôi đều nhớ kỹ rồi."],["我的自行车让朋友骑走了。","wǒ de zì xíng chē ràng péng you qí zǒu le","Xe đạp của tôi bị bạn đạp đi mất rồi."],["下班的时候，别忘了关上电脑。","xià bān de shí hou bié wàng le guān shàng diàn nǎo","Lúc tan làm, đừng quên tắt máy tính."]]},{"n":58,"c":["句子成分","补语","趋向补语2"],"z":"趋向补语的引申用法：表示结果意义：动词+出/起/下","t":"Nghĩa mở rộng của bổ ngữ xu hướng: 出/起/下 (kết quả)","d":"想出 = nghĩ ra; 想起 = nhớ ra; 写下 = viết lại, ghi lại.","e":[["我们终于想出了一个好办法。","wǒ men zhōng yú xiǎng chū le yí gè hǎo bàn fǎ","Cuối cùng chúng tôi đã nghĩ ra một cách hay."],["你想起她的名字了没有？","nǐ xiǎng qǐ tā de míng zi le méi yǒu","Bạn đã nhớ ra tên cô ấy chưa?"],["请在这儿写下您的电话。","qǐng zài zhè r xiě xià nín de diàn huà","Mời ông/bà ghi lại số điện thoại ở đây."]]},{"n":59,"c":["句子成分","补语","趋向补语2"],"z":"趋向补语的引申用法：表示动作行为的开始：动词+上/起来","t":"Nghĩa mở rộng: 上/起来 (bắt đầu)","d":"Động từ + 上/起来 = bắt đầu (và tiếp tục): 聊起来 = bắt đầu nói chuyện, 哭起来 = òa khóc. Tân ngữ đặt giữa 起 và 来.","e":[["饿了一天，我们终于吃上饭了。","è le yì tiān wǒ men zhōng yú chī shàng fàn le","Đói cả ngày, cuối cùng chúng tôi cũng được ăn cơm."],["儿子刚到家就玩上了电脑游戏。","ér zi gāng dào jiā jiù wán shàng le diàn nǎo yóu xì","Con trai vừa về đến nhà là đã chơi trò chơi điện tử."],["他们一见面就聊起来了。","tā men yí jiàn miàn jiù liáo qǐ lái le","Họ vừa gặp nhau là bắt đầu trò chuyện."],["妈妈一出门，孩子就哭起来了。","mā ma yì chū mén hái zi jiù kū qǐ lái le","Mẹ vừa ra khỏi nhà, đứa bé liền òa khóc."]]},{"n":60,"c":["句子成分","补语","趋向补语2"],"z":"趋向补语的引申用法：表示动作行为的持续：动词+下去/下来","t":"Nghĩa mở rộng: 下去/下来 (tiếp tục)","d":"下去 = tiếp tục từ giờ trở đi (tương lai). 下来 = duy trì từ trước đến giờ, hoặc trải qua cả quá trình.","e":[["虽然学习汉语不容易，但是我一定会坚持下去。","suī rán xué xí hàn yǔ bù róng yì dàn shì wǒ yí dìng huì jiān chí xià qù","Tuy học tiếng Hán không dễ, nhưng tôi nhất định sẽ kiên trì tiếp."],["在老师的帮助下，我一定可以学下去。","zài lǎo shī de bāng zhù xià wǒ yí dìng kě yǐ xué xià qù","Với sự giúp đỡ của thầy cô, tôi nhất định có thể học tiếp được."],["在过去的一年里，我把每天练习汉字的习惯坚持下来了。","zài guò qù de yì nián lǐ wǒ bǎ měi tiān liàn xí hàn zì de xí guàn jiān chí xià lái le","Trong một năm qua, tôi đã duy trì được thói quen luyện chữ Hán mỗi ngày."],["这三天玩下来太累了，我得好好休息休息。","zhè sān tiān wán xià lái tài lèi le wǒ děi hǎo hǎo xiū xi xiū xi","Chơi suốt ba ngày mệt quá, tôi phải nghỉ ngơi cho thật đã."]]},{"n":61,"c":["句子成分","补语","可能补语1"],"z":"动词+得/不+动词/形容词","t":"Bổ ngữ khả năng: động từ + 得/不 + bổ ngữ","d":"听得懂 = nghe hiểu được; 看不清楚 = nhìn không rõ. Hỏi: 听得懂吗？ hoặc 听得懂听不懂？","e":[["老师说的话你听得懂吗？","lǎo shī shuō de huà nǐ tīng de dǒng ma","Lời thầy giáo nói bạn có nghe hiểu không?"],["黑板上的字太小，我看不清楚。","hēi bǎn shàng de zì tài xiǎo wǒ kàn bù qīng chu","Chữ trên bảng nhỏ quá, tôi nhìn không rõ."]]},{"n":62,"c":["句子成分","补语","程度补语1"],"z":"形容词+得很","t":"Bổ ngữ mức độ: tính từ + 得很","d":"= rất…, …lắm (khẩu ngữ).","e":[["这里的环境好得很。","zhè lǐ de huán jìng hǎo de hěn","Môi trường ở đây tốt lắm."],["这儿从早到晚都有风，凉快得很。","zhè r cóng zǎo dào wǎn dōu yǒu fēng liáng kuai de hěn","Ở đây từ sáng đến tối đều có gió, mát lắm."]]},{"n":63,"c":["句子成分","补语","程度补语1"],"z":"形容词/动词+极了/坏了","t":"Bổ ngữ mức độ: 极了, 坏了","d":"Tính từ + 极了 = cực kỳ; 坏了 = …muốn chết, …rã rời (mức độ rất cao, thường là cảm giác khó chịu hoặc vui sướng).","e":[["看见考试成绩的时候，我高兴极了。","kàn jiàn kǎo shì chéng jì de shí hou wǒ gāo xìng jí le","Lúc nhìn thấy điểm thi, tôi vui cực kỳ."],["爬山回来，大家都累坏了。","pá shān huí lái dà jiā dōu lèi huài le","Leo núi về, mọi người đều mệt rã rời."]]},{"n":64,"c":["句子成分","补语","数量补语3"],"z":"表示动作结束到某个时间点的间隔时间","t":"Bổ ngữ thời lượng: khoảng cách từ khi kết thúc đến nay","d":"Động từ (không kéo dài) + khoảng thời gian + 了 = đã…được bao lâu (từ lúc hành động xảy ra).","e":[["开学已经两个星期了。","kāi xué yǐ jīng liǎng gè xīng qī le","Khai giảng đã được hai tuần rồi."],["这件事已经过去五年了。","zhè jiàn shì yǐ jīng guò qù wǔ nián le","Chuyện này đã qua năm năm rồi."]]},{"n":65,"c":["句子的类型","句类","疑问句"],"z":"“怎样+动词”的特指问句","t":"Câu hỏi 怎样 + động từ","d":"Hỏi cách thức: làm thế nào, bằng cách nào.","e":[["怎样才能学好汉语呢？","zěn yàng cái néng xué hǎo hàn yǔ ne","Làm thế nào mới học giỏi tiếng Hán được nhỉ?"],["中国人是怎样过新年的？","zhōng guó rén shì zěn yàng guò xīn nián de","Người Trung Quốc đón năm mới như thế nào?"]]},{"n":66,"c":["句子的类型","句类","反问句1"],"z":"用反问句表示强调：不是……吗？","t":"Câu hỏi tu từ: 不是……吗？","d":"= chẳng phải…sao? (khẳng định điều mình nghĩ, có ý ngạc nhiên).","e":[["你不是写完作业了吗？","nǐ bú shì xiě wán zuò yè le ma","Chẳng phải bạn làm xong bài tập rồi sao?"],["考试不是下个星期一吗？","kǎo shì bú shì xià gè xīng qī yī ma","Chẳng phải thứ Hai tuần sau mới thi sao?"]]},{"n":67,"c":["句子的类型","特殊句型","“把”字句1"],"z":"主语+把+宾语+动词+在/到+处所","t":"Câu chữ 把: 把 + tân ngữ + động từ + 在/到 + nơi chốn","d":"Đặt/chuyển vật đến đâu. Với 在/到 + nơi chốn sau động từ, gần như bắt buộc dùng câu 把.","e":[["你把箱子放在这儿吧。","nǐ bǎ xiāng zi fàng zài zhè r ba","Bạn để cái vali ở đây nhé."],["我们把桌子搬到教室外边了。","wǒ men bǎ zhuō zi bān dào jiào shì wài biān le","Chúng tôi đã chuyển bàn ra ngoài lớp học."]]},{"n":68,"c":["句子的类型","特殊句型","“把”字句1"],"z":"主语+把+宾语1+动词（+给）+宾语2","t":"Câu chữ 把: 把 + tân ngữ 1 + động từ (+给) + tân ngữ 2","d":"Đưa/tặng/cho mượn vật gì cho ai.","e":[["我们把礼物送给老师了。","wǒ men bǎ lǐ wù sòng gěi lǎo shī le","Chúng tôi đã tặng quà cho thầy giáo."],["他把那本书借给我了。","tā bǎ nà běn shū jiè gěi wǒ le","Anh ấy đã cho tôi mượn quyển sách đó."]]},{"n":69,"c":["句子的类型","特殊句型","“把”字句1"],"z":"主语+把+宾语+动词+结果补语/趋向补语/状态补语","t":"Câu chữ 把: 把 + tân ngữ + động từ + bổ ngữ","d":"Động từ phía sau không được đứng một mình, phải có bổ ngữ kết quả/xu hướng/trạng thái hoặc 了. Phủ định, động từ năng nguyện đặt trước 把.","e":[["我已经把晚饭准备好了。","wǒ yǐ jīng bǎ wǎn fàn zhǔn bèi hǎo le","Tôi đã chuẩn bị xong bữa tối rồi."],["咱们把这些桌子搬进去吧。","zán men bǎ zhè xiē zhuō zi bān jìn qù ba","Chúng ta chuyển mấy cái bàn này vào trong đi."],["妈妈把衣服洗得干干净净。","mā ma bǎ yī fu xǐ de gān gān jìng jìng","Mẹ giặt quần áo sạch sành sanh."]]},{"n":70,"c":["句子的类型","特殊句型","被动句1"],"z":"主语+被+宾语+动词+其他成分","t":"Câu bị động: 被 + người làm + động từ + thành phần khác","d":"Chủ ngữ (vật chịu tác động) + 被 + người làm + động từ + bổ ngữ/了. Thường mang sắc thái không mong muốn.","e":[["我的词典被朋友借走了。","wǒ de cí diǎn bèi péng you jiè zǒu le","Từ điển của tôi bị bạn mượn đi rồi."],["冰箱里的水果被谁吃了？","bīng xiāng lǐ de shuǐ guǒ bèi shuí chī le","Hoa quả trong tủ lạnh bị ai ăn mất rồi?"]]},{"n":71,"c":["句子的类型","特殊句型","被动句1"],"z":"主语+被+动词+其他成分","t":"Câu bị động: 被 + động từ (không nêu người làm)","d":"Có thể lược người làm sau 被 (riêng 叫, 让 thì không lược được).","e":[["桌子上的作业被拿走了。","zhuō zi shàng de zuò yè bèi ná zǒu le","Bài tập trên bàn bị lấy đi rồi."],["病人已经被送到医院了。","bìng rén yǐ jīng bèi sòng dào yī yuàn le","Bệnh nhân đã được đưa đến bệnh viện rồi."]]},{"n":72,"c":["句子的类型","特殊句型","连动句2"],"z":"“着”表示动作的伴随：动词1+着+动词2","t":"Câu liên động với 着: động từ 1 + 着 + động từ 2","d":"Động từ 1 + 着 chỉ cách thức đi kèm của động từ 2: 笑着回答 = cười trả lời.","e":[["老师总是笑着回答大家的问题。","lǎo shī zǒng shì xiào zhe huí dá dà jiā de wèn tí","Thầy giáo lúc nào cũng mỉm cười trả lời câu hỏi của mọi người."],["我喜欢听着音乐做运动。","wǒ xǐ huan tīng zhe yīn yuè zuò yùn dòng","Tôi thích vừa nghe nhạc vừa tập thể dục."]]},{"n":73,"c":["句子的类型","特殊句型","比较句2"],"z":"A比B+更/还+形容词","t":"Câu so sánh: A 比 B + 更/还 + tính từ","d":"= A còn…hơn B (B vốn đã …).","e":[["她的汉语比我更好。","tā de hàn yǔ bǐ wǒ gèng hǎo","Tiếng Hán của cô ấy còn giỏi hơn tôi."],["今天比昨天还冷。","jīn tiān bǐ zuó tiān hái lěng","Hôm nay còn lạnh hơn hôm qua."]]},{"n":74,"c":["句子的类型","特殊句型","比较句2"],"z":"A跟B一样","t":"Câu so sánh: A 跟 B 一样","d":"= A giống B. Phủ định: A 跟 B 不一样.","e":[["我的爱好跟他一样。","wǒ de ài hào gēn tā yí yàng","Sở thích của tôi giống anh ấy."],["他买的新手机跟我的一样。","tā mǎi de xīn shǒu jī gēn wǒ de yí yàng","Chiếc điện thoại mới anh ấy mua giống của tôi."]]},{"n":75,"c":["句子的类型","特殊句型","比较句2"],"z":"A跟B一样+形容词","t":"Câu so sánh: A 跟 B 一样 + tính từ","d":"= A … bằng B (ngang nhau).","e":[["坐地铁跟坐公交车一样方便。","zuò dì tiě gēn zuò gōng jiāo chē yí yàng fāng biàn","Đi tàu điện ngầm cũng tiện như đi xe buýt."],["这个房间跟那个房间一样大。","zhè ge fáng jiān gēn nà ge fáng jiān yí yàng dà","Phòng này rộng bằng phòng kia."]]},{"n":76,"c":["句子的类型","特殊句型","比较句2"],"z":"A不比B+形容词","t":"Câu so sánh: A 不比 B + tính từ","d":"= A không hơn B (có thể bằng hoặc kém), thường dùng để phản bác ý kiến người khác.","e":[["这张画不比那张好看。","zhè zhāng huà bù bǐ nà zhāng hǎo kàn","Bức tranh này không đẹp hơn bức kia."],["我的汉语水平不比他高。","wǒ de hàn yǔ shuǐ píng bù bǐ tā gāo","Trình độ tiếng Hán của tôi không cao hơn anh ấy."]]},{"n":77,"c":["句子的类型","特殊句型","比较句2"],"z":"A比B+多/少/早/晚+动词+数量短语","t":"Câu so sánh: A 比 B + 多/少/早/晚 + động từ + số lượng","d":"早到十分钟 = đến sớm hơn 10 phút; 多吃了三个 = ăn nhiều hơn 3 cái.","e":[["我比他早到十分钟。","wǒ bǐ tā zǎo dào shí fēn zhōng","Tôi đến sớm hơn anh ấy mười phút."],["哥哥比弟弟多吃了三个饺子。","gē ge bǐ dì di duō chī le sān gè jiǎo zi","Anh trai ăn nhiều hơn em trai ba cái sủi cảo."]]},{"n":78,"c":["句子的类型","特殊句型","存现句3"],"z":"表示出现：处所词+动词+趋向补语/结果补语+动态助词（了）+数量短语+人/物","t":"Câu tồn hiện: xuất hiện","d":"Nơi chốn + động từ + bổ ngữ (+了) + số lượng + người/vật: ở đâu xuất hiện ai/cái gì. Người/vật đứng SAU động từ và là thông tin mới.","e":[["前边开过来一辆出租车。","qián biān kāi guò lái yí liàng chū zū chē","Phía trước có một chiếc taxi chạy tới."],["楼上搬来了一家人。","lóu shàng bān lái le yì jiā rén","Trên lầu có một gia đình chuyển đến."],["校门外走进来几个学生。","xiào mén wài zǒu jìn lái jǐ gè xué shēng","Ngoài cổng trường có mấy học sinh đi vào."]]},{"n":79,"c":["句子的类型","特殊句型","存现句3"],"z":"表示消失：处所词+动词+结果补语+动态助词（了）+数量短语+人/物","t":"Câu tồn hiện: biến mất","d":"Nơi chốn + động từ + bổ ngữ kết quả (+了) + số lượng + người/vật: ở đâu mất đi ai/cái gì.","e":[["树上飞走了三只小鸟。","shù shàng fēi zǒu le sān zhī xiǎo niǎo","Trên cây bay đi mất ba chú chim nhỏ."],["他家里跑丢了一只羊。","tā jiā lǐ pǎo diū le yì zhī yáng","Nhà anh ấy bị sổng mất một con cừu."]]},{"n":80,"c":["句子的类型","特殊句型","“是……的”句2"],"z":"强调说话人的看法或态度","t":"Câu 是……的: nhấn mạnh quan điểm, thái độ","d":"是 + nhận xét + 的: khẳng định, nhấn mạnh quan điểm của người nói.","e":[["这个问题其实是很简单的。","zhè ge wèn tí qí shí shì hěn jiǎn dān de","Câu hỏi này thực ra rất đơn giản."],["多写多练对学习汉字是很有帮助的。","duō xiě duō liàn duì xué xí hàn zì shì hěn yǒu bāng zhù de","Viết nhiều luyện nhiều rất có ích cho việc học chữ Hán."]]},{"n":81,"c":["句子的类型","特殊句型","重动句"],"z":"主语+动词+宾语+动词+补语","t":"Câu lặp động từ","d":"Động từ + tân ngữ + lặp lại động từ + bổ ngữ: 打篮球打了一个下午. Vì sau tân ngữ không thể gắn trực tiếp bổ ngữ.","e":[["我们昨天打篮球打了一个下午。","wǒ men zuó tiān dǎ lán qiú dǎ le yí gè xià wǔ","Hôm qua chúng tôi chơi bóng rổ suốt cả buổi chiều."],["你今天上课上得怎么样？","nǐ jīn tiān shàng kè shàng de zěn me yàng","Hôm nay bạn học trên lớp thế nào?"]]},{"n":82,"c":["句子的类型","复句","承接复句"],"z":"先……，再/然后……","t":"Câu phức nối tiếp: 先……，再/然后……","d":"= Trước tiên…, rồi/sau đó….","e":[["你先去买门票，再来这里找我。","nǐ xiān qù mǎi mén piào zài lái zhè lǐ zhǎo wǒ","Bạn đi mua vé vào cửa trước, rồi đến đây tìm tôi."],["我想先吃饭，然后回房间休息。","wǒ xiǎng xiān chī fàn rán hòu huí fáng jiān xiū xi","Tôi muốn ăn cơm trước, sau đó về phòng nghỉ ngơi."]]},{"n":83,"c":["句子的类型","复句","选择复句"],"z":"或者……，或者……","t":"Câu phức lựa chọn: 或者……，或者……","d":"= Hoặc…, hoặc… (câu trần thuật).","e":[["每周末，我们或者踢足球，或者打篮球。","měi zhōu mò wǒ men huò zhě tī zú qiú huò zhě dǎ lán qiú","Cuối tuần nào chúng tôi cũng hoặc đá bóng, hoặc chơi bóng rổ."],["春节的时候，人们或者回家过节，或者出门旅游。","chūn jié de shí hou rén men huò zhě huí jiā guò jié huò zhě chū mén lǚ yóu","Dịp Tết, mọi người hoặc về nhà ăn Tết, hoặc đi du lịch."]]},{"n":84,"c":["句子的类型","复句","并列复句"],"z":"一会儿……，一会儿……","t":"Câu phức đẳng lập: 一会儿……，一会儿……","d":"= Lúc thì…, lúc thì… (thay đổi liên tục).","e":[["他一会儿进来，一会儿出去，忙得很。","tā yí huì r jìn lái yí huì r chū qù máng de hěn","Anh ấy lúc thì đi vào, lúc thì đi ra, bận lắm."],["最近的天气一会儿冷，一会儿热。","zuì jìn de tiān qì yí huì r lěng yí huì r rè","Thời tiết dạo này lúc lạnh lúc nóng."]]},{"n":85,"c":["句子的类型","复句","并列复句"],"z":"又……，又……","t":"Câu phức đẳng lập: 又……，又……","d":"= Vừa…vừa… (hai tính chất cùng tồn tại).","e":[["这件衣服又便宜又好看。","zhè jiàn yī fu yòu pián yi yòu hǎo kàn","Bộ quần áo này vừa rẻ vừa đẹp."],["那个又高又漂亮的女孩儿是谁？","nà ge yòu gāo yòu piào liang de nǚ hái r shì shuí","Cô gái vừa cao vừa xinh kia là ai?"]]},{"n":86,"c":["句子的类型","复句","并列复句"],"z":"一边……，一边……","t":"Câu phức đẳng lập: 一边……，一边……","d":"= Vừa…vừa… (hai hành động cùng lúc).","e":[["他一边工作，一边学习中文。","tā yì biān gōng zuò yì biān xué xí zhōng wén","Anh ấy vừa làm việc vừa học tiếng Trung."],["我喜欢一边跑步，一边听音乐。","wǒ xǐ huan yì biān pǎo bù yì biān tīng yīn yuè","Tôi thích vừa chạy bộ vừa nghe nhạc."]]},{"n":87,"c":["句子的类型","复句","递进复句"],"z":"不但……，而且……","t":"Câu phức tăng tiến: 不但……，而且……","d":"= Không những…mà còn…. Hai vế cùng chủ ngữ: chủ ngữ đứng trước 不但; khác chủ ngữ: 不但 đứng trước chủ ngữ.","e":[["不但我学习中文，而且我的弟弟也学习中文。","bú dàn wǒ xué xí zhōng wén ér qiě wǒ de dì di yě xué xí zhōng wén","Không những tôi học tiếng Trung mà em trai tôi cũng học tiếng Trung."],["我哥哥不但会打篮球，而且打得很好。","wǒ gē ge bú dàn huì dǎ lán qiú ér qiě dǎ de hěn hǎo","Anh trai tôi không những biết chơi bóng rổ mà còn chơi rất giỏi."]]},{"n":88,"c":["句子的类型","复句","转折复句"],"z":"虽然……，可是……","t":"Câu phức chuyển ngoặt: 虽然……，可是……","d":"= Tuy…nhưng….","e":[["房间虽然不大，可是很干净。","fáng jiān suī rán bú dà kě shì hěn gān jìng","Căn phòng tuy không lớn nhưng rất sạch sẽ."],["虽然天气很冷，可是他还是坚持每天锻炼。","suī rán tiān qì hěn lěng kě shì tā hái shì jiān chí měi tiān duàn liàn","Tuy thời tiết rất lạnh nhưng anh ấy vẫn kiên trì tập luyện mỗi ngày."]]},{"n":89,"c":["句子的类型","复句","假设复句"],"z":"如果……，就……","t":"Câu phức giả thiết: 如果……，就……","d":"= Nếu…thì….","e":[["如果明天不下雨，我们就去爬山。","rú guǒ míng tiān bú xià yǔ wǒ men jiù qù pá shān","Nếu ngày mai không mưa thì chúng ta đi leo núi."],["如果你需要帮忙，就给我打电话。","rú guǒ nǐ xū yào bāng máng jiù gěi wǒ dǎ diàn huà","Nếu bạn cần giúp đỡ thì gọi điện cho tôi."]]},{"n":90,"c":["句子的类型","复句","假设复句"],"z":"……的话，就……","t":"Câu phức giả thiết: ……的话，就……","d":"= Nếu…thì… (khẩu ngữ).","e":[["你有时间的话，就一起去吧。","nǐ yǒu shí jiān de huà jiù yì qǐ qù ba","Nếu bạn có thời gian thì cùng đi luôn nhé."],["你觉得满意的话，咱们就买。","nǐ jué de mǎn yì de huà zán men jiù mǎi","Nếu bạn thấy hài lòng thì chúng ta mua."]]},{"n":91,"c":["句子的类型","复句","条件复句"],"z":"只有……，才……","t":"Câu phức điều kiện: 只有……，才……","d":"= Chỉ có…mới… (điều kiện duy nhất, bắt buộc).","e":[["只有努力学习，才能得到好成绩。","zhǐ yǒu nǔ lì xué xí cái néng dé dào hǎo chéng jì","Chỉ có chăm chỉ học tập mới đạt được thành tích tốt."],["只有多听、多说、多看，你的中文水平才能提高。","zhǐ yǒu duō tīng duō shuō duō kàn nǐ de zhōng wén shuǐ píng cái néng tí gāo","Chỉ có nghe nhiều, nói nhiều, đọc nhiều thì trình độ tiếng Trung của bạn mới nâng cao được."]]},{"n":92,"c":["句子的类型","复句","条件复句"],"z":"只要……，就……","t":"Câu phức điều kiện: 只要……，就……","d":"= Chỉ cần…là… (điều kiện đủ). Phân biệt: 只有…才… (bắt buộc), 只要…就… (đủ).","e":[["只要你坚持学习，就一定能学好。","zhǐ yào nǐ jiān chí xué xí jiù yí dìng néng xué hǎo","Chỉ cần bạn kiên trì học thì nhất định sẽ học giỏi."],["只要你同意，我们就这么决定了。","zhǐ yào nǐ tóng yì wǒ men jiù zhè me jué dìng le","Chỉ cần bạn đồng ý thì chúng ta quyết định như vậy."]]},{"n":93,"c":["句子的类型","复句","目的复句"],"z":"为了……，……","t":"Câu phức mục đích: 为了……，……","d":"= Để…, …. Vế 为了 nêu mục đích, thường đứng trước.","e":[["为了考上大学，她每天努力学习。","wèi le kǎo shàng dà xué tā měi tiān nǔ lì xué xí","Để thi đỗ đại học, ngày nào cô ấy cũng chăm chỉ học tập."],["为了早点儿到家，我打算坐飞机。","wèi le zǎo diǎn r dào jiā wǒ dǎ suàn zuò fēi jī","Để về nhà sớm một chút, tôi định đi máy bay."]]},{"n":94,"c":["句子的类型","复句","紧缩复句"],"z":"……了……（就）……","t":"Câu rút gọn: ……了……(就)……","d":"Động từ 1 + 了 + (就) + động từ 2 = làm xong việc 1 thì (sẽ) làm việc 2.","e":[["他吃了药就好多了。","tā chī le yào jiù hǎo duō le","Anh ấy uống thuốc xong là đỡ hơn nhiều."],["我打算下了课就去图书馆。","wǒ dǎ suàn xià le kè jiù qù tú shū guǎn","Tôi định tan học xong là đi thư viện."]]},{"n":95,"c":["特殊表达法","数的表达法",""],"z":"概数表达法2：用“大概”表示概数","t":"Số ước lượng với 大概","d":"大概 + số lượng = khoảng, chừng.","e":[["你大概多长时间能到？","nǐ dà gài duō cháng shí jiān néng dào","Bạn khoảng bao lâu nữa thì đến?"],["这些水果大概五十块钱。","zhè xiē shuǐ guǒ dà gài wǔ shí kuài qián","Chỗ hoa quả này khoảng năm mươi đồng."]]},{"n":96,"c":["特殊表达法","数的表达法",""],"z":"概数表达法2：相邻数词连用表示概数","t":"Số ước lượng: hai số liền nhau","d":"七八个 = bảy tám cái; 十五六 = mười lăm mười sáu. Không dùng với cặp 9 và 10.","e":[["教室里来了七八个学生。","jiào shì lǐ lái le qī bā gè xué shēng","Trong lớp có bảy tám học sinh đến."],["从我家到学校，走路需要十五六分钟。","cóng wǒ jiā dào xué xiào zǒu lù xū yào shí wǔ liù fēn zhōng","Từ nhà tôi đến trường đi bộ mất mười lăm mười sáu phút."]]}],"4":[{"n":1,"c":["词类","动词","能愿动词"],"z":"敢","t":"Động từ năng nguyện 敢","d":"敢 + động từ = dám làm gì. Phủ định: 不敢.","e":[["我刚学会开车，不敢开得很快。","wǒ gāng xué huì kāi chē bù gǎn kāi de hěn kuài","Tôi mới học lái xe, không dám lái nhanh."],["你敢不敢跟我比一比，谁的力气大？","nǐ gǎn bu gǎn gēn wǒ bǐ yi bǐ shuí de lì qi dà","Bạn có dám thi với tôi một trận xem ai khỏe hơn không?"]]},{"n":2,"c":["词类","代词","指示代词"],"z":"各、各位、各种、任何、此","t":"Đại từ chỉ thị 各, 各位, 各种, 任何, 此","d":"各 = mỗi, các (各地 các nơi; 各有各的 = mỗi người một…); 各位 = các vị (lịch sự); 各种 = các loại; 任何 = bất kỳ (hay đi với 都/也); 此 = này, đây (văn viết).","e":[["对于这个问题，同学们各有各的看法。","duì yú zhè ge wèn tí tóng xué men gè yǒu gè de kàn fǎ","Về vấn đề này, các bạn học sinh mỗi người có một cách nhìn riêng."],["节日期间，各地举行了丰富的庆祝活动。","jié rì qī jiān gè dì jǔ xíng le fēng fù de qìng zhù huó dòng","Trong dịp lễ, các nơi tổ chức nhiều hoạt động chúc mừng phong phú."],["各位同学，请大家安静一下。","gè wèi tóng xué qǐng dà jiā ān jìng yí xià","Các bạn học sinh, mời mọi người trật tự một chút."],["欢迎各位报名参加这次运动会。","huān yíng gè wèi bào míng cān jiā zhè cì yùn dòng huì","Hoan nghênh các vị đăng ký tham gia đại hội thể thao lần này."],["南方各种花都开了，可是北方还比较冷。","nán fāng gè zhǒng huā dōu kāi le kě shì běi fāng hái bǐ jiào lěng","Ở miền Nam các loại hoa đều nở rồi, nhưng miền Bắc vẫn còn khá lạnh."],["商场、超市总是通过各种方式吸引顾客。","shāng chǎng chāo shì zǒng shì tōng guò gè zhǒng fāng shì xī yǐn gù kè","Trung tâm thương mại, siêu thị luôn dùng đủ mọi cách để thu hút khách hàng."],["你遇到任何困难都可以联系我。","nǐ yù dào rèn hé kùn nán dōu kě yǐ lián xì wǒ","Bạn gặp bất kỳ khó khăn nào cũng có thể liên hệ với tôi."],["在中国，几乎任何一家商店都可以使用手机支付。","zài zhōng guó jī hū rèn hé yì jiā shāng diàn dōu kě yǐ shǐ yòng shǒu jī zhī fù","Ở Trung Quốc, hầu như bất kỳ cửa hàng nào cũng có thể thanh toán bằng điện thoại."],["此处不能扔垃圾，请扔到垃圾桶里。","cǐ chù bù néng rēng lā jī qǐng rēng dào lā jī tǒng lǐ","Nơi này không được vứt rác, xin vứt vào thùng rác."],["对于此事，你的父母有什么意见？","duì yú cǐ shì nǐ de fù mǔ yǒu shén me yì jiàn","Về việc này, bố mẹ bạn có ý kiến gì không?"]]},{"n":3,"c":["词类","量词","名量词"],"z":"专用名量词：打、袋、棵、台、幅","t":"Lượng từ chuyên dùng 打, 袋, 棵, 台, 幅","d":"打 tá (12 cái), 袋 túi/gói, 棵 cây (cây cối), 台 chiếc/cỗ (máy móc), 幅 bức (tranh, chữ).","e":[["昨晚老张买了一打啤酒。","zuó wǎn lǎo zhāng mǎi le yì dǎ pí jiǔ","Tối qua lão Trương mua một tá bia."],["我买了一打鸡蛋，准备做蛋糕。","wǒ mǎi le yì dǎ jī dàn zhǔn bèi zuò dàn gāo","Tôi mua một tá trứng gà, chuẩn bị làm bánh kem."],["我这儿有一袋方便面，你要不要吃？","wǒ zhè r yǒu yí dài fāng biàn miàn nǐ yào bu yào chī","Chỗ tôi có một gói mì ăn liền, bạn có ăn không?"],["妈妈从市场买回来好几袋水果。","mā ma cóng shì chǎng mǎi huí lái hǎo jǐ dài shuǐ guǒ","Mẹ mua từ chợ về mấy túi hoa quả."],["我家院子里种着两棵苹果树。","wǒ jiā yuàn zi lǐ zhòng zhe liǎng kē píng guǒ shù","Trong sân nhà tôi trồng hai cây táo."],["小猫爬上了路边的一棵大树。","xiǎo māo pá shàng le lù biān de yì kē dà shù","Con mèo nhỏ trèo lên một cái cây lớn bên đường."],["这台空调太旧了，没办法修。","zhè tái kōng tiáo tài jiù le méi bàn fǎ xiū","Chiếc điều hòa này cũ quá rồi, không có cách nào sửa."],["搬家时，我把家里那台冰箱卖了。","bān jiā shí wǒ bǎ jiā lǐ nà tái bīng xiāng mài le","Lúc chuyển nhà, tôi đã bán chiếc tủ lạnh trong nhà."],["您能介绍一下这幅画吗？","nín néng jiè shào yí xià zhè fú huà ma","Ông/bà có thể giới thiệu một chút về bức tranh này không?"],["张老师，我想请您给我写一幅字。","zhāng lǎo shī wǒ xiǎng qǐng nín gěi wǒ xiě yì fú zì","Thầy Trương, em muốn nhờ thầy viết cho em một bức thư pháp."]]},{"n":4,"c":["词类","量词","名量词"],"z":"借用名量词：脸、手、盒、屋子、桌子","t":"Lượng từ mượn 脸, 手, 盒, 屋子, 桌子","d":"一 + danh từ (脸, 身, 屋子, 桌子…) = đầy, khắp cả…: 一脸兴奋 = mặt mày hớn hở, 一屋子书 = cả phòng toàn sách. 一手好字 = viết chữ đẹp. 盒 = hộp.","e":[["她拿着礼物，一脸兴奋地跑了进来。","tā ná zhe lǐ wù yì liǎn xīng fèn de pǎo le jìn lái","Cô ấy cầm quà, mặt mày hớn hở chạy vào."],["小明见到了自己喜欢的作家，满脸高兴。","xiǎo míng jiàn dào le zì jǐ xǐ huan de zuò jiā mǎn liǎn gāo xìng","Tiểu Minh gặp được nhà văn mình yêu thích, mặt rạng rỡ niềm vui."],["我不知道从哪儿弄了一手油。","wǒ bù zhī dao cóng nǎ r nòng le yì shǒu yóu","Tôi không biết dính dầu từ đâu mà đầy cả tay."],["他从小练习书法，写得一手好字。","tā cóng xiǎo liàn xí shū fǎ xiě de yì shǒu hǎo zì","Anh ấy luyện thư pháp từ nhỏ, viết được một tay chữ đẹp."],["我从国外买回来一盒巧克力。","wǒ cóng guó wài mǎi huí lái yì hé qiǎo kè lì","Tôi mua từ nước ngoài về một hộp sô-cô-la."],["老师让我们准备一盒画笔。","lǎo shī ràng wǒ men zhǔn bèi yì hé huà bǐ","Thầy giáo bảo chúng tôi chuẩn bị một hộp bút vẽ."],["我非常喜欢读书，家里有一屋子的书。","wǒ fēi cháng xǐ huan dú shū jiā lǐ yǒu yì wū zi de shū","Tôi rất thích đọc sách, trong nhà có cả một phòng sách."],["我有一屋子的衣服，你随便选。","wǒ yǒu yì wū zi de yī fu nǐ suí biàn xuǎn","Tôi có cả một phòng quần áo, bạn cứ thoải mái chọn."],["听到这个消息，一桌子的人都很开心。","tīng dào zhè ge xiāo xī yì zhuō zi de rén dōu hěn kāi xīn","Nghe tin này, cả bàn ai cũng rất vui."],["我每次回家，父母都会准备一桌子饭菜。","wǒ měi cì huí jiā fù mǔ dōu huì zhǔn bèi yì zhuō zi fàn cài","Mỗi lần tôi về nhà, bố mẹ đều chuẩn bị cả một bàn đầy thức ăn."]]},{"n":5,"c":["词类","量词","动量词"],"z":"场、顿、趟","t":"Động lượng từ 场, 顿, 趟","d":"场 = trận, buổi (biểu diễn, thi đấu, hoạt động, mưa); 顿 = bữa (ăn), trận (mắng, đánh); 趟 = chuyến (đi và về).","e":[["大卫参加了一场文化活动，体验了美食和音乐。","dà wèi cān jiā le yì chǎng wén huà huó dòng tǐ yàn le měi shí hé yīn yuè","David đã tham gia một buổi hoạt động văn hóa, trải nghiệm ẩm thực và âm nhạc."],["同学们都想在中国观看一场京剧演出。","tóng xué men dōu xiǎng zài zhōng guó guān kàn yì chǎng jīng jù yǎn chū","Các bạn học sinh đều muốn được xem một buổi biểu diễn Kinh kịch ở Trung Quốc."],["周末咱们去饭馆好好吃一顿，怎么样？","zhōu mò zán men qù fàn guǎn hǎo hǎo chī yí dùn zěn me yàng","Cuối tuần chúng ta đến nhà hàng ăn một bữa thật ngon, thế nào?"],["中秋节我们一起吃了一顿饭。","zhōng qiū jié wǒ men yì qǐ chī le yí dùn fàn","Tết Trung thu chúng tôi đã cùng nhau ăn một bữa cơm."],["我假期打算回一趟家，看看父母。","wǒ jià qī dǎ suàn huí yí tàng jiā kàn kàn fù mǔ","Kỳ nghỉ tôi định về nhà một chuyến, thăm bố mẹ."],["我刚才去了一趟办公室，没看见王老师。","wǒ gāng cái qù le yí tàng bàn gōng shì méi kàn jiàn wáng lǎo shī","Vừa nãy tôi đã đến văn phòng một chuyến, không thấy thầy Vương."]]},{"n":6,"c":["词类","副词","程度副词"],"z":"十分、更加、稍、稍微、尤其、多么","t":"Phó từ mức độ 十分, 更加, 稍, 稍微, 尤其, 多么","d":"十分 = vô cùng, hết sức; 更加 = càng thêm; 稍/稍微 = hơi, một chút (thường đi với 一点儿/一些/一下); 尤其 = nhất là, đặc biệt là; 多么 = biết bao.","e":[["她十分激动地对我们表示感谢。","tā shí fēn jī dòng de duì wǒ men biǎo shì gǎn xiè","Cô ấy vô cùng xúc động bày tỏ lòng cảm ơn với chúng tôi."],["那位导游对游客十分热情。","nà wèi dǎo yóu duì yóu kè shí fēn rè qíng","Người hướng dẫn viên du lịch đó vô cùng nhiệt tình với du khách."],["随着互联网的发展，网上购物变得更加方便了。","suí zhe hù lián wǎng de fā zhǎn wǎng shàng gòu wù biàn de gèng jiā fāng biàn le","Cùng với sự phát triển của Internet, mua sắm trên mạng trở nên thuận tiện hơn nữa."],["读完这本书，他对中国历史更加感兴趣了。","dú wán zhè běn shū tā duì zhōng guó lì shǐ gèng jiā gǎn xìng qù le","Đọc xong quyển sách này, anh ấy càng thêm hứng thú với lịch sử Trung Quốc."],["请您在这儿稍等一下，王经理马上就到。","qǐng nín zài zhè r shāo děng yí xià wáng jīng lǐ mǎ shàng jiù dào","Mời ông/bà đợi ở đây một chút, giám đốc Vương sẽ đến ngay."],["对于这个词，两本词典的解释稍有不同。","duì yú zhè ge cí liǎng běn cí diǎn de jiě shì shāo yǒu bù tóng","Về từ này, hai cuốn từ điển giải thích hơi khác nhau."],["如果裙子的颜色稍微浅一点儿，那就更好了。","rú guǒ qún zi de yán sè shāo wēi qiǎn yì diǎn r nà jiù gèng hǎo le","Nếu màu của chiếc váy nhạt hơn một chút thì càng tốt."],["你能不能把字写得稍微大一些？","nǐ néng bu néng bǎ zì xiě de shāo wēi dà yì xiē","Bạn có thể viết chữ to hơn một chút không?"],["人与人之间，尤其是父母和孩子之间，相互理解是很重要的。","rén yǔ rén zhī jiān yóu qí shì fù mǔ hé hái zi zhī jiān xiāng hù lǐ jiě shì hěn zhòng yào de","Giữa người với người, nhất là giữa bố mẹ và con cái, thấu hiểu lẫn nhau là rất quan trọng."],["刚开始，我对这里的生活很不适应，尤其不习惯吃中国菜。","gāng kāi shǐ wǒ duì zhè lǐ de shēng huó hěn bú shì yìng yóu qí bù xí guàn chī zhōng guó cài","Lúc mới đầu, tôi rất không thích nghi với cuộc sống ở đây, nhất là không quen ăn món Trung Quốc."],["你听，她唱得多么好听啊！","nǐ tīng tā chàng de duō me hǎo tīng a","Bạn nghe xem, cô ấy hát hay biết bao!"],["成为母亲以后，我才明白教育孩子有多么不容易。","chéng wéi mǔ qīn yǐ hòu wǒ cái míng bai jiào yù hái zi yǒu duō me bù róng yì","Trở thành mẹ rồi, tôi mới hiểu dạy con không dễ dàng biết bao."]]},{"n":7,"c":["词类","副词","范围副词"],"z":"共、全、光、仅、仅仅、至少","t":"Phó từ phạm vi 共, 全, 光, 仅, 仅仅, 至少","d":"共 = tổng cộng, cùng (văn viết); 全 = toàn bộ, hết; 光 = chỉ, riêng (khẩu ngữ); 仅/仅仅 = chỉ, vẻn vẹn; 至少 = ít nhất.","e":[["上一年大学，学费和生活费共需多少钱？","shàng yì nián dà xué xué fèi hé shēng huó fèi gòng xū duō shǎo qián","Học đại học một năm, học phí và sinh hoạt phí tổng cộng cần bao nhiêu tiền?"],["中国人习惯一家人共吃一桌菜。","zhōng guó rén xí guàn yì jiā rén gòng chī yì zhuō cài","Người Trung Quốc có thói quen cả nhà cùng ăn chung một mâm."],["昨天学习的生词和语法我已经全记住了。","zuó tiān xué xí de shēng cí hé yǔ fǎ wǒ yǐ jīng quán jì zhù le","Từ mới và ngữ pháp học hôm qua tôi đã nhớ hết rồi."],["全班同学都报名参加了这次的运动会。","quán bān tóng xué dōu bào míng cān jiā le zhè cì de yùn dòng huì","Cả lớp đều đăng ký tham gia đại hội thể thao lần này."],["光这一间教室，他就打扫了一整天。","guāng zhè yì jiān jiào shì tā jiù dǎ sǎo le yì zhěng tiān","Riêng một phòng học này thôi mà anh ấy đã dọn cả một ngày."],["你不能光练口语，不练汉字，这样你的中文水平很难提高。","nǐ bù néng guāng liàn kǒu yǔ bú liàn hàn zì zhè yàng nǐ de zhōng wén shuǐ píng hěn nán tí gāo","Bạn không thể chỉ luyện khẩu ngữ mà không luyện chữ Hán, như vậy trình độ tiếng Trung của bạn rất khó nâng cao."],["这个公园平时不开，仅在周末开放。","zhè ge gōng yuán píng shí bù kāi jǐn zài zhōu mò kāi fàng","Công viên này ngày thường không mở, chỉ mở cửa vào cuối tuần."],["他仅用一年多的时间就学完了高中所有的课程。","tā jǐn yòng yì nián duō de shí jiān jiù xué wán le gāo zhōng suǒ yǒu de kè chéng","Anh ấy chỉ dùng hơn một năm đã học xong toàn bộ chương trình cấp ba."],["她仅仅去过一次，就深深地爱上了那里。","tā jǐn jǐn qù guò yí cì jiù shēn shēn de ài shàng le nà lǐ","Cô ấy chỉ mới đến đó một lần mà đã yêu say đắm nơi ấy."],["你想学好中文，仅仅有想法是不够的，必须努力学习。","nǐ xiǎng xué hǎo zhōng wén jǐn jǐn yǒu xiǎng fǎ shì bú gòu de bì xū nǔ lì xué xí","Bạn muốn học giỏi tiếng Trung, chỉ có ý tưởng thôi là không đủ, phải nỗ lực học tập."],["你们两个人一起去，遇到问题至少能商量一下。","nǐ men liǎng gè rén yì qǐ qù yù dào wèn tí zhì shǎo néng shāng liáng yí xià","Hai người các bạn cùng đi, gặp vấn đề ít nhất còn có thể bàn bạc với nhau."],["那里的景点很多，都参观完至少要三天的时间。","nà lǐ de jǐng diǎn hěn duō dōu cān guān wán zhì shǎo yào sān tiān de shí jiān","Ở đó có rất nhiều điểm tham quan, tham quan hết ít nhất phải mất ba ngày."]]},{"n":8,"c":["词类","副词","时间副词"],"z":"按时、从来、赶紧、赶快、已、忽然、将、将要、从、本来","t":"Phó từ thời gian 按时, 从来, 赶紧, 赶快, 已, 忽然, 将, 将要, 从, 本来","d":"按时 = đúng giờ; 从来 + 不/没 = từ trước đến nay chưa bao giờ; 赶紧/赶快 = vội, nhanh chóng; 已 = đã (văn viết); 忽然 = bỗng nhiên; 将/将要 = sẽ, sắp (văn viết); 从 + 不/没 = chưa từng; 本来 = vốn dĩ, ban đầu.","e":[["时间很紧张，但我们必须按时完成任务。","shí jiān hěn jǐn zhāng dàn wǒ men bì xū àn shí wán chéng rèn wu","Thời gian rất gấp nhưng chúng ta phải hoàn thành nhiệm vụ đúng hạn."],["医生让我回家按时吃药，多喝热水。","yī shēng ràng wǒ huí jiā àn shí chī yào duō hē rè shuǐ","Bác sĩ bảo tôi về nhà uống thuốc đúng giờ, uống nhiều nước nóng."],["我从来没有离开过家乡，父母不放心我一个人出国留学。","wǒ cóng lái méi yǒu lí kāi guò jiā xiāng fù mǔ bú fàng xīn wǒ yí gè rén chū guó liú xué","Tôi chưa bao giờ rời quê hương, bố mẹ không yên tâm để tôi một mình ra nước ngoài du học."],["我常常吃饺子，可是从来不知道饺子是怎么做的。","wǒ cháng cháng chī jiǎo zi kě shì cóng lái bù zhī dao jiǎo zi shì zěn me zuò de","Tôi thường ăn sủi cảo nhưng chưa bao giờ biết sủi cảo được làm như thế nào."],["服务员见到我们，赶紧跑过来，热情地说“欢迎”。","fú wù yuán jiàn dào wǒ men gǎn jǐn pǎo guò lái rè qíng de shuō huān yíng","Nhân viên phục vụ nhìn thấy chúng tôi, vội chạy tới, nhiệt tình nói \"Hoan nghênh\"."],["这儿的风景太漂亮了，我得赶紧拍几张照片。","zhè r de fēng jǐng tài piào liang le wǒ děi gǎn jǐn pāi jǐ zhāng zhào piàn","Phong cảnh ở đây đẹp quá, tôi phải nhanh chóng chụp mấy tấm ảnh."],["咱们赶快往前走，大家都在前面等着呢。","zán men gǎn kuài wǎng qián zǒu dà jiā dōu zài qián miàn děng zhe ne","Chúng ta mau đi về phía trước, mọi người đều đang đợi ở phía trước đấy."],["你现在赶快叫一辆出租车，马上出发。","nǐ xiàn zài gǎn kuài jiào yí liàng chū zū chē mǎ shàng chū fā","Bây giờ bạn mau gọi một chiếc taxi, xuất phát ngay."],["到今年十月，公司的收入已超过去年。","dào jīn nián shí yuè gōng sī de shōu rù yǐ chāo guò qù nián","Tính đến tháng 10 năm nay, thu nhập của công ty đã vượt năm ngoái."],["他的父亲已有五十多岁，两个姐姐也都已结婚了。","tā de fù qīn yǐ yǒu wǔ shí duō suì liǎng gè jiě jie yě dōu yǐ jié hūn le","Bố anh ấy đã hơn năm mươi tuổi, hai chị gái cũng đều đã kết hôn."],["看着儿子努力学习的样子，我忽然觉得他长大了。","kàn zhe ér zi nǔ lì xué xí de yàng zi wǒ hū rán jué de tā zhǎng dà le","Nhìn dáng vẻ con trai chăm chỉ học tập, tôi bỗng thấy con đã lớn rồi."],["忽然，我听到一个声音说“小伙子，等一等”。","hū rán wǒ tīng dào yí gè shēng yīn shuō xiǎo huǒ zi děng yi děng","Bỗng nhiên, tôi nghe thấy một giọng nói: \"Chàng trai, đợi một chút\"."],["比赛一结束，他就将自己获奖的消息告诉了父母。","bǐ sài yì jié shù tā jiù jiāng zì jǐ huò jiǎng de xiāo xī gào su le fù mǔ","Trận đấu vừa kết thúc, anh ấy đã báo tin mình đoạt giải cho bố mẹ."],["如果孩子学到自己感兴趣的知识，他的能力将得到更好的发展。","rú guǒ hái zi xué dào zì jǐ gǎn xìng qù de zhī shi tā de néng lì jiāng dé dào gèng hǎo de fā zhǎn","Nếu trẻ học được những kiến thức mình hứng thú, năng lực của trẻ sẽ được phát triển tốt hơn."],["根据计划，公司下周将要推出新产品。","gēn jù jì huà gōng sī xià zhōu jiāng yào tuī chū xīn chǎn pǐn","Theo kế hoạch, tuần sau công ty sẽ ra mắt sản phẩm mới."],["学校最近将要安排我们到南方进行调查研究。","xué xiào zuì jìn jiāng yào ān pái wǒ men dào nán fāng jìn xíng diào chá yán jiū","Thời gian tới nhà trường sẽ sắp xếp cho chúng tôi xuống miền Nam điều tra nghiên cứu."],["我从没有听说过这个消息。","wǒ cóng méi yǒu tīng shuō guò zhè ge xiāo xī","Tôi chưa từng nghe nói tin này."],["父母总是鼓励我，从不批评我。","fù mǔ zǒng shì gǔ lì wǒ cóng bù pī píng wǒ","Bố mẹ luôn khích lệ tôi, chưa bao giờ phê bình tôi."],["我本来计划学习一年中文就回国工作，现在我想继续学下去。","wǒ běn lái jì huà xué xí yì nián zhōng wén jiù huí guó gōng zuò xiàn zài wǒ xiǎng jì xù xué xià qù","Tôi vốn định học tiếng Trung một năm rồi về nước làm việc, giờ tôi muốn học tiếp."],["我本来以为父母会反对我留在中国，没想到他们竟然这么支持。","wǒ běn lái yǐ wéi fù mǔ huì fǎn duì wǒ liú zài zhōng guó méi xiǎng dào tā men jìng rán zhè me zhī chí","Tôi vốn tưởng bố mẹ sẽ phản đối việc tôi ở lại Trung Quốc, không ngờ họ lại ủng hộ đến vậy."]]},{"n":9,"c":["词类","副词","频率副词"],"z":"重新、往往、偶尔、再次、老","t":"Phó từ tần suất 重新, 往往, 偶尔, 再次, 老","d":"重新 = làm lại (từ đầu); 往往 = thường thường (theo quy luật); 偶尔 = thỉnh thoảng; 再次 = một lần nữa; 老 = cứ, luôn (khẩu ngữ, thường có ý không hài lòng).","e":[["我们需要重新安排会议时间。","wǒ men xū yào chóng xīn ān pái huì yì shí jiān","Chúng ta cần sắp xếp lại thời gian cuộc họp."],["这个问题，您能不能重新考虑一下？","zhè ge wèn tí nín néng bu néng chóng xīn kǎo lǜ yí xià","Vấn đề này, ông/bà có thể cân nhắc lại một chút không?"],["其实，一些看起来很小的事情往往会影响人的一生。","qí shí yì xiē kàn qǐ lái hěn xiǎo de shì qing wǎng wǎng huì yǐng xiǎng rén de yì shēng","Thực ra, một số việc trông rất nhỏ thường lại ảnh hưởng đến cả cuộc đời một người."],["这两个词意思差不多，如果不知道它们的区别，往往容易用错。","zhè liǎng gè cí yì si chà bù duō rú guǒ bù zhī dao tā men de qū bié wǎng wǎng róng yì yòng cuò","Hai từ này nghĩa gần giống nhau, nếu không biết sự khác biệt của chúng thì thường dễ dùng sai."],["他平时工作很忙，回家以后看看书、上上网，偶尔运动一下，就睡觉了。","tā píng shí gōng zuò hěn máng huí jiā yǐ hòu kàn kàn shū shàng shàng wǎng ǒu ěr yùn dòng yí xià jiù shuì jiào le","Ngày thường anh ấy làm việc rất bận, về nhà đọc sách, lướt mạng, thỉnh thoảng vận động một chút rồi đi ngủ."],["我们偶尔会一起出去玩儿，有时候看电影，有时候踢足球。","wǒ men ǒu ěr huì yì qǐ chū qù wán r yǒu shí hou kàn diàn yǐng yǒu shí hou tī zú qiú","Thỉnh thoảng chúng tôi cùng nhau đi chơi, có lúc xem phim, có lúc đá bóng."],["老师再次提醒同学们考试以前一定要认真复习。","lǎo shī zài cì tí xǐng tóng xué men kǎo shì yǐ qián yí dìng yào rèn zhēn fù xí","Thầy giáo một lần nữa nhắc nhở các bạn trước khi thi nhất định phải ôn tập kỹ."],["再次回到童年时生活的地方，我感到既熟悉又感动。","zài cì huí dào tóng nián shí shēng huó de dì fang wǒ gǎn dào jì shú xī yòu gǎn dòng","Một lần nữa quay về nơi mình sống thời thơ ấu, tôi cảm thấy vừa quen thuộc vừa xúc động."],["他老说要跟同学们多交流，可是从来不参加班级活动。","tā lǎo shuō yào gēn tóng xué men duō jiāo liú kě shì cóng lái bù cān jiā bān jí huó dòng","Anh ấy cứ nói là muốn giao lưu nhiều với các bạn, nhưng chưa bao giờ tham gia hoạt động của lớp."],["大家的工作都很忙，你老想让别人照顾你，是不可能的。","dà jiā de gōng zuò dōu hěn máng nǐ lǎo xiǎng ràng bié rén zhào gù nǐ shì bù kě néng de","Công việc của ai cũng bận, bạn cứ muốn người khác chăm sóc mình là điều không thể."]]},{"n":10,"c":["词类","副词","方式副词"],"z":"故意、互相、相互","t":"Phó từ cách thức 故意, 互相, 相互","d":"故意 = cố ý; 互相/相互 = lẫn nhau, với nhau (相互 trang trọng hơn, còn làm định ngữ: 相互影响).","e":[["真对不起，我不是故意的，你千万别生气。","zhēn duì bù qǐ wǒ bú shì gù yì de nǐ qiān wàn bié shēng qì","Thật xin lỗi, tôi không cố ý, bạn ngàn vạn lần đừng giận."],["他故意提高声音，好让大家都能听见。","tā gù yì tí gāo shēng yīn hǎo ràng dà jiā dōu néng tīng jiàn","Anh ấy cố ý nói to lên để mọi người đều nghe thấy."],["我想练习中文，咱们互相学习，互相帮助，怎么样？","wǒ xiǎng liàn xí zhōng wén zán men hù xiāng xué xí hù xiāng bāng zhù zěn me yàng","Tôi muốn luyện tiếng Trung, chúng ta học hỏi lẫn nhau, giúp đỡ lẫn nhau, thế nào?"],["大家都是同学，应该互相关心，互相照顾。","dà jiā dōu shì tóng xué yīng gāi hù xiāng guān xīn hù xiāng zhào gù","Mọi người đều là bạn học, nên quan tâm lẫn nhau, chăm sóc lẫn nhau."],["国家之间应该相互尊重，相互交流，共同发展。","guó jiā zhī jiān yīng gāi xiāng hù zūn zhòng xiāng hù jiāo liú gòng tóng fā zhǎn","Các quốc gia nên tôn trọng lẫn nhau, giao lưu với nhau, cùng phát triển."],["随着信息技术的发展，不同语言的相互影响越来越普遍。","suí zhe xìn xī jì shù de fā zhǎn bù tóng yǔ yán de xiāng hù yǐng xiǎng yuè lái yuè pǔ biàn","Cùng với sự phát triển của công nghệ thông tin, sự ảnh hưởng lẫn nhau giữa các ngôn ngữ khác nhau ngày càng phổ biến."]]},{"n":11,"c":["词类","副词","关联副词"],"z":"却","t":"Phó từ liên kết 却","d":"却 = lại, nhưng lại (chuyển ý, trái với mong đợi). Đứng sau chủ ngữ, trước động từ.","e":[["有些打折的商品尽管便宜，质量却不能让人满意。","yǒu xiē dǎ zhé de shāng pǐn jǐn guǎn pián yi zhì liàng què bù néng ràng rén mǎn yì","Một số hàng giảm giá tuy rẻ nhưng chất lượng lại không làm người ta hài lòng."],["她长得很像她的姐姐，但两个人的性格却完全不同。","tā zhǎng de hěn xiàng tā de jiě jie dàn liǎng gè rén de xìng gé què wán quán bù tóng","Cô ấy trông rất giống chị gái, nhưng tính cách hai người lại hoàn toàn khác nhau."]]},{"n":12,"c":["词类","副词","情态副词"],"z":"也许、恐怕","t":"Phó từ tình thái 也许, 恐怕","d":"也许 = có lẽ (phỏng đoán trung tính). 恐怕 = e là, sợ là (phỏng đoán điều không mong muốn).","e":[["你可以加一点儿糖，味道也许不错。","nǐ kě yǐ jiā yì diǎn r táng wèi dào yě xǔ bú cuò","Bạn có thể cho thêm một chút đường, có lẽ vị sẽ ngon đấy."],["现在不愿意花时间练习写汉字，你将来也许会后悔的。","xiàn zài bú yuàn yì huā shí jiān liàn xí xiě hàn zì nǐ jiāng lái yě xǔ huì hòu huǐ de","Bây giờ không chịu bỏ thời gian luyện viết chữ Hán, sau này có lẽ bạn sẽ hối hận."],["我感觉头疼，还有点儿咳嗽，恐怕是感冒了。","wǒ gǎn jué tóu téng hái yǒu diǎn r ké sou kǒng pà shì gǎn mào le","Tôi thấy đau đầu, lại hơi ho, e là bị cảm rồi."],["年底是公司最忙的时候，你想休假恐怕不行。","nián dǐ shì gōng sī zuì máng de shí hou nǐ xiǎng xiū jià kǒng pà bù xíng","Cuối năm là lúc công ty bận nhất, bạn muốn nghỉ phép e là không được."]]},{"n":13,"c":["词类","副词","语气副词"],"z":"才⁴、就⁵、并¹、还⁴、竟然、究竟、正好、到底、难道、千万、确实、只好、差（一）点儿","t":"Phó từ ngữ khí 才, 就, 并, 还, 竟然, 究竟, 正好, 到底, 难道, 千万, 确实, 只好, 差(一)点儿","d":"才…呢 = mới thật là (nhấn mạnh); 才不 = đâu có (phủ định mạnh); 就 = cứ, chính là (khẳng định chắc chắn); 并 + 不/没 = hoàn toàn không (bác bỏ); 还真 = quả thật cũng; 竟然 = vậy mà, không ngờ; 究竟/到底 = rốt cuộc; 正好 = vừa đúng lúc; 难道…吗 = lẽ nào; 千万 = nhất định, ngàn vạn lần (dặn dò); 确实 = quả thực; 只好 = đành phải; 差点儿 = suýt nữa.","e":[["昨天那场比赛才精彩呢！","zuó tiān nà chǎng bǐ sài cái jīng cǎi ne","Trận đấu hôm qua mới thật là hấp dẫn!"],["他总是迟到，我才不相信他今天能准时来。","tā zǒng shì chí dào wǒ cái bù xiāng xìn tā jīn tiān néng zhǔn shí lái","Anh ấy lúc nào cũng đến muộn, tôi mới không tin hôm nay anh ấy đến đúng giờ được."],["我就知道他肯定会答应的。","wǒ jiù zhī dao tā kěn dìng huì dā ying de","Tôi biết ngay là anh ấy chắc chắn sẽ đồng ý mà."],["我就不信我考不上大学。","wǒ jiù bú xìn wǒ kǎo bú shàng dà xué","Tôi không tin là tôi không thi đỗ đại học."],["她并不相信我说的话。","tā bìng bù xiāng xìn wǒ shuō de huà","Cô ấy hoàn toàn không tin những lời tôi nói."],["我以为考试很简单，其实并没有那么简单。","wǒ yǐ wéi kǎo shì hěn jiǎn dān qí shí bìng méi yǒu nà me jiǎn dān","Tôi tưởng bài thi rất dễ, thực ra không hề đơn giản như vậy."],["没想到他的中文说得还真不错。","méi xiǎng dào tā de zhōng wén shuō de hái zhēn bú cuò","Không ngờ anh ấy nói tiếng Trung cũng giỏi thật."],["老张还真厉害，这么快就把问题解决了。","lǎo zhāng hái zhēn lì hài zhè me kuài jiù bǎ wèn tí jiě jué le","Lão Trương giỏi thật đấy, nhanh như vậy đã giải quyết xong vấn đề."],["他竟然在那么短的时间内完成了这么复杂的工作，太厉害了。","tā jìng rán zài nà me duǎn de shí jiān nèi wán chéng le zhè me fù zá de gōng zuò tài lì hài le","Anh ấy vậy mà hoàn thành công việc phức tạp như thế trong thời gian ngắn như thế, giỏi quá."],["昨天天气还很暖和，没想到今天竟然下雪了。","zuó tiān tiān qì hái hěn nuǎn huo méi xiǎng dào jīn tiān jìng rán xià xuě le","Hôm qua trời còn rất ấm, không ngờ hôm nay lại có tuyết rơi."],["他究竟是不是真的喜欢我，我还是有些怀疑。","tā jiū jìng shì bu shì zhēn de xǐ huan wǒ wǒ hái shì yǒu xiē huái yí","Rốt cuộc anh ấy có thật sự thích tôi không, tôi vẫn còn hơi nghi ngờ."],["我很想知道汉字究竟是怎么产生的。","wǒ hěn xiǎng zhī dao hàn zì jiū jìng shì zěn me chǎn shēng de","Tôi rất muốn biết rốt cuộc chữ Hán đã ra đời như thế nào."],["我明天下午正好有时间，可以帮你一起搬家。","wǒ míng tiān xià wǔ zhèng hǎo yǒu shí jiān kě yǐ bāng nǐ yì qǐ bān jiā","Chiều mai tôi vừa hay có thời gian, có thể giúp bạn chuyển nhà."],["上个月我借了一本书，今天正好一个月了，你帮我还回去吧。","shàng gè yuè wǒ jiè le yì běn shū jīn tiān zhèng hǎo yí gè yuè le nǐ bāng wǒ huán huí qù ba","Tháng trước tôi mượn một quyển sách, hôm nay vừa đúng một tháng, bạn giúp tôi trả lại nhé."],["明天就是最后一天了，你到底想不想报名？","míng tiān jiù shì zuì hòu yì tiān le nǐ dào dǐ xiǎng bu xiǎng bào míng","Ngày mai là ngày cuối cùng rồi, rốt cuộc bạn có muốn đăng ký không?"],["昨天的比赛你看了吗？他们队到底赢了没有？","zuó tiān de bǐ sài nǐ kàn le ma tā men duì dào dǐ yíng le méi yǒu","Trận đấu hôm qua bạn xem chưa? Rốt cuộc đội họ có thắng không?"],["难道你不知道坐飞机需要带护照吗？","nán dào nǐ bù zhī dao zuò fēi jī xū yào dài hù zhào ma","Lẽ nào bạn không biết đi máy bay cần mang hộ chiếu sao?"],["你难道不认为网上购物更方便吗？","nǐ nán dào bú rèn wéi wǎng shàng gòu wù gèng fāng biàn ma","Lẽ nào bạn không cho rằng mua sắm trên mạng tiện hơn sao?"],["你把地址写在这儿，千万别写错了。","nǐ bǎ dì zhǐ xiě zài zhè r qiān wàn bié xiě cuò le","Bạn viết địa chỉ vào đây, nhất định đừng viết sai nhé."],["路上人多车也多，骑车时千万要小心。","lù shang rén duō chē yě duō qí chē shí qiān wàn yào xiǎo xīn","Trên đường đông người lại nhiều xe, khi đạp xe nhất định phải cẩn thận."],["昨天晚上的京剧演出确实精彩。","zuó tiān wǎn shang de jīng jù yǎn chū què shí jīng cǎi","Buổi biểu diễn Kinh kịch tối qua quả thực rất đặc sắc."],["跟过去相比，这里确实发生了巨大的变化。","gēn guò qù xiāng bǐ zhè lǐ què shí fā shēng le jù dà de biàn huà","So với trước đây, nơi này quả thực đã có những thay đổi to lớn."],["电梯坏了，我们只好走楼梯上去。","diàn tī huài le wǒ men zhǐ hǎo zǒu lóu tī shàng qù","Thang máy hỏng rồi, chúng ta đành phải đi cầu thang bộ lên."],["因为没买到火车票，我假期只好留在学校。","yīn wèi méi mǎi dào huǒ chē piào wǒ jià qī zhǐ hǎo liú zài xué xiào","Vì không mua được vé tàu nên kỳ nghỉ tôi đành ở lại trường."],["出门的时候太着急，我差（一）点儿忘带手机。","chū mén de shí hou tài zháo jí wǒ chà yì diǎn r wàng dài shǒu jī","Lúc ra khỏi nhà vội quá, tôi suýt nữa quên mang điện thoại."],["我早上七点半才起床，差（一）点儿没迟到。","wǒ zǎo shang qī diǎn bàn cái qǐ chuáng chà yì diǎn r méi chí dào","Sáng nay bảy rưỡi tôi mới dậy, suýt nữa thì muộn (may mà không muộn)."]]},{"n":14,"c":["词类","介词","引出时间、处所"],"z":"自、当、由¹、随着、等¹","t":"Giới từ 自, 当, 由, 随着, 等 (thời gian, nơi chốn)","d":"自 = từ (văn viết); 当…时/的时候 = khi…; 由 = từ (khởi điểm); 随着 = cùng với, theo đà; 等 + sự việc = đợi đến khi….","e":[["自1978年以来，中国发生了很大的变化。","zì nián yǐ lái zhōng guó fā shēng le hěn dà de biàn huà","Từ năm 1978 đến nay, Trung Quốc đã có những thay đổi rất lớn."],["我们自北京出发，开车往南走，来到了上海。","wǒ men zì běi jīng chū fā kāi chē wǎng nán zǒu lái dào le shàng hǎi","Chúng tôi xuất phát từ Bắc Kinh, lái xe về phía nam, đến Thượng Hải."],["当遇到困难时，先冷静地想一想。","dāng yù dào kùn nán shí xiān lěng jìng de xiǎng yi xiǎng","Khi gặp khó khăn, hãy bình tĩnh suy nghĩ trước đã."],["当听到放假的消息时，同学们都非常高兴。","dāng tīng dào fàng jià de xiāo xī shí tóng xué men dōu fēi cháng gāo xìng","Khi nghe tin được nghỉ, các bạn học sinh đều rất vui."],["各位乘客，由北京飞往上海的航班就要起飞了。","gè wèi chéng kè yóu běi jīng fēi wǎng shàng hǎi de háng bān jiù yào qǐ fēi le","Thưa quý hành khách, chuyến bay từ Bắc Kinh đi Thượng Hải sắp cất cánh."],["学校决定由下个月开始每周增加一节中文课。","xué xiào jué dìng yóu xià gè yuè kāi shǐ měi zhōu zēng jiā yì jié zhōng wén kè","Nhà trường quyết định từ tháng sau mỗi tuần tăng thêm một tiết tiếng Trung."],["随着生活水平的提高，人们对食品健康的要求越来越高。","suí zhe shēng huó shuǐ píng de tí gāo rén men duì shí pǐn jiàn kāng de yāo qiú yuè lái yuè gāo","Cùng với việc nâng cao mức sống, yêu cầu của mọi người về an toàn thực phẩm ngày càng cao."],["随着春天的到来，天气一天比一天暖和了。","suí zhe chūn tiān de dào lái tiān qì yì tiān bǐ yì tiān nuǎn huo le","Cùng với mùa xuân đến, thời tiết mỗi ngày một ấm hơn."],["等我写完作业，咱们一起去踢足球。","děng wǒ xiě wán zuò yè zán men yì qǐ qù tī zú qiú","Đợi tôi làm xong bài tập, chúng ta cùng đi đá bóng."],["等我们赶到车站，火车已经开走了。","děng wǒ men gǎn dào chē zhàn huǒ chē yǐ jīng kāi zǒu le","Đợi đến khi chúng tôi chạy đến ga thì tàu đã chạy mất rồi."]]},{"n":15,"c":["词类","介词","引出施事、受事"],"z":"将、由²、叫、让","t":"Giới từ 将, 由, 叫, 让 (người làm, đối tượng)","d":"将 = 把 (văn viết); 由 + người + động từ = do ai (làm, chịu trách nhiệm); 叫/让 = 被 (bị, khẩu ngữ, không lược được người làm).","e":[["离开教室时，请将垃圾带走，并将门窗关好。","lí kāi jiào shì shí qǐng jiāng lā jī dài zǒu bìng jiāng mén chuāng guān hǎo","Khi rời lớp học, xin mang rác đi và đóng kỹ cửa ra vào, cửa sổ."],["根据规定，禁止将食物带入图书馆。","gēn jù guī dìng jìn zhǐ jiāng shí wù dài rù tú shū guǎn","Theo quy định, cấm mang đồ ăn vào thư viện."],["这些商品的质量问题应该由工厂负责。","zhè xiē shāng pǐn de zhì liàng wèn tí yīng gāi yóu gōng chǎng fù zé","Vấn đề chất lượng của những hàng hóa này phải do nhà máy chịu trách nhiệm."],["我只是提供一些建议，到底怎么做由你决定。","wǒ zhǐ shì tí gōng yì xiē jiàn yì dào dǐ zěn me zuò yóu nǐ jué dìng","Tôi chỉ đưa ra một số đề xuất, rốt cuộc làm thế nào là do bạn quyết định."],["我刚才放在桌上的那些文件叫谁拿走了？","wǒ gāng cái fàng zài zhuō shàng de nà xiē wén jiàn jiào shuí ná zǒu le","Mấy tập tài liệu tôi vừa để trên bàn bị ai lấy đi rồi?"],["我本来想去图书馆借书，可是学生证让我弄丢了。","wǒ běn lái xiǎng qù tú shū guǎn jiè shū kě shì xué shēng zhèng ràng wǒ nòng diū le","Tôi vốn định đến thư viện mượn sách, nhưng thẻ sinh viên bị tôi làm mất rồi."]]},{"n":16,"c":["词类","介词","引出原因"],"z":"由于¹","t":"Giới từ 由于 (nguyên nhân)","d":"由于 + danh từ = do, bởi vì (văn viết hơn 因为).","e":[["由于上次失败的经历，她对自己失去了信心。","yóu yú shàng cì shī bài de jīng lì tā duì zì jǐ shī qù le xìn xīn","Do trải nghiệm thất bại lần trước, cô ấy đã mất tự tin vào bản thân."],["由于工作的原因，我一年内搬了好几次家。","yóu yú gōng zuò de yuán yīn wǒ yì nián nèi bān le hǎo jǐ cì jiā","Vì lý do công việc, trong một năm tôi đã chuyển nhà mấy lần."]]},{"n":17,"c":["词类","介词","引出对象"],"z":"对于、与¹","t":"Giới từ 对于, 与","d":"对于 = đối với (đối tượng được bàn tới); 与 = với, cùng (văn viết của 和/跟).","e":[["对于任何一种语言，文字的出现都是十分重要的。","duì yú rèn hé yì zhǒng yǔ yán wén zì de chū xiàn dōu shì shí fēn zhòng yào de","Đối với bất kỳ ngôn ngữ nào, sự xuất hiện của chữ viết đều vô cùng quan trọng."],["对于学习成绩优秀的同学，学校每年都会提供奖学金。","duì yú xué xí chéng jì yōu xiù de tóng xué xué xiào měi nián dōu huì tí gōng jiǎng xué jīn","Đối với những học sinh có thành tích học tập xuất sắc, hằng năm nhà trường đều cấp học bổng."],["你放心，我们会与你共同解决这个问题。","nǐ fàng xīn wǒ men huì yǔ nǐ gòng tóng jiě jué zhè ge wèn tí","Bạn yên tâm, chúng tôi sẽ cùng bạn giải quyết vấn đề này."],["这件事我没与任何人交流过。","zhè jiàn shì wǒ méi yǔ rèn hé rén jiāo liú guò","Chuyện này tôi chưa trao đổi với bất kỳ ai."]]},{"n":18,"c":["词类","介词","引出凭借、依据"],"z":"作为、按、按照","t":"Giới từ 作为, 按, 按照","d":"作为 = với tư cách là, là (một)…; 按/按照 = theo, dựa theo (按 còn dùng với đơn vị: 按月 theo tháng).","e":[["作为生活在中国的外国人，我很想了解中国人的生活习惯。","zuò wéi shēng huó zài zhōng guó de wài guó rén wǒ hěn xiǎng liǎo jiě zhōng guó rén de shēng huó xí guàn","Là một người nước ngoài sống ở Trung Quốc, tôi rất muốn tìm hiểu thói quen sinh hoạt của người Trung Quốc."],["作为首都，北京的发展比一般的城市更快，工作机会更多。","zuò wéi shǒu dū běi jīng de fā zhǎn bǐ yì bān de chéng shì gèng kuài gōng zuò jī huì gèng duō","Là thủ đô, Bắc Kinh phát triển nhanh hơn các thành phố bình thường, cơ hội việc làm nhiều hơn."],["你应该按医生说的方法坚持锻炼。","nǐ yīng gāi àn yī shēng shuō de fāng fǎ jiān chí duàn liàn","Bạn nên kiên trì tập luyện theo cách bác sĩ nói."],["这里租房子比较方便，房租可以按月付，也可以按天付。","zhè lǐ zū fáng zi bǐ jiào fāng biàn fáng zū kě yǐ àn yuè fù yě kě yǐ àn tiān fù","Thuê nhà ở đây khá tiện, tiền thuê có thể trả theo tháng, cũng có thể trả theo ngày."],["按照北方人的习惯，过年一般要吃饺子。","àn zhào běi fāng rén de xí guàn guò nián yì bān yào chī jiǎo zi","Theo thói quen của người miền Bắc, ăn Tết thường phải ăn sủi cảo."],["我们已经按照计划完成了全部工作。","wǒ men yǐ jīng àn zhào jì huà wán chéng le quán bù gōng zuò","Chúng tôi đã hoàn thành toàn bộ công việc theo kế hoạch."]]},{"n":19,"c":["词类","连词","连接词或词组"],"z":"并²、而¹、与²","t":"Liên từ 并, 而, 与 (nối từ, cụm từ)","d":"并 = và (nối hai động từ, văn viết); 而 = mà, và (nối hai tính từ); 与 = và (nối danh từ, văn viết).","e":[["学校同意并支持学生们的想法。","xué xiào tóng yì bìng zhī chí xué shēng men de xiǎng fǎ","Nhà trường đồng ý và ủng hộ ý tưởng của các học sinh."],["公司讨论并通过了这项计划。","gōng sī tǎo lùn bìng tōng guò le zhè xiàng jì huà","Công ty đã thảo luận và thông qua kế hoạch này."],["这里的人民热情而友好。","zhè lǐ de rén mín rè qíng ér yǒu hǎo","Người dân nơi đây nhiệt tình và thân thiện."],["她工作起来积极而努力。","tā gōng zuò qǐ lái jī jí ér nǔ lì","Cô ấy làm việc tích cực và chăm chỉ."],["学校与家庭对孩子的影响同样重要。","xué xiào yǔ jiā tíng duì hái zi de yǐng xiǎng tóng yàng zhòng yào","Ảnh hưởng của nhà trường và gia đình đối với trẻ quan trọng như nhau."],["课程目标是帮助学生提高阅读能力与听说能力。","kè chéng mù biāo shì bāng zhù xué shēng tí gāo yuè dú néng lì yǔ tīng shuō néng lì","Mục tiêu khóa học là giúp học viên nâng cao khả năng đọc và khả năng nghe nói."]]},{"n":20,"c":["词类","连词","连接分句或句子"],"z":"此外、而²、既然、甚至、不过、并且","t":"Liên từ 此外, 而, 既然, 甚至, 不过, 并且","d":"此外 = ngoài ra; 而 = còn, trong khi đó (đối lập); 既然…就… = đã…thì…; 甚至 = thậm chí; 不过 = có điều, nhưng; 并且 = và, hơn nữa.","e":[["我每天要上两节中文课，此外一周还要参加一次文化活动。","wǒ měi tiān yào shàng liǎng jié zhōng wén kè cǐ wài yì zhōu hái yào cān jiā yí cì wén huà huó dòng","Mỗi ngày tôi phải học hai tiết tiếng Trung, ngoài ra mỗi tuần còn phải tham gia một buổi hoạt động văn hóa."],["我来中国是想提高自己的汉语水平，此外还想学习中国文化。","wǒ lái zhōng guó shì xiǎng tí gāo zì jǐ de hàn yǔ shuǐ píng cǐ wài hái xiǎng xué xí zhōng guó wén huà","Tôi đến Trung Quốc là muốn nâng cao trình độ tiếng Hán, ngoài ra còn muốn học văn hóa Trung Quốc."],["冬天的时候，北方下雪比较多，而南方下雪比较少。","dōng tiān de shí hou běi fāng xià xuě bǐ jiào duō ér nán fāng xià xuě bǐ jiào shǎo","Vào mùa đông, miền Bắc có tuyết khá nhiều, còn miền Nam thì ít tuyết."],["他们兄弟的性格完全不同，哥哥喜欢热闹，而弟弟喜欢安静。","tā men xiōng dì de xìng gé wán quán bù tóng gē ge xǐ huan rè nao ér dì di xǐ huan ān jìng","Tính cách hai anh em họ hoàn toàn khác nhau, anh thích náo nhiệt còn em thì thích yên tĩnh."],["你说得对，既然来了中国，就要学习一些中国的文化。","nǐ shuō de duì jì rán lái le zhōng guó jiù yào xué xí yì xiē zhōng guó de wén huà","Bạn nói đúng, đã đến Trung Quốc rồi thì phải học một chút văn hóa Trung Quốc."],["既然你决定应聘那份工作，就应该认真准备面试。","jì rán nǐ jué dìng yìng pìn nà fèn gōng zuò jiù yīng gāi rèn zhēn zhǔn bèi miàn shì","Đã quyết định ứng tuyển công việc đó thì bạn nên chuẩn bị phỏng vấn thật kỹ."],["活动还没开始，教室里就坐满了人，甚至还有人站在后面。","huó dòng hái méi kāi shǐ jiào shì lǐ jiù zuò mǎn le rén shèn zhì hái yǒu rén zhàn zài hòu miàn","Hoạt động chưa bắt đầu mà lớp học đã ngồi kín người, thậm chí còn có người đứng ở phía sau."],["他最近工作很忙，有时候甚至连吃饭的时间都没有。","tā zuì jìn gōng zuò hěn máng yǒu shí hou shèn zhì lián chī fàn de shí jiān dōu méi yǒu","Dạo này anh ấy rất bận, có lúc thậm chí đến thời gian ăn cơm cũng không có."],["我姐姐还没有结婚，不过已经有男朋友了。","wǒ jiě jie hái méi yǒu jié hūn bú guò yǐ jīng yǒu nán péng you le","Chị tôi vẫn chưa kết hôn, có điều đã có bạn trai rồi."],["那家公司的地址我也不知道，不过我可以上网帮你查查。","nà jiā gōng sī de dì zhǐ wǒ yě bù zhī dao bú guò wǒ kě yǐ shàng wǎng bāng nǐ chá chá","Địa chỉ của công ty đó tôi cũng không biết, nhưng tôi có thể lên mạng tra giúp bạn."],["从那天开始，我就跟着老师学习中国功夫，并且一直坚持到现在。","cóng nà tiān kāi shǐ wǒ jiù gēn zhe lǎo shī xué xí zhōng guó gōng fū bìng qiě yì zhí jiān chí dào xiàn zài","Từ hôm đó, tôi theo thầy học Kung Fu Trung Quốc và kiên trì cho đến tận bây giờ."],["她打算在中国学习中文，并且还想申请读研究生。","tā dǎ suàn zài zhōng guó xué xí zhōng wén bìng qiě hái xiǎng shēn qǐng dú yán jiū shēng","Cô ấy định học tiếng Trung ở Trung Quốc, hơn nữa còn muốn xin học cao học."]]},{"n":21,"c":["词类","连词","连接分句或句子"],"z":"不光、不仅、另外、要是、因此、由于²、加上","t":"Liên từ 不光, 不仅, 另外, 要是, 因此, 由于, 加上","d":"不光/不仅 = không chỉ; 另外 = ngoài ra; 要是 = nếu (khẩu ngữ); 因此 = vì vậy; 由于 = do, vì; 加上 = cộng thêm, lại thêm.","e":[["我不光要学习中文，还要学习中国的历史和文化。","wǒ bù guāng yào xué xí zhōng wén hái yào xué xí zhōng guó de lì shǐ hé wén huà","Tôi không chỉ phải học tiếng Trung mà còn phải học lịch sử và văn hóa Trung Quốc."],["学校周围不光环境好，交通也很方便。","xué xiào zhōu wéi bù guāng huán jìng hǎo jiāo tōng yě hěn fāng biàn","Xung quanh trường không chỉ môi trường tốt mà giao thông cũng rất thuận tiện."],["我弟弟不仅学习成绩好，而且性格也很好。","wǒ dì di bù jǐn xué xí chéng jì hǎo ér qiě xìng gé yě hěn hǎo","Em trai tôi không những học giỏi mà tính cách cũng rất tốt."],["骑自行车旅行不仅便宜，还能锻炼身体。","qí zì xíng chē lǚ xíng bù jǐn pián yi hái néng duàn liàn shēn tǐ","Du lịch bằng xe đạp không chỉ rẻ mà còn rèn luyện được sức khỏe."],["我大学学的是广告专业，另外还有三年工作经验。","wǒ dà xué xué de shì guǎng gào zhuān yè lìng wài hái yǒu sān nián gōng zuò jīng yàn","Đại học tôi học chuyên ngành quảng cáo, ngoài ra còn có ba năm kinh nghiệm làm việc."],["这些商品质量不错，另外价格也比较便宜。","zhè xiē shāng pǐn zhì liàng bú cuò lìng wài jià gé yě bǐ jiào pián yi","Chất lượng những hàng hóa này khá tốt, ngoài ra giá cũng khá rẻ."],["要是你也觉得满意，咱们就买吧。","yào shi nǐ yě jué de mǎn yì zán men jiù mǎi ba","Nếu bạn cũng thấy hài lòng thì chúng ta mua nhé."],["要是天气不好，明天的活动就取消。","yào shi tiān qì bù hǎo míng tiān de huó dòng jiù qǔ xiāo","Nếu thời tiết xấu thì hoạt động ngày mai sẽ hủy."],["买汽车的人越来越多，因此堵车成为了城市交通的大问题。","mǎi qì chē de rén yuè lái yuè duō yīn cǐ dǔ chē chéng wéi le chéng shì jiāo tōng de dà wèn tí","Người mua ô tô ngày càng nhiều, vì vậy tắc đường trở thành vấn đề lớn của giao thông đô thị."],["她在中国生活过，因此对中国文化有一些了解。","tā zài zhōng guó shēng huó guò yīn cǐ duì zhōng guó wén huà yǒu yì xiē liǎo jiě","Cô ấy đã từng sống ở Trung Quốc, vì vậy có hiểu biết nhất định về văn hóa Trung Quốc."],["由于去晚了，前面没有座位了，我只好坐在最后一排。","yóu yú qù wǎn le qián miàn méi yǒu zuò wèi le wǒ zhǐ hǎo zuò zài zuì hòu yì pái","Vì đến muộn, phía trước không còn chỗ, tôi đành phải ngồi hàng cuối cùng."],["由于天气原因，我们的航班被取消了。","yóu yú tiān qì yuán yīn wǒ men de háng bān bèi qǔ xiāo le","Vì lý do thời tiết, chuyến bay của chúng tôi đã bị hủy."],["我爸爸平时工作很忙，加上经常出差，有时候一周也见不到他。","wǒ bà ba píng shí gōng zuò hěn máng jiā shàng jīng cháng chū chāi yǒu shí hou yì zhōu yě jiàn bú dào tā","Bố tôi ngày thường làm việc rất bận, lại thêm hay đi công tác, có lúc cả tuần cũng không gặp được bố."],["景区实在太大了，加上天气这么热，走了半天，我们又累又渴。","jǐng qū shí zài tài dà le jiā shàng tiān qì zhè me rè zǒu le bàn tiān wǒ men yòu lèi yòu kě","Khu du lịch thật sự quá rộng, lại thêm trời nóng như thế này, đi cả buổi trời, chúng tôi vừa mệt vừa khát."]]},{"n":22,"c":["词类","助词","其他助词"],"z":"等²、者、之、就是","t":"Trợ từ 等, 者, 之, 就是","d":"等 = v.v. (liệt kê); 者 = người (…者: người làm gì, văn viết); 之 = của (văn viết, 之内 = trong vòng); 就是了 = …là được (thôi mà).","e":[["我会说英语、汉语、法语等很多种语言。","wǒ huì shuō yīng yǔ hàn yǔ fǎ yǔ děng hěn duō zhǒng yǔ yán","Tôi biết nói rất nhiều thứ tiếng như tiếng Anh, tiếng Hán, tiếng Pháp…"],["你最好提前上网了解一下那里的天气、交通、景点等方面的信息。","nǐ zuì hǎo tí qián shàng wǎng liǎo jiě yí xià nà lǐ de tiān qì jiāo tōng jǐng diǎn děng fāng miàn de xìn xī","Tốt nhất bạn nên lên mạng tìm hiểu trước thông tin về thời tiết, giao thông, điểm tham quan… ở đó."],["根据学校的规定，迟到十分钟以上者不允许参加考试。","gēn jù xué xiào de guī dìng chí dào shí fēn zhōng yǐ shàng zhě bù yǔn xǔ cān jiā kǎo shì","Theo quy định của trường, người đến muộn quá mười phút không được dự thi."],["申请参加会议者，请将您的个人信息发送到此邮箱。","shēn qǐng cān jiā huì yì zhě qǐng jiāng nín de gè rén xìn xī fā sòng dào cǐ yóu xiāng","Người đăng ký tham dự hội nghị, xin gửi thông tin cá nhân của bạn đến hộp thư này."],["其实，来中国留学一开始并不在我的计划之内。","qí shí lái zhōng guó liú xué yì kāi shǐ bìng bú zài wǒ de jì huà zhī nèi","Thực ra, du học Trung Quốc lúc đầu hoàn toàn không nằm trong kế hoạch của tôi."],["我希望在提高中文水平的基础之上，能够学习一些专业知识。","wǒ xī wàng zài tí gāo zhōng wén shuǐ píng de jī chǔ zhī shàng néng gòu xué xí yì xiē zhuān yè zhī shi","Tôi hy vọng trên cơ sở nâng cao trình độ tiếng Trung, có thể học thêm một số kiến thức chuyên ngành."],["我们明天一定完成任务，您放心就是了。","wǒ men míng tiān yí dìng wán chéng rèn wu nín fàng xīn jiù shì le","Ngày mai chúng tôi nhất định hoàn thành nhiệm vụ, ông/bà cứ yên tâm là được."],["我开车去学校接你，你在门口等我就是了。","wǒ kāi chē qù xué xiào jiē nǐ nǐ zài mén kǒu děng wǒ jiù shì le","Tôi lái xe đến trường đón bạn, bạn cứ đợi tôi ở cổng là được."]]},{"n":23,"c":["词类","叹词",""],"z":"啊、嗯","t":"Thán từ 啊, 嗯","d":"啊 (á/à): ngạc nhiên, chợt hiểu ra. 嗯 (ừ): đồng ý, trả lời.","e":[["啊，原来是这么一回事！","a yuán lái shì zhè me yì huí shì","À, hóa ra là chuyện như vậy!"],["啊，这么多人排队！","a zhè me duō rén pái duì","Á, nhiều người xếp hàng thế!"],["A：八点出发来得及吗？","bā diǎn chū fā lái de jí ma","A: Tám giờ xuất phát có kịp không?"],["B：嗯，应该来得及。","ǹg yīng gāi lái de jí","B: Ừ, chắc là kịp."]]},{"n":24,"c":["短语","结构类型",""],"z":"数词+形容词+量词","t":"Cụm số + tính từ + lượng từ","d":"Chèn 大/小/满… giữa số và lượng từ: 一小盒 (một hộp nhỏ), 两大包 (hai túi to).","e":[["奶奶把一小盒巧克力装进了孙子的书包里。","nǎi nai bǎ yì xiǎo hé qiǎo kè lì zhuāng jìn le sūn zi de shū bāo lǐ","Bà đã bỏ một hộp sô-cô-la nhỏ vào cặp sách của cháu."],["回国前，我给父母买了两大包中国茶作为礼物。","huí guó qián wǒ gěi fù mǔ mǎi le liǎng dà bāo zhōng guó chá zuò wéi lǐ wù","Trước khi về nước, tôi mua cho bố mẹ hai túi to trà Trung Quốc làm quà."]]},{"n":25,"c":["短语","固定短语","四字格"],"z":"一A一B","t":"Cấu trúc bốn chữ 一A一B","d":"一字一句 = từng chữ từng câu; 一来一回 = một lượt đi một lượt về.","e":[["她说话的声音不大，但是一字一句说得很清楚。","tā shuō huà de shēng yīn bú dà dàn shì yí zì yí jù shuō de hěn qīng chu","Giọng cô ấy nói không to nhưng từng chữ từng câu đều rất rõ ràng."],["这会儿路上堵车，一来一回至少需要两个小时。","zhè huì r lù shang dǔ chē yì lái yì huí zhì shǎo xū yào liǎng gè xiǎo shí","Lúc này trên đường đang tắc, đi một lượt về một lượt ít nhất mất hai tiếng."]]},{"n":26,"c":["短语","固定短语","四字格"],"z":"无A无B","t":"Cấu trúc bốn chữ 无A无B","d":"= không…không… (nhấn mạnh hoàn toàn không có): 无儿无女 = không con không cái; 无日无夜 = không kể ngày đêm.","e":[["我无儿无女，一人吃饱全家不饿。","wǒ wú ér wú nǚ yì rén chī bǎo quán jiā bú è","Tôi không con không cái, một mình ăn no là cả nhà không đói."],["母亲无日无夜地照顾着生病的孩子。","mǔ qīn wú rì wú yè de zhào gù zhe shēng bìng de hái zi","Người mẹ không kể ngày đêm chăm sóc đứa con bị ốm."]]},{"n":27,"c":["短语","固定短语","四字格"],"z":"有A有B","t":"Cấu trúc bốn chữ 有A有B","d":"= có…có… (vừa…vừa…): 有说有笑 = cười cười nói nói; 有血有肉 = sống động như thật.","e":[["下课了，同学们有说有笑地走出了教室。","xià kè le tóng xué men yǒu shuō yǒu xiào de zǒu chū le jiào shì","Tan học rồi, các bạn học sinh cười cười nói nói đi ra khỏi lớp."],["这部作品的每个人物都写得有血有肉。","zhè bù zuò pǐn de měi gè rén wù dōu xiě de yǒu xuè yǒu ròu","Mỗi nhân vật trong tác phẩm này đều được viết sống động như thật."]]},{"n":28,"c":["短语","固定短语","其他"],"z":"来得及/来不及","t":"Cụm cố định 来得及/来不及","d":"来得及 = kịp; 来不及 = không kịp. 没来得及 = đã không kịp (làm gì).","e":[["我这两天很忙，没来得及考虑这个问题。","wǒ zhè liǎng tiān hěn máng méi lái de jí kǎo lǜ zhè ge wèn tí","Mấy hôm nay tôi rất bận, chưa kịp cân nhắc vấn đề này."],["我想参加明天的比赛，现在报名来得及吗？","wǒ xiǎng cān jiā míng tiān de bǐ sài xiàn zài bào míng lái de jí ma","Tôi muốn tham gia trận đấu ngày mai, bây giờ đăng ký còn kịp không?"],["我发现这个问题时已经太晚了，来不及做出任何改变。","wǒ fā xiàn zhè ge wèn tí shí yǐ jīng tài wǎn le lái bù jí zuò chū rèn hé gǎi biàn","Lúc tôi phát hiện vấn đề này thì đã quá muộn, không kịp thay đổi gì nữa."],["飞机就要起飞了，你得快一点儿，否则就来不及了。","fēi jī jiù yào qǐ fēi le nǐ děi kuài yì diǎn r fǒu zé jiù lái bù jí le","Máy bay sắp cất cánh rồi, bạn phải nhanh lên, nếu không sẽ không kịp."]]},{"n":29,"c":["短语","固定短语","其他"],"z":"有的是","t":"Cụm cố định 有的是","d":"= có đầy, thiếu gì (rất nhiều).","e":[["一次失败并不可怕，以后有的是机会。","yí cì shī bài bìng bù kě pà yǐ hòu yǒu de shì jī huì","Một lần thất bại không có gì đáng sợ, sau này thiếu gì cơ hội."],["这种水果我的家乡有的是。","zhè zhǒng shuǐ guǒ wǒ de jiā xiāng yǒu de shì","Loại hoa quả này quê tôi có đầy."]]},{"n":30,"c":["短语","固定短语","其他"],"z":"说不定","t":"Cụm cố định 说不定","d":"= không chừng, chưa biết chừng; cũng có thể là \"chưa chắc chắn\".","e":[["客人来不来还说不定。","kè rén lái bu lái hái shuō bú dìng","Khách có đến hay không vẫn chưa chắc chắn."],["说不定路上堵车，再等一会儿吧。","shuō bú dìng lù shang dǔ chē zài děng yí huì r ba","Không chừng trên đường bị tắc, đợi thêm một lát nữa đi."]]},{"n":31,"c":["短语","固定短语","其他"],"z":"不怎么","t":"Cụm cố định 不怎么","d":"不怎么 + động từ/tính từ = không…lắm.","e":[["她从来都不怎么关心别人的看法。","tā cóng lái dōu bù zěn me guān xīn bié rén de kàn fǎ","Cô ấy xưa nay không mấy quan tâm đến cách nhìn của người khác."],["从检查结果来看，他受的伤不怎么严重。","cóng jiǎn chá jié guǒ lái kàn tā shòu de shāng bù zěn me yán zhòng","Từ kết quả kiểm tra mà xem, vết thương của anh ấy không nghiêm trọng lắm."]]},{"n":32,"c":["短语","固定短语","其他"],"z":"就是说/这就是说","t":"Cụm cố định 就是说/这就是说","d":"= nghĩa là, tức là (giải thích, rút ra kết luận).","e":[["他们没有直接拒绝你，而是让你回来等消息，就是说，你还有机会，千万不要放弃。","tā men méi yǒu zhí jiē jù jué nǐ ér shì ràng nǐ huí lái děng xiāo xī jiù shì shuō nǐ hái yǒu jī huì qiān wàn bú yào fàng qì","Họ không từ chối thẳng bạn mà bảo bạn về chờ tin, tức là bạn vẫn còn cơ hội, ngàn vạn lần đừng bỏ cuộc."],["他总是为自己的错误找各种原因，这就是说，他是一个不愿意负责任的人。","tā zǒng shì wèi zì jǐ de cuò wù zhǎo gè zhǒng yuán yīn zhè jiù shì shuō tā shì yí gè bú yuàn yì fù zé rèn de rén","Anh ta luôn tìm đủ mọi lý do cho lỗi của mình, điều đó có nghĩa anh ta là người không muốn chịu trách nhiệm."]]},{"n":33,"c":["固定格式","",""],"z":"一+量词+比+一+量词","t":"Cấu trúc 一 + lượng từ + 比 + 一 + lượng từ","d":"= mỗi…một hơn: 一天比一天暖和 = mỗi ngày một ấm hơn; 一次比一次 = lần sau hơn lần trước.","e":[["他的表演一次比一次精彩。","tā de biǎo yǎn yí cì bǐ yí cì jīng cǎi","Màn biểu diễn của anh ấy lần sau đặc sắc hơn lần trước."],["最近天气一天比一天暖和。","zuì jìn tiān qì yì tiān bǐ yì tiān nuǎn huo","Dạo này thời tiết mỗi ngày một ấm hơn."]]},{"n":34,"c":["固定格式","",""],"z":"在……方面","t":"Cấu trúc 在……方面","d":"= về mặt…, trong lĩnh vực….","e":[["在教育孩子方面，张老师有丰富的经验。","zài jiào yù hái zi fāng miàn zhāng lǎo shī yǒu fēng fù de jīng yàn","Về mặt dạy con, cô Trương có kinh nghiệm phong phú."],["在生活方面，他还不太习惯。","zài shēng huó fāng miàn tā hái bú tài xí guàn","Về mặt sinh hoạt, anh ấy vẫn chưa quen lắm."]]},{"n":35,"c":["固定格式","",""],"z":"够……的","t":"Cấu trúc 够……的","d":"(真)够 + tính từ + 的 = …thật đấy, đủ…lắm rồi (mức độ cao, khẩu ngữ).","e":[["这个房间真够大的，估计能住七八个人。","zhè ge fáng jiān zhēn gòu dà de gū jì néng zhù qī bā gè rén","Phòng này rộng thật đấy, chắc ở được bảy tám người."],["你男朋友真够浪漫的，每天都给你送一枝花。","nǐ nán péng you zhēn gòu làng màn de měi tiān dōu gěi nǐ sòng yì zhī huā","Bạn trai cậu lãng mạn thật đấy, ngày nào cũng tặng cậu một bông hoa."]]},{"n":36,"c":["固定格式","",""],"z":"拿……来说","t":"Cấu trúc 拿……来说","d":"= lấy…ra mà nói (đưa ví dụ).","e":[["中国各地的生活习惯各不相同，拿吃饭来说，南方人一般喜欢吃米饭，而北方人爱吃面条、馒头等面食。","zhōng guó gè dì de shēng huó xí guàn gè bù xiāng tóng ná chī fàn lái shuō nán fāng rén yì bān xǐ huan chī mǐ fàn ér běi fāng rén ài chī miàn tiáo mán tou děng miàn shí","Thói quen sinh hoạt ở các vùng của Trung Quốc mỗi nơi một khác, lấy việc ăn uống mà nói, người miền Nam thường thích ăn cơm, còn người miền Bắc thích ăn các món từ bột mì như mì sợi, màn thầu."],["科技改变了人类的生活，拿交通来说，高铁的出现使人们的日常出行更快、更方便了。","kē jì gǎi biàn le rén lèi de shēng huó ná jiāo tōng lái shuō gāo tiě de chū xiàn shǐ rén men de rì cháng chū xíng gèng kuài gèng fāng biàn le","Khoa học công nghệ đã thay đổi cuộc sống loài người, lấy giao thông mà nói, sự xuất hiện của tàu cao tốc đã làm cho việc đi lại hằng ngày của mọi người nhanh hơn, tiện hơn."]]},{"n":37,"c":["固定格式","",""],"z":"再也不/没……","t":"Cấu trúc 再也不/没……","d":"再也不 = không bao giờ…nữa (tương lai); 再也没 = từ đó không…nữa (quá khứ).","e":[["我保证今后再也不迟到了。","wǒ bǎo zhèng jīn hòu zài yě bù chí dào le","Tôi hứa sau này không bao giờ đến muộn nữa."],["大学毕业以后，我再也没见过他。","dà xué bì yè yǐ hòu wǒ zài yě méi jiàn guò tā","Sau khi tốt nghiệp đại học, tôi không gặp lại anh ấy nữa."]]},{"n":38,"c":["固定格式","",""],"z":"怎么都/也+不/没……","t":"Cấu trúc 怎么都/也 + 不/没……","d":"= thế nào cũng không…, kiểu gì cũng không….","e":[["他们跑了好几家医院，怎么也没查出孩子生病的原因。","tā men pǎo le hǎo jǐ jiā yī yuàn zěn me yě méi chá chū hái zi shēng bìng de yuán yīn","Họ chạy mấy bệnh viện liền mà thế nào cũng không tìm ra nguyên nhân đứa bé bị ốm."],["尽管每天细心照顾，可阳台上的花怎么都不开。","jǐn guǎn měi tiān xì xīn zhào gù kě yáng tái shàng de huā zěn me dōu bù kāi","Tuy ngày nào cũng chăm sóc cẩn thận nhưng hoa ngoài ban công thế nào cũng không nở."]]},{"n":39,"c":["固定格式","",""],"z":"为了……而……","t":"Cấu trúc 为了……而……","d":"= vì…mà… (mục đích + hành động).","e":[["为了梦想而努力的人值得我们学习。","wèi le mèng xiǎng ér nǔ lì de rén zhí de wǒ men xué xí","Những người nỗ lực vì ước mơ đáng để chúng ta học hỏi."],["我们减少使用塑料袋，是为了保护环境而改变习惯。","wǒ men jiǎn shǎo shǐ yòng sù liào dài shì wèi le bǎo hù huán jìng ér gǎi biàn xí guàn","Chúng tôi giảm dùng túi ni lông là thay đổi thói quen vì bảo vệ môi trường."]]},{"n":40,"c":["固定格式","",""],"z":"动词+一X是一X","t":"Cấu trúc động từ + 一X是一X","d":"= được…nào hay…nấy: 学一点儿是一点儿 = học được chút nào hay chút ấy; 过一天是一天 = sống ngày nào hay ngày ấy (sống qua ngày).","e":[["虽然日子过得很难，但也不能过一天是一天。","suī rán rì zi guò de hěn nán dàn yě bù néng guò yì tiān shì yì tiān","Tuy cuộc sống rất khó khăn nhưng cũng không thể sống ngày nào hay ngày ấy."],["要学的内容实在太多了，学一点儿是一点儿吧。","yào xué de nèi róng shí zài tài duō le xué yì diǎn r shì yì diǎn r ba","Nội dung phải học thật sự quá nhiều, học được chút nào hay chút ấy thôi."]]},{"n":41,"c":["固定格式","",""],"z":"（没）有什么（好）X的","t":"Cấu trúc (没)有什么(好)X的","d":"= có gì đáng…đâu, chẳng có gì phải….","e":[["想好了就直接做，有什么好害怕的。","xiǎng hǎo le jiù zhí jiē zuò yǒu shén me hǎo hài pà de","Nghĩ kỹ rồi thì cứ làm luôn, có gì đáng sợ đâu."],["只是一次考试没考好，没有什么好难过的。","zhǐ shì yí cì kǎo shì méi kǎo hǎo méi yǒu shén me hǎo nán guò de","Chỉ là một lần thi không tốt thôi, chẳng có gì phải buồn cả."]]},{"n":42,"c":["固定格式","",""],"z":"X是X，Y是Y","t":"Cấu trúc X是X，Y是Y","d":"= X là X, Y là Y (hai chuyện tách bạch, không lẫn lộn).","e":[["他是他，我是我，我们的意见不一样。","tā shì tā wǒ shì wǒ wǒ men de yì jiàn bù yí yàng","Anh ấy là anh ấy, tôi là tôi, ý kiến của chúng tôi không giống nhau."],["工作是工作，家庭是家庭，不要用工作的方式解决家里的问题。","gōng zuò shì gōng zuò jiā tíng shì jiā tíng bú yào yòng gōng zuò de fāng shì jiě jué jiā lǐ de wèn tí","Công việc là công việc, gia đình là gia đình, đừng dùng cách làm việc để giải quyết chuyện trong nhà."]]},{"n":43,"c":["固定格式","",""],"z":"X也得X，不X也得X","t":"Cấu trúc X也得X，不X也得X","d":"= có muốn hay không cũng phải… (bắt buộc).","e":[["这场会议很重要，你去也得去，不去也得去。","zhè chǎng huì yì hěn zhòng yào nǐ qù yě děi qù bú qù yě děi qù","Cuộc họp này rất quan trọng, bạn muốn đi cũng phải đi, không muốn đi cũng phải đi."],["结果改变不了了，你接受也得接受，不接受也得接受。","jié guǒ gǎi biàn bù liǎo le nǐ jiē shòu yě děi jiē shòu bù jiē shòu yě děi jiē shòu","Kết quả không thay đổi được nữa rồi, bạn chấp nhận cũng phải chấp nhận, không chấp nhận cũng phải chấp nhận."]]},{"n":44,"c":["固定格式","",""],"z":"X就是了","t":"Cấu trúc X就是了","d":"= cứ…là được (thôi mà), giọng nhẹ nhàng, khuyên nhủ.","e":[["别浪费时间了，有什么想法说就是了。","bié làng fèi shí jiān le yǒu shén me xiǎng fǎ shuō jiù shì le","Đừng lãng phí thời gian nữa, có ý gì thì cứ nói ra là được."],["你不要生气，下次别答应他就是了。","nǐ bú yào shēng qì xià cì bié dā ying tā jiù shì le","Bạn đừng giận, lần sau đừng đồng ý với anh ta là được."]]},{"n":45,"c":["固定格式","",""],"z":"还X呢","t":"Cấu trúc 还X呢","d":"= …mà cũng (gọi là)…(chê bai: không xứng với danh nghĩa).","e":[["还国际公司呢，服务质量这么差。","hái guó jì gōng sī ne fú wù zhì liàng zhè me chà","Công ty quốc tế gì chứ, chất lượng phục vụ kém thế này."],["还中文专业的呢，中文说得还不如我。","hái zhōng wén zhuān yè de ne zhōng wén shuō de hái bù rú wǒ","Học chuyên ngành tiếng Trung mà nói tiếng Trung còn không bằng tôi."]]},{"n":46,"c":["固定格式","",""],"z":"你X你的吧","t":"Cấu trúc 你X你的吧","d":"= bạn cứ…việc của bạn đi (đừng để ý đến tôi).","e":[["我不饿，你吃你的吧，不用等我。","wǒ bú è nǐ chī nǐ de ba bú yòng děng wǒ","Tôi không đói, bạn cứ ăn đi, không cần đợi tôi."],["没有什么重要的事，你忙你的吧。","méi yǒu shén me zhòng yào de shì nǐ máng nǐ de ba","Không có việc gì quan trọng đâu, bạn cứ làm việc của bạn đi."]]},{"n":47,"c":["固定格式","",""],"z":"让/叫你X你就X","t":"Cấu trúc 让/叫你X你就X","d":"= bảo bạn…thì bạn cứ…(đi).","e":[["老师让你多练你就多练，肯定没坏处。","lǎo shī ràng nǐ duō liàn nǐ jiù duō liàn kěn dìng méi huài chù","Thầy bảo bạn luyện nhiều thì bạn cứ luyện nhiều, chắc chắn không có hại."],["叫你拿着你就拿着，不用跟我客气。","jiào nǐ ná zhe nǐ jiù ná zhe bú yòng gēn wǒ kè qi","Bảo bạn cầm thì bạn cứ cầm, không cần khách sáo với tôi."]]},{"n":48,"c":["固定格式","",""],"z":"说什么/怎么（着）也得X","t":"Cấu trúc 说什么/怎么(着)也得X","d":"= dù thế nào cũng phải….","e":[["他受伤了，我说什么也得去看看他。","tā shòu shāng le wǒ shuō shén me yě děi qù kàn kàn tā","Anh ấy bị thương rồi, dù thế nào tôi cũng phải đi thăm anh ấy."],["快要迟到了，说什么也得走了。","kuài yào chí dào le shuō shén me yě děi zǒu le","Sắp muộn rồi, dù thế nào cũng phải đi thôi."],["这么有用的技术，我怎么（着）也得学。","zhè me yǒu yòng de jì shù wǒ zěn me zhe yě děi xué","Kỹ thuật hữu ích như vậy, dù thế nào tôi cũng phải học."]]},{"n":49,"c":["固定格式","",""],"z":"X就X（点儿）吧","t":"Cấu trúc X就X(点儿)吧","d":"= …thì…(một chút) thôi (chấp nhận, nhượng bộ).","e":[["买就买（点儿）吧，也不太贵。","mǎi jiù mǎi diǎn r ba yě bú tài guì","Mua thì mua thôi, cũng không đắt lắm."],["慢就慢（点儿）吧，能做完就行。","màn jiù màn diǎn r ba néng zuò wán jiù xíng","Chậm thì chậm một chút thôi, làm xong được là được."]]},{"n":50,"c":["固定格式","",""],"z":"X是X","t":"Cấu trúc X是X","d":"X 是 X，可是/不过… = …thì có…, nhưng… (thừa nhận rồi chuyển ý).","e":[["我们讨论是讨论了，可是大家各有各的想法。","wǒ men tǎo lùn shì tǎo lùn le kě shì dà jiā gè yǒu gè de xiǎng fǎ","Chúng tôi thảo luận thì có thảo luận rồi, nhưng mỗi người một ý."],["留学生活累是累，不过我们学到了很多知识。","liú xué shēng huó lèi shì lèi bú guò wǒ men xué dào le hěn duō zhī shi","Cuộc sống du học mệt thì có mệt, nhưng chúng tôi học được rất nhiều kiến thức."]]},{"n":51,"c":["句子成分","","程度补语2"],"z":"形容词/心理动词+死了/厉害","t":"Bổ ngữ mức độ: 死了, 厉害","d":"Tính từ/động từ tâm lý + 死了 = …chết đi được; + 得厉害 = …kinh khủng, dữ dội.","e":[["面试的时候，我心里紧张死了。","miàn shì de shí hou wǒ xīn lǐ jǐn zhāng sǐ le","Lúc phỏng vấn, trong lòng tôi hồi hộp chết đi được."],["不知道从哪儿来的声音，吵死了。","bù zhī dao cóng nǎ r lái de shēng yīn chǎo sǐ le","Không biết tiếng ồn từ đâu ra, ồn chết đi được."],["吃完冰激凌，我突然牙疼得厉害。","chī wán bīng jī líng wǒ tū rán yá téng de lì hài","Ăn kem xong, tôi đột nhiên đau răng kinh khủng."],["我们这儿有个同学病得很厉害，请你们赶快来看看。","wǒ men zhè r yǒu gè tóng xué bìng de hěn lì hài qǐng nǐ men gǎn kuài lái kàn kàn","Chỗ chúng tôi có một bạn bị ốm rất nặng, các anh mau đến xem giúp."]]},{"n":52,"c":["句子成分","","可能补语2"],"z":"动词+得/不+了","t":"Bổ ngữ khả năng: động từ + 得/不 + 了","d":"吃得了 = ăn hết được; 拿不了 = không cầm nổi; 参加不了 = không tham gia được.","e":[["你点了这么多菜，咱们两个人吃得了吗？","nǐ diǎn le zhè me duō cài zán men liǎng gè rén chī de liǎo ma","Bạn gọi nhiều món thế này, hai chúng ta ăn hết được không?"],["我帮你一起做，下班之前肯定完成得了。","wǒ bāng nǐ yì qǐ zuò xià bān zhī qián kěn dìng wán chéng de liǎo","Tôi giúp bạn làm cùng, trước giờ tan làm chắc chắn hoàn thành được."],["行李太重了，我一个人拿不了。","xíng li tài zhòng le wǒ yí gè rén ná bù liǎo","Hành lý nặng quá, một mình tôi không xách nổi."],["明天的比赛他参加不了。","míng tiān de bǐ sài tā cān jiā bù liǎo","Trận đấu ngày mai anh ấy không tham gia được."]]},{"n":53,"c":["句子的类型","句类","反问句2"],"z":"难道……吗？","t":"Câu hỏi tu từ: 难道……吗？","d":"= Lẽ nào…sao? (nhấn mạnh ý ngược lại).","e":[["作为学生，难道学习不是最重要的事情吗？","zuò wéi xué shēng nán dào xué xí bú shì zuì zhòng yào de shì qing ma","Là học sinh, lẽ nào học tập không phải là việc quan trọng nhất sao?"],["工作出了问题，你难道不应该负责吗？","gōng zuò chū le wèn tí nǐ nán dào bú yīng gāi fù zé ma","Công việc xảy ra vấn đề, lẽ nào bạn không nên chịu trách nhiệm sao?"]]},{"n":54,"c":["句子的类型","句类","反问句2"],"z":"由疑问代词构成的反问句","t":"Câu hỏi tu từ dùng đại từ nghi vấn","d":"谁不… = ai mà không… (= ai cũng); 怎么会… = sao mà… được; 哪儿有… = làm gì có….","e":[["这么有名的作家，谁不认识他？","zhè me yǒu míng de zuò jiā shuí bú rèn shi tā","Nhà văn nổi tiếng thế này, ai mà không biết ông ấy?"],["他去哪儿从来不说，我怎么会知道呢？","tā qù nǎ r cóng lái bù shuō wǒ zěn me huì zhī dao ne","Anh ấy đi đâu chưa bao giờ nói, sao tôi biết được?"],["事情这么多，我哪儿有时间出去旅游啊？","shì qing zhè me duō wǒ nǎ r yǒu shí jiān chū qù lǚ yóu a","Việc nhiều thế này, tôi làm gì có thời gian đi du lịch chứ?"]]},{"n":55,"c":["句子的类型","特殊句型","“把”字句2"],"z":"主语+把+宾语+动词（+一/了）+动词","t":"Câu chữ 把: 把 + tân ngữ + động từ lặp lại","d":"把 + tân ngữ + V一V / V了V: làm thử, làm qua một chút.","e":[["你再把那件衣服洗一洗。","nǐ zài bǎ nà jiàn yī fu xǐ yi xǐ","Bạn giặt lại cái áo đó một chút."],["你把窗户擦一擦，我把地板扫一扫。","nǐ bǎ chuāng hù cā yi cā wǒ bǎ dì bǎn sǎo yi sǎo","Bạn lau cửa sổ một chút, tôi quét sàn một chút."],["他把钱算了算，又取了一点儿出来。","tā bǎ qián suàn le suàn yòu qǔ le yì diǎn r chū lái","Anh ấy tính lại số tiền, rồi lại rút ra thêm một ít."]]},{"n":56,"c":["句子的类型","特殊句型","“把”字句2"],"z":"主语+把+宾语+动词+了","t":"Câu chữ 把: 把 + tân ngữ + động từ + 了","d":"Động từ mang nghĩa mất đi (忘, 丢, 卖, 喝…) + 了.","e":[["我把银行卡密码忘了。","wǒ bǎ yín háng kǎ mì mǎ wàng le","Tôi quên mật khẩu thẻ ngân hàng rồi."],["他把新买的手机丢了。","tā bǎ xīn mǎi de shǒu jī diū le","Anh ấy làm mất chiếc điện thoại mới mua rồi."]]},{"n":57,"c":["句子的类型","特殊句型","“把”字句2"],"z":"主语+把+宾语+动词+动量补语/时量补语","t":"Câu chữ 把: 把 + tân ngữ + động từ + bổ ngữ động lượng/thời lượng","d":"Sau động từ là số lần hoặc khoảng thời gian.","e":[["因为不收拾房间，妈妈把他批评了一顿。","yīn wèi bù shōu shi fáng jiān mā ma bǎ tā pī píng le yí dùn","Vì không dọn phòng, mẹ đã mắng cậu ấy một trận."],["同学们把课文读了两遍。","tóng xué men bǎ kè wén dú le liǎng biàn","Các bạn học sinh đã đọc bài khóa hai lượt."],["他把这个问题认真地考虑了好几天。","tā bǎ zhè ge wèn tí rèn zhēn de kǎo lǜ le hǎo jǐ tiān","Anh ấy đã suy nghĩ kỹ vấn đề này mấy ngày liền."]]},{"n":58,"c":["句子的类型","特殊句型","“把”字句2"],"z":"主语+把+宾语+状语+动词","t":"Câu chữ 把: 把 + tân ngữ + trạng ngữ + động từ","d":"Trạng ngữ (往地上, 认真…) đặt giữa tân ngữ và động từ.","e":[["你别把垃圾往地上扔。","nǐ bié bǎ lā jī wǎng dì shàng rēng","Bạn đừng vứt rác xuống đất."],["请大家把说明书认真读一读。","qǐng dà jiā bǎ shuō míng shū rèn zhēn dú yi dú","Mời mọi người đọc kỹ bản hướng dẫn."]]},{"n":59,"c":["句子的类型","特殊句型","被动句2"],"z":"主语+叫/让+宾语+动词+其他成分","t":"Câu bị động với 叫/让","d":"Chủ ngữ + 叫/让 + người làm + động từ + thành phần khác. Khẩu ngữ, không được lược người làm.","e":[["我的自行车让朋友借去了。","wǒ de zì xíng chē ràng péng you jiè qù le","Xe đạp của tôi bị bạn mượn đi rồi."],["相机叫谁拿走了？","xiàng jī jiào shuí ná zǒu le","Máy ảnh bị ai lấy đi rồi?"]]},{"n":60,"c":["句子的类型","特殊句型","兼语句2"],"z":"表爱憎义：主语+表扬/批评+宾语1+动词+宾语2","t":"Câu kiêm ngữ: khen/chê","d":"Chủ ngữ + 表扬 (khen)/批评 (phê bình) + người + hành động (lý do được khen/chê).","e":[["老师表扬我取得了好成绩。","lǎo shī biǎo yáng wǒ qǔ dé le hǎo chéng jì","Thầy giáo khen tôi đạt thành tích tốt."],["警察表扬那个小伙子帮助了别人。","jǐng chá biǎo yáng nà ge xiǎo huǒ zi bāng zhù le bié rén","Cảnh sát khen chàng trai đó đã giúp đỡ người khác."],["妈妈总是批评我不收拾房间。","mā ma zǒng shì pī píng wǒ bù shōu shi fáng jiān","Mẹ luôn phê bình tôi không dọn phòng."],["经理批评我没带会议资料。","jīng lǐ pī píng wǒ méi dài huì yì zī liào","Giám đốc phê bình tôi không mang tài liệu họp."]]},{"n":61,"c":["句子的类型","特殊句型","兼语句2"],"z":"表称谓或认定义：主语+收/选+宾语1+做/当/为+宾语2","t":"Câu kiêm ngữ: gọi tên, công nhận","d":"Chủ ngữ + 选 (bầu)/收 (nhận) + người + 做/当/为 + vai trò.","e":[["同学们选我做小组长。","tóng xué men xuǎn wǒ zuò xiǎo zǔ zhǎng","Các bạn bầu tôi làm tổ trưởng."],["大家想选他当队长。","dà jiā xiǎng xuǎn tā dāng duì zhǎng","Mọi người muốn bầu anh ấy làm đội trưởng."],["张教授同意收我为学生。","zhāng jiào shòu tóng yì shōu wǒ wéi xué shēng","Giáo sư Trương đồng ý nhận tôi làm học trò."]]},{"n":62,"c":["句子的类型","特殊句型","兼语句2"],"z":"表致使：主语+使/让+人称代词+动词短语","t":"Câu kiêm ngữ: khiến","d":"Chủ ngữ + 使/让 + người + động từ/tính từ = khiến ai….","e":[["这件事使我改变了对她的印象。","zhè jiàn shì shǐ wǒ gǎi biàn le duì tā de yìn xiàng","Chuyện này khiến tôi thay đổi ấn tượng về cô ấy."],["那些美好的回忆让我永远难忘。","nà xiē měi hǎo de huí yì ràng wǒ yǒng yuǎn nán wàng","Những kỷ niệm đẹp đó khiến tôi mãi mãi khó quên."]]},{"n":63,"c":["句子的类型","特殊句型","比较句3"],"z":"A不如B（+形容词）","t":"Câu so sánh: A 不如 B (+ tính từ)","d":"= A không bằng B.","e":[["现在堵车，打车不如坐地铁快。","xiàn zài dǔ chē dǎ chē bù rú zuò dì tiě kuài","Bây giờ đang tắc đường, đi taxi không nhanh bằng đi tàu điện ngầm."],["我觉得玩游戏不如看小说有意思。","wǒ jué de wán yóu xì bù rú kàn xiǎo shuō yǒu yì si","Tôi thấy chơi game không thú vị bằng đọc tiểu thuyết."]]},{"n":64,"c":["句子的类型","特殊句型","比较句3"],"z":"跟……相比","t":"Câu so sánh: 跟……相比","d":"= So với….","e":[["跟线下购物相比，上网买东西更符合年轻人的习惯。","gēn xiàn xià gòu wù xiāng bǐ shàng wǎng mǎi dōng xi gèng fú hé nián qīng rén de xí guàn","So với mua sắm trực tiếp, mua đồ trên mạng hợp với thói quen của người trẻ hơn."],["跟其他公司相比，我们的产品不但便宜，而且服务也好。","gēn qí tā gōng sī xiāng bǐ wǒ men de chǎn pǐn bú dàn pián yi ér qiě fú wù yě hǎo","So với các công ty khác, sản phẩm của chúng tôi không những rẻ mà dịch vụ cũng tốt."]]},{"n":65,"c":["句子的类型","特殊句型","双重否定句"],"z":"用双重否定表示强调","t":"Câu phủ định kép","d":"Hai lần phủ định = khẳng định mạnh: 没有…不… = không ai không… (= ai cũng); 不可能没… = không thể không… (chắc chắn đã).","e":[["没有学生不喜欢放假。","méi yǒu xué shēng bù xǐ huan fàng jià","Không có học sinh nào không thích được nghỉ."],["这么重要的内容老师不可能没讲过。","zhè me zhòng yào de nèi róng lǎo shī bù kě néng méi jiǎng guò","Nội dung quan trọng như vậy thầy giáo không thể nào chưa giảng."]]},{"n":66,"c":["句子的类型","复句","并列复句"],"z":"不是……，而是……","t":"Câu phức đẳng lập: 不是……，而是……","d":"= Không phải…mà là….","e":[["他不是不想帮忙，而是确实没时间。","tā bú shì bù xiǎng bāng máng ér shì què shí méi shí jiān","Anh ấy không phải không muốn giúp, mà là thật sự không có thời gian."],["我不是不爱喝咖啡，而是担心晚上睡不着。","wǒ bú shì bú ài hē kā fēi ér shì dān xīn wǎn shang shuì bù zhe","Tôi không phải không thích uống cà phê, mà là sợ buổi tối không ngủ được."]]},{"n":67,"c":["句子的类型","复句","并列复句"],"z":"既……，又/也……","t":"Câu phức đẳng lập: 既……，又/也……","d":"= Vừa…vừa…, đã…lại….","e":[["这个牌子的奶茶既好喝，又健康。","zhè ge pái zi de nǎi chá jì hǎo hē yòu jiàn kāng","Trà sữa của nhãn hiệu này vừa ngon vừa tốt cho sức khỏe."],["我每天骑自行车上学，这样既能锻炼身体，也对环境保护有帮助。","wǒ měi tiān qí zì xíng chē shàng xué zhè yàng jì néng duàn liàn shēn tǐ yě duì huán jìng bǎo hù yǒu bāng zhù","Mỗi ngày tôi đạp xe đi học, như vậy vừa rèn luyện được sức khỏe, vừa có ích cho việc bảo vệ môi trường."]]},{"n":68,"c":["句子的类型","复句","并列复句"],"z":"一方面……，另一方面……","t":"Câu phức đẳng lập: 一方面……，另一方面……","d":"= Một mặt…, mặt khác….","e":[["参加文化活动一方面可以增长知识，另一方面可以认识新的朋友。","cān jiā wén huà huó dòng yì fāng miàn kě yǐ zēng zhǎng zhī shi lìng yì fāng miàn kě yǐ rèn shi xīn de péng you","Tham gia hoạt động văn hóa một mặt có thể tăng thêm hiểu biết, mặt khác có thể quen bạn mới."],["想要解决大城市堵车的问题，一方面要提高公共交通服务质量，另一方面要让人们养成绿色出行的习惯。","xiǎng yào jiě jué dà chéng shì dǔ chē de wèn tí yì fāng miàn yào tí gāo gōng gòng jiāo tōng fú wù zhì liàng lìng yì fāng miàn yào ràng rén men yǎng chéng lǜ sè chū xíng de xí guàn","Muốn giải quyết vấn đề tắc đường ở thành phố lớn, một mặt phải nâng cao chất lượng dịch vụ giao thông công cộng, mặt khác phải giúp mọi người hình thành thói quen đi lại xanh."]]},{"n":69,"c":["句子的类型","复句","承接复句"],"z":"首先……，其次……","t":"Câu phức nối tiếp: 首先……，其次……","d":"= Trước hết…, tiếp đến….","e":[["选择职业的时候，应该首先了解自己的性格、能力，其次再考虑工资、收入等方面的问题。","xuǎn zé zhí yè de shí hou yīng gāi shǒu xiān liǎo jiě zì jǐ de xìng gé néng lì qí cì zài kǎo lǜ gōng zī shōu rù děng fāng miàn de wèn tí","Khi chọn nghề, trước hết nên hiểu rõ tính cách, năng lực của mình, tiếp đến mới cân nhắc lương bổng, thu nhập."],["我学汉语首先是因为对中国文化感兴趣，其次是为了获得更多的工作机会。","wǒ xué hàn yǔ shǒu xiān shì yīn wèi duì zhōng guó wén huà gǎn xìng qù qí cì shì wèi le huò dé gèng duō de gōng zuò jī huì","Tôi học tiếng Hán trước hết là vì hứng thú với văn hóa Trung Quốc, tiếp đến là để có thêm cơ hội việc làm."]]},{"n":70,"c":["句子的类型","复句","承接复句"],"z":"首先……，然后……","t":"Câu phức nối tiếp: 首先……，然后……","d":"= Trước hết…, sau đó….","e":[["首先要找到一个合适的目标，然后坚持学习，这样才能学好中文。","shǒu xiān yào zhǎo dào yí gè hé shì de mù biāo rán hòu jiān chí xué xí zhè yàng cái néng xué hǎo zhōng wén","Trước hết phải tìm được một mục tiêu phù hợp, sau đó kiên trì học tập, như vậy mới học giỏi tiếng Trung được."],["校长首先对同学们表示欢迎，然后介绍了学校的一些基本情况。","xiào zhǎng shǒu xiān duì tóng xué men biǎo shì huān yíng rán hòu jiè shào le xué xiào de yì xiē jī běn qíng kuàng","Hiệu trưởng trước hết chào mừng các bạn học sinh, sau đó giới thiệu một số tình hình cơ bản của trường."]]},{"n":71,"c":["句子的类型","复句","承接复句"],"z":"……，于是……","t":"Câu phức nối tiếp: ……，于是……","d":"= …, thế là/vì thế….","e":[["人们喜欢一边喝咖啡，一边聊天儿，于是城市里的咖啡馆越来越多。","rén men xǐ huan yì biān hē kā fēi yì biān liáo tiān r yú shì chéng shì lǐ de kā fēi guǎn yuè lái yuè duō","Mọi người thích vừa uống cà phê vừa trò chuyện, thế là quán cà phê trong thành phố ngày càng nhiều."],["大家不断地鼓励我，于是我决定报名参加这个比赛。","dà jiā bú duàn de gǔ lì wǒ yú shì wǒ jué dìng bào míng cān jiā zhè ge bǐ sài","Mọi người không ngừng động viên tôi, thế là tôi quyết định đăng ký tham gia cuộc thi này."]]},{"n":72,"c":["句子的类型","复句","递进复句"],"z":"……,甚至……","t":"Câu phức tăng tiến: ……，甚至……","d":"= …, thậm chí….","e":[["为了锻炼身体，我一有空就去健身房，甚至专门请了一个健身教练。","wèi le duàn liàn shēn tǐ wǒ yì yǒu kòng jiù qù jiàn shēn fáng shèn zhì zhuān mén qǐng le yí gè jiàn shēn jiào liàn","Để rèn luyện sức khỏe, hễ rảnh là tôi đến phòng gym, thậm chí còn thuê riêng một huấn luyện viên."],["收到大学的入学通知，我高兴极了，甚至觉得自己是世界上最幸福的人。","shōu dào dà xué de rù xué tōng zhī wǒ gāo xìng jí le shèn zhì jué de zì jǐ shì shì jiè shàng zuì xìng fú de rén","Nhận được giấy báo nhập học đại học, tôi vui cực kỳ, thậm chí cảm thấy mình là người hạnh phúc nhất trên đời."]]},{"n":73,"c":["句子的类型","复句","递进复句"],"z":"不仅/不光……，还/而且……","t":"Câu phức tăng tiến: 不仅/不光……，还/而且……","d":"= Không chỉ…mà còn….","e":[["我们学习生词，不仅要理解词语的意思，而且应该知道怎么使用。","wǒ men xué xí shēng cí bù jǐn yào lǐ jiě cí yǔ de yì si ér qiě yīng gāi zhī dao zěn me shǐ yòng","Chúng ta học từ mới, không chỉ phải hiểu nghĩa của từ mà còn nên biết cách sử dụng."],["这里不光有美丽的风景，还有各种少见的动物、植物。","zhè lǐ bù guāng yǒu měi lì de fēng jǐng hái yǒu gè zhǒng shǎo jiàn de dòng wù zhí wù","Ở đây không chỉ có phong cảnh đẹp mà còn có đủ loại động vật, thực vật hiếm thấy."]]},{"n":74,"c":["句子的类型","复句","递进复句"],"z":"……，并且……","t":"Câu phức tăng tiến: ……，并且……","d":"= …, và còn/hơn nữa….","e":[["经过四年的努力，他终于顺利毕业，并且有了一家自己的公司。","jīng guò sì nián de nǔ lì tā zhōng yú shùn lì bì yè bìng qiě yǒu le yì jiā zì jǐ de gōng sī","Sau bốn năm nỗ lực, cuối cùng anh ấy đã tốt nghiệp suôn sẻ, và còn có một công ty của riêng mình."],["随着经济的发展，人们的生活水平提高了，并且对健康和生活质量的要求也越来越高。","suí zhe jīng jì de fā zhǎn rén men de shēng huó shuǐ píng tí gāo le bìng qiě duì jiàn kāng hé shēng huó zhì liàng de yāo qiú yě yuè lái yuè gāo","Cùng với sự phát triển kinh tế, mức sống của người dân được nâng cao, và yêu cầu về sức khỏe, chất lượng cuộc sống cũng ngày càng cao."]]},{"n":75,"c":["句子的类型","复句","递进复句"],"z":"连……也/都……，……更……","t":"Câu phức tăng tiến: 连……也/都……，……更……","d":"= Ngay cả…cũng…, (thì)…càng….","e":[["我有时候连老师说的话也听不懂，听广播就更难了。","wǒ yǒu shí hou lián lǎo shī shuō de huà yě tīng bù dǒng tīng guǎng bō jiù gèng nán le","Có lúc ngay cả lời thầy giáo nói tôi cũng nghe không hiểu, nghe đài thì càng khó hơn."],["受伤以后，他连走路都困难，踢足球更不可能了。","shòu shāng yǐ hòu tā lián zǒu lù dōu kùn nán tī zú qiú gèng bù kě néng le","Sau khi bị thương, ngay cả đi lại anh ấy cũng khó khăn, đá bóng càng không thể."]]},{"n":76,"c":["句子的类型","复句","选择复句"],"z":"不是……，就是……","t":"Câu phức lựa chọn: 不是……，就是……","d":"= Không phải…thì là… (một trong hai).","e":[["毕业以后，同学们不是留在中国继续学习，就是回国工作。","bì yè yǐ hòu tóng xué men bú shì liú zài zhōng guó jì xù xué xí jiù shì huí guó gōng zuò","Sau khi tốt nghiệp, các bạn không ở lại Trung Quốc học tiếp thì cũng về nước làm việc."],["周末他不是在游泳馆游泳，就是在篮球场打篮球。","zhōu mò tā bú shì zài yóu yǒng guǎn yóu yǒng jiù shì zài lán qiú chǎng dǎ lán qiú","Cuối tuần anh ấy không bơi ở bể bơi thì cũng chơi bóng rổ ở sân bóng rổ."]]},{"n":77,"c":["句子的类型","复句","转折复句"],"z":"尽管……，但是/可是……","t":"Câu phức chuyển ngoặt: 尽管……，但是/可是……","d":"= Mặc dù…nhưng….","e":[["尽管收入不高，但是我对这份工作很满意。","jǐn guǎn shōu rù bù gāo dàn shì wǒ duì zhè fèn gōng zuò hěn mǎn yì","Mặc dù thu nhập không cao nhưng tôi rất hài lòng với công việc này."],["尽管已经很晚了，可是她仍然在学习。","jǐn guǎn yǐ jīng hěn wǎn le kě shì tā réng rán zài xué xí","Mặc dù đã rất muộn rồi nhưng cô ấy vẫn đang học."]]},{"n":78,"c":["句子的类型","复句","转折复句"],"z":"……，然而……","t":"Câu phức chuyển ngoặt: ……，然而……","d":"= …, nhưng/thế nhưng… (văn viết).","e":[["我知道那部电影很有意思，然而太忙了，一直没时间看。","wǒ zhī dao nà bù diàn yǐng hěn yǒu yì si rán ér tài máng le yì zhí méi shí jiān kàn","Tôi biết bộ phim đó rất hay, thế nhưng bận quá, mãi không có thời gian xem."],["她以为能轻松通过考试，然而成绩却不太好。","tā yǐ wéi néng qīng sōng tōng guò kǎo shì rán ér chéng jì què bú tài hǎo","Cô ấy tưởng có thể dễ dàng vượt qua kỳ thi, thế nhưng kết quả lại không tốt lắm."]]},{"n":79,"c":["句子的类型","复句","转折复句"],"z":"……，不过……","t":"Câu phức chuyển ngoặt: ……，不过……","d":"= …, có điều/nhưng… (nhẹ nhàng hơn 但是).","e":[["我很想参加你的生日晚会，不过我明天有考试，得好好复习。","wǒ hěn xiǎng cān jiā nǐ de shēng rì wǎn huì bú guò wǒ míng tiān yǒu kǎo shì děi hǎo hǎo fù xí","Tôi rất muốn dự tiệc sinh nhật của bạn, có điều ngày mai tôi có bài thi, phải ôn tập cho tốt."],["他只学了三个月中文，不过已经说得不错了。","tā zhǐ xué le sān gè yuè zhōng wén bú guò yǐ jīng shuō de bú cuò le","Anh ấy mới học tiếng Trung ba tháng, nhưng đã nói khá tốt rồi."]]},{"n":80,"c":["句子的类型","复句","转折复句"],"z":"……X是X，就是/不过……","t":"Câu phức chuyển ngoặt: ……X是X，就是/不过……","d":"= …thì có…, chỉ là/có điều….","e":[["这些衣服便宜是便宜，就是感觉质量不太好。","zhè xiē yī fu pián yi shì pián yi jiù shì gǎn jué zhì liàng bú tài hǎo","Những bộ quần áo này rẻ thì có rẻ, chỉ là cảm thấy chất lượng không tốt lắm."],["小张这个人聪明是聪明，不过有时候比较懒。","xiǎo zhāng zhè ge rén cōng ming shì cōng ming bú guò yǒu shí hou bǐ jiào lǎn","Cậu Trương này thông minh thì có thông minh, có điều đôi khi hơi lười."]]},{"n":81,"c":["句子的类型","复句","假设复句"],"z":"……，否则……","t":"Câu phức giả thiết: ……，否则……","d":"= …, nếu không thì….","e":[["你下了飞机记得给妈妈打个电话，否则她会一直担心你。","nǐ xià le fēi jī jì de gěi mā ma dǎ gè diàn huà fǒu zé tā huì yì zhí dān xīn nǐ","Xuống máy bay nhớ gọi điện cho mẹ, nếu không mẹ sẽ cứ lo cho bạn."],["课后一定要经常复习，否则很快就会忘记。","kè hòu yí dìng yào jīng cháng fù xí fǒu zé hěn kuài jiù huì wàng jì","Sau giờ học nhất định phải thường xuyên ôn tập, nếu không sẽ quên rất nhanh."]]},{"n":82,"c":["句子的类型","复句","假设复句"],"z":"要是……，就……","t":"Câu phức giả thiết: 要是……，就……","d":"= Nếu…thì… (khẩu ngữ).","e":[["你要是想取得成功，就必须坚持到底。","nǐ yào shi xiǎng qǔ dé chéng gōng jiù bì xū jiān chí dào dǐ","Nếu bạn muốn thành công thì phải kiên trì đến cùng."],["要是人人都能节约用水，地球的环境就能得到更好的保护。","yào shì rén rén dōu néng jié yuē yòng shuǐ dì qiú de huán jìng jiù néng dé dào gèng hǎo de bǎo hù","Nếu ai ai cũng tiết kiệm nước thì môi trường trái đất sẽ được bảo vệ tốt hơn."]]},{"n":83,"c":["句子的类型","复句","假设复句"],"z":"要是……，（就）……，否则……","t":"Câu phức giả thiết: 要是……，(就)……，否则……","d":"= Nếu…thì…, nếu không thì….","e":[["要是你打算假期去旅游，就提前上网订票，否则到时候就买不到了。","yào shi nǐ dǎ suàn jià qī qù lǚ yóu jiù tí qián shàng wǎng dìng piào fǒu zé dào shí hou jiù mǎi bú dào le","Nếu bạn định đi du lịch vào kỳ nghỉ thì đặt vé trên mạng trước, nếu không đến lúc đó sẽ không mua được."],["要是你不常穿，最好就不要买，否则买了也是浪费。","yào shi nǐ bù cháng chuān zuì hǎo jiù bú yào mǎi fǒu zé mǎi le yě shì làng fèi","Nếu bạn không hay mặc thì tốt nhất đừng mua, nếu không mua về cũng phí."]]},{"n":84,"c":["句子的类型","复句","条件复句"],"z":"不管……，都/也……","t":"Câu phức điều kiện: 不管……，都/也……","d":"= Bất kể…đều/cũng…. Vế 不管 thường có từ để hỏi hoặc lựa chọn.","e":[["不管在什么地方，说话、办事都要有礼貌。","bù guǎn zài shén me dì fang shuō huà bàn shì dōu yào yǒu lǐ mào","Bất kể ở đâu, nói năng, làm việc đều phải lịch sự."],["不管别人怎么说，我也不会改变主意。","bù guǎn bié rén zěn me shuō wǒ yě bú huì gǎi biàn zhǔ yì","Bất kể người khác nói gì, tôi cũng sẽ không thay đổi ý định."]]},{"n":85,"c":["句子的类型","复句","条件复句"],"z":"无论……，都/也……","t":"Câu phức điều kiện: 无论……，都/也……","d":"= Bất luận…đều/cũng… (trang trọng hơn 不管).","e":[["无论在多么紧张的情况下，他都表现得非常冷静。","wú lùn zài duō me jǐn zhāng de qíng kuàng xià tā dōu biǎo xiàn de fēi cháng lěng jìng","Bất luận trong tình huống căng thẳng đến mức nào, anh ấy đều tỏ ra vô cùng bình tĩnh."],["无论遇到多大的困难，我们也不应该随便放弃。","wú lùn yù dào duō dà de kùn nán wǒ men yě bú yīng gāi suí biàn fàng qì","Bất luận gặp khó khăn lớn đến đâu, chúng ta cũng không nên tùy tiện bỏ cuộc."]]},{"n":86,"c":["句子的类型","复句","因果复句"],"z":"既然……，就……","t":"Câu phức nhân quả: 既然……，就……","d":"= Đã…thì… (dựa vào sự thật đã có để suy ra).","e":[["既然你这么喜欢小孩儿，毕业以后就当老师吧。","jì rán nǐ zhè me xǐ huan xiǎo hái r bì yè yǐ hòu jiù dāng lǎo shī ba","Bạn đã thích trẻ con như vậy thì tốt nghiệp xong đi làm giáo viên đi."],["既然来了，就进屋喝杯茶吧。","jì rán lái le jiù jìn wū hē bēi chá ba","Đã đến rồi thì vào nhà uống chén trà đi."]]},{"n":87,"c":["句子的类型","复句","因果复句"],"z":"（由于）……，因此……","t":"Câu phức nhân quả: (由于)……，因此……","d":"= (Do)…, vì vậy….","e":[["由于您没带护照，因此不能办理银行卡。","yóu yú nín méi dài hù zhào yīn cǐ bù néng bàn lǐ yín háng kǎ","Do ông/bà không mang hộ chiếu nên không thể làm thẻ ngân hàng."],["我对京剧很感兴趣，因此报名参加了这次活动。","wǒ duì jīng jù hěn gǎn xìng qù yīn cǐ bào míng cān jiā le zhè cì huó dòng","Tôi rất hứng thú với Kinh kịch, vì vậy đã đăng ký tham gia hoạt động lần này."]]},{"n":88,"c":["句子的类型","复句","目的复句"],"z":"……，好……","t":"Câu phức mục đích: ……，好……","d":"= …, để…(có thể).","e":[["我每天都给父母打电话，好让他们放心。","wǒ měi tiān dōu gěi fù mǔ dǎ diàn huà hǎo ràng tā men fàng xīn","Ngày nào tôi cũng gọi điện cho bố mẹ để họ yên tâm."],["我们应该多鼓励他，好让他有信心。","wǒ men yīng gāi duō gǔ lì tā hǎo ràng tā yǒu xìn xīn","Chúng ta nên động viên anh ấy nhiều để anh ấy có tự tin."]]},{"n":89,"c":["句子的类型","复句","让步复句"],"z":"即使……，也……","t":"Câu phức nhượng bộ: 即使……，也……","d":"= Cho dù…cũng….","e":[["你即使干到明天早上，恐怕也干不完。","nǐ jí shǐ gàn dào míng tiān zǎo shang kǒng pà yě gàn bù wán","Cho dù bạn làm đến sáng mai, e là cũng làm không xong."],["即使工作再忙，也要常回家看看父母。","jí shǐ gōng zuò zài máng yě yào cháng huí jiā kàn kàn fù mǔ","Cho dù công việc bận đến đâu cũng phải thường xuyên về nhà thăm bố mẹ."]]},{"n":90,"c":["句子的类型","复句","让步复句"],"z":"就是……，也……","t":"Câu phức nhượng bộ: 就是……，也……","d":"= Cho dù…cũng… (khẩu ngữ).","e":[["我今天晚上就是不睡觉，也必须解决这个问题。","wǒ jīn tiān wǎn shang jiù shì bú shuì jiào yě bì xū jiě jué zhè ge wèn tí","Tối nay cho dù không ngủ, tôi cũng phải giải quyết vấn đề này."],["你就是不同意，我也不会改变自己的决定。","nǐ jiù shì bù tóng yì wǒ yě bú huì gǎi biàn zì jǐ de jué dìng","Cho dù bạn không đồng ý, tôi cũng sẽ không thay đổi quyết định của mình."]]},{"n":91,"c":["句子的类型","复句","紧缩复句"],"z":"无标记","t":"Câu rút gọn không có từ nối","d":"Hai vế ghép sát nhau, không dấu phẩy, quan hệ hiểu qua ngữ cảnh (giả thiết, điều kiện…).","e":[["你着急你先走吧。","nǐ zháo jí nǐ xiān zǒu ba","Bạn vội thì bạn cứ đi trước đi."],["站得高看得远。","zhàn de gāo kàn de yuǎn","Đứng cao thì nhìn xa."],["他同意我不同意。","tā tóng yì wǒ bù tóng yì","Anh ấy đồng ý nhưng tôi không đồng ý."]]},{"n":92,"c":["句子的类型","复句","紧缩复句"],"z":"不……也……","t":"Câu rút gọn: 不……也……","d":"= Không…cũng phải… / dù không…cũng….","e":[["今晚我不睡觉也要把作业写完。","jīn wǎn wǒ bú shuì jiào yě yào bǎ zuò yè xiě wán","Tối nay tôi không ngủ cũng phải làm xong bài tập."],["你不喜欢做也得做。","nǐ bù xǐ huan zuò yě děi zuò","Bạn không thích làm cũng phải làm."]]},{"n":93,"c":["特殊表达法","数的表示法",""],"z":"概数表示法3：数词+来+量词","t":"Số ước lượng: số + 来 + lượng từ","d":"来 = khoảng, chừng (xấp xỉ hoặc hơn một chút), dùng với số tròn: 三百来间 = khoảng ba trăm phòng.","e":[["我们的宿舍楼有三百来间房。","wǒ men de sù shè lóu yǒu sān bǎi lái jiān fáng","Ký túc xá của chúng tôi có khoảng ba trăm phòng."],["书架上放着一百来本书。","shū jià shàng fàng zhe yì bǎi lái běn shū","Trên giá sách để khoảng một trăm quyển sách."],["这条大鱼估计有十来斤重。","zhè tiáo dà yú gū jì yǒu shí lái jīn zhòng","Con cá to này ước chừng nặng khoảng mười cân."]]},{"n":94,"c":["特殊表达法","数的表示法",""],"z":"用“大约、左右、前后”表示概数","t":"Số ước lượng với 大约, 左右, 前后","d":"大约 + số = khoảng (đứng trước); số + 左右 = khoảng, tầm (đứng sau); thời điểm + 前后 = trước sau, xung quanh (thời gian).","e":[["客人大约下午两点到公司参观。","kè rén dà yuē xià wǔ liǎng diǎn dào gōng sī cān guān","Khách khoảng hai giờ chiều sẽ đến tham quan công ty."],["我的中文老师四十岁左右。","wǒ de zhōng wén lǎo shī sì shí suì zuǒ yòu","Thầy giáo tiếng Trung của tôi khoảng bốn mươi tuổi."],["春节前后，很多商场有打折活动。","chūn jié qián hòu hěn duō shāng chǎng yǒu dǎ zhé huó dòng","Khoảng trước sau Tết, nhiều trung tâm thương mại có chương trình giảm giá."]]},{"n":95,"c":["特殊表达法","数的表示法",""],"z":"小数、分数、百分数、倍数的表示法","t":"Số thập phân, phân số, phần trăm, bội số","d":"点 = phẩy (零点五 = 0,5); 分之 = phần (三分之一 = 1/3, đọc mẫu số trước); 百分之二十 = 20%; 倍 = lần (提高了两倍 = tăng thêm hai lần).","e":[["零点五、三分之一、百分之二十、两倍","líng diǎn wǔ sān fēn zhī yī bǎi fēn zhī èr shí liǎng bèi","không phẩy năm, một phần ba, hai mươi phần trăm, hai lần"],["老师听写了二十个汉字，每个汉字零点五分，一共十分。","lǎo shī tīng xiě le èr shí gè hàn zì měi gè hàn zì líng diǎn wǔ fēn yí gòng shí fēn","Thầy giáo cho chép chính tả hai mươi chữ Hán, mỗi chữ 0,5 điểm, tổng cộng mười điểm."],["我们班有三分之一的同学没去过长城。","wǒ men bān yǒu sān fēn zhī yī de tóng xué méi qù guò cháng chéng","Lớp chúng tôi có một phần ba số bạn chưa đến Trường Thành."],["跟去年相比，今年游客的数量减少了百分之二十。","gēn qù nián xiāng bǐ jīn nián yóu kè de shù liàng jiǎn shǎo le bǎi fēn zhī èr shí","So với năm ngoái, số lượng du khách năm nay giảm hai mươi phần trăm."],["我的收入比去年提高了两倍。","wǒ de shōu rù bǐ qù nián tí gāo le liǎng bèi","Thu nhập của tôi đã tăng thêm hai lần so với năm ngoái."]]}],"5":[{"n":1,"c":["语素","后缀",""],"z":"—头","t":"Hậu tố 头","d":"Danh từ/phương vị + 头 (đọc thanh nhẹ \"tou\"): 石头 = hòn đá, 里头 = bên trong.","e":[["那块石头上刻着一些汉字。","nà kuài shí tou shàng kè zhe yì xiē hàn zì","Trên tảng đá kia có khắc một số chữ Hán."],["那本书里头是不是有一封信？","nà běn shū lǐ tou shì bu shì yǒu yì fēng xìn","Trong quyển sách kia có phải có một bức thư không?"]]},{"n":2,"c":["词类","代词","指示代词"],"z":"彼此、如此、本","t":"Đại từ chỉ thị 彼此, 如此, 本","d":"彼此 = lẫn nhau, đôi bên; 如此 = như thế, như vậy (văn viết); 本 = này, của chúng tôi (本规定 = quy định này, 本次 = lần/chuyến này).","e":[["在日常交流中，我们应该尊重彼此。","zài rì cháng jiāo liú zhōng wǒ men yīng gāi zūn zhòng bǐ cǐ","Trong giao tiếp hằng ngày, chúng ta nên tôn trọng lẫn nhau."],["他们已经认识很久了，对彼此的习惯非常了解。","tā men yǐ jīng rèn shi hěn jiǔ le duì bǐ cǐ de xí guàn fēi cháng liǎo jiě","Họ đã quen nhau rất lâu rồi, rất hiểu thói quen của nhau."],["这里的夏天异常炎热，年年如此。","zhè lǐ de xià tiān yì cháng yán rè nián nián rú cǐ","Mùa hè ở đây nóng bức lạ thường, năm nào cũng vậy."],["很多人都没有想到乡村的变化如此巨大。","hěn duō rén dōu méi yǒu xiǎng dào xiāng cūn de biàn huà rú cǐ jù dà","Rất nhiều người không ngờ nông thôn lại thay đổi to lớn như vậy."],["本规定自明日起正式实施。","běn guī dìng zì míng rì qǐ zhèng shì shí shī","Quy định này chính thức có hiệu lực từ ngày mai."],["本次列车开往北京西站。","běn cì liè chē kāi wǎng běi jīng xī zhàn","Chuyến tàu này chạy đến ga Bắc Kinh Tây."]]},{"n":3,"c":["词类","量词","名量词"],"z":"册、朵、届、颗、匹、行、架、群、支、根、批、束、副、集、周","t":"Lượng từ chuyên dùng (nhóm 5)","d":"册 cuốn/tập, 朵 bông (hoa, mây), 届 khóa/lần (hội nghị, khóa học), 颗 hạt/viên/ngôi (sao), 匹 con (ngựa), 行 hàng/dòng, 架 chiếc (máy bay), 群 đàn/bầy/nhóm, 支 đội/cây (bút), 根 cây/sợi (vật dài mảnh), 批 lô/đợt, 束 bó, 副 đôi/cặp (găng tay, kính), 集 tập (phim), 周 vòng.","e":[["这册历史书讲述了古代中国的发展过程。","zhè cè lì shǐ shū jiǎng shù le gǔ dài zhōng guó de fā zhǎn guò chéng","Cuốn sách lịch sử này kể về quá trình phát triển của Trung Quốc cổ đại."],["第一次见面时他送给了我一朵玫瑰花。","dì yī cì jiàn miàn shí tā sòng gěi le wǒ yì duǒ méi guī huā","Lần đầu gặp mặt anh ấy đã tặng tôi một bông hoa hồng."],["这届会议讨论了许多重要的话题。","zhè jiè huì yì tǎo lùn le xǔ duō zhòng yào de huà tí","Hội nghị khóa này đã thảo luận nhiều chủ đề quan trọng."],["城市夜晚的天空中几乎看不到几颗星星。","chéng shì yè wǎn de tiān kōng zhōng jī hū kàn bú dào jǐ kē xīng xīng","Trên bầu trời đêm thành phố hầu như không nhìn thấy mấy ngôi sao."],["那匹马跑得特别快，赢得了这次比赛。","nà pǐ mǎ pǎo de tè bié kuài yíng dé le zhè cì bǐ sài","Con ngựa đó chạy cực nhanh, đã thắng cuộc đua lần này."],["她在表格的最后一行写上了自己的名字。","tā zài biǎo gé de zuì hòu yì háng xiě shàng le zì jǐ de míng zi","Cô ấy viết tên mình vào dòng cuối cùng của bảng biểu."],["那架飞机在空中飞行了很久，最终安全降落。","nà jià fēi jī zài kōng zhōng fēi xíng le hěn jiǔ zuì zhōng ān quán jiàng luò","Chiếc máy bay đó bay trên không rất lâu, cuối cùng hạ cánh an toàn."],["一群可爱的孩子正在舞台上表演节目。","yì qún kě ài de hái zi zhèng zài wǔ tái shàng biǎo yǎn jié mù","Một nhóm trẻ em đáng yêu đang biểu diễn tiết mục trên sân khấu."],["这支队伍非常优秀，连续几年都获得了冠军。","zhè zhī duì wu fēi cháng yōu xiù lián xù jǐ nián dōu huò dé le guàn jūn","Đội này rất xuất sắc, liên tục mấy năm liền đều giành chức vô địch."],["他一不小心把一根筷子掉在了地上。","tā yí bù xiǎo xīn bǎ yì gēn kuài zi diào zài le dì shàng","Anh ấy không cẩn thận làm rơi một chiếc đũa xuống đất."],["王经理正在培训这批新员工。","wáng jīng lǐ zhèng zài péi xùn zhè pī xīn yuán gōng","Giám đốc Vương đang đào tạo đợt nhân viên mới này."],["为了表示对朋友的欢迎，他特意买了一束花。","wèi le biǎo shì duì péng you de huān yíng tā tè yì mǎi le yí shù huā","Để bày tỏ sự chào đón bạn, anh ấy đã đặc biệt mua một bó hoa."],["选来选去还是这副手套戴着最舒服。","xuǎn lái xuǎn qù hái shì zhè fù shǒu tào dài zhe zuì shū fu","Chọn tới chọn lui, vẫn là đôi găng tay này đeo thoải mái nhất."],["别看书了，打开电视，看两集电视剧吧。","bié kàn shū le dǎ kāi diàn shì kàn liǎng jí diàn shì jù ba","Đừng đọc sách nữa, bật tivi xem hai tập phim truyền hình đi."],["地球绕太阳一周需要一年。","dì qiú rào tài yáng yì zhōu xū yào yì nián","Trái đất quay quanh mặt trời một vòng mất một năm."]]},{"n":4,"c":["词类","量词","动量词"],"z":"眼","t":"Động lượng từ 眼","d":"看 + 一眼 = liếc nhìn một cái.","e":[["新娘看了一眼新郎，害羞得低下了头。","xīn niáng kàn le yì yǎn xīn láng hài xiū de dī xià le tóu","Cô dâu liếc nhìn chú rể một cái, ngượng ngùng cúi đầu."]]},{"n":5,"c":["词类","副词","程度副词"],"z":"过于、相当、较¹、可²、格外、极其","t":"Phó từ mức độ 过于, 相当, 较, 可, 格外, 极其","d":"过于 = quá (mức, mang ý chê); 相当 = khá, tương đối (mức cao); 较 = tương đối, khá (văn viết); 可 + tính từ + 了 = …lắm cơ (khẩu ngữ, nhấn mạnh); 格外 = đặc biệt, khác thường; 极其 = cực kỳ (văn viết).","e":[["他在面试时过于紧张，连话都说不清楚了。","tā zài miàn shì shí guò yú jǐn zhāng lián huà dōu shuō bù qīng chu le","Lúc phỏng vấn anh ấy quá căng thẳng, đến nói cũng không rõ ràng."],["过于追求完美反而会让人总是对现状不满意。","guò yú zhuī qiú wán měi fǎn ér huì ràng rén zǒng shì duì xiàn zhuàng bù mǎn yì","Quá theo đuổi sự hoàn hảo ngược lại sẽ khiến người ta luôn không hài lòng với hiện tại."],["这次考试的题目相当难，很多同学都没有及格。","zhè cì kǎo shì de tí mù xiāng dāng nán hěn duō tóng xué dōu méi yǒu jí gé","Đề thi lần này khá khó, rất nhiều bạn không đạt."],["他的中文水平相当不错，可以和中国人流利对话。","tā de zhōng wén shuǐ píng xiāng dāng bú cuò kě yǐ hé zhōng guó rén liú lì duì huà","Trình độ tiếng Trung của anh ấy khá tốt, có thể nói chuyện trôi chảy với người Trung Quốc."],["如何才能在短期内较快地提高中文水平？","rú hé cái néng zài duǎn qī nèi jiào kuài de tí gāo zhōng wén shuǐ píng","Làm thế nào để nâng cao trình độ tiếng Trung tương đối nhanh trong thời gian ngắn?"],["年轻人学习新事物的能力较强，能够很快适应新的环境。","nián qīng rén xué xí xīn shì wù de néng lì jiào qiáng néng gòu hěn kuài shì yìng xīn de huán jìng","Khả năng học cái mới của người trẻ khá mạnh, có thể nhanh chóng thích nghi với môi trường mới."],["那家公司今年推出的新产品可受欢迎了。","nà jiā gōng sī jīn nián tuī chū de xīn chǎn pǐn kě shòu huān yíng le","Sản phẩm mới công ty đó ra mắt năm nay được ưa chuộng lắm."],["这部电影拍得可精彩了，你千万不能错过！","zhè bù diàn yǐng pāi de kě jīng cǎi le nǐ qiān wàn bù néng cuò guò","Bộ phim này quay hay lắm, bạn nhất định không được bỏ lỡ!"],["这家餐厅的服务态度格外热情，常常需要提前预约。","zhè jiā cān tīng de fú wù tài dù gé wài rè qíng cháng cháng xū yào tí qián yù yuē","Thái độ phục vụ của nhà hàng này đặc biệt nhiệt tình, thường phải đặt trước."],["国庆假期的景区格外热闹，到处都是外地来的游客。","guó qìng jià qī de jǐng qū gé wài rè nao dào chù dōu shì wài dì lái de yóu kè","Khu du lịch dịp nghỉ lễ Quốc khánh đặc biệt náo nhiệt, khắp nơi đều là du khách từ nơi khác đến."],["那天的天气极其恶劣，我们不得不取消旅行计划。","nà tiān de tiān qì jí qí è liè wǒ men bù dé bù qǔ xiāo lǚ xíng jì huà","Thời tiết hôm đó cực kỳ xấu, chúng tôi buộc phải hủy kế hoạch du lịch."],["这次旅行给我留下了极其深刻的印象，尤其是当地的美食和历史。","zhè cì lǚ xíng gěi wǒ liú xià le jí qí shēn kè de yìn xiàng yóu qí shì dāng dì de měi shí hé lì shǐ","Chuyến du lịch này để lại cho tôi ấn tượng cực kỳ sâu sắc, nhất là ẩm thực và lịch sử địa phương."]]},{"n":6,"c":["词类","副词","时间副词"],"z":"时刻、曾经、立刻、连忙、始终、早已、即将、急忙、渐渐、尽快、早晚","t":"Phó từ thời gian 时刻, 曾经, 立刻, 连忙, 始终, 早已, 即将, 急忙, 渐渐, 尽快, 早晚","d":"时刻 = luôn luôn, từng giây phút; 曾经 = đã từng; 立刻 = lập tức; 连忙/急忙 = vội vàng (chỉ dùng kể việc đã xảy ra); 始终 = trước sau vẫn, luôn; 早已 = đã từ lâu; 即将 = sắp sửa; 渐渐 = dần dần; 尽快 = càng sớm càng tốt; 早晚 = sớm muộn gì.","e":[["父母要时刻关心孩子的心理健康。","fù mǔ yào shí kè guān xīn hái zi de xīn lǐ jiàn kāng","Bố mẹ phải luôn quan tâm đến sức khỏe tâm lý của con cái."],["他提醒我旅行时一定要时刻注意自己的护照和钱包。","tā tí xǐng wǒ lǚ xíng shí yí dìng yào shí kè zhù yì zì jǐ de hù zhào hé qián bāo","Anh ấy nhắc tôi khi đi du lịch nhất định phải luôn chú ý hộ chiếu và ví tiền của mình."],["她曾经当过导游，在设计旅行线路方面很有经验。","tā céng jīng dāng guò dǎo yóu zài shè jì lǚ xíng xiàn lù fāng miàn hěn yǒu jīng yàn","Cô ấy từng làm hướng dẫn viên du lịch, rất có kinh nghiệm trong việc thiết kế tuyến du lịch."],["王校长去年曾经来我们学校访问过。","wáng xiào zhǎng qù nián céng jīng lái wǒ men xué xiào fǎng wèn guò","Năm ngoái hiệu trưởng Vương từng đến thăm trường chúng tôi."],["为了迎接客人的到来，他一下班就立刻回家准备晚餐。","wèi le yíng jiē kè rén de dào lái tā yí xià bān jiù lì kè huí jiā zhǔn bèi wǎn cān","Để đón khách, anh ấy vừa tan làm đã lập tức về nhà chuẩn bị bữa tối."],["张教授刚说完，学生们就立刻认真地写起来。","zhāng jiào shòu gāng shuō wán xué shēng men jiù lì kè rèn zhēn de xiě qǐ lái","Giáo sư Trương vừa nói xong, các sinh viên lập tức chăm chú viết."],["妈妈连忙检查摔倒的孩子有没有受伤。","mā ma lián máng jiǎn chá shuāi dǎo de hái zi yǒu méi yǒu shòu shāng","Mẹ vội vàng kiểm tra đứa bé bị ngã có bị thương không."],["他连忙向交警解释自己并非故意违反交通规则。","tā lián máng xiàng jiāo jǐng jiě shì zì jǐ bìng fēi gù yì wéi fǎn jiāo tōng guī zé","Anh ấy vội vàng giải thích với cảnh sát giao thông rằng mình không cố ý vi phạm luật giao thông."],["最近一年，这套教材的销量始终保持增长。","zuì jìn yì nián zhè tào jiào cái de xiāo liàng shǐ zhōng bǎo chí zēng zhǎng","Một năm gần đây, lượng bán bộ giáo trình này luôn duy trì tăng trưởng."],["无论如何，亲朋好友始终是你的依靠。","wú lùn rú hé qīn péng hǎo yǒu shǐ zhōng shì nǐ de yī kào","Dù thế nào đi nữa, người thân bạn bè trước sau vẫn là chỗ dựa của bạn."],["这里的乡村早已实现了现代化，不再是当年的样子。","zhè lǐ de xiāng cūn zǎo yǐ shí xiàn le xiàn dài huà bú zài shì dāng nián de yàng zi","Nông thôn ở đây đã hiện đại hóa từ lâu, không còn như năm xưa nữa."],["科学家早已研发出治疗这种疾病的药物。","kē xué jiā zǎo yǐ yán fā chū zhì liáo zhè zhǒng jí bìng de yào wù","Các nhà khoa học đã nghiên cứu ra thuốc điều trị bệnh này từ lâu."],["明天公司即将召开新品发布会，欢迎大家参加！","míng tiān gōng sī jí jiāng zhào kāi xīn pǐn fā bù huì huān yíng dà jiā cān jiā","Ngày mai công ty sắp tổ chức buổi ra mắt sản phẩm mới, hoan nghênh mọi người tham dự!"],["他们的婚礼即将在下个月举行。","tā men de hūn lǐ jí jiāng zài xià gè yuè jǔ xíng","Đám cưới của họ sắp được tổ chức vào tháng sau."],["听到消息后，她急忙收拾行李赶往机场。","tīng dào xiāo xī hòu tā jí máng shōu shi xíng li gǎn wǎng jī chǎng","Nghe tin xong, cô ấy vội vàng thu dọn hành lý chạy ra sân bay."],["车祸发生后，他急忙打电话叫救护车。","chē huò fā shēng hòu tā jí máng dǎ diàn huà jiào jiù hù chē","Sau khi tai nạn xảy ra, anh ấy vội gọi điện gọi xe cấp cứu."],["计算机技术渐渐成为各行各业的关键技术。","jì suàn jī jì shù jiàn jiàn chéng wéi gè háng gè yè de guān jiàn jì shù","Công nghệ máy tính dần dần trở thành công nghệ then chốt của mọi ngành nghề."],["春天一到，气温就开始渐渐上升了。","chūn tiān yí dào qì wēn jiù kāi shǐ jiàn jiàn shàng shēng le","Mùa xuân vừa đến, nhiệt độ bắt đầu tăng dần."],["如果您有任何问题，请尽快联系我。","rú guǒ nín yǒu rèn hé wèn tí qǐng jǐn kuài lián xì wǒ","Nếu ông/bà có bất kỳ vấn đề gì, xin hãy liên hệ với tôi càng sớm càng tốt."],["医生建议他尽快接受手术治疗。","yī shēng jiàn yì tā jǐn kuài jiē shòu shǒu shù zhì liáo","Bác sĩ khuyên anh ấy nên phẫu thuật điều trị càng sớm càng tốt."],["他们再这样一直吵下去，早晚会离婚的。","tā men zài zhè yàng yì zhí chǎo xià qù zǎo wǎn huì lí hūn de","Họ cứ cãi nhau mãi như thế này thì sớm muộn gì cũng ly hôn."],["父母应该明白，孩子早晚是要独立生活的。","fù mǔ yīng gāi míng bai hái zi zǎo wǎn shì yào dú lì shēng huó de","Bố mẹ nên hiểu rằng con cái sớm muộn gì cũng phải sống tự lập."]]},{"n":7,"c":["词类","副词","频率副词"],"z":"老是、通常、时常","t":"Phó từ tần suất 老是, 通常, 时常","d":"老是 = cứ, luôn (khẩu ngữ, thường không hài lòng); 通常 = thông thường; 时常 = thường thường.","e":[["他最近老是熬夜，所以脸色很不好。","tā zuì jìn lǎo shì áo yè suǒ yǐ liǎn sè hěn bù hǎo","Dạo này anh ấy cứ thức khuya nên sắc mặt rất kém."],["你出门老是忘记带钥匙，这个坏习惯一定要改！","nǐ chū mén lǎo shì wàng jì dài yào shi zhè ge huài xí guàn yí dìng yào gǎi","Bạn ra ngoài cứ quên mang chìa khóa, thói xấu này nhất định phải sửa!"],["旅行社通常在寒暑假生意更好。","lǚ xíng shè tōng cháng zài hán shǔ jià shēng yì gèng hǎo","Công ty du lịch thông thường làm ăn tốt hơn vào kỳ nghỉ đông và hè."],["中国的大学通常会为学生提供更换专业的机会。","zhōng guó de dà xué tōng cháng huì wèi xué shēng tí gōng gēng huàn zhuān yè de jī huì","Các trường đại học Trung Quốc thông thường sẽ cho sinh viên cơ hội đổi chuyên ngành."],["他时常下班后去公园散步，顺便放松一下心情。","tā shí cháng xià bān hòu qù gōng yuán sàn bù shùn biàn fàng sōng yí xià xīn qíng","Anh ấy thường đi dạo công viên sau giờ làm, nhân tiện thư giãn tinh thần."],["夫妻二人的工作都很忙，所以时常没有人做家务。","fū qī èr rén de gōng zuò dōu hěn máng suǒ yǐ shí cháng méi yǒu rén zuò jiā wù","Công việc của hai vợ chồng đều rất bận nên thường không có ai làm việc nhà."]]},{"n":8,"c":["词类","副词","方式副词"],"z":"尽量、亲自","t":"Phó từ cách thức 尽量, 亲自","d":"尽量 = cố gắng hết mức; 亲自 = đích thân, tự mình.","e":[["冬天尽量少吃雪糕，容易着凉。","dōng tiān jǐn liàng shǎo chī xuě gāo róng yì zháo liáng","Mùa đông cố gắng ăn ít kem, dễ bị nhiễm lạnh."],["请大家尽量在本周五提交论文。","qǐng dà jiā jǐn liàng zài běn zhōu wǔ tí jiāo lùn wén","Mời mọi người cố gắng nộp luận văn trong thứ Sáu tuần này."],["公司老板亲自参与了新产品的设计与开发。","gōng sī lǎo bǎn qīn zì cān yù le xīn chǎn pǐn de shè jì yǔ kāi fā","Ông chủ công ty đã đích thân tham gia thiết kế và phát triển sản phẩm mới."],["这些点心是我亲自为你做的。","zhè xiē diǎn xīn shì wǒ qīn zì wèi nǐ zuò de","Những món điểm tâm này là tự tay tôi làm cho bạn."]]},{"n":9,"c":["词类","副词","关联副词"],"z":"便、一旦","t":"Phó từ liên kết 便, 一旦","d":"便 = liền, thì (văn viết của 就); 一旦 = một khi, hễ mà.","e":[["会议一结束，我便赶回公司了。","huì yì yì jié shù wǒ biàn gǎn huí gōng sī le","Cuộc họp vừa kết thúc, tôi liền vội về công ty."],["这个学生很聪明，一教便懂。","zhè ge xué shēng hěn cōng ming yí jiāo biàn dǒng","Học sinh này rất thông minh, dạy một lần là hiểu."],["一旦确定了目标，就不要放弃。","yí dàn què dìng le mù biāo jiù bú yào fàng qì","Một khi đã xác định mục tiêu thì đừng bỏ cuộc."],["这次机会非常难得，一旦错过了，你会后悔的。","zhè cì jī huì fēi cháng nán dé yí dàn cuò guò le nǐ huì hòu huǐ de","Cơ hội lần này rất hiếm có, một khi bỏ lỡ, bạn sẽ hối hận đấy."]]},{"n":10,"c":["词类","副词","情态副词"],"z":"似乎、仿佛","t":"Phó từ tình thái 似乎, 仿佛","d":"似乎 = dường như, hình như; 仿佛 = dường như, như thể (hay đi với 似的).","e":[["他似乎在犹豫要不要接受这份新工作。","tā sì hū zài yóu yù yào bu yào jiē shòu zhè fèn xīn gōng zuò","Anh ấy dường như đang do dự có nên nhận công việc mới này không."],["这家便利店似乎两周前就关门了。","zhè jiā biàn lì diàn sì hū liǎng zhōu qián jiù guān mén le","Cửa hàng tiện lợi này hình như đã đóng cửa từ hai tuần trước."],["我们仿佛在哪儿见过似的。","wǒ men fǎng fú zài nǎ r jiàn guò shì de","Chúng ta dường như đã gặp nhau ở đâu đó rồi thì phải."],["他俩见面不打招呼，仿佛谁也不认识谁。","tā liǎ jiàn miàn bù dǎ zhāo hu fǎng fú shuí yě bú rèn shi shuí","Hai người họ gặp nhau không chào hỏi, như thể chẳng ai quen ai."]]},{"n":11,"c":["词类","副词","语气副词"],"z":"毕竟、居然、反正、根本、果然、简直、绝对、的确、反而、白、刚好、可³","t":"Phó từ ngữ khí 毕竟, 居然, 反正, 根本, 果然, 简直, 绝对, 的确, 反而, 白, 刚好, 可","d":"毕竟 = dù sao thì, suy cho cùng; 居然 = vậy mà (bất ngờ); 反正 = dù sao, đằng nào cũng; 根本 = hoàn toàn (không), căn bản; 果然 = quả nhiên; 简直 = quả thật là, đúng là (cường điệu); 绝对 = tuyệt đối; 的确 = quả thật; 反而 = ngược lại; 白 = uổng công, vô ích; 刚好 = vừa đúng lúc; 可 = nhất định, thật (nhấn mạnh trong câu cầu khiến).","e":[["毕竟他刚来公司一个月，还需要时间适应。","bì jìng tā gāng lái gōng sī yí gè yuè hái xū yào shí jiān shì yìng","Dù sao anh ấy mới đến công ty một tháng, vẫn cần thời gian thích nghi."],["他毕竟是个孩子，有些错误可以被原谅。","tā bì jìng shì gè hái zi yǒu xiē cuò wù kě yǐ bèi yuán liàng","Dù sao nó cũng chỉ là đứa trẻ, có những lỗi có thể được tha thứ."],["昨天我才发现新来的同事居然是我的邻居。","zuó tiān wǒ cái fā xiàn xīn lái de tóng shì jū rán shì wǒ de lín jū","Hôm qua tôi mới phát hiện đồng nghiệp mới đến vậy mà là hàng xóm của tôi."],["这么冷的天他居然没穿外套。","zhè me lěng de tiān tā jū rán méi chuān wài tào","Trời lạnh thế này mà anh ấy vậy mà không mặc áo khoác."],["你要去就去吧，反正我肯定不会去。","nǐ yào qù jiù qù ba fǎn zhèng wǒ kěn dìng bú huì qù","Bạn muốn đi thì đi đi, dù sao tôi chắc chắn sẽ không đi."],["反正我已经辞职了，今晚加班我是不会去的。","fǎn zhèng wǒ yǐ jīng cí zhí le jīn wǎn jiā bān wǒ shì bú huì qù de","Đằng nào tôi cũng nghỉ việc rồi, tối nay tăng ca tôi sẽ không đi đâu."],["你不用再劝他了，他根本不会听。","nǐ bú yòng zài quàn tā le tā gēn běn bú huì tīng","Bạn không cần khuyên anh ấy nữa, anh ấy hoàn toàn không nghe đâu."],["我看根本没必要追求完美，世界上不存在完美的人和事。","wǒ kàn gēn běn méi bì yào zhuī qiú wán měi shì jiè shàng bù cún zài wán měi de rén hé shì","Tôi thấy hoàn toàn không cần theo đuổi sự hoàn hảo, trên đời không tồn tại người và việc hoàn hảo."],["她果然选择了自己最喜欢的文学专业。","tā guǒ rán xuǎn zé le zì jǐ zuì xǐ huan de wén xué zhuān yè","Cô ấy quả nhiên đã chọn chuyên ngành văn học mà mình thích nhất."],["他果然没有放弃，坚持完成了比赛。","tā guǒ rán méi yǒu fàng qì jiān chí wán chéng le bǐ sài","Anh ấy quả nhiên không bỏ cuộc, kiên trì hoàn thành cuộc thi."],["这简直是在开玩笑！","zhè jiǎn zhí shì zài kāi wán xiào","Đây đúng là đang đùa mà!"],["画面里的竹子简直像真的一样。","huà miàn lǐ de zhú zi jiǎn zhí xiàng zhēn de yí yàng","Cây trúc trong bức tranh quả thật như thật vậy."],["高科技绝对会成为各行各业发展的重要因素。","gāo kē jì jué duì huì chéng wéi gè háng gè yè fā zhǎn de zhòng yào yīn sù","Công nghệ cao tuyệt đối sẽ trở thành yếu tố quan trọng cho sự phát triển của mọi ngành nghề."],["老张这个人绝对可靠。","lǎo zhāng zhè ge rén jué duì kě kào","Lão Trương là người tuyệt đối đáng tin cậy."],["近年来城乡差距的确缩小了不少。","jìn nián lái chéng xiāng chā jù dí què suō xiǎo le bù shǎo","Những năm gần đây khoảng cách giữa thành thị và nông thôn quả thật đã thu hẹp không ít."],["我今天上班的确迟到了，因为路上发生了交通事故。","wǒ jīn tiān shàng bān dí què chí dào le yīn wèi lù shang fā shēng le jiāo tōng shì gù","Hôm nay tôi đi làm quả thật bị muộn, vì trên đường xảy ra tai nạn giao thông."],["道歉不会损害企业的形象，反而能够赢得消费者的信任。","dào qiàn bú huì sǔn hài qǐ yè de xíng xiàng fǎn ér néng gòu yíng dé xiāo fèi zhě de xìn rèn","Xin lỗi sẽ không làm tổn hại hình ảnh doanh nghiệp, ngược lại còn có thể giành được lòng tin của người tiêu dùng."],["我妈妈退休以后反而更忙了。","wǒ mā ma tuì xiū yǐ hòu fǎn ér gèng máng le","Mẹ tôi sau khi nghỉ hưu ngược lại còn bận hơn."],["不用白费力气了，结果已经无法改变了。","bú yòng bái fèi lì qi le jié guǒ yǐ jīng wú fǎ gǎi biàn le","Đừng phí công vô ích nữa, kết quả đã không thể thay đổi được rồi."],["妈妈的话白说了，孩子并没有听。","mā ma de huà bái shuō le hái zi bìng méi yǒu tīng","Lời mẹ nói uổng công rồi, đứa trẻ hoàn toàn không nghe."],["今天刚好有空儿，咱们去爬山吧。","jīn tiān gāng hǎo yǒu kòng r zán men qù pá shān ba","Hôm nay vừa hay rảnh, chúng ta đi leo núi đi."],["我们去找他玩的时候，他刚好做完作业。","wǒ men qù zhǎo tā wán de shí hou tā gāng hǎo zuò wán zuò yè","Lúc chúng tôi đi tìm anh ấy chơi, anh ấy vừa làm xong bài tập."],["这么难得的机会，你可不能错过啊！","zhè me nán dé de jī huì nǐ kě bù néng cuò guò a","Cơ hội hiếm có như vậy, bạn nhất định không được bỏ lỡ đấy!"],["下周就要比赛了，咱们可得抓紧时间训练。","xià zhōu jiù yào bǐ sài le zán men kě de zhuā jǐn shí jiān xùn liàn","Tuần sau là thi đấu rồi, chúng ta thật sự phải tranh thủ thời gian tập luyện."]]},{"n":12,"c":["词类","介词","引出时间、处所"],"z":"自从","t":"Giới từ 自从","d":"自从 = kể từ khi (chỉ thời điểm trong quá khứ), hay đi với 以后/以来.","e":[["自从和丈夫离了婚，她一个人去了很多地方旅行。","zì cóng hé zhàng fu lí le hūn tā yí gè rén qù le hěn duō dì fang lǚ xíng","Kể từ khi ly hôn với chồng, cô ấy đã một mình đi du lịch rất nhiều nơi."],["自从进入大学，每次与就业有关的讲座他都会参加。","zì cóng jìn rù dà xué měi cì yǔ jiù yè yǒu guān de jiǎng zuò tā dōu huì cān jiā","Kể từ khi vào đại học, buổi tọa đàm nào liên quan đến việc làm anh ấy cũng tham gia."]]},{"n":13,"c":["词类","介词","引出方向、路径"],"z":"朝、沿（着）","t":"Giới từ 朝, 沿(着)","d":"朝 = hướng về, về phía; 沿(着) = dọc theo, men theo (cả nghĩa bóng: theo hướng suy nghĩ).","e":[["沿着这条路朝东走就是我们今晚要住的酒店。","yán zhe zhè tiáo lù cháo dōng zǒu jiù shì wǒ men jīn wǎn yào zhù de jiǔ diàn","Đi dọc con đường này về phía đông chính là khách sạn tối nay chúng ta sẽ ở."],["冬天许多鸟都会朝南方温暖的地方飞去。","dōng tiān xǔ duō niǎo dōu huì cháo nán fāng wēn nuǎn de dì fang fēi qù","Mùa đông nhiều loài chim sẽ bay về những nơi ấm áp ở phương Nam."],["沿着这条高速公路一直开，就能到达那座城市。","yán zhe zhè tiáo gāo sù gōng lù yì zhí kāi jiù néng dào dá nà zuò chéng shì","Cứ lái dọc theo đường cao tốc này là có thể đến thành phố đó."],["老人沿着墙边种了很多花。","lǎo rén yán zhe qiáng biān zhòng le hěn duō huā","Ông cụ trồng rất nhiều hoa dọc theo chân tường."],["你沿着这个思路进行下去，就能找到解决问题的方法。","nǐ yán zhe zhè ge sī lù jìn xíng xià qù jiù néng zhǎo dào jiě jué wèn tí de fāng fǎ","Bạn cứ đi tiếp theo hướng suy nghĩ này là sẽ tìm ra cách giải quyết vấn đề."]]},{"n":14,"c":["词类","介词","引出对象"],"z":"替、同¹、较²","t":"Giới từ 替, 同, 较 (dẫn đối tượng)","d":"替 = thay cho, giúp; 同 = với, cùng (văn viết, giống 跟); 较 = so với (văn viết, giống 比).","e":[["希望这次采访能替我们宣传一下公司的新产品。","xī wàng zhè cì cǎi fǎng néng tì wǒ men xuān chuán yí xià gōng sī de xīn chǎn pǐn","Hy vọng buổi phỏng vấn lần này có thể giúp chúng tôi quảng bá sản phẩm mới của công ty."],["我出差期间，同事替我照顾我的宠物。","wǒ chū chāi qī jiān tóng shì tì wǒ zhào gù wǒ de chǒng wù","Trong thời gian tôi đi công tác, đồng nghiệp đã chăm sóc thú cưng giúp tôi."],["汉语同其他语言一样，有很多独特的表达方式。","hàn yǔ tóng qí tā yǔ yán yí yàng yǒu hěn duō dú tè de biǎo dá fāng shì","Tiếng Hán cũng như các ngôn ngữ khác, có rất nhiều cách diễn đạt độc đáo."],["这件事我得同父母谈谈，看看他们同意不同意。","zhè jiàn shì wǒ děi tóng fù mǔ tán tán kàn kàn tā men tóng yì bù tóng yì","Chuyện này tôi phải bàn với bố mẹ, xem họ có đồng ý không."],["今年的放假时间较去年稍有变化。","jīn nián de fàng jià shí jiān jiào qù nián shāo yǒu biàn huà","Thời gian nghỉ lễ năm nay hơi thay đổi so với năm ngoái."],["本月产品销量较上月增长百分之十五。","běn yuè chǎn pǐn xiāo liàng jiào shàng yuè zēng zhǎng bǎi fēn zhī shí wǔ","Doanh số sản phẩm tháng này tăng mười lăm phần trăm so với tháng trước."]]},{"n":15,"c":["词类","介词","引出凭借、依据"],"z":"凭","t":"Giới từ 凭","d":"凭 = dựa vào, bằng (vào): 凭这张票 = bằng tấm vé này.","e":[["她凭这部电影成为了今年的最佳导演。","tā píng zhè bù diàn yǐng chéng wéi le jīn nián de zuì jiā dǎo yǎn","Cô ấy nhờ bộ phim này mà trở thành đạo diễn xuất sắc nhất năm nay."],["凭这张票，你可以免费参观这场展览。","píng zhè zhāng piào nǐ kě yǐ miǎn fèi cān guān zhè chǎng zhǎn lǎn","Bằng tấm vé này, bạn có thể tham quan miễn phí triển lãm này."]]},{"n":16,"c":["词类","介词","引出凭借、依据"],"z":"据","t":"Giới từ 据","d":"据 = theo, căn cứ vào (thông tin, quan sát): 据我观察 = theo tôi quan sát.","e":[["据我们掌握的数据，这个地区的石油资源十分丰富。","jù wǒ men zhǎng wò de shù jù zhè ge dì qū de shí yóu zī yuán shí fēn fēng fù","Theo số liệu chúng tôi nắm được, tài nguyên dầu mỏ của khu vực này vô cùng phong phú."],["据我观察，这个问题不难解决。","jù wǒ guān chá zhè ge wèn tí bù nán jiě jué","Theo tôi quan sát, vấn đề này không khó giải quyết."]]},{"n":17,"c":["词类","介词","引出凭借、依据"],"z":"依据","t":"Giới từ 依据","d":"依据 = căn cứ vào, dựa theo (văn viết).","e":[["法律的修改应当依据社会现实。","fǎ lǜ de xiū gǎi yīng dāng yī jù shè huì xiàn shí","Việc sửa đổi pháp luật nên căn cứ vào thực tế xã hội."],["企业要依据消费者的需求研发新产品。","qǐ yè yào yī jù xiāo fèi zhě de xū qiú yán fā xīn chǎn pǐn","Doanh nghiệp phải dựa theo nhu cầu của người tiêu dùng để nghiên cứu sản phẩm mới."]]},{"n":18,"c":["词类","连词","连接词或词组"],"z":"以及、同²","t":"Liên từ 以及, 同","d":"以及 = cùng với, và (văn viết, nối nhiều mục); 同 = và, với.","e":[["他负责项目的设计、执行以及最终的总结工作。","tā fù zé xiàng mù de shè jì zhí xíng yǐ jí zuì zhōng de zǒng jié gōng zuò","Anh ấy phụ trách thiết kế, thực hiện cũng như công việc tổng kết cuối cùng của dự án."],["我对这本书的内容以及作者还不太了解，你能介绍一下吗？","wǒ duì zhè běn shū de nèi róng yǐ jí zuò zhě hái bú tài liǎo jiě nǐ néng jiè shào yí xià ma","Tôi vẫn chưa hiểu lắm về nội dung cũng như tác giả của quyển sách này, bạn giới thiệu một chút được không?"],["你同新来的同事一起去吧，顺便给他介绍一下公司的情况。","nǐ tóng xīn lái de tóng shì yì qǐ qù ba shùn biàn gěi tā jiè shào yí xià gōng sī de qíng kuàng","Bạn đi cùng đồng nghiệp mới đến đi, nhân tiện giới thiệu cho anh ấy tình hình công ty."],["这项比赛要求孩子同家长一起参加。","zhè xiàng bǐ sài yāo qiú hái zi tóng jiā zhǎng yì qǐ cān jiā","Cuộc thi này yêu cầu trẻ tham gia cùng phụ huynh."]]},{"n":19,"c":["词类","连词","连接分句或句子"],"z":"从而、可见、假如、总之","t":"Liên từ 从而, 可见, 假如, 总之","d":"从而 = từ đó, nhờ đó; 可见 = có thể thấy; 假如 = giả như, nếu; 总之 = tóm lại, nói chung.","e":[["学校更新了教学设备，从而为学生提供了更好的学习环境。","xué xiào gēng xīn le jiào xué shè bèi cóng ér wèi xué shēng tí gōng le gèng hǎo de xué xí huán jìng","Nhà trường đã đổi mới thiết bị dạy học, từ đó tạo môi trường học tập tốt hơn cho học sinh."],["这次合作让我们加深了对彼此的了解，从而建立了深厚的友谊。","zhè cì hé zuò ràng wǒ men jiā shēn le duì bǐ cǐ de liǎo jiě cóng ér jiàn lì le shēn hòu de yǒu yì","Lần hợp tác này giúp chúng tôi hiểu nhau hơn, từ đó xây dựng nên tình bạn sâu sắc."],["他每天都工作到很晚，可见他十分热爱这份工作。","tā měi tiān dōu gōng zuò dào hěn wǎn kě jiàn tā shí fēn rè ài zhè fèn gōng zuò","Ngày nào anh ấy cũng làm việc đến rất muộn, có thể thấy anh ấy rất yêu công việc này."],["他的演讲得到了热烈的掌声，可见大家都很支持他的观点。","tā de yǎn jiǎng dé dào le rè liè de zhǎng shēng kě jiàn dà jiā dōu hěn zhī chí tā de guān diǎn","Bài diễn thuyết của anh ấy nhận được tràng pháo tay nhiệt liệt, có thể thấy mọi người đều ủng hộ quan điểm của anh ấy."],["假如让我重新选择，我还是会选择医学专业。","jiǎ rú ràng wǒ chóng xīn xuǎn zé wǒ hái shì huì xuǎn zé yī xué zhuān yè","Giả như được chọn lại, tôi vẫn sẽ chọn chuyên ngành y."],["假如你有机会出国旅行，你最想去哪个国家？","jiǎ rú nǐ yǒu jī huì chū guó lǚ xíng nǐ zuì xiǎng qù nǎ gè guó jiā","Giả như bạn có cơ hội đi du lịch nước ngoài, bạn muốn đến nước nào nhất?"],["一个人在国外生活，要自己照顾自己，还要学习当地的语言和文化，总之，挺不容易的。","yí gè rén zài guó wài shēng huó yào zì jǐ zhào gù zì jǐ hái yào xué xí dāng dì de yǔ yán hé wén huà zǒng zhī tǐng bù róng yì de","Một mình sống ở nước ngoài, phải tự chăm sóc bản thân, còn phải học ngôn ngữ và văn hóa bản địa, tóm lại là khá không dễ dàng."],["你同意也好，不同意也好，总之，我一定要去北京。","nǐ tóng yì yě hǎo bù tóng yì yě hǎo zǒng zhī wǒ yí dìng yào qù běi jīng","Bạn đồng ý cũng được, không đồng ý cũng được, tóm lại tôi nhất định phải đi Bắc Kinh."]]},{"n":20,"c":["词类","助词","其他助词"],"z":"似的","t":"Trợ từ 似的","d":"(像)……似的 = giống như…vậy (so sánh, ví von). 似的 đọc là shìde.","e":[["她笑得像个孩子似的。","tā xiào de xiàng gè hái zi shì de","Cô ấy cười như một đứa trẻ vậy."],["他们讨论得很激烈，像是要吵起来似的。","tā men tǎo lùn de hěn jī liè xiàng shì yào chǎo qǐ lái shì de","Họ thảo luận rất gay gắt, như thể sắp cãi nhau đến nơi."]]},{"n":21,"c":["短语","固定短语","四字格"],"z":"A来A去","t":"Cấu trúc bốn chữ A来A去","d":"= …đi…lại, …tới…lui (lặp lại nhiều lần): 想来想去 = nghĩ đi nghĩ lại.","e":[["我们争来争去，还是没找到最佳方案。","wǒ men zhēng lái zhēng qù hái shì méi zhǎo dào zuì jiā fāng àn","Chúng tôi tranh luận qua lại, vẫn chưa tìm được phương án tốt nhất."],["他工作很忙，经常在国内外飞来飞去。","tā gōng zuò hěn máng jīng cháng zài guó nèi wài fēi lái fēi qù","Anh ấy làm việc rất bận, thường xuyên bay đi bay lại trong và ngoài nước."],["我想来想去，决定先不告诉她这个坏消息。","wǒ xiǎng lái xiǎng qù jué dìng xiān bú gào su tā zhè ge huài xiāo xī","Tôi nghĩ đi nghĩ lại, quyết định tạm thời chưa nói với cô ấy tin xấu này."]]},{"n":22,"c":["短语","固定短语","四字格"],"z":"A着A着","t":"Cấu trúc bốn chữ A着A着","d":"= đang…thì (bỗng)…: 写着写着就睡着了 = đang viết thì ngủ thiếp đi.","e":[["我今天太困了，写着写着作业就睡着了。","wǒ jīn tiān tài kùn le xiě zhe xiě zhe zuò yè jiù shuì zháo le","Hôm nay tôi buồn ngủ quá, đang làm bài tập thì ngủ thiếp đi."],["他走着走着，突然发现自己迷路了。","tā zǒu zhe zǒu zhe tū rán fā xiàn zì jǐ mí lù le","Anh ấy đi mãi đi mãi, bỗng phát hiện mình bị lạc đường."]]},{"n":23,"c":["短语","固定短语","四字格"],"z":"没A没B","t":"Cấu trúc bốn chữ 没A没B","d":"= không…không… (thiếu hẳn): 没日没夜 = không kể ngày đêm; 没大没小 = không phân lớn bé (hỗn hào).","e":[["你这样没日没夜地工作，身体早晚会出问题的。","nǐ zhè yàng méi rì méi yè de gōng zuò shēn tǐ zǎo wǎn huì chū wèn tí de","Bạn làm việc không kể ngày đêm như thế, sớm muộn gì sức khỏe cũng có vấn đề."],["这孩子说话没大没小，父母必须要好好教育。","zhè hái zi shuō huà méi dà méi xiǎo fù mǔ bì xū yào hǎo hǎo jiào yù","Đứa trẻ này nói năng không phân lớn bé, bố mẹ phải dạy dỗ cho tốt."]]},{"n":24,"c":["短语","固定短语","四字格"],"z":"说A就A","t":"Cấu trúc bốn chữ 说A就A","d":"= nói…là…ngay (hành động ngay lập tức).","e":[["越来越多的年轻人选择说走就走的旅行。","yuè lái yuè duō de nián qīng rén xuǎn zé shuō zǒu jiù zǒu de lǚ xíng","Ngày càng nhiều người trẻ chọn những chuyến đi nói đi là đi."],["他总是说干就干，从不浪费时间。","tā zǒng shì shuō gàn jiù gàn cóng bú làng fèi shí jiān","Anh ấy luôn nói làm là làm, không bao giờ lãng phí thời gian."]]},{"n":25,"c":["短语","固定短语","其他"],"z":"不得了","t":"Cụm cố định 不得了","d":"① …得不得了 = …vô cùng, hết sức; ② 不得了了！ = Nguy rồi! Chết rồi!","e":[["他最近的表现好得不得了，老师都说他进步很大。","tā zuì jìn de biǎo xiàn hǎo de bù dé liǎo lǎo shī dōu shuō tā jìn bù hěn dà","Biểu hiện dạo này của cậu ấy tốt vô cùng, thầy cô đều nói cậu ấy tiến bộ rất nhiều."],["不得了了，厨房着火了！","bù dé liǎo le chú fáng zháo huǒ le","Nguy rồi, nhà bếp cháy rồi!"]]},{"n":26,"c":["短语","固定短语","其他"],"z":"用不着","t":"Cụm cố định 用不着","d":"= không cần đến, không cần phải.","e":[["这点儿小病，用不着去医院。","zhè diǎn r xiǎo bìng yòng bu zháo qù yī yuàn","Bệnh nhẹ thế này, không cần phải đi bệnh viện."],["这件事用不着大家都来帮忙，我自己就能完成。","zhè jiàn shì yòng bu zháo dà jiā dōu lái bāng máng wǒ zì jǐ jiù néng wán chéng","Việc này không cần mọi người đến giúp, tự tôi làm được."],["我们还有时间，你现在用不着着急。","wǒ men hái yǒu shí jiān nǐ xiàn zài yòng bu zháo zháo jí","Chúng ta vẫn còn thời gian, bây giờ bạn không cần phải vội."]]},{"n":27,"c":["固定格式","",""],"z":"从……来看","t":"Cấu trúc 从……来看","d":"= Xét từ…mà thấy, nhìn từ góc độ….","e":[["从这次的考试成绩来看，大家都付出了很多努力。","cóng zhè cì de kǎo shì chéng jì lái kàn dà jiā dōu fù chū le hěn duō nǔ lì","Xét từ kết quả thi lần này, mọi người đều đã bỏ ra rất nhiều nỗ lực."],["从长远来看，掌握一门外语对个人发展很有帮助。","cóng cháng yuǎn lái kàn zhǎng wò yì mén wài yǔ duì gè rén fā zhǎn hěn yǒu bāng zhù","Về lâu dài mà nói, thông thạo một ngoại ngữ rất có ích cho sự phát triển cá nhân."]]},{"n":28,"c":["固定格式","",""],"z":"A的A，B的B","t":"Cấu trúc A的A，B的B","d":"= cái thì…, cái thì… / người thì…, người thì… (miêu tả tình trạng lộn xộn hoặc sôi nổi).","e":[["这些汉字写得大的大、小的小，一点儿也不整齐。","zhè xiē hàn zì xiě de dà de dà xiǎo de xiǎo yì diǎn r yě bù zhěng qí","Những chữ Hán này viết cái to cái nhỏ, chẳng đều chút nào."],["广场上孩子们跑的跑，跳的跳，热闹极了。","guǎng chǎng shàng hái zi men pǎo de pǎo tiào de tiào rè nao jí le","Trên quảng trường, bọn trẻ đứa thì chạy, đứa thì nhảy, náo nhiệt vô cùng."]]},{"n":29,"c":["固定格式","",""],"z":"（自）……以来","t":"Cấu trúc (自)……以来","d":"= Kể từ…đến nay.","e":[["自改革开放以来，中国社会发生了巨大的改变。","zì gǎi gé kāi fàng yǐ lái zhōng guó shè huì fā shēng le jù dà de gǎi biàn","Kể từ cải cách mở cửa đến nay, xã hội Trung Quốc đã có những thay đổi to lớn."],["外公去世以来，我时常梦到他。","wài gōng qù shì yǐ lái wǒ shí cháng mèng dào tā","Từ khi ông ngoại mất đến nay, tôi thường mơ thấy ông."]]},{"n":30,"c":["固定格式","",""],"z":"由……组成","t":"Cấu trúc 由……组成","d":"= Do…tạo thành, gồm có….","e":[["本课程由理论学习和实践操作两部分内容组成。","běn kè chéng yóu lǐ lùn xué xí hé shí jiàn cāo zuò liǎng bù fen nèi róng zǔ chéng","Khóa học này gồm hai phần nội dung: học lý thuyết và thực hành thao tác."],["项目团队由三位工程师组成。","xiàng mù tuán duì yóu sān wèi gōng chéng shī zǔ chéng","Nhóm dự án gồm có ba kỹ sư."]]},{"n":31,"c":["固定格式","",""],"z":"X也不是，Y也不是","t":"Cấu trúc X也不是，Y也不是","d":"= …cũng không được, …cũng không xong (khó xử, lúng túng).","e":[["马上就要面试了，他紧张得坐也不是，站也不是。","mǎ shàng jiù yào miàn shì le tā jǐn zhāng de zuò yě bú shì zhàn yě bú shì","Sắp phỏng vấn rồi, anh ấy căng thẳng đến mức ngồi cũng không yên, đứng cũng không xong."],["公司已经三个月没有发工资了，他走也不是，留也不是，不知道怎么办好。","gōng sī yǐ jīng sān gè yuè méi yǒu fā gōng zī le tā zǒu yě bú shì liú yě bú shì bù zhī dao zěn me bàn hǎo","Công ty đã ba tháng không trả lương, anh ấy đi cũng không được, ở cũng không xong, không biết làm thế nào."]]},{"n":32,"c":["固定格式","",""],"z":"X也X不得，Y也Y不得","t":"Cấu trúc X也X不得，Y也Y不得","d":"= …cũng không được, …cũng chẳng xong (không biết xử lý thế nào).","e":[["对这个孩子他实在没办法，打也打不得，说也说不得。","duì zhè ge hái zi tā shí zài méi bàn fǎ dǎ yě dǎ bù de shuō yě shuō bù de","Với đứa trẻ này anh ấy thật hết cách, đánh cũng không được, mắng cũng không xong."],["听到消息后，她哭也哭不得，笑也笑不得。","tīng dào xiāo xī hòu tā kū yě kū bù de xiào yě xiào bù de","Nghe tin xong, cô ấy khóc cũng không được, cười cũng chẳng xong (dở khóc dở cười)."]]},{"n":33,"c":["固定格式","",""],"z":"X是它，Y也是它","t":"Cấu trúc X是它，Y也是它","d":"= …cũng là nó, …cũng là nó (chấp nhận, không có lựa chọn khác).","e":[["好是它，坏也是它，你没有别的选择。","hǎo shì tā huài yě shì tā nǐ méi yǒu bié de xuǎn zé","Tốt cũng là nó, xấu cũng là nó, bạn không có lựa chọn nào khác."],["成功是它，失败也是它，这个决定我绝对不后悔。","chéng gōng shì tā shī bài yě shì tā zhè ge jué dìng wǒ jué duì bù hòu huǐ","Thành công cũng vậy, thất bại cũng vậy, quyết định này tôi tuyệt đối không hối hận."]]},{"n":34,"c":["固定格式","",""],"z":"X着也是X着","t":"Cấu trúc X着也是X着","d":"= đằng nào cũng…không (tận dụng thời gian/đồ vật đang bỏ không).","e":[["闲着也是闲着，明天我准备把车库打扫一遍。","xián zhe yě shì xián zhe míng tiān wǒ zhǔn bèi bǎ chē kù dǎ sǎo yí biàn","Rảnh rỗi cũng là rảnh rỗi, ngày mai tôi định dọn nhà để xe một lượt."],["那辆旧车你很少开，放着也是放着，要不卖了吧。","nà liàng jiù chē nǐ hěn shǎo kāi fàng zhe yě shì fàng zhe yào bú mài le ba","Chiếc xe cũ đó bạn rất ít lái, để không cũng là để không, hay là bán đi?"]]},{"n":35,"c":["固定格式","",""],"z":"不管怎样说","t":"Cụm cố định 不管怎么说","d":"= Dù nói thế nào đi nữa, dù sao đi nữa.","e":[["不管怎么说，健康才是最重要的，要注意身体。","bù guǎn zěn me shuō jiàn kāng cái shì zuì zhòng yào de yào zhù yì shēn tǐ","Dù sao đi nữa, sức khỏe mới là quan trọng nhất, phải giữ gìn sức khỏe."],["不管怎么说，用打骂的方法教育孩子是不对的。","bù guǎn zěn me shuō yòng dǎ mà de fāng fǎ jiào yù hái zi shì bú duì de","Dù nói thế nào, dùng cách đánh mắng để dạy con là không đúng."]]},{"n":36,"c":["固定格式","",""],"z":"真有你/他/她的","t":"Cấu trúc 真有你/他/她的","d":"= Giỏi thật đấy! / Phục bạn thật! (khen hoặc trêu, tùy ngữ cảnh).","e":[["真有你的，这么难的题目都做对了！","zhēn yǒu nǐ de zhè me nán de tí mù dōu zuò duì le","Giỏi thật đấy, đề khó thế này mà cũng làm đúng hết!"],["真有他的，一个人爬上了这么高的山！","zhēn yǒu tā de yí gè rén pá shàng le zhè me gāo de shān","Phục anh ấy thật, một mình leo lên ngọn núi cao như vậy!"],["真有她的，在这么吵的地方都能睡着！","zhēn yǒu tā de zài zhè me chǎo de dì fang dōu néng shuì zháo","Phục cô ấy thật, chỗ ồn ào thế này mà cũng ngủ được!"]]},{"n":37,"c":["固定格式","",""],"z":"X什么X","t":"Cấu trúc X什么X","d":"= …cái gì mà…! (ngăn cản, trách móc).","e":[["吵什么吵，公共场所禁止大声说话！","chǎo shén me chǎo gōng gòng chǎng suǒ jìn zhǐ dà shēng shuō huà","Ồn ào cái gì mà ồn ào, nơi công cộng cấm nói to!"],["玩什么玩，作业还没写完呢！","wán shén me wán zuò yè hái méi xiě wán ne","Chơi gì mà chơi, bài tập còn chưa làm xong kia kìa!"]]},{"n":38,"c":["固定格式","",""],"z":"什么X不X（的）","t":"Cấu trúc 什么X不X(的)","d":"= …với chả…, …gì mà… (gạt đi, không cần khách sáo).","e":[["什么谢不谢的，我们之间不用这么客气。","shén me xiè bu xiè de wǒ men zhī jiān bú yòng zhè me kè qi","Cảm ơn gì chứ, giữa chúng ta không cần khách sáo vậy đâu."],["什么麻烦不麻烦的，朋友之间互相帮忙是应该的。","shén me má fan bù má fan de péng you zhī jiān hù xiāng bāng máng shì yīng gāi de","Phiền với chả phiền, bạn bè giúp đỡ nhau là chuyện nên làm."]]},{"n":39,"c":["固定格式","",""],"z":"不X白不X","t":"Cấu trúc 不X白不X","d":"= không…thì phí (có lợi mà không tận dụng thì uổng).","e":[["音乐会的门票是客户赠送的，咱们不听白不听。","yīn yuè huì de mén piào shì kè hù zèng sòng de zán men bù tīng bái bù tīng","Vé xem hòa nhạc là khách hàng tặng, chúng ta không nghe thì phí."],["这件衣服难得打折，不买白不买。","zhè jiàn yī fu nán dé dǎ zhé bù mǎi bái bù mǎi","Bộ quần áo này hiếm khi giảm giá, không mua thì phí."]]},{"n":40,"c":["固定格式","",""],"z":"X来X去，都是/就是……","t":"Cấu trúc X来X去，都是/就是……","d":"= …đi…lại, vẫn là… / vẫn không….","e":[["听来听去，都是一些差不多的意见。","tīng lái tīng qù dōu shì yì xiē chà bù duō de yì jiàn","Nghe đi nghe lại, toàn là những ý kiến na ná nhau."],["大家商量来商量去，就是想不出什么好办法。","dà jiā shāng liáng lái shāng liáng qù jiù shì xiǎng bù chū shén me hǎo bàn fǎ","Mọi người bàn đi bàn lại mà vẫn không nghĩ ra cách gì hay."]]},{"n":41,"c":["固定格式","",""],"z":"动词+什么（就）是什么","t":"Cấu trúc động từ + 什么(就)是什么","d":"= …gì thì là nấy (không được bàn cãi).","e":[["孩子长大了，不像以前，父母说什么就是什么。","hái zi zhǎng dà le bú xiàng yǐ qián fù mǔ shuō shén me jiù shì shén me","Con cái lớn rồi, không như trước đây, bố mẹ nói gì là nghe nấy."],["工作要按照公司的规定执行，不能你想什么就是什么。","gōng zuò yào àn zhào gōng sī de guī dìng zhí xíng bù néng nǐ xiǎng shén me jiù shì shén me","Công việc phải làm theo quy định của công ty, không thể bạn nghĩ gì thì làm nấy."]]},{"n":42,"c":["句子成分","状语",""],"z":"多项状语","t":"Trạng ngữ nhiều tầng","d":"Thứ tự thường gặp: mục đích → thời gian → (người cùng) → nơi chốn → cách thức (认真地) → động từ.","e":[["他为了锻炼身体每天早上在公园里跑步。","tā wèi le duàn liàn shēn tǐ měi tiān zǎo shang zài gōng yuán lǐ pǎo bù","Để rèn luyện sức khỏe, sáng nào anh ấy cũng chạy bộ trong công viên."],["他昨天晚上一个人在图书馆认真地复习了三个小时。","tā zuó tiān wǎn shang yí gè rén zài tú shū guǎn rèn zhēn de fù xí le sān gè xiǎo shí","Tối hôm qua anh ấy một mình ở thư viện chăm chỉ ôn tập suốt ba tiếng."]]},{"n":43,"c":["句子成分","补语","可能补语2"],"z":"动词+得/不得","t":"Bổ ngữ khả năng: động từ + 得/不得","d":"不得 = không được phép, không nên (vì có hại): 开不得 = không được đùa; 急不得 = không vội được.","e":[["伤害人的玩笑可开不得。","shāng hài rén de wán xiào kě kāi bù de","Những trò đùa làm tổn thương người khác thì không được đùa."],["这院是出得还是出不得，得先问问医生的建议。","zhè yuàn shì chū dé hái shì chū bu dé děi xiān wèn wèn yī shēng de jiàn yì","Có xuất viện được hay không, phải hỏi ý kiến bác sĩ trước đã."],["写论文这件事情急不得，你得多看多想。","xiě lùn wén zhè jiàn shì qing jí bù de nǐ děi duō kàn duō xiǎng","Việc viết luận văn không thể vội được, bạn phải xem nhiều nghĩ nhiều."]]},{"n":44,"c":["句子成分","补语","程度补语2"],"z":"形容词/心理动词+得+不得了","t":"Bổ ngữ mức độ: …得不得了","d":"Tính từ/động từ tâm lý + 得不得了 = …vô cùng, …hết chỗ nói.","e":[["收到大学的录取通知书，她激动得不得了。","shōu dào dà xué de lù qǔ tōng zhī shū tā jī dòng de bù dé liǎo","Nhận được giấy báo trúng tuyển đại học, cô ấy xúc động vô cùng."],["听到父亲被送去急诊的消息，她担心得不得了。","tīng dào fù qīn bèi sòng qù jí zhěn de xiāo xī tā dān xīn de bù dé liǎo","Nghe tin bố được đưa vào cấp cứu, cô ấy lo lắng vô cùng."]]},{"n":45,"c":["句子成分","补语","趋向补语3"],"z":"趋向补语的引申用法：表示状态意义：动词/形容词+下来/下去/起来/过来/过去","t":"Nghĩa mở rộng của bổ ngữ xu hướng: trạng thái","d":"下来: từ động sang tĩnh (平静下来 = bình tĩnh lại); 下去: tiếp tục giảm (低了下去 = nhỏ dần); 起来: tập hợp, cất đi (收拾起来); 过来: trở lại trạng thái bình thường (醒过来 = tỉnh lại); 过去: mất trạng thái bình thường (睡过去 = thiếp đi).","e":[["听着窗外的雨声，我的心慢慢地平静下来了。","tīng zhe chuāng wài de yǔ shēng wǒ de xīn màn màn de píng jìng xià lái le","Nghe tiếng mưa ngoài cửa sổ, lòng tôi dần dần bình tĩnh lại."],["不知道是什么原因，他的声音渐渐低了下去。","bù zhī dao shì shén me yuán yīn tā de shēng yīn jiàn jiàn dī le xià qù","Không biết vì lý do gì, giọng anh ấy nhỏ dần đi."],["该睡觉了，快把你的玩具收拾起来。","gāi shuì jiào le kuài bǎ nǐ de wán jù shōu shi qǐ lái","Đến giờ đi ngủ rồi, mau cất đồ chơi của con đi."],["在医生们的努力下，病人终于醒过来了。","zài yī shēng men de nǔ lì xià bìng rén zhōng yú xǐng guò lái le","Nhờ sự nỗ lực của các bác sĩ, bệnh nhân cuối cùng đã tỉnh lại."],["经过一天的长途旅行，大家都很累，一上车就纷纷睡过去了。","jīng guò yì tiān de cháng tú lǚ xíng dà jiā dōu hěn lèi yí shàng chē jiù fēn fēn shuì guò qù le","Sau một ngày đi đường dài, mọi người đều rất mệt, vừa lên xe đã lần lượt ngủ thiếp đi."]]},{"n":46,"c":["句子成分","补语","状态补语2"],"z":"动词/形容词+得+动词短语","t":"Bổ ngữ trạng thái: …得 + cụm động từ","d":"Kết quả/mức độ được miêu tả bằng một hành động: 玩得忘了时间 = chơi đến quên cả thời gian.","e":[["孩子们玩儿得忘了时间，直到天黑才回家。","hái zi men wán r de wàng le shí jiān zhí dào tiān hēi cái huí jiā","Bọn trẻ chơi đến quên cả thời gian, đến tận tối mịt mới về nhà."],["面对自己喜欢的明星，他紧张得说不出话。","miàn duì zì jǐ xǐ huan de míng xīng tā jǐn zhāng de shuō bù chū huà","Đối diện với ngôi sao mình yêu thích, anh ấy hồi hộp đến không nói nên lời."]]},{"n":47,"c":["句子成分","补语","状态补语2"],"z":"动词/形容词+得+主谓短语","t":"Bổ ngữ trạng thái: …得 + cụm chủ – vị","d":"跑得全身是汗 = chạy đến mức mồ hôi đầy người; 热得大家都不想出门 = nóng đến mức chẳng ai muốn ra ngoài.","e":[["他跑得全身是汗，终于按时到了公司。","tā pǎo de quán shēn shì hàn zhōng yú àn shí dào le gōng sī","Anh ấy chạy đến mức mồ hôi ướt đẫm người, cuối cùng cũng đến công ty đúng giờ."],["天气热得大家都不想出门。","tiān qì rè de dà jiā dōu bù xiǎng chū mén","Trời nóng đến mức mọi người đều không muốn ra khỏi nhà."]]},{"n":48,"c":["句子成分","补语","状态补语2"],"z":"动词/形容词+得+固定短语","t":"Bổ ngữ trạng thái: …得 + thành ngữ","d":"跑得上气不接下气 = chạy đến hụt hơi; 累得满头大汗 = mệt đến toát mồ hôi đầy đầu.","e":[["快上课了，他跑得上气不接下气。","kuài shàng kè le tā pǎo de shàng qì bù jiē xià qì","Sắp vào học rồi, cậu ấy chạy đến thở hồng hộc."],["为了准备年夜饭，她累得满头大汗。","wèi le zhǔn bèi nián yè fàn tā lèi de mǎn tóu dà hàn","Để chuẩn bị bữa cơm tất niên, cô ấy mệt đến mồ hôi đầm đìa."]]},{"n":49,"c":["句子的类型","特殊句型","“有”字句3"],"z":"表示存在、具有：主语+有+着+宾语","t":"Câu chữ 有: 有着 (tồn tại, có)","d":"有着 + danh từ trừu tượng = có (văn viết): 有着长期友好的关系 = có quan hệ hữu nghị lâu dài.","e":[["尽管是兄弟，但是他们心里有着很深的矛盾。","jǐn guǎn shì xiōng dì dàn shì tā men xīn lǐ yǒu zhe hěn shēn de máo dùn","Tuy là anh em, nhưng trong lòng họ có những mâu thuẫn rất sâu sắc."],["两国之间有着长期友好的关系。","liǎng guó zhī jiān yǒu zhe cháng qī yǒu hǎo de guān xi","Giữa hai nước có mối quan hệ hữu nghị lâu dài."]]},{"n":50,"c":["句子的类型","特殊句型","“有”字句3"],"z":"表示附着：主语+动词+有+宾语","t":"Câu chữ 有: động từ + 有 (gắn kèm)","d":"挂有 = có treo, 写有 = có ghi (văn viết).","e":[["门关着，墙上挂有“暂停营业”的牌子。","mén guān zhe qiáng shàng guà yǒu zàn tíng yíng yè de pái zi","Cửa đóng, trên tường treo tấm biển \"Tạm ngừng kinh doanh\"."],["这本书的第一页写有作者的名字。","zhè běn shū de dì yī yè xiě yǒu zuò zhě de míng zi","Trang đầu tiên của cuốn sách này có ghi tên tác giả."]]},{"n":51,"c":["句子的类型","特殊句型","“把”字句3"],"z":"主语+把+宾语+一+动词","t":"Câu chữ 把: 把 + tân ngữ + 一 + động từ","d":"一 + động từ: hành động xảy ra nhanh, đột ngột, sau đó có kết quả: 把书包一扔 = quăng cặp một cái.","e":[["孩子把书包一扔，坐在地上哭了起来。","hái zi bǎ shū bāo yì rēng zuò zài dì shàng kū le qǐ lái","Đứa trẻ quăng cặp sách một cái, ngồi bệt xuống đất khóc."],["经理把任务一说，员工们就开始干活了。","jīng lǐ bǎ rèn wu yì shuō yuán gōng men jiù kāi shǐ gàn huó le","Giám đốc vừa giao nhiệm vụ, nhân viên liền bắt tay vào làm việc."]]},{"n":52,"c":["句子的类型","特殊句型","“把”字句3"],"z":"主语+把+宾语1+动词+宾语2","t":"Câu chữ 把: 把 + tân ngữ 1 + động từ + tân ngữ 2","d":"Biến tân ngữ 1 thành tân ngữ 2 / dùng tân ngữ 1 vào việc gì: 把存款都买车了 = lấy hết tiền tiết kiệm mua xe.","e":[["他把存款都买车了。","tā bǎ cún kuǎn dōu mǎi chē le","Anh ấy đã lấy hết tiền tiết kiệm để mua xe."],["我把父母给的生活费借朋友了。","wǒ bǎ fù mǔ gěi de shēng huó fèi jiè péng you le","Tôi đã cho bạn mượn số tiền sinh hoạt bố mẹ cho."]]},{"n":53,"c":["句子的类型","特殊句型","连动句3"],"z":"前后两个动词性词语具有因果、转折、条件关系","t":"Câu liên động: quan hệ nhân quả, chuyển ngoặt, điều kiện","d":"Hai cụm động từ nối tiếp có quan hệ nhân quả (ốm → nằm viện), chuyển ngoặt (họp → quên mang) hoặc điều kiện/phương thức.","e":[["她丈夫生病住院了。（因果）","tā zhàng fu shēng bìng zhù yuàn le yīn guǒ","Chồng cô ấy bị ốm phải nằm viện. (nhân quả)"],["王经理开会忘了带会议资料。（转折）","wáng jīng lǐ kāi huì wàng le dài huì yì zī liào zhuǎn zhé","Giám đốc Vương đi họp mà quên mang tài liệu họp. (chuyển ngoặt)"],["面对快速变化的形势，我们应该尽快制定方案应对风险。（条件）","miàn duì kuài sù biàn huà de xíng shì wǒ men yīng gāi jǐn kuài zhì dìng fāng àn yìng duì fēng xiǎn tiáo jiàn","Trước tình hình thay đổi nhanh chóng, chúng ta nên nhanh chóng xây dựng phương án để ứng phó rủi ro. (điều kiện)"]]},{"n":54,"c":["句子的类型","特殊句型","比较句4"],"z":"A+形容词+B+数量补语","t":"Câu so sánh: A + tính từ + B + số lượng","d":"Không dùng 比: 他高我一头 = Anh ấy cao hơn tôi một cái đầu.","e":[["他高我一头。","tā gāo wǒ yì tóu","Anh ấy cao hơn tôi một cái đầu."],["姐姐重我两公斤。","jiě jie zhòng wǒ liǎng gōng jīn","Chị gái nặng hơn tôi hai cân (kg)."],["哥哥早我两年上学。","gē ge zǎo wǒ liǎng nián shàng xué","Anh trai đi học sớm hơn tôi hai năm."]]},{"n":55,"c":["句子的类型","特殊句型","被动句3"],"z":"主语+被/叫/让+宾语+给+动词+其他成分","t":"Câu bị động: 被/叫/让 + người làm + 给 + động từ","d":"Thêm 给 trước động từ để nhấn mạnh (khẩu ngữ), thường là kết quả không mong muốn.","e":[["我新买的衣服被他给洗坏了。","wǒ xīn mǎi de yī fu bèi tā gěi xǐ huài le","Bộ quần áo tôi mới mua bị anh ấy giặt hỏng mất rồi."],["她的帽子叫风给吹跑了。","tā de mào zi jiào fēng gěi chuī pǎo le","Mũ của cô ấy bị gió thổi bay mất rồi."],["对不起，这些资料让我给搞乱了。","duì bù qǐ zhè xiē zī liào ràng wǒ gěi gǎo luàn le","Xin lỗi, những tài liệu này bị tôi làm lộn xộn hết rồi."]]},{"n":56,"c":["句子的类型","复句","承接复句"],"z":"……，便……","t":"Câu phức nối tiếp: ……，便……","d":"= …, liền/thì… (văn viết của 就).","e":[["领导还没讲完，他便提前离开了。","lǐng dǎo hái méi jiǎng wán tā biàn tí qián lí kāi le","Lãnh đạo còn chưa nói xong, anh ấy đã rời đi trước."],["他看我心情不好，便陪我聊了半天。","tā kàn wǒ xīn qíng bù hǎo biàn péi wǒ liáo le bàn tiān","Anh ấy thấy tâm trạng tôi không tốt, liền ngồi trò chuyện với tôi cả buổi."],["我写完作业便和朋友一起出去玩儿了。","wǒ xiě wán zuò yè biàn hé péng you yì qǐ chū qù wán r le","Tôi làm xong bài tập liền cùng bạn bè ra ngoài chơi."]]},{"n":57,"c":["句子的类型","复句","选择复句"],"z":"或是……，或是……","t":"Câu phức lựa chọn: 或是……，或是……","d":"= Hoặc là…, hoặc là….","e":[["晚餐我或是吃面条儿，或是喝粥。","wǎn cān wǒ huò shì chī miàn tiáo r huò shì hē zhōu","Bữa tối tôi hoặc là ăn mì, hoặc là ăn cháo."],["假期他或是去海边度假，或是去爬山。","jià qī tā huò shì qù hǎi biān dù jià huò shì qù pá shān","Kỳ nghỉ anh ấy hoặc đi biển nghỉ dưỡng, hoặc đi leo núi."]]},{"n":58,"c":["句子的类型","复句","假设复句"],"z":"一旦……，就……","t":"Câu phức giả thiết: 一旦……，就……","d":"= Một khi…thì….","e":[["一旦养成坏习惯，就很难改变。","yí dàn yǎng chéng huài xí guàn jiù hěn nán gǎi biàn","Một khi đã hình thành thói quen xấu thì rất khó thay đổi."],["孩子一旦发烧，就赶快送去医院。","hái zi yí dàn fā shāo jiù gǎn kuài sòng qù yī yuàn","Trẻ một khi bị sốt thì phải nhanh chóng đưa đến bệnh viện."]]},{"n":59,"c":["句子的类型","复句","假设复句"],"z":"假如……，（就）……","t":"Câu phức giả thiết: 假如……，(就)……","d":"= Giả như…thì….","e":[["假如他们也同意，我们就按照计划开展工作。","jiǎ rú tā men yě tóng yì wǒ men jiù àn zhào jì huà kāi zhǎn gōng zuò","Giả như họ cũng đồng ý thì chúng ta sẽ triển khai công việc theo kế hoạch."],["假如有一天你当了校长，你会制定什么规则？","jiǎ rú yǒu yì tiān nǐ dāng le xiào zhǎng nǐ huì zhì dìng shén me guī zé","Giả như một ngày nào đó bạn làm hiệu trưởng, bạn sẽ đặt ra quy tắc gì?"]]},{"n":60,"c":["句子的类型","复句","假设复句"],"z":"万一……，（就）……","t":"Câu phức giả thiết: 万一……，(就)……","d":"= Lỡ như, nhỡ mà…thì… (giả thiết điều không mong muốn).","e":[["万一他不配合，我们就要想其他办法。","wàn yī tā bú pèi hé wǒ men jiù yào xiǎng qí tā bàn fǎ","Lỡ như anh ta không hợp tác, chúng ta phải nghĩ cách khác."],["万一失败了，你考虑过后果吗？","wàn yī shī bài le nǐ kǎo lǜ guò hòu guǒ ma","Nhỡ thất bại thì sao, bạn đã nghĩ đến hậu quả chưa?"]]},{"n":61,"c":["句子的类型","复句","假设复句"],"z":"……，要不然/不然……","t":"Câu phức giả thiết: ……，要不然/不然……","d":"= …, nếu không thì….","e":[["公司需要敢想敢干的年轻人，要不然就很难有发展。","gōng sī xū yào gǎn xiǎng gǎn gàn de nián qīng rén yào bù rán jiù hěn nán yǒu fā zhǎn","Công ty cần những người trẻ dám nghĩ dám làm, nếu không sẽ rất khó phát triển."],["还好我反应快，不然孩子就摔倒了。","hái hǎo wǒ fǎn yìng kuài bù rán hái zi jiù shuāi dǎo le","May mà tôi phản ứng nhanh, nếu không đứa bé đã ngã rồi."]]},{"n":62,"c":["句子的类型","复句","因果复句"],"z":"……，因而……","t":"Câu phức nhân quả: ……，因而……","d":"= …, cho nên/vì thế… (văn viết).","e":[["她上课坚持认真听讲，因而成绩始终非常优秀。","tā shàng kè jiān chí rèn zhēn tīng jiǎng yīn ér chéng jì shǐ zhōng fēi cháng yōu xiù","Cô ấy luôn chăm chú nghe giảng trên lớp, vì thế thành tích luôn rất xuất sắc."],["我和他认识很多年了，因而很了解他的性格。","wǒ hé tā rèn shi hěn duō nián le yīn ér hěn liǎo jiě tā de xìng gé","Tôi và anh ấy quen nhau nhiều năm rồi, cho nên rất hiểu tính cách anh ấy."]]},{"n":63,"c":["句子的类型","复句","因果复句"],"z":"……，可见……","t":"Câu phức nhân quả: ……，可见……","d":"= …, có thể thấy… (rút ra kết luận từ sự thật).","e":[["这个项目完成得如此顺利，可见团队的合作非常有效。","zhè ge xiàng mù wán chéng de rú cǐ shùn lì kě jiàn tuán duì de hé zuò fēi cháng yǒu xiào","Dự án này hoàn thành thuận lợi như vậy, có thể thấy sự phối hợp của nhóm rất hiệu quả."],["他每天都在图书馆学习，可见他对考试非常重视。","tā měi tiān dōu zài tú shū guǎn xué xí kě jiàn tā duì kǎo shì fēi cháng zhòng shì","Ngày nào anh ấy cũng học ở thư viện, có thể thấy anh ấy rất coi trọng kỳ thi."]]},{"n":64,"c":["句子的类型","复句","让步复句"],"z":"哪怕……，也……","t":"Câu phức nhượng bộ: 哪怕……，也……","d":"= Cho dù/dẫu cho…cũng….","e":[["哪怕时间再紧张，也要按时完成任务。","nǎ pà shí jiān zài jǐn zhāng yě yào àn shí wán chéng rèn wu","Cho dù thời gian gấp đến đâu cũng phải hoàn thành nhiệm vụ đúng hạn."],["哪怕租金继续提高，也仍然有很多人愿意住在这里。","nǎ pà zū jīn jì xù tí gāo yě réng rán yǒu hěn duō rén yuàn yì zhù zài zhè lǐ","Cho dù tiền thuê tiếp tục tăng, vẫn có rất nhiều người muốn sống ở đây."]]},{"n":65,"c":["句子的类型","复句","递进复句"],"z":"不但不/不但没有……，反而……","t":"Câu phức tăng tiến: 不但不/不但没有……，反而……","d":"= Không những không…, ngược lại còn….","e":[["他不但不改正错误，反而继续犯更大的错误。","tā bú dàn bù gǎi zhèng cuò wù fǎn ér jì xù fàn gèng dà de cuò wù","Anh ta không những không sửa lỗi, ngược lại còn tiếp tục phạm lỗi lớn hơn."],["你这样做不但没有解决问题，反而增加了新问题。","nǐ zhè yàng zuò bú dàn méi yǒu jiě jué wèn tí fǎn ér zēng jiā le xīn wèn tí","Bạn làm như vậy không những không giải quyết được vấn đề, ngược lại còn thêm vấn đề mới."],["火不但没有灭，反而越来越大了。","huǒ bú dàn méi yǒu miè fǎn ér yuè lái yuè dà le","Lửa không những không tắt, ngược lại càng lúc càng to."]]},{"n":66,"c":["句子的类型","复句","递进复句"],"z":"不是……，还/还是……","t":"Câu phức tăng tiến: 不是……，还/还是……","d":"= Không phải (chỉ)…là được, còn phải….","e":[["不是光有目标就可以，还要行动起来。","bú shì guāng yǒu mù biāo jiù kě yǐ hái yào xíng dòng qǐ lái","Không phải chỉ có mục tiêu là được, còn phải hành động nữa."],["这个问题不是我一个人就能解决的，还是需要大家积极配合。","zhè ge wèn tí bú shì wǒ yí gè rén jiù néng jiě jué de hái shì xū yào dà jiā jī jí pèi hé","Vấn đề này không phải một mình tôi giải quyết được, vẫn cần mọi người tích cực phối hợp."]]},{"n":67,"c":["句子的类型","复句","目的复句"],"z":"……，为的是……","t":"Câu phức mục đích: ……，为的是……","d":"= …, là để…/mục đích là….","e":[["他每天早起锻炼，为的是保持健康。","tā měi tiān zǎo qǐ duàn liàn wèi de shì bǎo chí jiàn kāng","Anh ấy dậy sớm tập thể dục mỗi ngày là để giữ gìn sức khỏe."],["她每天都练习中文，为的是将来能够来中国留学。","tā měi tiān dōu liàn xí zhōng wén wèi de shì jiāng lái néng gòu lái zhōng guó liú xué","Ngày nào cô ấy cũng luyện tiếng Trung là để sau này có thể sang Trung Quốc du học."]]},{"n":68,"c":["句子的类型","复句","紧缩复句"],"z":"没有……就没有……","t":"Câu rút gọn: 没有……就没有……","d":"= Không có…thì không có….","e":[["没有老师的努力付出就没有我们今天的成绩。","méi yǒu lǎo shī de nǔ lì fù chū jiù méi yǒu wǒ men jīn tiān de chéng jì","Không có sự cống hiến của thầy cô thì không có thành tích của chúng em hôm nay."],["没有汗水就没有收获。","méi yǒu hàn shuǐ jiù méi yǒu shōu huò","Không có mồ hôi thì không có thu hoạch."]]},{"n":69,"c":["句子的类型","复句","紧缩复句"],"z":"不……不……","t":"Câu rút gọn: 不……不……","d":"= Không…thì không… (điều kiện): 不尝不知道 = không nếm thì không biết.","e":[["不尝不知道，这种水果的味道果然很独特。","bù cháng bù zhī dao zhè zhǒng shuǐ guǒ de wèi dào guǒ rán hěn dú tè","Không nếm thì không biết, vị của loại quả này quả nhiên rất độc đáo."],["毛病虽然不大，但还是应该修理一下，不修不安全。","máo bìng suī rán bú dà dàn hái shì yīng gāi xiū lǐ yí xià bù xiū bù ān quán","Hỏng hóc tuy không lớn nhưng vẫn nên sửa một chút, không sửa thì không an toàn."]]},{"n":70,"c":["句子的类型","复句","紧缩复句"],"z":"再……也……","t":"Câu rút gọn: 再……也……","d":"= Dù…đến đâu cũng….","e":[["这首歌再听多少遍也不会烦。","zhè shǒu gē zài tīng duō shǎo biàn yě bú huì fán","Bài hát này nghe bao nhiêu lần cũng không chán."],["困难再大也要坚持下去。","kùn nán zài dà yě yào jiān chí xià qù","Khó khăn lớn đến đâu cũng phải kiên trì tiếp."]]}],"6":[{"n":1,"c":["语素","类前缀",""],"z":"超—、多—、反—、无—、亚—、准—","t":"Tiền tố loại 超, 多, 反, 无, 亚, 准","d":"超 = siêu, vượt (超水平 = vượt trình độ thường ngày); 多 = đa (多层次 = nhiều tầng lớp); 反 = phản, ngược (反作用 = tác dụng ngược); 无 = vô, không (无病毒 = không vi-rút); 亚 = á, thứ cấp (亚中心 = trung tâm phụ); 准 = chuẩn, sắp trở thành (准媳妇 = con dâu tương lai).","e":[["没想到他竟然超水平发挥，最终赢得了这场比赛。","méi xiǎng dào tā jìng rán chāo shuǐ píng fā huī zuì zhōng yíng dé le zhè chǎng bǐ sài","Không ngờ anh ấy lại thi đấu vượt trình độ, cuối cùng giành chiến thắng trận đấu này."],["这位演员的表演总能展现出多层次的人物心理。","zhè wèi yǎn yuán de biǎo yǎn zǒng néng zhǎn xiàn chū duō céng cì de rén wù xīn lǐ","Màn diễn của diễn viên này luôn thể hiện được tâm lý nhân vật nhiều tầng lớp."],["父母过分关注孩子的一举一动，会对孩子的成长起到反作用。","fù mǔ guò fèn guān zhù hái zi de yì jǔ yí dòng huì duì hái zi de chéng zhǎng qǐ dào fǎn zuò yòng","Bố mẹ quá chú ý đến từng cử chỉ hành động của con sẽ gây tác dụng ngược cho sự trưởng thành của con."],["公司所有电脑系统都经过了严格的安全检查，确保无病毒运行。","gōng sī suǒ yǒu diàn nǎo xì tǒng dōu jīng guò le yán gé de ān quán jiǎn chá què bǎo wú bìng dú yùn xíng","Toàn bộ hệ thống máy tính của công ty đều đã qua kiểm tra an ninh nghiêm ngặt, đảm bảo vận hành không vi-rút."],["新开发的商业区已经成为了城市亚中心，发展潜力巨大。","xīn kāi fā de shāng yè qū yǐ jīng chéng wéi le chéng shì yà zhōng xīn fā zhǎn qián lì jù dà","Khu thương mại mới phát triển đã trở thành trung tâm phụ của thành phố, tiềm năng phát triển rất lớn."],["小张和女朋友小李已经订婚了，小李现在是张家的准媳妇。","xiǎo zhāng hé nǚ péng you xiǎo lǐ yǐ jīng dìng hūn le xiǎo lǐ xiàn zài shì zhāng jiā de zhǔn xí fù","Cậu Trương và bạn gái là cô Lý đã đính hôn, giờ cô Lý là con dâu tương lai của nhà họ Trương."]]},{"n":2,"c":["语素","类后缀",""],"z":"—化、—式、—型、—性","t":"Hậu tố loại 化, 式, 型, 性","d":"化 = hóa (数字化 = số hóa); 式 = kiểu, dạng (专题式 = theo chuyên đề); 型 = loại, mẫu (观赏型 = loại để ngắm); 性 = tính (便捷性 = tính tiện lợi).","e":[["随着科技的发展，人们迎来了数字化时代。","suí zhe kē jì de fā zhǎn rén men yíng lái le shù zì huà shí dài","Cùng với sự phát triển của khoa học công nghệ, con người đã bước vào thời đại số hóa."],["本课程采用专题式的教学方法，每课介绍一个专题。","běn kè chéng cǎi yòng zhuān tí shì de jiào xué fāng fǎ měi kè jiè shào yí gè zhuān tí","Khóa học này áp dụng phương pháp dạy theo chuyên đề, mỗi bài giới thiệu một chuyên đề."],["这种鱼是观赏型的，很多人把它们当做宠物。","zhè zhǒng yú shì guān shǎng xíng de hěn duō rén bǎ tā men dàng zuò chǒng wù","Loài cá này thuộc loại cá cảnh, nhiều người nuôi chúng làm thú cưng."],["这款产品具备很好的便捷性，使用十分方便。","zhè kuǎn chǎn pǐn jù bèi hěn hǎo de biàn jié xìng shǐ yòng shí fēn fāng biàn","Sản phẩm này có tính tiện lợi rất tốt, sử dụng vô cùng dễ dàng."]]},{"n":3,"c":["词类","代词","人称代词"],"z":"人家","t":"Đại từ nhân xưng 人家","d":"人家 (rénjia) = người ta, người khác; đôi khi chỉ chính mình (nũng nịu).","e":[["这是人家的东西，咱们不能随便拿。","zhè shì rén jiā de dōng xi zán men bù néng suí biàn ná","Đây là đồ của người ta, chúng ta không được tùy tiện lấy."],["今天多亏了老张来帮忙，我们得好好感谢人家。","jīn tiān duō kuī le lǎo zhāng lái bāng máng wǒ men děi hǎo hǎo gǎn xiè rén jiā","Hôm nay may mà có lão Trương đến giúp, chúng ta phải cảm ơn người ta cho tử tế."]]},{"n":4,"c":["词类","量词","名量词"],"z":"专用名量词：串、滴、枝、扇、卷¹、卷²","t":"Lượng từ chuyên dùng 串, 滴, 枝, 扇, 卷","d":"串 chuỗi/xâu, 滴 giọt, 枝 cành/bông (hoa có cành), 扇 cánh (cửa), 卷 (juǎn) cuộn; 卷 (juàn) quyển, tập (sách chia tập).","e":[["这串项链是丈夫送给我的订婚礼物。","zhè chuàn xiàng liàn shì zhàng fu sòng gěi wǒ de dìng hūn lǐ wù","Chuỗi vòng cổ này là quà đính hôn chồng tặng tôi."],["你试试往碗里加几滴醋，说不定味道会更好。","nǐ shì shì wǎng wǎn lǐ jiā jǐ dī cù shuō bú dìng wèi dào huì gèng hǎo","Bạn thử cho mấy giọt giấm vào bát, không chừng vị sẽ ngon hơn."],["下班回家的路上，妈妈买了几枝玫瑰花。","xià bān huí jiā de lù shang mā ma mǎi le jǐ zhī méi guī huā","Trên đường tan làm về nhà, mẹ đã mua mấy bông hoa hồng."],["听了他的话，我心里就像打开了一扇窗，突然亮了。","tīng le tā de huà wǒ xīn lǐ jiù xiàng dǎ kāi le yí shàn chuāng tū rán liàng le","Nghe lời anh ấy nói, trong lòng tôi như mở ra một cánh cửa sổ, bỗng sáng bừng lên."],["你把桌子上那卷胶带递给我一下。","nǐ bǎ zhuō zi shàng nà juàn jiāo dài dì gěi wǒ yí xià","Bạn đưa giúp tôi cuộn băng dính trên bàn kia một chút."],["这套书分为上、中、下三卷。","zhè tào shū fēn wéi shàng zhōng xià sān juàn","Bộ sách này chia làm ba quyển: thượng, trung, hạ."]]},{"n":5,"c":["词类","量词","动量词"],"z":"番","t":"Động lượng từ 番","d":"一番 = một phen, một hồi (quá trình tốn công sức).","e":[["经过一番激烈的争论，我们最终达成了一致。","jīng guò yì fān jī liè de zhēng lùn wǒ men zuì zhōng dá chéng le yí zhì","Sau một hồi tranh luận gay gắt, cuối cùng chúng tôi đã đạt được sự thống nhất."]]},{"n":6,"c":["词类","副词","程度副词"],"z":"特、异常、较为","t":"Phó từ mức độ 特, 异常, 较为","d":"特 = rất, cực (khẩu ngữ); 异常 = khác thường, hết sức; 较为 = tương đối, khá (văn viết).","e":[["听说我获得了奖学金，同学们都特羡慕。","tīng shuō wǒ huò dé le jiǎng xué jīn tóng xué men dōu tè xiàn mù","Nghe tin tôi được học bổng, các bạn đều rất ngưỡng mộ."],["相声是一种幽默的艺术，特有意思。","xiàng sheng shì yì zhǒng yōu mò de yì shù tè yǒu yì si","Tướng thanh là một loại hình nghệ thuật hài hước, cực kỳ thú vị."],["改进后的仪器操作异常便捷。","gǎi jìn hòu de yí qì cāo zuò yì cháng biàn jié","Thiết bị sau khi cải tiến thao tác hết sức thuận tiện."],["今年夏天异常炎热。","jīn nián xià tiān yì cháng yán rè","Mùa hè năm nay nóng bức khác thường."],["这本小说较为客观地反映了当时的社会现实。","zhè běn xiǎo shuō jiào wéi kè guān de fǎn yìng le dāng shí de shè huì xiàn shí","Cuốn tiểu thuyết này phản ánh tương đối khách quan hiện thực xã hội thời đó."],["专家们一致认为这项研究的设计较为合理。","zhuān jiā men yí zhì rèn wéi zhè xiàng yán jiū de shè jì jiào wéi hé lǐ","Các chuyên gia đều cho rằng thiết kế của nghiên cứu này khá hợp lý."]]},{"n":7,"c":["词类","副词","范围副词"],"z":"净、一同、大都","t":"Phó từ phạm vi 净, 一同, 大都","d":"净 = toàn, chỉ toàn (khẩu ngữ); 一同 = cùng nhau; 大都 = phần lớn, đại đa số.","e":[["我们净忙着说话，甚至忘了给客人倒茶。","wǒ men jìng máng zhe shuō huà shèn zhì wàng le gěi kè rén dào chá","Chúng tôi chỉ mải nói chuyện, thậm chí quên cả rót trà cho khách."],["那位老师的书房里净是外文书。","nà wèi lǎo shī de shū fáng lǐ jìng shì wài wén shū","Trong thư phòng của thầy giáo đó toàn là sách ngoại văn."],["我明天在大厅等你，咱们一同出发。","wǒ míng tiān zài dà tīng děng nǐ zán men yì tóng chū fā","Ngày mai tôi đợi bạn ở sảnh, chúng ta cùng xuất phát."],["人们聚集在广场上，一同迎接新年的到来。","rén men jù jí zài guǎng chǎng shàng yì tóng yíng jiē xīn nián de dào lái","Mọi người tập trung ở quảng trường, cùng nhau đón chào năm mới."],["公园里散步的老年人大都是附近的居民。","gōng yuán lǐ sàn bù de lǎo nián rén dà dōu shì fù jìn de jū mín","Người già đi dạo trong công viên phần lớn là cư dân quanh đây."],["假期时，这里的人们大都选择去海边度假。","jià qī shí zhè lǐ de rén men dà dōu xuǎn zé qù hǎi biān dù jià","Vào kỳ nghỉ, người dân ở đây phần lớn chọn đi biển nghỉ dưỡng."]]},{"n":8,"c":["词类","副词","时间副词"],"z":"一时、不时、仍旧、依旧、一向","t":"Phó từ thời gian 一时, 不时, 仍旧, 依旧, 一向","d":"一时 = nhất thời, trong chốc lát; 不时 = thỉnh thoảng, chốc chốc; 仍旧/依旧 = vẫn, vẫn như cũ; 一向 = xưa nay, từ trước đến giờ.","e":[["他一时紧张，忘记要说什么了。","tā yì shí jǐn zhāng wàng jì yào shuō shén me le","Anh ấy nhất thời căng thẳng, quên mất định nói gì."],["面对眼前的比赛结果，人们一时难以接受。","miàn duì yǎn qián de bǐ sài jié guǒ rén men yì shí nán yǐ jiē shòu","Trước kết quả trận đấu trước mắt, mọi người nhất thời khó chấp nhận."],["她不时看看手机，等待着朋友的消息。","tā bù shí kàn kàn shǒu jī děng dài zhe péng you de xiāo xī","Cô ấy chốc chốc lại nhìn điện thoại, chờ tin của bạn."],["隔壁房间不时传来一阵笑声。","gé bì fáng jiān bù shí chuán lái yí zhèn xiào shēng","Phòng bên cạnh chốc chốc lại vọng sang một tràng cười."],["实验失败了，但他们没有放弃，仍旧坚持干下去。","shí yàn shī bài le dàn tā men méi yǒu fàng qì réng jiù jiān chí gàn xià qù","Thí nghiệm thất bại, nhưng họ không bỏ cuộc, vẫn kiên trì làm tiếp."],["他很努力地练习发音，但仍旧说得不太标准。","tā hěn nǔ lì de liàn xí fā yīn dàn réng jiù shuō de bú tài biāo zhǔn","Anh ấy luyện phát âm rất chăm chỉ, nhưng vẫn nói chưa chuẩn lắm."],["他们带着孩子又跑了几家医院，但依旧没有得到明确的诊断。","tā men dài zhe hái zi yòu pǎo le jǐ jiā yī yuàn dàn yī jiù méi yǒu dé dào míng què de zhěn duàn","Họ đưa con chạy thêm mấy bệnh viện nữa, nhưng vẫn chưa có chẩn đoán rõ ràng."],["二十多年过去了，她依旧那么美丽动人。","èr shí duō nián guò qù le tā yī jiù nà me měi lì dòng rén","Hơn hai mươi năm trôi qua, cô ấy vẫn xinh đẹp cuốn hút như vậy."],["作为老师，她一向严格要求自己的学生。","zuò wéi lǎo shī tā yí xiàng yán gé yāo qiú zì jǐ de xué shēng","Là giáo viên, cô ấy xưa nay luôn yêu cầu nghiêm khắc với học sinh của mình."],["他一向喜欢跟朋友开玩笑。","tā yí xiàng xǐ huan gēn péng you kāi wán xiào","Anh ấy xưa nay vẫn thích đùa với bạn bè."]]},{"n":9,"c":["词类","副词","频率副词"],"z":"一再、再三","t":"Phó từ tần suất 一再, 再三","d":"一再/再三 = nhiều lần, hết lần này đến lần khác.","e":[["出发前老师一再提醒大家带上护照，可我还是忘了。","chū fā qián lǎo shī yí zài tí xǐng dà jiā dài shàng hù zhào kě wǒ hái shì wàng le","Trước khi xuất phát, thầy giáo đã nhiều lần nhắc mọi người mang hộ chiếu, vậy mà tôi vẫn quên."],["王经理一再强调这个项目对于公司至关重要。","wáng jīng lǐ yí zài qiáng diào zhè ge xiàng mù duì yú gōng sī zhì guān zhòng yào","Giám đốc Vương nhiều lần nhấn mạnh dự án này cực kỳ quan trọng đối với công ty."],["他再三考虑要不要放弃工作的机会。","tā zài sān kǎo lǜ yào bu yào fàng qì gōng zuò de jī huì","Anh ấy cân nhắc đi cân nhắc lại có nên từ bỏ cơ hội việc làm hay không."],["小张再三向领导解释他上班迟到的原因。","xiǎo zhāng zài sān xiàng lǐng dǎo jiě shì tā shàng bān chí dào de yuán yīn","Cậu Trương hết lần này đến lần khác giải thích với lãnh đạo lý do đi làm muộn."]]},{"n":10,"c":["词类","副词","方式副词"],"z":"不禁、赶忙、特地、特意、偷偷","t":"Phó từ cách thức 不禁, 赶忙, 特地, 特意, 偷偷","d":"不禁 = không kìm được, bất giác; 赶忙 = vội vàng; 特地/特意 = đặc biệt, cất công (vì mục đích riêng); 偷偷 = lén lút.","e":[["听到这可怕的消息，我的心不禁凉了。","tīng dào zhè kě pà de xiāo xī wǒ de xīn bù jīn liáng le","Nghe tin đáng sợ này, lòng tôi bất giác lạnh đi."],["听完她的演讲，大家不禁鼓起掌来。","tīng wán tā de yǎn jiǎng dà jiā bù jīn gǔ qǐ zhǎng lái","Nghe xong bài diễn thuyết của cô ấy, mọi người không kìm được vỗ tay."],["上课铃一响，学生们就赶忙跑回了教室。","shàng kè líng yì xiǎng xué shēng men jiù gǎn máng pǎo huí le jiào shì","Chuông vào học vừa reo, học sinh liền vội vàng chạy về lớp."],["听到有人求助，他赶忙过去帮忙。","tīng dào yǒu rén qiú zhù tā gǎn máng guò qù bāng máng","Nghe thấy có người kêu cứu, anh ấy vội chạy đến giúp."],["回国当天，朋友特地开车把我送到了机场。","huí guó dàng tiān péng you tè dì kāi chē bǎ wǒ sòng dào le jī chǎng","Hôm về nước, bạn tôi đã cất công lái xe đưa tôi ra sân bay."],["为了掌握实际情况，政府特地组织专家团队到当地开展调查。","wèi le zhǎng wò shí jì qíng kuàng zhèng fǔ tè dì zǔ zhī zhuān jiā tuán duì dào dāng dì kāi zhǎn diào chá","Để nắm được tình hình thực tế, chính phủ đặc biệt tổ chức đoàn chuyên gia đến địa phương tiến hành điều tra."],["这些书是我特意请朋友从国外买回来的。","zhè xiē shū shì wǒ tè yì qǐng péng you cóng guó wài mǎi huí lái de","Những quyển sách này là tôi đặc biệt nhờ bạn mua từ nước ngoài về."],["我特意为您准备了一份礼物，请您一定收下。","wǒ tè yì wèi nín zhǔn bèi le yí fèn lǐ wù qǐng nín yí dìng shōu xià","Tôi đặc biệt chuẩn bị cho ông/bà một món quà, xin nhất định nhận cho."],["小女孩偷偷把糖装进了口袋。","xiǎo nǚ hái tōu tōu bǎ táng zhuāng jìn le kǒu dài","Cô bé lén bỏ kẹo vào túi."],["他偷偷把那件事告诉了老师。","tā tōu tōu bǎ nà jiàn shì gào su le lǎo shī","Anh ấy lén nói chuyện đó cho thầy giáo."]]},{"n":11,"c":["词类","副词","否定副词"],"z":"未必","t":"Phó từ phủ định 未必","d":"未必 = chưa chắc, không hẳn.","e":[["她最近工作很忙，未必有时间回老家。","tā zuì jìn gōng zuò hěn máng wèi bì yǒu shí jiān huí lǎo jiā","Dạo này cô ấy rất bận, chưa chắc đã có thời gian về quê."],["有钱就一定会幸福吗？那也未必。","yǒu qián jiù yí dìng huì xìng fú ma nà yě wèi bì","Có tiền là nhất định sẽ hạnh phúc sao? Cũng chưa chắc."]]},{"n":12,"c":["词类","副词","语气副词"],"z":"恰好、倒是、干脆、明明、总算","t":"Phó từ ngữ khí 恰好, 倒是, 干脆, 明明, 总算","d":"恰好 = vừa đúng, vừa khéo; 倒是 = thì cũng…(nhưng…) / ngược lại thì…; 干脆 = dứt khoát, luôn cho xong; 明明 = rõ ràng là (mà…); 总算 = cuối cùng cũng.","e":[["婚礼那天恰好是新娘的生日。","hūn lǐ nà tiān qià hǎo shì xīn niáng de shēng rì","Ngày cưới vừa khéo đúng là sinh nhật cô dâu."],["下周六我恰好有时间，咱们可以一起去爬山。","xià zhōu liù wǒ qià hǎo yǒu shí jiān zán men kě yǐ yì qǐ qù pá shān","Thứ Bảy tuần sau tôi vừa hay có thời gian, chúng ta có thể cùng đi leo núi."],["你计划得倒是很好，可是你能做到吗？","nǐ jì huà de dào shì hěn hǎo kě shì nǐ néng zuò dào ma","Bạn lên kế hoạch thì hay đấy, nhưng bạn làm được không?"],["这部漫画的内容一般，绘画风格倒是生动有趣。","zhè bù màn huà de nèi róng yì bān huì huà fēng gé dào shì shēng dòng yǒu qù","Nội dung bộ truyện tranh này bình thường, nhưng phong cách vẽ thì lại sinh động thú vị."],["既然双方不愿意合作，干脆就不要浪费时间再谈了。","jì rán shuāng fāng bú yuàn yì hé zuò gān cuì jiù bú yào làng fèi shí jiān zài tán le","Hai bên đã không muốn hợp tác thì dứt khoát đừng lãng phí thời gian đàm phán nữa."],["你今天这么累，干脆早点休息，明天再工作吧！","nǐ jīn tiān zhè me lèi gān cuì zǎo diǎn xiū xi míng tiān zài gōng zuò ba","Hôm nay bạn mệt thế này, dứt khoát nghỉ sớm đi, mai hẵng làm!"],["你明明不胖，为什么总嫌自己胖呢？","nǐ míng míng bú pàng wèi shén me zǒng xián zì jǐ pàng ne","Bạn rõ ràng là không béo, sao lúc nào cũng chê mình béo vậy?"],["明明是他做错了事，凭什么让我向他道歉？","míng míng shì tā zuò cuò le shì píng shén me ràng wǒ xiàng tā dào qiàn","Rõ ràng là anh ta làm sai, dựa vào đâu mà bắt tôi xin lỗi anh ta?"],["我们在路边等了很久，总算有位好心的司机让我们搭车回到了学校。","wǒ men zài lù biān děng le hěn jiǔ zǒng suàn yǒu wèi hǎo xīn de sī jī ràng wǒ men dā chē huí dào le xué xiào","Chúng tôi đợi bên đường rất lâu, cuối cùng cũng có một bác tài tốt bụng cho chúng tôi đi nhờ về trường."],["连着下了一周小雨，今天总算迎来了一个晴天。","lián zhe xià le yì zhōu xiǎo yǔ jīn tiān zǒng suàn yíng lái le yí gè qíng tiān","Mưa nhỏ liền một tuần, hôm nay cuối cùng cũng đón được một ngày nắng."]]},{"n":13,"c":["词类","介词","引出时间、处所"],"z":"于","t":"Giới từ 于","d":"于 = ở, vào (thời gian, nơi chốn — văn viết, đặt sau động từ hoặc trước động từ).","e":[["这所学校成立于1950年。","zhè suǒ xué xiào chéng lì yú nián","Ngôi trường này được thành lập vào năm 1950."],["他已于上月离京。","tā yǐ yú shàng yuè lí jīng","Anh ấy đã rời Bắc Kinh vào tháng trước."]]},{"n":14,"c":["词类","介词","引出对象"],"z":"至于","t":"Giới từ 至于","d":"至于 = còn về, đến như (chuyển sang chủ đề liên quan).","e":[["刚来中国时，我既听不懂也说不清楚，至于写作和阅读，就更不行了。","gāng lái zhōng guó shí wǒ jì tīng bù dǒng yě shuō bù qīng chu zhì yú xiě zuò hé yuè dú jiù gèng bù xíng le","Hồi mới đến Trung Quốc, tôi vừa nghe không hiểu vừa nói không rõ, còn viết và đọc thì càng kém."],["新产品已经开始生产了，至于销售时间和价格，现在还不能确定。","xīn chǎn pǐn yǐ jīng kāi shǐ shēng chǎn le zhì yú xiāo shòu shí jiān hé jià gé xiàn zài hái bù néng què dìng","Sản phẩm mới đã bắt đầu sản xuất, còn về thời gian bán và giá cả thì hiện vẫn chưa thể xác định."]]},{"n":15,"c":["词类","介词","引出目的、原因"],"z":"因","t":"Giới từ 因","d":"因 = vì, do (văn viết). 因…而… = vì…mà….","e":[["因天气原因，运动会延期至周六举行。","yīn tiān qì yuán yīn yùn dòng huì yán qī zhì zhōu liù jǔ xíng","Vì lý do thời tiết, đại hội thể thao được hoãn đến thứ Bảy."],["他因迟到而错过了这次面试。","tā yīn chí dào ér cuò guò le zhè cì miàn shì","Anh ấy vì đến muộn mà lỡ mất buổi phỏng vấn lần này."]]},{"n":16,"c":["词类","介词","表示排除"],"z":"除","t":"Giới từ 除","d":"除…外/以外 = ngoài…ra (văn viết của 除了).","e":[["除特殊情况外，不得随意离开工作岗位。","chú tè shū qíng kuàng wài bù de suí yì lí kāi gōng zuò gǎng wèi","Trừ trường hợp đặc biệt, không được tùy ý rời khỏi vị trí làm việc."],["除申请表以外，申请人还应提交一份个人简历。","chú shēn qǐng biǎo yǐ wài shēn qǐng rén hái yìng tí jiāo yí fèn gè rén jiǎn lì","Ngoài đơn đăng ký, người nộp đơn còn phải nộp một bản sơ yếu lý lịch."]]},{"n":17,"c":["词类","连词","连接分句或句子"],"z":"不料","t":"Liên từ 不料","d":"不料 = không ngờ (sự việc xảy ra ngoài dự tính).","e":[["我本来打算在房间看书，不料突然停电了，我只好去图书馆。","wǒ běn lái dǎ suàn zài fáng jiān kàn shū bú liào tū rán tíng diàn le wǒ zhǐ hǎo qù tú shū guǎn","Tôi vốn định đọc sách trong phòng, không ngờ đột nhiên mất điện, tôi đành đến thư viện."],["我以为两个孩子能一起好好玩儿，不料他俩刚一见面就吵起来了。","wǒ yǐ wéi liǎng gè hái zi néng yì qǐ hǎo hǎo wán r bú liào tā liǎ gāng yí jiàn miàn jiù chǎo qǐ lái le","Tôi tưởng hai đứa trẻ có thể chơi vui vẻ với nhau, không ngờ hai đứa vừa gặp nhau đã cãi nhau."]]},{"n":18,"c":["词类","助词","结构助词"],"z":"所","t":"Trợ từ kết cấu 所","d":"所 + động từ (+的) + danh từ: dùng trong văn viết để nhấn mạnh đối tượng của động từ: 人们所熟悉的故事 = câu chuyện mà mọi người quen thuộc.","e":[["这部电影是根据人们所熟悉的故事改编的。","zhè bù diàn yǐng shì gēn jù rén men suǒ shú xī de gù shì gǎi biān de","Bộ phim này được chuyển thể từ câu chuyện mà mọi người quen thuộc."],["你所了解的情况只是一小部分。","nǐ suǒ liǎo jiě de qíng kuàng zhǐ shì yì xiǎo bù fen","Tình hình bạn nắm được chỉ là một phần nhỏ."]]},{"n":19,"c":["词类","助词","语气助词"],"z":"啦、嘛","t":"Trợ từ ngữ khí 啦, 嘛","d":"啦 = 了 + 啊 (vui vẻ, nhấn mạnh); 嘛 = mà (hiển nhiên, khuyên nhủ nhẹ nhàng).","e":[["我昨天就已经把作业交给老师啦！","wǒ zuó tiān jiù yǐ jīng bǎ zuò yè jiāo gěi lǎo shī lā","Hôm qua tôi đã nộp bài tập cho thầy rồi mà!"],["这些文件对于公司至关重要，你可千万别弄丢啦！","zhè xiē wén jiàn duì yú gōng sī zhì guān zhòng yào nǐ kě qiān wàn bié nòng diū lā","Những tài liệu này cực kỳ quan trọng với công ty, bạn nhất định đừng làm mất đấy!"],["我只是开个玩笑，你不要太认真嘛。","wǒ zhǐ shì kāi gè wán xiào nǐ bú yào tài rèn zhēn ma","Tôi chỉ đùa chút thôi mà, bạn đừng nghiêm túc quá."],["要是觉得累了，就走慢一点儿嘛。","yào shi jué de lèi le jiù zǒu màn yì diǎn r ma","Nếu thấy mệt thì đi chậm lại một chút mà."]]},{"n":20,"c":["词类","助词","其他助词"],"z":"也好","t":"Trợ từ 也好","d":"① …也好 = …cũng tốt, cũng được; ② A也好，B也好 = dù là A hay B (đều…).","e":[["孩子们假期不回来也好，我可以好好休息休息了。","hái zi men jià qī bù huí lái yě hǎo wǒ kě yǐ hǎo hǎo xiū xi xiū xi le","Bọn trẻ kỳ nghỉ không về cũng tốt, tôi có thể nghỉ ngơi cho thoải mái."],["手机也好，电脑也好，长时间使用都会造成眼睛疲劳。","shǒu jī yě hǎo diàn nǎo yě hǎo cháng shí jiān shǐ yòng dōu huì zào chéng yǎn jing pí láo","Dù là điện thoại hay máy tính, dùng lâu đều gây mỏi mắt."]]},{"n":21,"c":["短语","固定短语","四字格"],"z":"A这A那","t":"Cấu trúc bốn chữ A这A那","d":"= …cái này…cái kia (đủ thứ): 问这问那 = hỏi đủ thứ.","e":[["小孩子总是喜欢拉着父母问这问那。","xiǎo hái zi zǒng shì xǐ huan lā zhe fù mǔ wèn zhè wèn nà","Trẻ con lúc nào cũng thích níu bố mẹ hỏi cái này cái kia."],["既然决定了就大胆去做吧，不要总是想这想那。","jì rán jué dìng le jiù dà dǎn qù zuò ba bú yào zǒng shì xiǎng zhè xiǎng nà","Đã quyết định rồi thì cứ mạnh dạn làm đi, đừng lúc nào cũng nghĩ này nghĩ nọ."]]},{"n":22,"c":["短语","固定短语","四字格"],"z":"左A右B","t":"Cấu trúc bốn chữ 左A右B","d":"= …đi…lại (lặp đi lặp lại nhiều lần): 左思右想 = nghĩ tới nghĩ lui; 左挑右选 = chọn tới chọn lui.","e":[["天还没亮，他就醒了，躺在床上左思右想，怎么也睡不着。","tiān hái méi liàng tā jiù xǐng le tǎng zài chuáng shàng zuǒ sī yòu xiǎng zěn me yě shuì bù zhe","Trời còn chưa sáng anh ấy đã tỉnh, nằm trên giường nghĩ tới nghĩ lui, thế nào cũng không ngủ được."],["她在商场里左挑右选，始终没买到一件满意的衣服。","tā zài shāng chǎng lǐ zuǒ tiāo yòu xuǎn shǐ zhōng méi mǎi dào yí jiàn mǎn yì de yī fu","Cô ấy ở trung tâm thương mại chọn tới chọn lui, mãi vẫn không mua được bộ quần áo nào ưng ý."]]},{"n":23,"c":["短语","固定短语","其他"],"z":"好（不）容易","t":"Cụm cố định 好(不)容易","d":"好容易 = 好不容易 = khó khăn lắm mới… (hai cách nói cùng nghĩa), thường đi với 才.","e":[["我好不容易才获得这次面试机会，一定不会轻易放弃。","wǒ hǎo bù róng yì cái huò dé zhè cì miàn shì jī huì yí dìng bú huì qīng yì fàng qì","Khó khăn lắm tôi mới có được cơ hội phỏng vấn này, nhất định sẽ không dễ dàng từ bỏ."],["假期好不容易可以休息一下，你怎么还要去公司加班？","jià qī hǎo bù róng yì kě yǐ xiū xi yí xià nǐ zěn me hái yào qù gōng sī jiā bān","Kỳ nghỉ khó khăn lắm mới được nghỉ ngơi một chút, sao bạn vẫn còn đến công ty tăng ca?"]]},{"n":24,"c":["短语","固定短语","其他"],"z":"那倒（也）是","t":"Cụm cố định 那倒(也)是","d":"= Thế thì cũng (là)…, vậy thì cũng đúng (đồng tình một phần).","e":[["假如去那家公司工作能为你提供更多的发展空间，那倒也是个不错的选择。","jiǎ rú qù nà jiā gōng sī gōng zuò néng wèi nǐ tí gōng gèng duō de fā zhǎn kōng jiān nà dào yě shì gè bú cuò de xuǎn zé","Nếu làm việc ở công ty đó có thể cho bạn nhiều không gian phát triển hơn, thì đó cũng là một lựa chọn không tồi."],["要是你能从失败中吸取教训，那倒也是件值得高兴的事。","yào shi nǐ néng cóng shī bài zhōng xī qǔ jiào xùn nà dào yě shì jiàn zhí de gāo xìng de shì","Nếu bạn có thể rút ra bài học từ thất bại, thì đó cũng là điều đáng mừng."]]},{"n":25,"c":["短语","固定短语","其他"],"z":"算了","t":"Cụm cố định 算了","d":"= thôi, bỏ đi, …cho xong (kết thúc, không bàn nữa).","e":[["这些旧衣服扔掉算了，反正也不会再穿了。","zhè xiē jiù yī fu rēng diào suàn le fǎn zhèng yě bú huì zài chuān le","Mấy bộ quần áo cũ này vứt đi cho xong, đằng nào cũng không mặc nữa."],["雪下得这么大，估计不会有客人来了，干脆早点儿关门算了。","xuě xià de zhè me dà gū jì bú huì yǒu kè rén lái le gān cuì zǎo diǎn r guān mén suàn le","Tuyết rơi to thế này, chắc sẽ không có khách đến đâu, dứt khoát đóng cửa sớm cho xong."]]},{"n":26,"c":["短语","固定短语","其他"],"z":"得了","t":"Cụm cố định 得了","d":"得了 (déle) = thôi được rồi, thôi đi; …得了 = …cho xong (đề nghị dứt khoát).","e":[["得了，别再想了，结果不可能改变了。","dé le bié zài xiǎng le jié guǒ bù kě néng gǎi biàn le","Thôi đi, đừng nghĩ nữa, kết quả không thể thay đổi được đâu."],["你这么喜欢这本书，干脆送给你得了。","nǐ zhè me xǐ huan zhè běn shū gān cuì sòng gěi nǐ dé le","Bạn thích quyển sách này như vậy, dứt khoát tặng bạn luôn cho xong."]]},{"n":27,"c":["固定格式","",""],"z":"A一+量词，B一+量词","t":"Cấu trúc A一 + lượng từ，B一 + lượng từ","d":"你一言，我一语 = người một câu, kẻ một câu (bàn tán sôi nổi); 左一句、右一句 = hết câu này đến câu khác.","e":[["我们左一句、右一句地安慰，她才终于不哭了。","wǒ men zuǒ yí jù yòu yí jù de ān wèi tā cái zhōng yú bù kū le","Chúng tôi an ủi hết câu này đến câu khác, cô ấy mới chịu nín khóc."],["大家你一言，我一语，很快就商量出了解决的办法。","dà jiā nǐ yì yán wǒ yì yǔ hěn kuài jiù shāng liáng chū le jiě jué de bàn fǎ","Mọi người người một câu, kẻ một lời, chẳng mấy chốc đã bàn ra được cách giải quyết."]]},{"n":28,"c":["固定格式","",""],"z":"东一A，西一A","t":"Cấu trúc 东一A，西一A","d":"= chỗ này một…, chỗ kia một… (rải rác, lung tung).","e":[["房间里的衣服东一件，西一件，扔得哪儿都是。","fáng jiān lǐ de yī fu dōng yí jiàn xī yí jiàn rēng de nǎ r dōu shì","Quần áo trong phòng chỗ này một cái, chỗ kia một cái, vứt khắp mọi nơi."],["最近他东一本，西一本地看了不少书。","zuì jìn tā dōng yì běn xī yì běn de kàn le bù shǎo shū","Dạo này anh ấy đọc lung tung quyển này quyển kia, cũng được khá nhiều sách."]]},{"n":29,"c":["固定格式","",""],"z":"到……为止","t":"Cấu trúc 到……为止","d":"= Tính đến…, cho đến khi….","e":[["到目前为止，双方已经达成了初步的合作。","dào mù qián wéi zhǐ shuāng fāng yǐ jīng dá chéng le chū bù de hé zuò","Tính đến thời điểm hiện tại, hai bên đã đạt được sự hợp tác bước đầu."],["他把产品设计改了很多遍，一直到客户满意为止。","tā bǎ chǎn pǐn shè jì gǎi le hěn duō biàn yì zhí dào kè hù mǎn yì wéi zhǐ","Anh ấy sửa thiết kế sản phẩm rất nhiều lần, cho đến khi khách hàng hài lòng mới thôi."]]},{"n":30,"c":["固定格式","",""],"z":"X到Y头上来了","t":"Cấu trúc X到Y头上来了","d":"= …đến tận đầu Y (việc xấu rơi vào chính người nói, bất bình).","e":[["我把你当作好朋友，没想到你竟然骗到我头上来了。","wǒ bǎ nǐ dàng zuò hǎo péng you méi xiǎng dào nǐ jìng rán piàn dào wǒ tóu shàng lái le","Tôi coi bạn là bạn thân, không ngờ bạn lại lừa cả tôi."],["问题不是我造成的，怎么怪到我头上来了？","wèn tí bú shì wǒ zào chéng de zěn me guài dào wǒ tóu shàng lái le","Vấn đề không phải do tôi gây ra, sao lại đổ lên đầu tôi?"]]},{"n":31,"c":["固定格式","",""],"z":"不X不……，一X……","t":"Cấu trúc 不X不……，一X……","d":"= Không…thì không…, hễ…thì mới….","e":[["不学不知道，一学才知道汉字如此有魅力。","bù xué bù zhī dao yì xué cái zhī dao hàn zì rú cǐ yǒu mèi lì","Không học thì không biết, học rồi mới biết chữ Hán có sức hút như vậy."],["这茶不尝不知道，一尝就喜欢上了。","zhè chá bù cháng bù zhī dao yì cháng jiù xǐ huan shàng le","Trà này không nếm thì không biết, nếm một cái là thích ngay."]]},{"n":32,"c":["固定格式","",""],"z":"好你个X","t":"Cấu trúc 好你个X","d":"= Hay cho cái…! (trách mắng hoặc trêu chọc).","e":[["好你个老张，原来是你在背后说我坏话！","hǎo nǐ gè lǎo zhāng yuán lái shì nǐ zài bèi hòu shuō wǒ huài huà","Hay cho lão Trương nhà anh, hóa ra là anh nói xấu tôi sau lưng!"],["好你个骗子，赶紧把钱还给我，否则我就报警。","hǎo nǐ gè piàn zi gǎn jǐn bǎ qián huán gěi wǒ fǒu zé wǒ jiù bào jǐng","Đồ lừa đảo, mau trả tiền cho tôi, nếu không tôi sẽ báo cảnh sát."]]},{"n":33,"c":["固定格式","",""],"z":"早（也）不X，晚（也）不X","t":"Cấu trúc 早(也)不X，晚(也)不X","d":"= Sớm không…, muộn không…, (lại đúng lúc…) – sự việc xảy ra không đúng lúc.","e":[["早不来，晚不来，我正要出门你来了。","zǎo bù lái wǎn bù lái wǒ zhèng yào chū mén nǐ lái le","Sớm không đến, muộn không đến, đúng lúc tôi sắp ra ngoài thì bạn đến."],["早也不下雨，晚也不下雨，比赛刚一开始就下起来了。","zǎo yě bú xià yǔ wǎn yě bú xià yǔ bǐ sài gāng yì kāi shǐ jiù xià qǐ lái le","Sớm không mưa, muộn không mưa, trận đấu vừa mới bắt đầu thì trời đổ mưa."]]},{"n":34,"c":["固定格式","",""],"z":"看/瞧+把+宾语（施事）+X得","t":"Cấu trúc 看/瞧 + 把 + người + X得","d":"= Xem kìa, …đến thế kia (miêu tả trạng thái cực độ của ai đó).","e":[["瞧把他兴奋得，简直像个孩子一样。","qiáo bǎ tā xīng fèn de jiǎn zhí xiàng gè hái zi yí yàng","Xem anh ấy kìa, hưng phấn y như đứa trẻ vậy."],["看把你笑得，腰都直不起来了。","kàn bǎ nǐ xiào de yāo dōu zhí bù qǐ lái le","Nhìn bạn cười kìa, đến lưng cũng không thẳng lên được."]]},{"n":35,"c":["固定格式","",""],"z":"放着X不Y","t":"Cấu trúc 放着X不Y","d":"= có sẵn…mà không… (trách người bỏ qua thứ tốt có sẵn).","e":[["你为什么放着自己的车不开，跑去借别人的车？","nǐ wèi shén me fàng zhe zì jǐ de chē bù kāi pǎo qù jiè bié rén de chē","Tại sao bạn có xe của mình không lái, lại chạy đi mượn xe người khác?"],["他放着孩子不管，整天跑出去玩儿。","tā fàng zhe hái zi bù guǎn zhěng tiān pǎo chū qù wán r","Anh ta bỏ mặc con cái, suốt ngày chạy đi chơi."]]},{"n":36,"c":["固定格式","",""],"z":"X了就X了，（没）有……","t":"Cấu trúc X了就X了，(没)有……","d":"= …thì cũng …rồi, có gì mà… (chấp nhận, không bận tâm).","e":[["他已经是大人了，走了就走了，有什么好担心的？","tā yǐ jīng shì dà rén le zǒu le jiù zǒu le yǒu shén me hǎo dān xīn de","Nó đã là người lớn rồi, đi thì đi rồi, có gì mà lo?"],["东西丢了就丢了，没有什么好可惜的。","dōng xi diū le jiù diū le méi yǒu shén me hǎo kě xī de","Đồ mất thì cũng mất rồi, chẳng có gì đáng tiếc cả."]]},{"n":37,"c":["固定格式","",""],"z":"这/那也不X，那/这也不Y","t":"Cấu trúc 这/那也不X，那/这也不Y","d":"= Cái này cũng không…, cái kia cũng không… (kén chọn, chê hết).","e":[["这也不好吃，那也不好吃，你干脆饿着吧。","zhè yě bù hǎo chī nà yě bù hǎo chī nǐ gān cuì è zhe ba","Món này cũng không ngon, món kia cũng không ngon, dứt khoát nhịn đói đi."],["那也不喜欢，这也不满意，你到底想找什么样的工作？","nà yě bù xǐ huan zhè yě bù mǎn yì nǐ dào dǐ xiǎng zhǎo shén me yàng de gōng zuò","Cái kia cũng không thích, cái này cũng không vừa ý, rốt cuộc bạn muốn tìm công việc như thế nào?"]]},{"n":38,"c":["固定格式","",""],"z":"X归X，Y归Y","t":"Cấu trúc X归X，Y归Y","d":"= …thì là…, …thì là… (hai chuyện tách bạch; tuy…nhưng…).","e":[["打归打，骂归骂，父母永远是最疼你的人。","dǎ guī dǎ mà guī mà fù mǔ yǒng yuǎn shì zuì téng nǐ de rén","Đánh thì đánh, mắng thì mắng, bố mẹ mãi mãi là người thương bạn nhất."],["计划归计划，行动归行动，二者并不完全一样。","jì huà guī jì huà xíng dòng guī xíng dòng èr zhě bìng bù wán quán yí yàng","Kế hoạch là kế hoạch, hành động là hành động, hai thứ không hoàn toàn giống nhau."]]},{"n":39,"c":["固定格式","",""],"z":"看你X的/瞧他X的","t":"Cấu trúc 看你X的/瞧他X的","d":"= Xem bạn…kìa! (trêu, hoặc chê ai đó thái quá).","e":[["我跟你开玩笑呢！看你吓的！","wǒ gēn nǐ kāi wán xiào ne kàn nǐ xià de","Tôi đùa bạn thôi mà! Xem bạn sợ chưa kìa!"],["不就是得了奖学金吗？瞧他得意的！","bú jiù shì dé le jiǎng xué jīn ma qiáo tā dé yì de","Chẳng phải chỉ được học bổng thôi sao? Xem anh ta đắc ý chưa kìa!"]]},{"n":40,"c":["句子成分","补语","程度补语3"],"z":"动词/形容词+透+了","t":"Bổ ngữ mức độ: …透了","d":"Động từ/tính từ + 透了 = …thấu, …hoàn toàn, cực kỳ.","e":[["我恨透了那些不诚信的商家。","wǒ hèn tòu le nà xiē bù chéng xìn de shāng jiā","Tôi ghét cay ghét đắng những nhà buôn không trung thực."],["大雨把他身上的衣服全都淋透了。","dà yǔ bǎ tā shēn shàng de yī fu quán dōu lín tòu le","Cơn mưa lớn làm quần áo trên người anh ấy ướt sũng hết."]]},{"n":41,"c":["句子的类型","特殊句型","“把”字句4"],"z":"主语（非生物体）+把+宾语+动词+其他成分","t":"Câu chữ 把: chủ ngữ là vật vô tri","d":"Chủ ngữ là sự vật/hiện tượng tự nhiên tác động lên tân ngữ: 阳光把大地染成了红色 = Ánh nắng nhuộm đỏ mặt đất.","e":[["阳光把大地染成了红色。","yáng guāng bǎ dà dì rǎn chéng le hóng sè","Ánh nắng đã nhuộm mặt đất thành màu đỏ."],["音乐声把游客都吸引过去了。","yīn yuè shēng bǎ yóu kè dōu xī yǐn guò qù le","Tiếng nhạc đã thu hút hết du khách qua đó."]]},{"n":42,"c":["句子的类型","特殊句型","“把”字句4"],"z":"主语+把+宾语（施事）+动词+其他成分","t":"Câu chữ 把: tân ngữ là người chịu ảnh hưởng (gây ra trạng thái)","d":"A 把 B + động từ + kết quả: A khiến B ra sao: 孩子把妈妈气得睡不着觉 = Đứa trẻ làm mẹ tức đến mất ngủ.","e":[["孩子把妈妈气得睡不着觉。","hái zi bǎ mā ma qì de shuì bu zháo jiào","Đứa trẻ làm mẹ tức đến mức không ngủ được."],["她讲述的故事把大家感动哭了。","tā jiǎng shù de gù shì bǎ dà jiā gǎn dòng kū le","Câu chuyện cô ấy kể đã làm mọi người cảm động phát khóc."]]},{"n":43,"c":["句子的类型","复句","并列复句"],"z":"一时……一时……","t":"Câu phức đẳng lập: 一时……一时……","d":"= Lúc thì…, lúc thì….","e":[["最近产品价格不太稳定，一时上升一时下降。","zuì jìn chǎn pǐn jià gé bú tài wěn dìng yì shí shàng shēng yì shí xià jiàng","Dạo này giá sản phẩm không ổn định lắm, lúc tăng lúc giảm."],["这段时间天气变化快，一时冷一时热。","zhè duàn shí jiān tiān qì biàn huà kuài yì shí lěng yì shí rè","Thời gian này thời tiết thay đổi nhanh, lúc lạnh lúc nóng."]]},{"n":44,"c":["句子的类型","复句","选择复句"],"z":"要么……，要么……","t":"Câu phức lựa chọn: 要么……，要么……","d":"= Hoặc là…, hoặc là… (chỉ có hai khả năng).","e":[["我平常要么点外卖，要么自己做，很少去食堂吃。","wǒ píng cháng yào me diǎn wài mài yào me zì jǐ zuò hěn shǎo qù shí táng chī","Ngày thường tôi hoặc là gọi đồ ăn ngoài, hoặc là tự nấu, rất ít khi ăn ở nhà ăn."],["那家饭馆的菜要么太咸，要么太辣，我都不爱吃。","nà jiā fàn guǎn de cài yào me tài xián yào me tài là wǒ dōu bú ài chī","Món của quán đó không quá mặn thì quá cay, tôi đều không thích ăn."]]},{"n":45,"c":["句子的类型","复句","转折复句"],"z":"虽……，但/可/却/也……","t":"Câu phức chuyển ngoặt: 虽……，但/可/却/也……","d":"= Tuy…nhưng… (虽 văn viết, đứng sau chủ ngữ).","e":[["比赛虽未取得胜利，但我们收获了宝贵的经验。","bǐ sài suī wèi qǔ dé shèng lì dàn wǒ men shōu huò le bǎo guì de jīng yàn","Trận đấu tuy chưa giành chiến thắng, nhưng chúng tôi đã thu được kinh nghiệm quý báu."],["这道题虽有难度，可做出来的同学不在少数。","zhè dào tí suī yǒu nán dù kě zuò chū lái de tóng xué bú zài shǎo shù","Bài này tuy có độ khó, nhưng số bạn làm được không hề ít."],["文章虽短，读后却使人充满力量。","wén zhāng suī duǎn dú hòu què shǐ rén chōng mǎn lì liàng","Bài văn tuy ngắn, nhưng đọc xong lại khiến người ta tràn đầy sức mạnh."],["她心里虽不喜欢，也坚持来上班了。","tā xīn lǐ suī bù xǐ huan yě jiān chí lái shàng bān le","Trong lòng cô ấy tuy không thích, nhưng vẫn kiên trì đi làm."]]},{"n":46,"c":["句子的类型","复句","条件复句"],"z":"凡是……，都……","t":"Câu phức điều kiện: 凡是……，都……","d":"= Phàm là…đều…, hễ là…đều….","e":[["凡是有机会，他都会积极争取。","fán shì yǒu jī huì tā dōu huì jī jí zhēng qǔ","Hễ có cơ hội là anh ấy đều tích cực giành lấy."],["凡是错误的行为，我们都应该纠正。","fán shì cuò wù de xíng wéi wǒ men dōu yīng gāi jiū zhèng","Phàm là hành vi sai trái, chúng ta đều nên sửa chữa."]]},{"n":47,"c":["句子的类型","复句","条件复句"],"z":"除非……，才……","t":"Câu phức điều kiện: 除非……，才……","d":"= Trừ phi…thì mới… (điều kiện duy nhất).","e":[["除非你亲自邀请，他才有可能同意参加。","chú fēi nǐ qīn zì yāo qǐng tā cái yǒu kě néng tóng yì cān jiā","Trừ phi bạn đích thân mời, anh ấy mới có thể đồng ý tham gia."],["除非是紧急情况，我才会向他求助。","chú fēi shì jǐn jí qíng kuàng wǒ cái huì xiàng tā qiú zhù","Trừ phi là trường hợp khẩn cấp, tôi mới nhờ anh ấy giúp."]]},{"n":48,"c":["句子的类型","复句","条件复句"],"z":"除非……，否则/不然……","t":"Câu phức điều kiện: 除非……，否则/不然……","d":"= Trừ phi…, nếu không thì….","e":[["除非他承认错误并向我道歉，否则我不会原谅他。","chú fēi tā chéng rèn cuò wù bìng xiàng wǒ dào qiàn fǒu zé wǒ bú huì yuán liàng tā","Trừ phi anh ta thừa nhận sai lầm và xin lỗi tôi, nếu không tôi sẽ không tha thứ cho anh ta."],["除非你说清楚是什么事情，不然我不可能同意帮忙。","chú fēi nǐ shuō qīng chu shì shén me shì qing bù rán wǒ bù kě néng tóng yì bāng máng","Trừ phi bạn nói rõ là việc gì, nếu không tôi không thể đồng ý giúp."]]},{"n":49,"c":["句子的类型","复句","让步复句"],"z":"就算……，也……","t":"Câu phức nhượng bộ: 就算……，也……","d":"= Cho dù…cũng… (khẩu ngữ).","e":[["就算再累，我也要坚持完成任务。","jiù suàn zài lèi wǒ yě yào jiān chí wán chéng rèn wu","Cho dù mệt đến đâu, tôi cũng phải kiên trì hoàn thành nhiệm vụ."],["就算他做错了，你也要注意教育方法。","jiù suàn tā zuò cuò le nǐ yě yào zhù yì jiào yù fāng fǎ","Cho dù nó làm sai, bạn cũng phải chú ý cách giáo dục."]]},{"n":50,"c":["句子的类型","复句","目的复句"],"z":"……，以便……","t":"Câu phức mục đích: ……，以便……","d":"= …, để tiện cho…, nhằm… (văn viết).","e":[["请留下您的联系方式，以便日后联系。","qǐng liú xià nín de lián xì fāng shì yǐ biàn rì hòu lián xì","Xin để lại thông tin liên lạc của ông/bà để tiện liên hệ sau này."],["当地政府计划调整地铁的发车时间，以便更多的乘客能够乘坐公共交通。","dāng dì zhèng fǔ jì huà tiáo zhěng dì tiě de fā chē shí jiān yǐ biàn gèng duō de chéng kè néng gòu chéng zuò gōng gòng jiāo tōng","Chính quyền địa phương dự định điều chỉnh giờ chạy tàu điện ngầm để nhiều hành khách hơn có thể đi phương tiện công cộng."]]}],"7":[{"n":1,"c":["语素","类前缀",""],"z":"后—、亲—","t":"Tiền tố loại 后, 亲","d":"后 = hậu, sau (后奥运时代 = thời kỳ hậu Olympic); 亲 = tự, chính mình (亲手 = tự tay, 亲眼 = tận mắt).","e":[["奥运场馆开工之前，就要考虑到后奥运时代的需求。","ào yùn chǎng guǎn kāi gōng zhī qián jiù yào kǎo lǜ dào hòu ào yùn shí dài de xū qiú","Trước khi khởi công các nhà thi đấu Olympic, đã phải tính đến nhu cầu của thời kỳ hậu Olympic."],["市长对老人们嘘寒问暖，并亲手将慰问品送到老人手中。","shì zhǎng duì lǎo rén men xū hán wèn nuǎn bìng qīn shǒu jiāng wèi wèn pǐn sòng dào lǎo rén shǒu zhōng","Thị trưởng ân cần hỏi han các cụ già, và tự tay trao quà thăm hỏi đến tay các cụ."]]},{"n":2,"c":["语素","类后缀",""],"z":"—观、—鬼、—界、—然、—坛、—为、—制","t":"Hậu tố loại 观, 鬼, 界, 然, 坛, 为, 制","d":"观 = quan (quan điểm: 价值观 giá trị quan); 鬼 = kẻ, đồ (chê: 小气鬼 đồ keo kiệt); 界 = giới (学术界 giới học thuật); 然 = hậu tố tính/phó từ (安然 bình an); 坛 = giới, làng (体坛 làng thể thao); 为 = hậu tố phó từ (广为 = rộng rãi); 制 = chế độ (公有制 chế độ công hữu).","e":[["新时代农民的价值观、消费观、审美观都和以往有了很大的不同。","xīn shí dài nóng mín de jià zhí guān xiāo fèi guān shěn měi guān dōu hé yǐ wǎng yǒu le hěn dà de bù tóng","Giá trị quan, quan niệm tiêu dùng, quan niệm thẩm mỹ của người nông dân thời đại mới đều đã rất khác so với trước đây."],["只给孩子花钱却不花时间陪伴孩子的家长同样是小气鬼。","zhǐ gěi hái zi huā qián què bù huā shí jiān péi bàn hái zi de jiā zhǎng tóng yàng shì xiǎo qì guǐ","Những phụ huynh chỉ tiêu tiền cho con mà không dành thời gian ở bên con cũng là đồ keo kiệt."],["我的导师在学术界和产业界都享有崇高的声望。","wǒ de dǎo shī zài xué shù jiè hé chǎn yè jiè dōu xiǎng yǒu chóng gāo de shēng wàng","Thầy hướng dẫn của tôi có uy tín rất cao trong cả giới học thuật lẫn giới công nghiệp."],["经过七个小时的飞行，我终于在异国安然落地。","jīng guò qī gè xiǎo shí de fēi xíng wǒ zhōng yú zài yì guó ān rán luò dì","Sau bảy tiếng bay, cuối cùng tôi đã hạ cánh bình an nơi đất khách."],["今年的“体坛风云人物”颁奖仪式特别隆重。","jīn nián de tǐ tán fēng yún rén wù bān jiǎng yí shì tè bié lóng zhòng","Lễ trao giải \"Nhân vật nổi bật của làng thể thao\" năm nay đặc biệt long trọng."],["本公司的产品多年来广为消费者称赞。","běn gōng sī de chǎn pǐn duō nián lái guǎng wèi xiāo fèi zhě chēng zàn","Nhiều năm nay sản phẩm của công ty chúng tôi được người tiêu dùng khen ngợi rộng rãi."],["以公有制为主体、多种所有制经济共同发展,是中国现阶段的基本经济制度。","yǐ gōng yǒu zhì wéi zhǔ tǐ duō zhǒng suǒ yǒu zhì jīng jì gòng tóng fā zhǎn shì zhōng guó xiàn jiē duàn de jī běn jīng jì zhì dù","Lấy chế độ công hữu làm chủ thể, nhiều thành phần kinh tế cùng phát triển là chế độ kinh tế cơ bản của Trung Quốc ở giai đoạn hiện nay."]]},{"n":3,"c":["词类","动词",""],"z":"巴不得、并非、除外、犯不着、犯得着、恨不得、可否、可谓、免不了、所谓、有所、予以","t":"Động từ 巴不得, 并非, 除外, 犯不着, 犯得着, 恨不得, 可否, 可谓, 免不了, 所谓, 有所, 予以","d":"巴不得/恨不得 = chỉ mong, ước gì được ngay; 并非 = hoàn toàn không phải; 除外 = ngoại trừ; 犯不着 = không đáng (phải); 犯得着…吗 = có đáng… không (phản vấn); 可否 = có thể…hay không (văn viết); 可谓 = có thể nói là; 免不了 = khó tránh khỏi; 所谓 = cái gọi là; 有所 + động từ 2 âm tiết = có phần, ít nhiều; 予以 = dành cho, tiến hành (văn viết hành chính).","e":[["他巴不得早点儿退休，好能到处游山玩水。","tā bā bù de zǎo diǎn r tuì xiū hǎo néng dào chù yóu shān wán shuǐ","Ông ấy chỉ mong được nghỉ hưu sớm để đi ngao du khắp nơi."],["在外漂泊多年的游子归心似箭，巴不得一步跨进家门。","zài wài piāo bó duō nián de yóu zǐ guī xīn sì jiàn bā bù de yí bù kuà jìn jiā mén","Người con xa quê phiêu bạt nhiều năm lòng nóng như lửa đốt muốn về, chỉ mong một bước là vào đến cửa nhà."],["一种艺术风格的形成并非一蹴而就，必须经历一个渐进发展的过程。","yì zhǒng yì shù fēng gé de xíng chéng bìng fēi yí cù ér jiù bì xū jīng lì yí gè jiàn jìn fā zhǎn de guò chéng","Một phong cách nghệ thuật hình thành hoàn toàn không phải một bước là xong, mà phải trải qua một quá trình phát triển dần dần."],["你之所以落选，并非你不优秀，而是你的风格和他们的需求不完全匹配。","nǐ zhī suǒ yǐ luò xuǎn bìng fēi nǐ bù yōu xiù ér shì nǐ de fēng gé hé tā men de xū qiú bù wán quán pǐ pèi","Bạn bị loại hoàn toàn không phải vì bạn không xuất sắc, mà vì phong cách của bạn và nhu cầu của họ không hoàn toàn phù hợp."],["八折优惠仅限周一至周五使用，法定节假日除外。","bā zhé yōu huì jǐn xiàn zhōu yī zhì zhōu wǔ shǐ yòng fǎ dìng jié jià rì chú wài","Ưu đãi giảm 20% chỉ áp dụng từ thứ Hai đến thứ Sáu, trừ ngày lễ theo luật định."],["在场各位皆是西装革履，只有一人除外，穿着十分随意。","zài chǎng gè wèi jiē shì xī zhuāng gé lǚ zhǐ yǒu yì rén chú wài chuān zhe shí fēn suí yì","Những người có mặt đều mặc vest đi giày tây, chỉ trừ một người ăn mặc rất tùy tiện."],["他是个啥也不懂的毛头小子，你犯不着跟他一般见识。","tā shì gè shá yě bù dǒng de máo tóu xiǎo zi nǐ fàn bu zháo gēn tā yì bān jiàn shi","Nó là thằng nhóc miệng còn hôi sữa chẳng hiểu gì, anh không đáng phải chấp nhặt với nó."],["你们俩打小就认识，为了这么点儿小事闹翻，犯不着。","nǐ men liǎ dǎ xiǎo jiù rèn shi wèi le zhè me diǎn r xiǎo shì nào fān fàn bu zháo","Hai người các cậu quen nhau từ nhỏ, vì chút chuyện cỏn con này mà cãi nhau thì không đáng."],["现在是公司发展的关键时期，你犯得着为这些小事分心吗？","xiàn zài shì gōng sī fā zhǎn de guān jiàn shí qī nǐ fàn de zháo wèi zhè xiē xiǎo shì fēn xīn ma","Bây giờ đang là thời kỳ then chốt của sự phát triển công ty, có đáng để bạn phân tâm vì những chuyện nhỏ này không?"],["人家好心好意给你提些意见，你这么激动，犯得着吗？","rén jiā hǎo xīn hǎo yì gěi nǐ tí xiē yì jiàn nǐ zhè me jī dòng fàn de zháo ma","Người ta có lòng tốt góp ý cho bạn, bạn kích động như vậy, có đáng không?"],["一开始项目推动得非常缓慢，我们恨不得24小时都在工作。","yì kāi shǐ xiàng mù tuī dòng de fēi cháng huǎn màn wǒ men hèn bù de xiǎo shí dōu zài gōng zuò","Lúc đầu dự án triển khai rất chậm, chúng tôi chỉ mong được làm việc cả 24 tiếng."],["大家的学习热情很高，恨不得一下子把所有的先进技术都学到手。","dà jiā de xué xí rè qíng hěn gāo hèn bù de yí xià zi bǎ suǒ yǒu de xiān jìn jì shù dōu xué dào shǒu","Mọi người nhiệt tình học tập rất cao, chỉ mong học được ngay tất cả các kỹ thuật tiên tiến."],["此事可否容我思索几日，再行答复？","cǐ shì kě fǒu róng wǒ sī suǒ jǐ rì zài xíng dá fù","Việc này có thể cho tôi suy nghĩ vài ngày rồi trả lời được không?"],["关于先生会上所言，学生尚有不明之处，可否向先生进一步请教？","guān yú xiān sheng huì shàng suǒ yán xué shēng shàng yǒu bù míng zhī chù kě fǒu xiàng xiān sheng jìn yí bù qǐng jiào","Về những điều thầy nói trong hội nghị, em vẫn còn chỗ chưa rõ, có thể xin thầy chỉ giáo thêm được không ạ?"],["我申请与其当面对质，不知可否？","wǒ shēn qǐng yǔ qí dāng miàn duì zhì bù zhī kě fǒu","Tôi xin được đối chất trực tiếp với người đó, không biết có được không?"],["王安忆对上海人的观察和描写非常细腻，可谓“入木三分”。","wáng ān yì duì shàng hǎi rén de guān chá hé miáo xiě fēi cháng xì nì kě wèi rù mù sān fēn","Sự quan sát và miêu tả của Vương An Ức về người Thượng Hải vô cùng tinh tế, có thể nói là \"sâu sắc thấu đáo\"."],["《昆虫记》知识性、趣味性、哲理性兼具，真可谓是科学与艺术相结合的典范。","kūn chóng jì zhī shi xìng qù wèi xìng zhé lǐ xìng jiān jù zhēn kě wèi shì kē xué yǔ yì shù xiāng jié hé de diǎn fàn","\"Côn trùng ký\" vừa có tính tri thức, tính thú vị lại có tính triết lý, thật có thể nói là hình mẫu kết hợp giữa khoa học và nghệ thuật."],["在成长的道路上，免不了会遇到各种各样的问题。","zài chéng zhǎng de dào lù shang miǎn bù liǎo huì yù dào gè zhǒng gè yàng de wèn tí","Trên con đường trưởng thành, khó tránh khỏi gặp đủ loại vấn đề."],["这件事要是让他知道，一顿数落是免不了的。","zhè jiàn shì yào shi ràng tā zhī dao yí dùn shǔ luò shì miǎn bù liǎo de","Việc này mà để anh ấy biết thì khó tránh khỏi một trận càm ràm."],["所谓难得糊涂，并非是对生活的无奈妥协，而是一种张弛有度的处世之道。","suǒ wèi nán dé hú tú bìng fēi shì duì shēng huó de wú nài tuǒ xié ér shì yì zhǒng zhāng chí yǒu dù de chǔ shì zhī dào","Cái gọi là \"hiếm khi được hồ đồ\" không phải là sự thỏa hiệp bất lực với cuộc sống, mà là một cách đối nhân xử thế biết căng biết chùng."],["这家公司所谓的产品升级，不过是给商品换了一个更华丽的包装。","zhè jiā gōng sī suǒ wèi de chǎn pǐn shēng jí bú guò shì gěi shāng pǐn huàn le yí gè gèng huá lì de bāo zhuāng","Cái gọi là nâng cấp sản phẩm của công ty này, chẳng qua là thay cho hàng hóa một lớp bao bì lộng lẫy hơn."],["引进先进技术与优化管理流程后，各部门工作效率均有所提高。","yǐn jìn xiān jìn jì shù yǔ yōu huà guǎn lǐ liú chéng hòu gè bù mén gōng zuò xiào lǜ jūn yǒu suǒ tí gāo","Sau khi đưa vào kỹ thuật tiên tiến và tối ưu hóa quy trình quản lý, hiệu suất làm việc của các bộ phận đều có phần nâng cao."],["倘若事态紧急，无暇向上请示，你大可自行决断，不必有所顾虑。","tǎng ruò shì tài jǐn jí wú xiá xiàng shàng qǐng shì nǐ dà kě zì xíng jué duàn bú bì yǒu suǒ gù lǜ","Nếu tình hình khẩn cấp, không kịp xin chỉ thị cấp trên, anh hoàn toàn có thể tự quyết định, không cần có điều gì băn khoăn."],["限于作者水平，如有不当之处还望专家予以批评指正。","xiàn yú zuò zhě shuǐ píng rú yǒu bù dàng zhī chù hái wàng zhuān jiā yǔ yǐ pī píng zhǐ zhèng","Do trình độ tác giả có hạn, nếu có chỗ chưa thỏa đáng, mong các chuyên gia phê bình chỉ giáo."],["对于原告提出的高昂赔付要求，法院并未予以支持。","duì yú yuán gào tí chū de gāo áng péi fù yāo qiú fǎ yuàn bìng wèi yǔ yǐ zhī chí","Đối với yêu cầu bồi thường rất cao mà nguyên đơn đưa ra, tòa án đã không chấp thuận."]]},{"n":4,"c":["词类","代词","人称代词"],"z":"我","t":"Đại từ 我 (chỉ đơn vị của mình)","d":"我 + danh từ đơn vị = … chúng tôi (văn viết trang trọng): 我校 = trường chúng tôi, 我公司 = công ty chúng tôi.","e":[["我校教育质量上乘，办学几十年间为国家培养、输送了大批优秀人才。","wǒ xiào jiào yù zhì liàng shàng chéng bàn xué jǐ shí nián jiān wèi guó jiā péi yǎng shū sòng le dà pī yōu xiù rén cái","Chất lượng giáo dục của trường chúng tôi thuộc hàng tốt, mấy chục năm qua đã đào tạo, cung cấp cho đất nước rất nhiều nhân tài xuất sắc."],["我公司始终秉持“以客户为中心”的理念，致力于为客户提供最优质的服务。","wǒ gōng sī shǐ zhōng bǐng chí yǐ kè hù wèi zhōng xīn de lǐ niàn zhì lì yú wèi kè hù tí gōng zuì yōu zhì de fú wù","Công ty chúng tôi luôn giữ vững triết lý \"lấy khách hàng làm trung tâm\", nỗ lực cung cấp dịch vụ tốt nhất cho khách hàng."]]},{"n":5,"c":["词类","代词","指示代词"],"z":"彼、这么着、兹","t":"Đại từ chỉ thị 彼, 这么着, 兹","d":"彼 = kia, ấy, bên kia (văn viết: 彼时 lúc ấy; 知己知彼 biết mình biết người); 这么着 = như thế này (khẩu ngữ); 兹 = nay (văn bản hành chính: 兹证明 = nay chứng nhận).","e":[["“古典小说”鼎盛于明清时期，彼时涌现了如四大名著等众多经典之作。","gǔ diǎn xiǎo shuō dǐng shèng yú míng qīng shí qī bǐ shí yǒng xiàn le rú sì dà míng zhù děng zhòng duō jīng diǎn zhī zuò","\"Tiểu thuyết cổ điển\" phát triển cực thịnh vào thời Minh Thanh, lúc ấy xuất hiện rất nhiều tác phẩm kinh điển như Tứ đại danh tác."],["提起朝阳，人们往往会想到北京的朝阳区。然而我们今日前往参观的此“朝阳”非彼“朝阳”，乃是被誉为“三燕古都”的辽宁省朝阳市。","tí qǐ cháo yáng rén men wǎng wǎng huì xiǎng dào běi jīng de cháo yáng qū rán ér wǒ men jīn rì qián wǎng cān guān de cǐ cháo yáng fēi bǐ cháo yáng nǎi shì bèi yù wéi sān yàn gǔ dū de liáo níng shěng cháo yáng shì","Nhắc đến Triều Dương, người ta thường nghĩ đến quận Triều Dương của Bắc Kinh. Tuy nhiên \"Triều Dương\" mà hôm nay chúng ta đến tham quan không phải \"Triều Dương\" kia, mà là thành phố Triều Dương tỉnh Liêu Ninh, được mệnh danh là \"cố đô Tam Yên\"."],["在商务谈判中，应尽量做到知己知彼，这样才能争取到最大的利益。","zài shāng wù tán pàn zhōng yìng jǐn liàng zuò dào zhī jǐ zhī bǐ zhè yàng cái néng zhēng qǔ dào zuì dà de lì yì","Trong đàm phán thương mại, nên cố gắng biết mình biết người, như vậy mới giành được lợi ích lớn nhất."],["你们觉得这么着好就这么办，不必再来问我的意见了。","nǐ men jué de zhè me zhe hǎo jiù zhè me bàn bú bì zài lái wèn wǒ de yì jiàn le","Các anh thấy thế này là được thì cứ làm như vậy, không cần đến hỏi ý kiến tôi nữa."],["那地方你人生地不熟的，这么着吧，我陪你一起去看看。","nà dì fang nǐ rén shēng dì bù shú de zhè me zhe ba wǒ péi nǐ yì qǐ qù kàn kàn","Chỗ đó bạn lạ nước lạ cái, thế này nhé, tôi đi cùng bạn đến xem."],["兹证明李莉女士系本单位正式员工，已连续在本单位工作十年。","zī zhèng míng lǐ lì nǚ shì xì běn dān wèi zhèng shì yuán gōng yǐ lián xù zài běn dān wèi gōng zuò shí nián","Nay chứng nhận bà Lý Lợi là nhân viên chính thức của đơn vị, đã làm việc liên tục tại đơn vị mười năm."],["受有关机构委托，兹有以下标的拟予以转让，现公告如下，欢迎合格投标人参加该项目投标。","shòu yǒu guān jī gòu wěi tuō zī yǒu yǐ xià biāo dì nǐ yǔ yǐ zhuǎn ràng xiàn gōng gào rú xià huān yíng hé gé tóu biāo rén cān jiā gāi xiàng mù tóu biāo","Được sự ủy thác của cơ quan hữu quan, nay có các tài sản sau dự kiến chuyển nhượng, xin thông báo như sau, hoan nghênh các nhà thầu đủ điều kiện tham gia đấu thầu dự án."]]},{"n":6,"c":["词类","代词","疑问代词"],"z":"何、怎么着","t":"Đại từ nghi vấn 何, 怎么着","d":"何 = gì, nào, đâu (văn viết: 何时 khi nào, 何地 nơi nào, 何在 ở đâu, 因何 vì sao); 怎么着 = làm sao, thế nào (khẩu ngữ).","e":[["历史学家的任务之一是在浩瀚的史料中挖掘出何时、何地发生了何种事件。","lì shǐ xué jiā de rèn wu zhī yī shì zài hào hàn de shǐ liào zhōng wā jué chū hé shí hé dì fā shēng le hé zhǒng shì jiàn","Một trong những nhiệm vụ của nhà sử học là đào sâu trong biển sử liệu mênh mông để tìm ra sự kiện gì đã xảy ra vào lúc nào, ở đâu."],["这座滨江小城魅力何在？因何引得诸多文人骚客留下脍炙人口的名篇？","zhè zuò bīn jiāng xiǎo chéng mèi lì hé zài yīn hé yǐn de zhū duō wén rén sāo kè liú xià kuài zhì rén kǒu de míng piān","Sức hút của thị trấn nhỏ bên sông này nằm ở đâu? Vì sao lại khiến bao văn nhân thi sĩ để lại những áng văn nổi tiếng được truyền tụng?"],["他夜里翻来覆去地想着这件事，可是还是不知道该怎么着才好。","tā yè lǐ fān lái fù qù de xiǎng zhe zhè jiàn shì kě shì hái shì bù zhī dao gāi zěn me zhe cái hǎo","Đêm đó anh ấy trằn trọc nghĩ về chuyện này, nhưng vẫn không biết nên làm thế nào mới phải."],["你说她半天在那儿一声不吭，是生气了还是怎么着？","nǐ shuō tā bàn tiān zài nà r yì shēng bù kēng shì shēng qì le hái shì zěn me zhe","Bạn bảo cô ấy ngồi đó cả buổi không nói một lời, là giận rồi hay là sao?"]]},{"n":7,"c":["词类","代词","数量代词"],"z":"若干","t":"Đại từ số lượng 若干","d":"若干 = một số, bao nhiêu đó (số không xác định, văn viết).","e":[["经过初赛、复赛和决赛，大赛产生了“十佳歌手”和若干“优秀歌手”。","jīng guò chū sài fù sài hé jué sài dà sài chǎn shēng le shí jiā gē shǒu hé ruò gān yōu xiù gē shǒu","Qua vòng sơ khảo, bán kết và chung kết, cuộc thi đã chọn ra \"Mười ca sĩ xuất sắc nhất\" và một số \"Ca sĩ ưu tú\"."],["她一生著有长篇小说七部，另有中短篇小说、散文、诗歌、随笔若干。","tā yì shēng zhù yǒu cháng piān xiǎo shuō qī bù lìng yǒu zhōng duǎn piān xiǎo shuō sǎn wén shī gē suí bǐ ruò gān","Cả đời bà sáng tác bảy bộ tiểu thuyết dài, ngoài ra còn một số tiểu thuyết vừa và ngắn, tản văn, thơ ca, tùy bút."]]},{"n":8,"c":["词类","量词","名量词"],"z":"重、截、缕、码、枚、摊、丸、则、幢、宗","t":"Lượng từ chuyên dùng 重, 截, 缕, 码, 枚, 摊, 丸, 则, 幢, 宗","d":"重 (chóng) tầng, lớp (重重 = trùng trùng); 截 khúc, đoạn; 缕 sợi, làn (tóc, hương, khói); 码 chuyện, việc (两码事 = hai chuyện khác nhau); 枚 chiếc, tấm (đồng xu, huy chương); 摊 đống, mớ (việc); 丸 viên (thuốc); 则 mẩu, đoạn (tin tức, điển cố); 幢 tòa (nhà); 宗 vụ, mối (án, buôn bán).","e":[["该项目的延期是由多重原因所导致的，包括预算不足、人员短缺等。","gāi xiàng mù de yán qī shì yóu duō chóng yuán yīn suǒ dǎo zhì de bāo kuò yù suàn bù zú rén yuán duǎn quē děng","Việc dự án bị kéo dài là do nhiều nguyên nhân gây ra, bao gồm thiếu ngân sách, thiếu nhân sự…"],["她们团队克服重重困难和阻碍，出色地完成了艰巨的任务。","tā men tuán duì kè fú chóng chóng kùn nán hé zǔ ài chū sè de wán chéng le jiān jù de rèn wu","Nhóm của các cô ấy đã vượt qua trùng trùng khó khăn trở ngại, hoàn thành xuất sắc nhiệm vụ gian khổ."],["他想找一截木头做个镇纸。","tā xiǎng zhǎo yì jié mù tou zuò gè zhèn zhǐ","Anh ấy muốn tìm một khúc gỗ để làm cái chặn giấy."],["他看到这里简陋的生活环境，心里顿时凉了半截。","tā kàn dào zhè lǐ jiǎn lòu de shēng huó huán jìng xīn lǐ dùn shí liáng le bàn jié","Nhìn môi trường sống sơ sài ở đây, lòng anh ấy lập tức nguội đi một nửa."],["迎面走来一个身着白色T恤的女学生，白皙的额头上垂落着一缕秀发。","yíng miàn zǒu lái yí gè shēn zhe bái sè xù de nǚ xué shēng bái xī de é tóu shàng chuí luò zhe yì lǚ xiù fā","Một nữ sinh mặc áo phông trắng đi tới, một lọn tóc mềm mại rủ xuống vầng trán trắng ngần."],["忽地起了一阵微风，送来缕缕清香，将所有的烦恼瞬间驱散。","hū dì qǐ le yí zhèn wēi fēng sòng lái lǚ lǚ qīng xiāng jiāng suǒ yǒu de fán nǎo shùn jiān qū sàn","Bỗng nổi lên một làn gió nhẹ, mang theo từng làn hương thơm, xua tan mọi phiền muộn trong chốc lát."],["科研和科普是两码事。杰出的科学家未必能写出好的科普作品，优秀的科普作家也不一定能做好科研工作。","kē yán hé kē pǔ shì liǎng mǎ shì jié chū de kē xué jiā wèi bì néng xiě chū hǎo de kē pǔ zuò pǐn yōu xiù de kē pǔ zuò jiā yě bù yí dìng néng zuò hǎo kē yán gōng zuò","Nghiên cứu khoa học và phổ biến khoa học là hai chuyện khác nhau. Nhà khoa học kiệt xuất chưa chắc viết được tác phẩm phổ biến khoa học hay, nhà văn phổ biến khoa học giỏi cũng chưa chắc làm tốt công tác nghiên cứu."],["虽然你们私交很好，但工作上的事情还是应该一码归一码，公事公办。","suī rán nǐ men sī jiāo hěn hǎo dàn gōng zuò shàng de shì qing hái shì yīng gāi yì mǎ guī yì mǎ gōng shì gōng bàn","Tuy quan hệ riêng của các bạn rất tốt, nhưng chuyện công việc vẫn nên việc nào ra việc nấy, công tư phân minh."],["权利与义务犹如一枚硬币的两面，相互依存，密不可分。","quán lì yǔ yì wù yóu rú yì méi yìng bì de liǎng miàn xiāng hù yī cún mì bù kě fēn","Quyền lợi và nghĩa vụ giống như hai mặt của một đồng xu, dựa vào nhau, không thể tách rời."],["他工作非常出色，十年里共获得五枚奖章。","tā gōng zuò fēi cháng chū sè shí nián lǐ gòng huò dé wǔ méi jiǎng zhāng","Anh ấy làm việc vô cùng xuất sắc, trong mười năm đã nhận tổng cộng năm tấm huân chương."],["苏州有一对老夫妻，子女们平日里各为自己的一摊事忙活，只有节假日才有机会团聚。","sū zhōu yǒu yí duì lǎo fū qī zǐ nǚ men píng rì lǐ gè wèi zì jǐ de yì tān shì máng huó zhǐ yǒu jié jià rì cái yǒu jī huì tuán jù","Ở Tô Châu có một đôi vợ chồng già, con cái ngày thường ai cũng bận lo mớ việc riêng của mình, chỉ có ngày lễ mới có dịp đoàn tụ."],["公司的事已经让他焦头烂额，家中还另有一摊，他感到身心俱疲。","gōng sī de shì yǐ jīng ràng tā jiāo tóu làn é jiā zhōng hái lìng yǒu yì tān tā gǎn dào shēn xīn jù pí","Việc công ty đã khiến anh ấy rối như canh hẹ, trong nhà lại còn một mớ việc khác, anh ấy cảm thấy kiệt sức cả thể xác lẫn tinh thần."],["要制成一丸药，需用上三十多种原料并经过多道工序。","yào zhì chéng yì wán yào xū yòng shàng sān shí duō zhǒng yuán liào bìng jīng guò duō dào gōng xù","Để bào chế một viên thuốc cần dùng hơn ba mươi loại nguyên liệu và trải qua nhiều công đoạn."],["这个药每日三次，每次六丸，餐后半小时服用。","zhè ge yào měi rì sān cì měi cì liù wán cān hòu bàn xiǎo shí fú yòng","Thuốc này ngày uống ba lần, mỗi lần sáu viên, uống sau bữa ăn nửa tiếng."],["今天《人民日报》上刊登的一则新闻，令我大吃一惊。","jīn tiān rén mín rì bào shàng kān dēng de yì zé xīn wén lìng wǒ dà chī yì jīng","Một mẩu tin đăng trên \"Nhân dân nhật báo\" hôm nay khiến tôi vô cùng kinh ngạc."],["在不到两小时的演讲过程中，他至少引用了20则古代典故。","zài bú dào liǎng xiǎo shí de yǎn jiǎng guò chéng zhōng tā zhì shǎo yǐn yòng le zé gǔ dài diǎn gù","Trong bài diễn thuyết chưa đầy hai tiếng, ông ấy đã dẫn ít nhất 20 điển cố cổ."],["历经一年，长乐村建成了一幢两层高的标准化教学楼。","lì jīng yì nián cháng lè cūn jiàn chéng le yí zhuàng liǎng céng gāo de biāo zhǔn huà jiào xué lóu","Sau một năm, thôn Trường Lạc đã xây xong một tòa nhà học hai tầng đạt chuẩn."],["医院今年新建职工宿舍三幢，医技大楼两幢。","yī yuàn jīn nián xīn jiàn zhí gōng sù shè sān zhuàng yī jì dà lóu liǎng zhuàng","Năm nay bệnh viện xây mới ba tòa ký túc xá cho nhân viên, hai tòa nhà kỹ thuật y tế."],["法官必须具有超乎寻常的耐心和细心，才能办好每一宗案件。","fǎ guān bì xū jù yǒu chāo hū xún cháng de nài xīn hé xì xīn cái néng bàn hǎo měi yì zōng àn jiàn","Thẩm phán phải có sự kiên nhẫn và tỉ mỉ hơn người mới có thể xử lý tốt mỗi vụ án."],["他匆匆赶往机场，准备飞去香港谈宗生意。","tā cōng cōng gǎn wǎng jī chǎng zhǔn bèi fēi qù xiāng gǎng tán zōng shēng yì","Anh ấy vội vã ra sân bay, chuẩn bị bay đi Hồng Kông bàn một mối làm ăn."]]},{"n":9,"c":["词类","量词","动量词"],"z":"通","t":"Động lượng từ 通","d":"一通 = một trận, một hồi (mắng, phê bình, nói…).","e":[["了解了我的饮食习惯以后，那位医生将我好一通批评，说我没有管住嘴。","liǎo jiě le wǒ de yǐn shí xí guàn yǐ hòu nà wèi yī shēng jiāng wǒ hǎo yì tōng pī píng shuō wǒ méi yǒu guǎn zhù zuǐ","Sau khi biết thói quen ăn uống của tôi, vị bác sĩ đó đã phê bình tôi một trận ra trò, nói tôi không biết kiêng miệng."],["因为他的失误，公司利益受到了重大损失，老板把他狠狠训了一通。","yīn wèi tā de shī wù gōng sī lì yì shòu dào le zhòng dà sǔn shī lǎo bǎn bǎ tā hěn hěn xùn le yì tōng","Vì sai sót của anh ta, lợi ích công ty bị tổn thất nặng nề, ông chủ đã mắng anh ta một trận nên thân."]]},{"n":10,"c":["词类","量词","复合量词"],"z":"人次","t":"Lượng từ phức hợp 人次","d":"人次 = lượt người (tổng số lượt, một người đến nhiều lần thì tính nhiều lượt).","e":[["旅游大数据显示，今年一季度辽宁省共接待游客1.71亿人次，同比增长68.2%。","lǚ yóu dà shù jù xiǎn shì jīn nián yī jì dù liáo níng shěng gòng jiē dài yóu kè yì rén cì tóng bǐ zēng zhǎng","Dữ liệu lớn về du lịch cho thấy, quý một năm nay tỉnh Liêu Ninh đã đón tổng cộng 171 triệu lượt khách, tăng 68,2% so với cùng kỳ."],["各大图书馆的古旧书刊，因近年借阅人次大幅增加，损坏非常严重。","gè dà tú shū guǎn de gǔ jiù shū kān yīn jìn nián jiè yuè rén cì dà fú zēng jiā sǔn huài fēi cháng yán zhòng","Sách báo cổ ở các thư viện lớn, do số lượt mượn đọc tăng mạnh những năm gần đây, bị hư hại rất nghiêm trọng."]]},{"n":11,"c":["词类","副词","程度副词"],"z":"大为、分外、何等、极度、极力、略、略微、颇、稍稍、万分、微、尤为、愈加、越发","t":"Phó từ mức độ 大为, 分外, 何等, 极度, 极力, 略, 略微, 颇, 稍稍, 万分, 微, 尤为, 愈加, 越发","d":"大为 = hết sức, rất (大为惊叹/不满); 分外 = đặc biệt, hết sức; 何等 = biết bao (cảm thán); 极度 = cực độ; 极力 = ra sức, cố hết sức; 略/略微/稍稍/微 = hơi, một chút; 颇 = khá, rất (văn viết); 万分 = vô cùng; 尤为 = càng, đặc biệt là; 愈加/越发 = càng thêm, ngày càng.","e":[["该歌手的演唱会门票，每张均以高价售出，但其表演水平并不高，观众看后大为不满。","gāi gē shǒu de yǎn chàng huì mén piào měi zhāng jūn yǐ gāo jià shòu chū dàn qí biǎo yǎn shuǐ píng bìng bù gāo guān zhòng kàn hòu dà wèi bù mǎn","Vé buổi hòa nhạc của ca sĩ này đều bán với giá cao, nhưng trình độ biểu diễn lại không cao, khán giả xem xong hết sức bất mãn."],["由于周边建筑都比较低矮，这座大楼显得分外高大。","yóu yú zhōu biān jiàn zhù dōu bǐ jiào dī ǎi zhè zuò dà lóu xiǎn de fèn wài gāo dà","Vì các tòa nhà xung quanh đều khá thấp nên tòa nhà này trông đặc biệt cao lớn."],["拥有一双发现美的眼睛，在平淡生活中捕捉到一点一滴的美好，是何等幸运！","yōng yǒu yì shuāng fā xiàn měi de yǎn jing zài píng dàn shēng huó zhōng bǔ zhuō dào yì diǎn yì dī de měi hǎo shì hé děng xìng yùn","Có một đôi mắt biết phát hiện cái đẹp, nắm bắt từng chút tốt đẹp trong cuộc sống bình lặng, thật may mắn biết bao!"],["即使在极度困难的条件下，他仍执着地追求着自己的艺术理想。","jí shǐ zài jí dù kùn nán de tiáo jiàn xià tā réng zhí zhuó de zhuī qiú zhe zì jǐ de yì shù lǐ xiǎng","Ngay cả trong điều kiện cực kỳ khó khăn, anh ấy vẫn kiên trì theo đuổi lý tưởng nghệ thuật của mình."],["他极力想忍住，但疼痛还是使他叫出声来。","tā jí lì xiǎng rěn zhù dàn téng tòng hái shì shǐ tā jiào chū shēng lái","Anh ấy cố hết sức nhịn, nhưng cơn đau vẫn khiến anh ấy kêu thành tiếng."],["今年这套试卷注重考查学生灵活运用语言知识的能力，整体难度略高于历年考题。","jīn nián zhè tào shì juàn zhù zhòng kǎo chá xué shēng líng huó yùn yòng yǔ yán zhī shi de néng lì zhěng tǐ nán dù lüè gāo yú lì nián kǎo tí","Bộ đề năm nay chú trọng kiểm tra khả năng vận dụng linh hoạt kiến thức ngôn ngữ của học sinh, độ khó tổng thể hơi cao hơn đề các năm."],["他脸上挂着浅浅笑意，听到问题后总会先略微思考一下，再不紧不慢地作答。","tā liǎn shàng guà zhe qiǎn qiǎn xiào yì tīng dào wèn tí hòu zǒng huì xiān lüè wēi sī kǎo yí xià zài bù jǐn bú màn de zuò dá","Trên mặt anh ấy nở nụ cười nhẹ, nghe câu hỏi xong luôn suy nghĩ một chút rồi mới thong thả trả lời."],["城市民宿往往隐于闹市，因其风格独特，活动自由，如今颇受顾客青睐。","chéng shì mín sù wǎng wǎng yǐn yú nào shì yīn qí fēng gé dú tè huó dòng zì yóu rú jīn pō shòu gù kè qīng lài","Homestay trong thành phố thường ẩn mình giữa phố xá náo nhiệt, vì phong cách độc đáo, sinh hoạt tự do nên hiện nay khá được khách hàng ưa chuộng."],["她坐在那里，低头摆弄着衣角，稍稍有些拘谨。","tā zuò zài nà lǐ dī tóu bǎi nòng zhe yī jiǎo shāo shāo yǒu xiē jū jǐn","Cô ấy ngồi đó, cúi đầu mân mê vạt áo, có hơi gò bó."],["按照赵医生的手术治疗方案，患者最后转危为安，家属对其万分感激。","àn zhào zhào yī shēng de shǒu shù zhì liáo fāng àn huàn zhě zuì hòu zhuǎn wēi wéi ān jiā shǔ duì qí wàn fēn gǎn jī","Theo phương án phẫu thuật của bác sĩ Triệu, bệnh nhân cuối cùng đã qua cơn nguy kịch, gia đình vô cùng biết ơn ông."],["谈及自己的远大理想，他有点儿激动，面色微红，声音也有点儿颤抖。","tán jí zì jǐ de yuǎn dà lǐ xiǎng tā yǒu diǎn r jī dòng miàn sè wēi hóng shēng yīn yě yǒu diǎn r chàn dǒu","Nói đến lý tưởng lớn lao của mình, anh ấy hơi xúc động, mặt hơi đỏ, giọng cũng hơi run."],["这次比赛中，9号选手的表现尤为突出，给评委和观众都留下了深刻的印象。","zhè cì bǐ sài zhōng hào xuǎn shǒu de biǎo xiàn yóu wèi tū chū gěi píng wěi hé guān zhòng dōu liú xià le shēn kè de yìn xiàng","Trong cuộc thi lần này, màn thể hiện của thí sinh số 9 đặc biệt nổi bật, để lại ấn tượng sâu sắc cho cả giám khảo và khán giả."],["近年来，两国战略沟通合作日益密切，兄弟情谊愈加深厚。","jìn nián lái liǎng guó zhàn lüè gōu tōng hé zuò rì yì mì qiè xiōng dì qíng yì yù jiā shēn hòu","Những năm gần đây, trao đổi và hợp tác chiến lược giữa hai nước ngày càng chặt chẽ, tình anh em càng thêm sâu đậm."],["经过数百次的舞台历练，他的演技越发纯熟。","jīng guò shù bǎi cì de wǔ tái lì liàn tā de yǎn jì yuè fā chún shú","Sau hàng trăm lần rèn luyện trên sân khấu, diễn xuất của anh ấy càng thêm điêu luyện."]]},{"n":12,"c":["词类","副词","范围副词"],"z":"大体、概、皆、尽、均、通通、统统、唯、唯独、唯有、无非、一概","t":"Phó từ phạm vi 大体, 概, 皆, 尽, 均, 通通, 统统, 唯, 唯独, 唯有, 无非, 一概","d":"大体 = nhìn chung, về cơ bản; 概/一概 = nhất loạt, hoàn toàn (không); 皆/均 = đều (văn viết); 尽 = toàn là, hết thảy; 通通/统统 = tất cả, hết thảy (khẩu ngữ); 唯/唯独 = chỉ, duy chỉ; 唯有 = chỉ có; 无非 = chẳng qua là, không ngoài.","e":[["他的身体已经大体恢复了，我觉得可以进行一些基础性训练了。","tā de shēn tǐ yǐ jīng dà tǐ huī fù le wǒ jué de kě yǐ jìn xíng yì xiē jī chǔ xìng xùn liàn le","Sức khỏe của anh ấy về cơ bản đã hồi phục, tôi thấy có thể tập một số bài cơ bản được rồi."],["游客因擅自参加高危活动所造成的人身和财产损失，本旅行社概不负责。","yóu kè yīn shàn zì cān jiā gāo wēi huó dòng suǒ zào chéng de rén shēn hé cái chǎn sǔn shī běn lǚ xíng shè gài bú fù zé","Những thiệt hại về người và tài sản do du khách tự ý tham gia các hoạt động nguy hiểm, công ty du lịch chúng tôi hoàn toàn không chịu trách nhiệm."],["中国瓷器之所以享誉世界，皆因其实用与审美并存。","zhōng guó cí qì zhī suǒ yǐ xiǎng yù shì jiè jiē yīn qí shí yòng yǔ shěn měi bìng cún","Đồ sứ Trung Quốc sở dĩ nổi tiếng thế giới đều là vì nó vừa thực dụng vừa có giá trị thẩm mỹ."],["从广州塔顶楼俯瞰，羊城璀璨的夜景尽收眼底。","cóng guǎng zhōu tǎ dǐng lóu fǔ kàn yáng chéng cuǐ càn de yè jǐng jìn shōu yǎn dǐ","Nhìn xuống từ tầng thượng tháp Quảng Châu, cảnh đêm rực rỡ của Dương Thành thu trọn vào tầm mắt."],["在有关部门的大力监管下，存在环境安全隐患的酒店、餐厅等均已完成整改。","zài yǒu guān bù mén de dà lì jiān guǎn xià cún zài huán jìng ān quán yǐn huàn de jiǔ diàn cān tīng děng jūn yǐ wán chéng zhěng gǎi","Dưới sự giám sát chặt chẽ của các cơ quan liên quan, các khách sạn, nhà hàng có nguy cơ mất an toàn môi trường đều đã hoàn tất chỉnh đốn."],["那一大堆坏了的电器，他只用了一个晚上的时间，就通通修理好了。","nà yí dà duī huài le de diàn qì tā zhǐ yòng le yí gè wǎn shang de shí jiān jiù tōng tōng xiū lǐ hǎo le","Cả một đống đồ điện hỏng đó, anh ấy chỉ mất một buổi tối đã sửa xong hết."],["她对年轻后辈毫无保留，将自己多年来的经验教训统统分享给了大家。","tā duì nián qīng hòu bèi háo wú bǎo liú jiāng zì jǐ duō nián lái de jīng yàn jiào xùn tǒng tǒng fēn xiǎng gěi le dà jiā","Bà ấy không giấu giếm gì với lớp trẻ, chia sẻ hết thảy kinh nghiệm bài học nhiều năm của mình cho mọi người."],["修身之道不唯阅读，品茶、闲谈、对弈、抚琴、练武、游历山水均可养性。","xiū shēn zhī dào bù wéi yuè dú pǐn chá xián tán duì yì fǔ qín liàn wǔ yóu lì shān shuǐ jūn kě yǎng xìng","Con đường tu dưỡng không chỉ có đọc sách, thưởng trà, trò chuyện, chơi cờ, gảy đàn, luyện võ, du ngoạn sơn thủy đều có thể bồi dưỡng tâm tính."],["那么多同他一起备考的考生都放弃了，唯独他一个人坚持了下来。","nà me duō tóng tā yì qǐ bèi kǎo de kǎo shēng dōu fàng qì le wéi dú tā yí gè rén jiān chí le xià lái","Biết bao thí sinh cùng ôn thi với anh ấy đều bỏ cuộc, duy chỉ có mình anh ấy kiên trì đến cùng."],["在全球化的激烈竞争中，唯有持续创新才能立于不败之地。","zài quán qiú huà de jī liè jìng zhēng zhōng wéi yǒu chí xù chuàng xīn cái néng lì yú bú bài zhī dì","Trong cuộc cạnh tranh khốc liệt của toàn cầu hóa, chỉ có không ngừng đổi mới mới có thể đứng ở thế bất bại."],["邻居跟我偶然碰见时会闲聊几句，说的无非是些家长里短的事情。","lín jū gēn wǒ ǒu rán pèng jiàn shí huì xián liáo jǐ jù shuō de wú fēi shì xiē jiā cháng lǐ duǎn de shì qing","Hàng xóm thỉnh thoảng gặp tôi sẽ tán gẫu vài câu, chẳng qua toàn là chuyện vặt trong nhà."],["小夫妻俩决定婚礼一切从简，只摆几桌酒席，婚车和接亲环节一概取消。","xiǎo fū qī liǎ jué dìng hūn lǐ yí qiè cóng jiǎn zhǐ bǎi jǐ zhuō jiǔ xí hūn chē hé jiē qīn huán jié yí gài qǔ xiāo","Đôi vợ chồng trẻ quyết định đám cưới mọi thứ giản lược, chỉ bày vài mâm cỗ, xe hoa và màn rước dâu đều bỏ hết."]]},{"n":13,"c":["词类","副词","时间副词"],"z":"姑且、即、即时、届时、尽早、就此、历来、尚、随即、向来、一经、暂且、早日","t":"Phó từ thời gian 姑且, 即, 即时, 届时, 尽早, 就此, 历来, 尚, 随即, 向来, 一经, 暂且, 早日","d":"姑且/暂且 = tạm thời, tạm; 即 = liền, ngay (văn viết của 就); 即时 = tức thời; 届时 = đến lúc đó; 尽早 = càng sớm càng tốt; 就此 = từ đây, đến đây (thì dừng); 历来/向来 = xưa nay, từ trước đến nay; 尚 = còn, vẫn (văn viết của 还); 随即 = ngay sau đó; 一经 = một khi đã…(là); 早日 = sớm (ngày).","e":[["出于保护当事人的考虑，我们隐去了其真实姓名，姑且以“张某”代称。","chū yú bǎo hù dāng shì rén de kǎo lǜ wǒ men yǐn qù le qí zhēn shí xìng míng gū qiě yǐ zhāng mǒu dài chēng","Vì muốn bảo vệ đương sự, chúng tôi đã giấu tên thật, tạm gọi là \"anh Trương\"."],["“蜜月游”愈发流行，不少年轻人办完酒席即启程旅行。","mì yuè yóu yù fā liú xíng bù shǎo nián qīng rén bàn wán jiǔ xí jí qǐ chéng lǚ xíng","\"Du lịch tuần trăng mật\" ngày càng thịnh hành, nhiều người trẻ làm cỗ cưới xong là lên đường đi du lịch ngay."],["气象局在暴雨来临前，通过网络、电视、广播等多种媒介，即时发布有关暴雨的预警信号。","qì xiàng jú zài bào yǔ lái lín qián tōng guò wǎng luò diàn shì guǎng bō děng duō zhǒng méi jiè jí shí fā bù yǒu guān bào yǔ de yù jǐng xìn hào","Trước khi mưa bão đến, cục khí tượng đã phát tín hiệu cảnh báo mưa lớn tức thời qua nhiều phương tiện như Internet, truyền hình, phát thanh."],["大会将于9月10日至18日在北京举行，届时将会有近800名国外代表与会。","dà huì jiāng yú yuè rì zhì rì zài běi jīng jǔ xíng jiè shí jiāng huì yǒu jìn míng guó wài dài biǎo yù huì","Đại hội sẽ được tổ chức tại Bắc Kinh từ ngày 10 đến 18 tháng 9, đến lúc đó sẽ có gần 800 đại biểu nước ngoài tham dự."],["家长应尽早让孩子参与家务劳动，培养他们的责任感和自理能力。","jiā zhǎng yìng jǐn zǎo ràng hái zi cān yù jiā wù láo dòng péi yǎng tā men de zé rèn gǎn hé zì lǐ néng lì","Phụ huynh nên sớm cho trẻ tham gia làm việc nhà, bồi dưỡng tinh thần trách nhiệm và khả năng tự lập cho trẻ."],["相聚的时光总是短暂的，丰盛的晚餐过后大家就此告别。","xiāng jù de shí guāng zǒng shì duǎn zàn de fēng shèng de wǎn cān guò hòu dà jiā jiù cǐ gào bié","Thời gian sum họp luôn ngắn ngủi, sau bữa tối thịnh soạn mọi người chia tay nhau từ đây."],["苏州历来是经济富饶的鱼米之乡，与杭州齐名，并称“苏杭”。","sū zhōu lì lái shì jīng jì fù ráo de yú mǐ zhī xiāng yǔ háng zhōu qí míng bìng chēng sū háng","Tô Châu xưa nay là vùng đất lúa gạo cá tôm trù phú, nổi tiếng ngang Hàng Châu, được gọi chung là \"Tô Hàng\"."],["截至目前，搜救工作尚未发现幸存人员，事故原因尚待调查。","jié zhì mù qián sōu jiù gōng zuò shàng wèi fā xiàn xìng cún rén yuán shì gù yuán yīn shàng dài diào chá","Tính đến nay, công tác tìm kiếm cứu nạn vẫn chưa phát hiện người sống sót, nguyên nhân sự cố vẫn đang chờ điều tra."],["她犹豫了一下，随即拿起了电话，把这件事报告给总经理。","tā yóu yù le yí xià suí jí ná qǐ le diàn huà bǎ zhè jiàn shì bào gào gěi zǒng jīng lǐ","Cô ấy do dự một chút, ngay sau đó cầm điện thoại lên báo cáo việc này với tổng giám đốc."],["他深居简出，向来不喜与外界交往。","tā shēn jū jiǎn chū xiàng lái bù xǐ yǔ wài jiè jiāo wǎng","Ông ấy sống ẩn dật, xưa nay không thích giao du với bên ngoài."],["绿色农场种植出的果蔬天然无公害，一经上市便供不应求。","lǜ sè nóng chǎng zhòng zhí chū de guǒ shū tiān rán wú gōng hài yì jīng shàng shì biàn gōng bú yìng qiú","Rau quả trồng ở nông trại xanh tự nhiên, sạch, vừa đưa ra thị trường đã cung không đủ cầu."],["鉴于此问题情况复杂、涉及面广，本文限于篇幅，暂且不做讨论。","jiàn yú cǐ wèn tí qíng kuàng fù zá shè jí miàn guǎng běn wén xiàn yú piān fú zàn qiě bú zuò tǎo lùn","Do vấn đề này phức tạp, liên quan nhiều mặt, bài viết vì giới hạn độ dài nên tạm thời không bàn đến."],["孩子们自发来到病房里看望老师，感谢老师的辛勤付出并祝愿老师早日康复。","hái zi men zì fā lái dào bìng fáng lǐ kàn wàng lǎo shī gǎn xiè lǎo shī de xīn qín fù chū bìng zhù yuàn lǎo shī zǎo rì kāng fù","Bọn trẻ tự đến phòng bệnh thăm cô giáo, cảm ơn sự vất vả của cô và chúc cô sớm bình phục."]]},{"n":14,"c":["词类","副词","频率副词"],"z":"连连、屡次、屡屡、频、时而、时时、相继、一个劲（儿）、一连、再度","t":"Phó từ tần suất 连连, 屡次, 屡屡, 频, 时而, 时时, 相继, 一个劲(儿), 一连, 再度","d":"连连 = liên tục, liên tiếp; 屡次/屡屡 = nhiều lần, hết lần này đến lần khác; 频 = thường xuyên (频发 = xảy ra thường xuyên); 时而 = lúc thì, thỉnh thoảng; 时时 = luôn luôn; 相继 = lần lượt, nối tiếp nhau; 一个劲儿 = cứ một mực, liên tục; 一连 = liền một mạch; 再度 = lần nữa.","e":[["这家店的饭菜不但量大实惠，而且色香味俱全，每一个来吃的人都连连称赞。","zhè jiā diàn de fàn cài bú dàn liàng dà shí huì ér qiě sè xiāng wèi jù quán měi yí gè lái chī de rén dōu lián lián chēng zàn","Món ăn ở quán này không những nhiều, rẻ mà còn đủ cả sắc hương vị, ai đến ăn cũng tấm tắc khen liên tục."],["嘉宾因说话屡次被主持人打断，已面露愠色。","jiā bīn yīn shuō huà lǚ cì bèi zhǔ chí rén dǎ duàn yǐ miàn lù yùn sè","Vị khách mời vì nhiều lần bị người dẫn chương trình ngắt lời nên đã lộ vẻ bực bội."],["凭借着高超的技艺和精巧的构思，民间艺术家的作品在国内外赛事中屡屡获奖。","píng jiè zhe gāo chāo de jì yì hé jīng qiǎo de gòu sī mín jiān yì shù jiā de zuò pǐn zài guó nèi wài sài shì zhōng lǚ lǚ huò jiǎng","Nhờ tay nghề cao siêu và ý tưởng tinh xảo, tác phẩm của các nghệ nhân dân gian nhiều lần đoạt giải trong các cuộc thi trong và ngoài nước."],["这里以前是沙尘暴频发的地区，通过植树造林、补绿复绿，现已成为国家级生态文明示范区。","zhè lǐ yǐ qián shì shā chén bào pín fā de dì qū tōng guò zhí shù zào lín bǔ lǜ fù lǜ xiàn yǐ chéng wéi guó jiā jí shēng tài wén míng shì fàn qū","Nơi đây trước kia là vùng thường xuyên có bão cát, nhờ trồng cây gây rừng, phủ xanh trở lại, nay đã trở thành khu mẫu văn minh sinh thái cấp quốc gia."],["他凝神望着前方连绵的青山，时而眉头微蹙，时而喜上眉梢，不知思绪飘到了何方。","tā níng shén wàng zhe qián fāng lián mián de qīng shān shí ér méi tóu wēi cù shí ér xǐ shàng méi shāo bù zhī sī xù piāo dào le hé fāng","Anh ấy chăm chú nhìn dãy núi xanh trập trùng phía trước, lúc thì hơi nhíu mày, lúc thì mặt mày rạng rỡ, không biết suy nghĩ đã trôi về phương nào."],["对这些好心人的善举，受帮助者时时感念于心，希望有朝一日能回报恩人。","duì zhè xiē hǎo xīn rén de shàn jǔ shòu bāng zhù zhě shí shí gǎn niàn yú xīn xī wàng yǒu zhāo yí rì néng huí bào ēn rén","Đối với việc làm tốt của những người tốt bụng này, người được giúp đỡ luôn ghi lòng tạc dạ, mong một ngày nào đó có thể báo đáp ân nhân."],["金秋九月，北京戏剧舞台异彩纷呈，相继展演了精品剧目114部。","jīn qiū jiǔ yuè běi jīng xì jù wǔ tái yì cǎi fēn chéng xiāng jì zhǎn yǎn le jīng pǐn jù mù bù","Tháng chín mùa thu vàng, sân khấu kịch Bắc Kinh muôn màu rực rỡ, lần lượt công diễn 114 vở kịch chất lượng cao."],["大嫂在旁边一个劲使眼色，示意哥哥不要再说下去了。","dà sǎo zài páng biān yí gè jìn shǐ yǎn sè shì yì gē ge bú yào zài shuō xià qù le","Chị dâu ở bên cạnh cứ nháy mắt mãi, ra hiệu cho anh trai đừng nói tiếp nữa."],["为了尽快研制出特效药，他常常在实验室里一连奋战十几个小时。","wèi le jǐn kuài yán zhì chū tè xiào yào tā cháng cháng zài shí yàn shì lǐ yì lián fèn zhàn shí jǐ gè xiǎo shí","Để sớm nghiên cứu ra thuốc đặc trị, anh ấy thường làm việc miệt mài liền mười mấy tiếng trong phòng thí nghiệm."],["时隔12年，中国队再度捧起冠军奖杯。","shí gé nián zhōng guó duì zài dù pěng qǐ guàn jūn jiǎng bēi","Sau 12 năm, đội Trung Quốc lại một lần nữa nâng cúp vô địch."]]},{"n":15,"c":["词类","副词","方式副词"],"z":"按理、按说、百般、不由得、趁机、趁早、大肆、断然、公然、火速、截然、竭力、尽情、就近、刻意、拼命、强行、任意、日趋、如期、擅自、私自、特此、瞎、一并、一举、一手、毅然、有意、照常、照例、照样、执意、骤然、逐一、专程","t":"Phó từ cách thức (nhóm HSK 7–9)","d":"按理/按说 = theo lẽ thường; 百般 = đủ mọi cách; 不由得 = không kìm được; 趁机 = nhân cơ hội; 趁早 = sớm, nhân lúc còn sớm; 大肆 = tràn lan, rầm rộ (nghĩa xấu); 断然 = dứt khoát; 公然 = công khai, trắng trợn; 火速 = cấp tốc; 截然 = hoàn toàn (khác); 竭力 = dốc sức; 尽情 = thỏa thích; 就近 = gần nhất; 刻意 = cố tình, dụng ý; 拼命 = liều mạng, hết sức; 强行 = cưỡng ép; 任意 = tùy ý; 日趋 = ngày càng; 如期 = đúng hạn; 擅自/私自 = tự ý, lén; 特此 = nay đặc biệt (văn bản); 瞎 = bừa, mù quáng; 一并 = cùng lúc, gộp luôn; 一举 = một lần (là thành công); 一手 = một tay (gây ra/gây dựng); 毅然 = kiên quyết; 有意 = cố ý; 照常 = như thường lệ; 照例 = theo lệ; 照样 = vẫn như thường; 执意 = khăng khăng; 骤然 = đột ngột; 逐一 = lần lượt từng cái; 专程 = chuyên đi (để làm gì).","e":[["你出现了这个失误，按理该扣一个月的工资，但看在你平时工作还算认真的份上，公司决定给你机会将功补过。","nǐ chū xiàn le zhè ge shī wù àn lǐ gāi kòu yí gè yuè de gōng zī dàn kàn zài nǐ píng shí gōng zuò hái suàn rèn zhēn de fèn shàng gōng sī jué dìng gěi nǐ jī huì jiāng gōng bǔ guò","Cậu mắc sai sót này, theo lẽ phải trừ một tháng lương, nhưng nể tình cậu ngày thường làm việc khá chăm chỉ, công ty quyết định cho cậu cơ hội lấy công chuộc tội."],["年轻人的私事，按说我不该多问，可是既然影响到了工作，我就不能不问一问了。","nián qīng rén de sī shì àn shuō wǒ bù gāi duō wèn kě shì jì rán yǐng xiǎng dào le gōng zuò wǒ jiù bù néng bú wèn yi wèn le","Chuyện riêng của người trẻ, theo lẽ tôi không nên hỏi nhiều, nhưng đã ảnh hưởng đến công việc thì tôi không thể không hỏi."],["养护工人对园内种植的一草一木百般呵护，定时浇水、悉心修剪。","yǎng hù gōng rén duì yuán nèi zhòng zhí de yì cǎo yí mù bǎi bān hē hù dìng shí jiāo shuǐ xī xīn xiū jiǎn","Công nhân chăm sóc dùng đủ mọi cách nâng niu từng ngọn cỏ cành cây trong vườn, tưới nước đúng giờ, cắt tỉa cẩn thận."],["看到新戏排练终于有了进展，导演不由得松了口气。","kàn dào xīn xì pái liàn zhōng yú yǒu le jìn zhǎn dǎo yǎn bù yóu de sōng le kǒu qì","Thấy buổi tập vở kịch mới cuối cùng đã có tiến triển, đạo diễn không khỏi thở phào nhẹ nhõm."],["对方球员心情焦躁，失误明显增多，黑龙江队趁机将比分反超。","duì fāng qiú yuán xīn qíng jiāo zào shī wù míng xiǎn zēng duō hēi lóng jiāng duì chèn jī jiāng bǐ fēn fǎn chāo","Cầu thủ đội bạn nôn nóng, sai sót tăng rõ rệt, đội Hắc Long Giang nhân cơ hội lật ngược tỷ số."],["你想靠炒股票赚钱？趁早打消这个念头儿吧。","nǐ xiǎng kào chǎo gǔ piào zhuàn qián chèn zǎo dǎ xiāo zhè ge niàn tóu r ba","Bạn muốn kiếm tiền nhờ chơi chứng khoán ư? Sớm dẹp bỏ ý nghĩ đó đi."],["他在饭桌上大肆吹嘘自己的财富和人脉，试图建立起一个成功人士的形象。","tā zài fàn zhuō shàng dà sì chuī xū zì jǐ de cái fù hé rén mài shì tú jiàn lì qǐ yí gè chéng gōng rén shì de xíng xiàng","Trên bàn ăn hắn ra sức khoe khoang tiền bạc và quan hệ của mình, cố tạo dựng hình ảnh một người thành đạt."],["对于贵方提出的无理要求，我方断然拒绝。","duì yú guì fāng tí chū de wú lǐ yāo qiú wǒ fāng duàn rán jù jué","Đối với yêu cầu vô lý mà quý phía đưa ra, phía chúng tôi dứt khoát từ chối."],["他在训练时公然顶撞主教练，受到严肃批评是理所当然的。","tā zài xùn liàn shí gōng rán dǐng zhuàng zhǔ jiào liàn shòu dào yán sù pī píng shì lǐ suǒ dāng rán de","Anh ta công khai cãi lại huấn luyện viên trưởng trong buổi tập, bị phê bình nghiêm khắc là lẽ đương nhiên."],["地震发生后，他主动终止休假，火速归队，毅然投身抢险救灾第一线。","dì zhèn fā shēng hòu tā zhǔ dòng zhōng zhǐ xiū jià huǒ sù guī duì yì rán tóu shēn qiǎng xiǎn jiù zāi dì yī xiàn","Sau khi động đất xảy ra, anh ấy chủ động dừng kỳ nghỉ, cấp tốc trở về đơn vị, kiên quyết lao vào tuyến đầu cứu hộ cứu nạn."],["他们俩虽是双胞胎，性格却截然相反。","tā men liǎ suī shì shuāng bāo tāi xìng gé què jié rán xiāng fǎn","Hai người họ tuy là sinh đôi nhưng tính cách lại hoàn toàn trái ngược."],["但凡旅客有需求，小到一针一线，大到轮椅担架，铁路工作人员都会竭力满足。","dàn fán lǚ kè yǒu xū qiú xiǎo dào yì zhēn yí xiàn dà dào lún yǐ dān jià tiě lù gōng zuò rén yuán dōu huì jié lì mǎn zú","Hễ hành khách có nhu cầu, nhỏ như cây kim sợi chỉ, lớn như xe lăn cáng cứu thương, nhân viên đường sắt đều dốc sức đáp ứng."],["游客们迫不及待地躺在草地上尽情呼吸新鲜的空气，享受灿烂的阳光。","yóu kè men pò bù jí dài de tǎng zài cǎo dì shàng jìn qíng hū xī xīn xiān de kōng qì xiǎng shòu càn làn de yáng guāng","Du khách nóng lòng nằm dài trên bãi cỏ, thỏa thích hít thở không khí trong lành, tận hưởng ánh nắng rực rỡ."],["过去驾驶证补换需前往车管所办理，现在在网上提交信息后即可就近领取。","guò qù jià shǐ zhèng bǔ huàn xū qián wǎng chē guǎn suǒ bàn lǐ xiàn zài zài wǎng shàng tí jiāo xìn xī hòu jí kě jiù jìn lǐng qǔ","Trước đây cấp đổi bằng lái phải đến phòng quản lý xe, bây giờ nộp thông tin trên mạng là có thể nhận ở điểm gần nhất."],["他在演讲中幽默的插话并非一时兴起，而是刻意为之，以赢得观众的好感。","tā zài yǎn jiǎng zhōng yōu mò de chā huà bìng fēi yì shí xìng qǐ ér shì kè yì wéi zhī yǐ yíng dé guān zhòng de hǎo gǎn","Những câu chen ngang hài hước trong bài diễn thuyết của anh ấy không phải ngẫu hứng, mà là cố tình làm vậy để chiếm cảm tình khán giả."],["你别这么拼命地工作，要注意身体啊！","nǐ bié zhè me pīn mìng de gōng zuò yào zhù yì shēn tǐ a","Bạn đừng làm việc liều mạng như thế, phải chú ý sức khỏe chứ!"],["当电梯关门时，不可强行挤入，以免发生危险。","dāng diàn tī guān mén shí bù kě qiáng xíng jǐ rù yǐ miǎn fā shēng wēi xiǎn","Khi thang máy đang đóng cửa, không được cố chen vào để tránh nguy hiểm."],["历史就是历史，谁都不能任意修改。","lì shǐ jiù shì lì shǐ shuí dōu bù néng rèn yì xiū gǎi","Lịch sử là lịch sử, không ai được tùy ý sửa đổi."],["智能手机市场现已日趋饱和，如何稳中求变，成了各大厂商首要解决的问题。","zhì néng shǒu jī shì chǎng xiàn yǐ rì qū bǎo hé rú hé wěn zhōng qiú biàn chéng le gè dà chǎng shāng shǒu yào jiě jué de wèn tí","Thị trường điện thoại thông minh hiện đã ngày càng bão hòa, làm sao để ổn định mà vẫn đổi mới đã trở thành vấn đề hàng đầu các hãng lớn phải giải quyết."],["虽然时间紧迫，工作量浩繁，工人们终于克服种种困难，如期完成了任务。","suī rán shí jiān jǐn pò gōng zuò liàng hào fán gōng rén men zhōng yú kè fú zhǒng zhǒng kùn nán rú qī wán chéng le rèn wu","Tuy thời gian gấp gáp, khối lượng công việc khổng lồ, các công nhân cuối cùng đã vượt qua mọi khó khăn, hoàn thành nhiệm vụ đúng hạn."],["未经商标注册人许可，任何组织和个人均不得擅自将该商标用于同类商品上。","wèi jīng shāng biāo zhù cè rén xǔ kě rèn hé zǔ zhī hé gè rén jūn bù de shàn zì jiāng gāi shāng biāo yòng yú tóng lèi shāng pǐn shàng","Khi chưa được người đăng ký nhãn hiệu cho phép, bất kỳ tổ chức, cá nhân nào cũng không được tự ý dùng nhãn hiệu đó cho hàng hóa cùng loại."],["行程中请务必听从导游安排，如私自离团，产生的一切后果均须自行承担。","xíng chéng zhōng qǐng wù bì tīng cóng dǎo yóu ān pái rú sī zì lí tuán chǎn shēng de yí qiè hòu guǒ jūn xū zì xíng chéng dān","Trong hành trình xin nhất định nghe theo sắp xếp của hướng dẫn viên, nếu tự ý rời đoàn, mọi hậu quả phát sinh đều phải tự chịu."],["贵公司为我们提供了极大的帮助，特此表示感谢。","guì gōng sī wèi wǒ men tí gōng le jí dà de bāng zhù tè cǐ biǎo shì gǎn xiè","Quý công ty đã giúp đỡ chúng tôi rất nhiều, nay xin đặc biệt bày tỏ lời cảm ơn."],["不明白的不要瞎做，不该说的不要瞎说。","bù míng bai de bú yào xiā zuò bù gāi shuō de bú yào xiā shuō","Không hiểu thì đừng làm bừa, không nên nói thì đừng nói bậy."],["关心支持我的朋友太多，无法一一列举，在此一并致谢。","guān xīn zhī chí wǒ de péng you tài duō wú fǎ yī yī liè jǔ zài cǐ yí bìng zhì xiè","Bạn bè quan tâm ủng hộ tôi quá nhiều, không thể kể hết, xin gửi lời cảm ơn chung tới tất cả."],["在奥运会乒乓球男子团体决赛中，三名中国选手团结一致，一举夺冠。","zài ào yùn huì pīng pāng qiú nán zǐ tuán tǐ jué sài zhōng sān míng zhōng guó xuǎn shǒu tuán jié yí zhì yì jǔ duó guàn","Trong trận chung kết đồng đội nam bóng bàn Olympic, ba tay vợt Trung Quốc đồng lòng, một trận giành ngôi vô địch."],["为了照顾生病的妻子和年幼的孩子，他关了自己一手创办的工作室，专心守着家人。","wèi le zhào gù shēng bìng de qī zi hé nián yòu de hái zi tā guān le zì jǐ yì shǒu chuàng bàn de gōng zuò shì zhuān xīn shǒu zhe jiā rén","Để chăm sóc người vợ ốm và đứa con nhỏ, anh ấy đã đóng cửa studio do chính tay mình gây dựng, chuyên tâm ở bên gia đình."],["他取得博士学位后，毅然放弃了国外良好的工作条件和优厚的物质待遇，回到了祖国的怀抱。","tā qǔ dé bó shì xué wèi hòu yì rán fàng qì le guó wài liáng hǎo de gōng zuò tiáo jiàn hé yōu hòu de wù zhì dài yù huí dào le zǔ guó de huái bào","Sau khi lấy bằng tiến sĩ, ông ấy kiên quyết từ bỏ điều kiện làm việc tốt và đãi ngộ vật chất hậu hĩnh ở nước ngoài, trở về vòng tay Tổ quốc."],["说到精彩之处，他有意不往下讲，吊足了大家的胃口。","shuō dào jīng cǎi zhī chù tā yǒu yì bù wǎng xià jiǎng diào zú le dà jiā de wèi kǒu","Kể đến đoạn hay, ông ấy cố ý không kể tiếp, khiến mọi người tò mò hết sức."],["尽管一周以来连续阴雨，但施工仍照常进行。","jǐn guǎn yì zhōu yǐ lái lián xù yīn yǔ dàn shī gōng réng zhào cháng jìn xíng","Mặc dù mưa dầm liên tục cả tuần, việc thi công vẫn tiến hành như thường lệ."],["这周末店里的生意比较忙，老郭没有照例休假，而是到店帮忙接待顾客。","zhè zhōu mò diàn lǐ de shēng yì bǐ jiào máng lǎo guō méi yǒu zhào lì xiū jià ér shì dào diàn bāng máng jiē dài gù kè","Cuối tuần này quán khá đông khách, lão Quách không nghỉ như thường lệ mà đến quán giúp tiếp khách."],["他年近80照样身板硬朗，精力和体力不输年轻人。","tā nián jìn zhào yàng shēn bǎn yìng lǎng jīng lì hé tǐ lì bù shū nián qīng rén","Ông ấy gần 80 tuổi mà vẫn khỏe mạnh như thường, tinh lực và thể lực không thua người trẻ."],["我和他多年未见，本想留他多住几天，可他执意不肯，说是家中有事。","wǒ hé tā duō nián wèi jiàn běn xiǎng liú tā duō zhù jǐ tiān kě tā zhí yì bù kěn shuō shì jiā zhōng yǒu shì","Tôi và anh ấy nhiều năm không gặp, vốn định giữ anh ấy ở thêm mấy ngày, nhưng anh ấy khăng khăng không chịu, nói là nhà có việc."],["一夜狂风暴雨过后，气温骤然下降了十几度。","yí yè kuáng fēng bào yǔ guò hòu qì wēn zhòu rán xià jiàng le shí jǐ dù","Sau một đêm mưa to gió lớn, nhiệt độ đột ngột giảm hơn mười độ."],["大幕拉开，节目主持人走上舞台，他首先感谢了观众的到来，然后逐一介绍在场嘉宾。","dà mù lā kāi jié mù zhǔ chí rén zǒu shàng wǔ tái tā shǒu xiān gǎn xiè le guān zhòng de dào lái rán hòu zhú yī jiè shào zài chǎng jiā bīn","Màn sân khấu kéo ra, người dẫn chương trình bước lên sân khấu, trước tiên cảm ơn khán giả đã đến, sau đó lần lượt giới thiệu từng vị khách mời."],["为了吃到最鲜美的河豚，远在新疆的刘先生跨越三千多公里专程来到扬中。","wèi le chī dào zuì xiān měi de hé tún yuǎn zài xīn jiāng de liú xiān sheng kuà yuè sān qiān duō gōng lǐ zhuān chéng lái dào yáng zhōng","Để được ăn cá nóc tươi ngon nhất, ông Lưu ở tận Tân Cương đã vượt hơn ba nghìn cây số chuyên đến Dương Trung."]]},{"n":16,"c":["词类","副词","否定副词"],"z":"不见得、绝不、无从、无须、无可、勿","t":"Phó từ phủ định 不见得, 绝不, 无从, 无须, 无可, 勿","d":"不见得 = chưa chắc; 绝不 = tuyệt đối không; 无从 = không biết từ đâu, không có cách (để…); 无须 = không cần; 无可 = không thể (无可奉告 = miễn bình luận); 勿 = chớ, đừng (văn viết).","e":[["这件事非常麻烦，你就是让比我厉害十倍的人去办，也不见得能办成。","zhè jiàn shì fēi cháng má fan nǐ jiù shì ràng bǐ wǒ lì hài shí bèi de rén qù bàn yě bú jiàn de néng bàn chéng","Việc này rất phiền phức, cho dù bạn để người giỏi hơn tôi mười lần đi làm, cũng chưa chắc đã làm xong."],["他那么聪明的人，绝不会干这种傻事。","tā nà me cōng ming de rén jué bú huì gàn zhè zhǒng shǎ shì","Người thông minh như anh ấy tuyệt đối sẽ không làm chuyện ngốc nghếch này."],["即将告别学生时代，我心有千言反而无从说起。","jí jiāng gào bié xué shēng shí dài wǒ xīn yǒu qiān yán fǎn ér wú cóng shuō qǐ","Sắp từ giã thời học sinh, trong lòng có ngàn lời muốn nói mà lại không biết bắt đầu từ đâu."],["她满墙贴的都是舞台上演奏的照片，音乐对她的重要性无须多言。","tā mǎn qiáng tiē de dōu shì wǔ tái shàng yǎn zòu de zhào piàn yīn yuè duì tā de zhòng yào xìng wú xū duō yán","Khắp tường nhà cô ấy dán toàn ảnh biểu diễn trên sân khấu, tầm quan trọng của âm nhạc với cô ấy không cần nói nhiều."],["当被问及该片是否以悲剧结尾，女主表示已签署保密协议，对此无可奉告。","dāng bèi wèn jí gāi piàn shì fǒu yǐ bēi jù jié wěi nǚ zhǔ biǎo shì yǐ qiān shǔ bǎo mì xié yì duì cǐ wú kě fèng gào","Khi được hỏi bộ phim có kết thúc bi kịch không, nữ chính cho biết đã ký thỏa thuận bảo mật, xin miễn bình luận về việc này."],["室内若发生煤气泄漏，应立即打开门窗通风，切勿使用明火。","shì nèi ruò fā shēng méi qì xiè lòu yìng lì jí dǎ kāi mén chuāng tōng fēng qiè wù shǐ yòng míng huǒ","Nếu trong nhà bị rò rỉ khí gas, phải lập tức mở cửa thông gió, tuyệt đối chớ dùng lửa."]]},{"n":17,"c":["词类","副词","语气副词"],"z":"必定、必将、不妨、不免、反倒、非得、分明、怪不得、果真、好在、何必、竟、愣、莫非、难怪、宁可、宁愿、碰巧、偏偏、恰巧、切、情愿、势必、索性、万万、未免、务必、幸好、幸亏、终究、何不、何尝、何苦","t":"Phó từ ngữ khí (nhóm HSK 7–9)","d":"必定/必将 = nhất định, ắt sẽ; 不妨 = cứ thử, không ngại; 不免 = khó tránh khỏi; 反倒 = ngược lại; 非得…(不可) = nhất thiết phải; 分明 = rõ ràng là; 怪不得/难怪 = thảo nào; 果真 = quả thật; 好在 = may mà, được cái; 何必 = cần gì phải; 竟 = vậy mà; 愣 = cứ nhất định, cứng đầu; 莫非 = lẽ nào, chẳng lẽ; 宁可/宁愿 = thà; 碰巧/恰巧 = vừa may, tình cờ; 偏偏 = lại cứ, cố tình; 切 = nhất thiết (切记, 切不可); 情愿 = cam lòng; 势必 = ắt hẳn; 索性 = dứt khoát; 万万 = tuyệt đối; 未免 = có phần, hơi quá; 务必 = nhất định phải; 幸好/幸亏 = may mà; 终究 = rốt cuộc, cuối cùng vẫn; 何不 = sao không; 何尝 = đâu có, há chẳng; 何苦 = khổ gì mà, việc gì phải.","e":[["以你的资质，假以时日必定会“青出于蓝而胜于蓝”。","yǐ nǐ de zī zhì jiǎ yǐ shí rì bì dìng huì qīng chū yú lán ér shèng yú lán","Với tư chất của cậu, cho thêm thời gian nhất định sẽ \"con hơn cha\"."],["这次友好访问，必将使两国关系上升到一个新的阶段。","zhè cì yǒu hǎo fǎng wèn bì jiāng shǐ liǎng guó guān xi shàng shēng dào yí gè xīn de jiē duàn","Chuyến thăm hữu nghị lần này ắt sẽ đưa quan hệ hai nước lên một tầm cao mới."],["巧用果蔬饰家居，可拥有回味无穷的诗情画意，有兴趣的不妨一试。","qiǎo yòng guǒ shū shì jiā jū kě yōng yǒu huí wèi wú qióng de shī qíng huà yì yǒu xìng qù de bù fáng yí shì","Khéo dùng rau quả trang trí nhà cửa có thể tạo nên vẻ thơ mộng đầy dư vị, ai có hứng thú cứ thử xem."],["每逢下雨天，她就不免想起一桩伤心的往事。","měi féng xià yǔ tiān tā jiù bù miǎn xiǎng qǐ yì zhuāng shāng xīn de wǎng shì","Cứ mỗi ngày mưa, cô ấy lại khó tránh khỏi nhớ đến một chuyện buồn đã qua."],["我让他走慢点儿，等等我，他反倒加快了脚步。","wǒ ràng tā zǒu màn diǎn r děng děng wǒ tā fǎn dào jiā kuài le jiǎo bù","Tôi bảo anh ấy đi chậm lại, đợi tôi với, anh ấy ngược lại còn bước nhanh hơn."],["要想练就一手好的毛笔字，非得花十年甚至数十年功夫不可。","yào xiǎng liàn jiù yì shǒu hǎo de máo bǐ zì fēi děi huā shí nián shèn zhì shù shí nián gōng fū bù kě","Muốn luyện được nét chữ bút lông đẹp, nhất thiết phải bỏ ra mười năm thậm chí mấy chục năm công phu."],["我分明看见他从办公室拿走了一份文件，可他就是不承认。","wǒ fēn míng kàn jiàn tā cóng bàn gōng shì ná zǒu le yí fèn wén jiàn kě tā jiù shì bù chéng rèn","Rõ ràng tôi thấy anh ta lấy một tập tài liệu từ văn phòng đi, nhưng anh ta cứ không chịu thừa nhận."],["他真是个精明能干的小伙子，怪不得厂长这么器重他。","tā zhēn shì gè jīng míng néng gàn de xiǎo huǒ zi guài bù de chǎng zhǎng zhè me qì zhòng tā","Cậu ấy thật là chàng trai tháo vát giỏi giang, thảo nào giám đốc nhà máy coi trọng cậu ấy như vậy."],["九寨沟的风景果真名不虚传，如人间仙境一般。","jiǔ zhài gōu de fēng jǐng guǒ zhēn míng bù xū chuán rú rén jiān xiān jìng yì bān","Phong cảnh Cửu Trại Câu quả thật danh bất hư truyền, như chốn tiên cảnh nơi trần gian."],["北京的胡同多得出奇，而且样子大同小异，穿梭其中极易迷路。好在北京人热心，问路时总能得到帮助。","běi jīng de hú tòng duō dé chū qí ér qiě yàng zi dà tóng xiǎo yì chuān suō qí zhōng jí yì mí lù hǎo zài běi jīng rén rè xīn wèn lù shí zǒng néng dé dào bāng zhù","Ngõ hẻm ở Bắc Kinh nhiều đến lạ, lại na ná nhau, đi trong đó rất dễ lạc. May mà người Bắc Kinh nhiệt tình, hỏi đường lúc nào cũng được giúp."],["清者自清，你自己是清白的，何必跟误会你的人解释那么多。","qīng zhě zì qīng nǐ zì jǐ shì qīng bái de hé bì gēn wù huì nǐ de rén jiě shì nà me duō","Trong sạch thì tự khắc trong sạch, bạn vô tội thì cần gì phải giải thích nhiều với người hiểu lầm bạn."],["整场比赛的战术执行得几乎无懈可击，对手在我方的猛烈进攻和严密防守下竟一分未得。","zhěng chǎng bǐ sài de zhàn shù zhí xíng de jī hū wú xiè kě jī duì shǒu zài wǒ fāng de měng liè jìn gōng hé yán mì fáng shǒu xià jìng yì fēn wèi de","Chiến thuật cả trận được thực hiện gần như không chê vào đâu được, đối thủ trước sự tấn công mạnh mẽ và phòng ngự chặt chẽ của ta vậy mà không ghi được điểm nào."],["事情明明就是他做的，可他愣不承认。","shì qing míng míng jiù shì tā zuò de kě tā lèng bù chéng rèn","Chuyện rõ ràng là anh ta làm, vậy mà anh ta cứ nhất định không thừa nhận."],["他这人一向无事不登三宝殿，今天忽然登门拜访，莫非有什么棘手的事相求？","tā zhè rén yí xiàng wú shì bù dēng sān bǎo diàn jīn tiān hū rán dēng mén bài fǎng mò fēi yǒu shén me jí shǒu de shì xiāng qiú","Anh ta xưa nay không có việc thì chẳng đến, hôm nay bỗng nhiên tới thăm, lẽ nào có việc gì khó muốn nhờ?"],["物美价廉的菜品，清爽整洁的装修，热情周到的服务，难怪这家店的生意越来越红火。","wù měi jià lián de cài pǐn qīng shuǎng zhěng jié de zhuāng xiū rè qíng zhōu dào de fú wù nán guài zhè jiā diàn de shēng yì yuè lái yuè hóng huǒ","Món ăn ngon rẻ, trang trí sạch sẽ gọn gàng, phục vụ nhiệt tình chu đáo, thảo nào quán này làm ăn ngày càng phát đạt."],["为了抓住这个宝贵的工作机会，他宁可每天双城通勤。","wèi le zhuā zhù zhè ge bǎo guì de gōng zuò jī huì tā nìng kě měi tiān shuāng chéng tōng qín","Để nắm lấy cơ hội việc làm quý giá này, anh ấy thà ngày nào cũng đi lại giữa hai thành phố."],["如果贵公司无法保证按时交付，我们宁愿放弃此次合作。","rú guǒ guì gōng sī wú fǎ bǎo zhèng àn shí jiāo fù wǒ men nìng yuàn fàng qì cǐ cì hé zuò","Nếu quý công ty không thể đảm bảo giao hàng đúng hạn, chúng tôi thà từ bỏ lần hợp tác này."],["我那时正为找房子发愁，碰巧有个同学租的两居室空出了一个房间，我就搬过去住了。","wǒ nà shí zhèng wèi zhǎo fáng zi fā chóu pèng qiǎo yǒu gè tóng xué zū de liǎng jū shì kòng chū le yí gè fáng jiān wǒ jiù bān guò qù zhù le","Lúc đó tôi đang rầu vì tìm nhà, vừa may căn hộ hai phòng một bạn học thuê trống ra một phòng, tôi liền chuyển đến ở."],["台风早不来，晚不来，偏偏赶在这个时候来！","tái fēng zǎo bù lái wǎn bù lái piān piān gǎn zài zhè ge shí hou lái","Bão sớm không đến, muộn không đến, lại cứ nhằm đúng lúc này mà đến!"],["因为“鱼”恰巧跟“余”字同音，所以年夜饭饭桌上一定有鱼，是希望“年年有余”的意思。","yīn wèi yú qià qiǎo gēn yú zì tóng yīn suǒ yǐ nián yè fàn fàn zhuō shàng yí dìng yǒu yú shì xī wàng nián nián yǒu yú de yì si","Vì chữ \"cá\" (鱼) tình cờ đồng âm với chữ \"dư\" (余), nên mâm cơm tất niên nhất định có cá, mang ý mong \"năm nào cũng dư dả\"."],["雪山海拔较高，游览过程中易产生高原反应，切记根据自身情况量力而行。","xuě shān hǎi bá jiào gāo yóu lǎn guò chéng zhōng yì chǎn shēng gāo yuán fǎn yìng qiè jì gēn jù zì shēn qíng kuàng liàng lì ér xíng","Núi tuyết có độ cao lớn, khi tham quan dễ bị phản ứng độ cao, nhất định phải nhớ tùy sức mình mà làm."],["这家火锅店口碑极好，很多顾客情愿排队等一两个小时，也要在这里吃。","zhè jiā huǒ guō diàn kǒu bēi jí hǎo hěn duō gù kè qíng yuàn pái duì děng yì liǎng gè xiǎo shí yě yào zài zhè lǐ chī","Quán lẩu này tiếng tăm cực tốt, nhiều khách cam lòng xếp hàng đợi một hai tiếng cũng phải ăn ở đây."],["如果这个关键技术问题得不到解决，公司的竞争力势必会受到影响。","rú guǒ zhè ge guān jiàn jì shù wèn tí de bú dào jiě jué gōng sī de jìng zhēng lì shì bì huì shòu dào yǐng xiǎng","Nếu vấn đề kỹ thuật then chốt này không được giải quyết, sức cạnh tranh của công ty ắt sẽ bị ảnh hưởng."],["他考了几次都没通过，索性不考了。","tā kǎo le jǐ cì dōu méi tōng guò suǒ xìng bù kǎo le","Anh ấy thi mấy lần đều không qua, dứt khoát không thi nữa."],["事实表明，代言人与品牌的匹配程度对商品销售有着重要影响，企业万万不可轻视。","shì shí biǎo míng dài yán rén yǔ pǐn pái de pǐ pèi chéng dù duì shāng pǐn xiāo shòu yǒu zhe zhòng yào yǐng xiǎng qǐ yè wàn wàn bù kě qīng shì","Thực tế cho thấy mức độ phù hợp giữa người đại diện và thương hiệu có ảnh hưởng quan trọng đến doanh số, doanh nghiệp tuyệt đối không được xem nhẹ."],["没有取得理想结果，他未免有些沮丧，此时最需要的是鼓励和安慰。","méi yǒu qǔ dé lǐ xiǎng jié guǒ tā wèi miǎn yǒu xiē jǔ sàng cǐ shí zuì xū yào de shì gǔ lì hé ān wèi","Không đạt được kết quả như ý, anh ấy không khỏi có phần chán nản, lúc này cần nhất là động viên và an ủi."],["演出期间，请各位观众务必将手机调至静音，以免影响他人。","yǎn chū qī jiān qǐng gè wèi guān zhòng wù bì jiāng shǒu jī tiáo zhì jìng yīn yǐ miǎn yǐng xiǎng tā rén","Trong thời gian biểu diễn, kính mong quý khán giả nhất định chuyển điện thoại sang chế độ im lặng để không ảnh hưởng người khác."],["我听见他的话后，吃惊地朝四周看了看，幸好附近无人，这才放了心。","wǒ tīng jiàn tā de huà hòu chī jīng de cháo sì zhōu kàn le kàn xìng hǎo fù jìn wú rén zhè cái fàng le xīn","Nghe anh ấy nói xong, tôi giật mình nhìn quanh, may mà gần đó không có ai, lúc ấy mới yên tâm."],["刘女士不小心把手提包落在了出租车上，幸亏遇到林师傅这样拾金不昧的司机，主动把包交还给了她。","liú nǚ shì bù xiǎo xīn bǎ shǒu tí bāo luò zài le chū zū chē shàng xìng kuī yù dào lín shī fu zhè yàng shí jīn bú mèi de sī jī zhǔ dòng bǎ bāo jiāo huán gěi le tā","Bà Lưu sơ ý để quên túi xách trên taxi, may mà gặp được bác tài Lâm nhặt được của rơi trả người đánh mất, chủ động trả lại túi cho bà."],["漂泊的游子，无论在外如何坚强，回到家也终究是个孩子。","piāo bó de yóu zǐ wú lùn zài wài rú hé jiān qiáng huí dào jiā yě zhōng jiū shì gè hái zi","Người con xa xứ, dù ở bên ngoài mạnh mẽ đến đâu, về đến nhà rốt cuộc vẫn là đứa trẻ."],["我要去海南旅游了，你最近不也休假吗，何不一起去？","wǒ yào qù hǎi nán lǚ yóu le nǐ zuì jìn bù yě xiū jià ma hé bù yì qǐ qù","Tôi sắp đi du lịch Hải Nam, dạo này bạn chẳng phải cũng được nghỉ sao, sao không đi cùng luôn?"],["体育比赛是这样，其他事情何尝不也是如此呢？","tǐ yù bǐ sài shì zhè yàng qí tā shì qing hé cháng bù yě shì rú cǐ ne","Thi đấu thể thao là như vậy, những việc khác há chẳng phải cũng thế sao?"],["小张刚毕业，社会经验不足，犯点错误也难免，你何苦为难她呢？","xiǎo zhāng gāng bì yè shè huì jīng yàn bù zú fàn diǎn cuò wù yě nán miǎn nǐ hé kǔ wéi nán tā ne","Tiểu Trương mới tốt nghiệp, kinh nghiệm xã hội còn ít, mắc chút lỗi cũng khó tránh, bạn việc gì phải làm khó cô ấy?"]]},{"n":18,"c":["词类","副词","判断副词"],"z":"乃","t":"Phó từ phán đoán 乃","d":"乃 = là, chính là (văn viết cổ, giống 是).","e":[["该片剧情严谨，全员演技在线，真乃一部不可多得的佳作。","gāi piàn jù qíng yán jǐn quán yuán yǎn jì zài xiàn zhēn nǎi yí bù bù kě duō de de jiā zuò","Bộ phim này cốt truyện chặt chẽ, toàn bộ diễn viên diễn xuất tốt, thật là một tác phẩm hay hiếm có."],["我问他是怎么知道的，他神秘地说：“此乃天机，不可泄露。”","wǒ wèn tā shì zěn me zhī dao de tā shén mì de shuō cǐ nǎi tiān jī bù kě xiè lòu","Tôi hỏi anh ấy làm sao biết được, anh ấy bí ẩn nói: \"Đây là thiên cơ, không thể tiết lộ.\""]]},{"n":19,"c":["词类","介词","引出时间、处所"],"z":"打","t":"Giới từ 打 (thời gian, nơi chốn)","d":"打 = từ (khẩu ngữ, giống 从): 打这天起 = từ hôm đó.","e":[["打这天起，小赵替父亲担起了全家的重担。","dǎ zhè tiān qǐ xiǎo zhào tì fù qīn dān qǐ le quán jiā de zhòng dàn","Từ hôm đó trở đi, Tiểu Triệu thay bố gánh vác gánh nặng cả nhà."],["他悄声说这可是件宝贝，打皇宫里流出来的。","tā qiǎo shēng shuō zhè kě shì jiàn bǎo bèi dǎ huáng gōng lǐ liú chū lái de","Ông ấy nói khẽ đây là bảo vật, từ trong hoàng cung lưu lạc ra."]]},{"n":20,"c":["词类","介词","引出对象"],"z":"当着、就⁶","t":"Giới từ 当着, 就","d":"当着 + người (+的面) = trước mặt ai; 就 + vấn đề = về (vấn đề gì) (văn viết: 就…进行讨论).","e":[["当着这么多人，那人只好把话咽了下去。","dāng zhe zhè me duō rén nà rén zhǐ hǎo bǎ huà yàn le xià qù","Trước mặt nhiều người như vậy, người đó đành phải nuốt lời lại."],["大家聊得正高兴，她却当着大家的面掉下泪来。","dà jiā liáo de zhèng gāo xìng tā què dāng zhe dà jiā de miàn diào xià lèi lái","Mọi người đang nói chuyện vui vẻ, cô ấy lại rơi nước mắt trước mặt mọi người."],["论坛期间，各国专家就共同感兴趣的专题进行了探讨和交流。","lùn tán qī jiān gè guó zhuān jiā jiù gòng tóng gǎn xìng qù de zhuān tí jìn xíng le tàn tǎo hé jiāo liú","Trong thời gian diễn đàn, các chuyên gia các nước đã thảo luận và trao đổi về những chủ đề cùng quan tâm."],["就离婚后的财产分割问题，双方产生了激烈的争论。","jiù lí hūn hòu de cái chǎn fēn gē wèn tí shuāng fāng chǎn shēng le jī liè de zhēng lùn","Về vấn đề phân chia tài sản sau ly hôn, hai bên đã tranh cãi gay gắt."]]},{"n":21,"c":["词类","介词","引出凭借、依据"],"z":"本着、基于、鉴于¹、经、依","t":"Giới từ 本着, 基于, 鉴于, 经, 依","d":"本着 = trên tinh thần, theo (nguyên tắc); 基于 = dựa trên; 鉴于 = xét thấy, căn cứ vào; 经 = qua, thông qua (quá trình); 依 = theo (依我看 = theo tôi thấy).","e":[["我们本着“友谊第一，比赛第二”的精神，充分享受比赛的乐趣。","wǒ men běn zhe yǒu yì dì yī bǐ sài dì èr de jīng shén chōng fèn xiǎng shòu bǐ sài de lè qù","Chúng tôi trên tinh thần \"hữu nghị là chính, thi đấu là phụ\", tận hưởng trọn vẹn niềm vui thi đấu."],["虽然我和小孙素日关系更近，但本着实事求是的态度，我还是把票投给了小魏。","suī rán wǒ hé xiǎo sūn sù rì guān xi gèng jìn dàn běn zhe shí shì qiú shì de tài dù wǒ hái shì bǎ piào tóu gěi le xiǎo wèi","Tuy ngày thường tôi thân với Tiểu Tôn hơn, nhưng trên tinh thần thực sự cầu thị, tôi vẫn bỏ phiếu cho Tiểu Ngụy."],["基于调研的结果，我们精准定位了产品的目标市场。","jī yú diào yán de jié guǒ wǒ men jīng zhǔn dìng wèi le chǎn pǐn de mù biāo shì chǎng","Dựa trên kết quả khảo sát, chúng tôi đã định vị chính xác thị trường mục tiêu của sản phẩm."],["这部电影是基于真实事件改编而成的。","zhè bù diàn yǐng shì jī yú zhēn shí shì jiàn gǎi biān ér chéng de","Bộ phim này được chuyển thể dựa trên sự kiện có thật."],["鉴于你在此次项目中的突出表现，公司决定对你予以嘉奖。","jiàn yú nǐ zài cǐ cì xiàng mù zhōng de tū chū biǎo xiàn gōng sī jué dìng duì nǐ yǔ yǐ jiā jiǎng","Xét thấy biểu hiện xuất sắc của anh trong dự án lần này, công ty quyết định khen thưởng anh."],["鉴于市场需求和用户偏好的不断变化，产品设计应适时转变策略，适应市场发展。","jiàn yú shì chǎng xū qiú hé yòng hù piān hǎo de bú duàn biàn huà chǎn pǐn shè jì yìng shì shí zhuǎn biàn cè lüè shì yìng shì chǎng fā zhǎn","Căn cứ vào sự thay đổi không ngừng của nhu cầu thị trường và sở thích người dùng, thiết kế sản phẩm nên kịp thời chuyển đổi chiến lược, thích ứng với sự phát triển của thị trường."],["决议成文程序严格，须经全体会议或代表大会讨论通过才能生效。","jué yì chéng wén chéng xù yán gé xū jīng quán tǐ huì yì huò dài biǎo dà huì tǎo lùn tōng guò cái néng shēng xiào","Thủ tục soạn thảo nghị quyết rất chặt chẽ, phải qua hội nghị toàn thể hoặc đại hội đại biểu thảo luận thông qua mới có hiệu lực."],["经医生细心诊治，哥哥身体状况日渐好转，已经可以自行下床行走了。","jīng yī shēng xì xīn zhěn zhì gē ge shēn tǐ zhuàng kuàng rì jiàn hǎo zhuǎn yǐ jīng kě yǐ zì xíng xià chuáng xíng zǒu le","Qua sự chẩn đoán điều trị tận tình của bác sĩ, sức khỏe anh trai ngày càng tốt lên, đã có thể tự xuống giường đi lại."],["经研究，公司决定把这一重要的新款产品交由你全权负责。","jīng yán jiū gōng sī jué dìng bǎ zhè yì zhòng yào de xīn kuǎn chǎn pǐn jiāo yóu nǐ quán quán fù zé","Qua nghiên cứu, công ty quyết định giao toàn quyền phụ trách sản phẩm mới quan trọng này cho anh."],["一些无良的鉴定专家不依市场价值而是依主观价值评定东西等级的行为，严重扰乱了市场秩序。","yì xiē wú liáng de jiàn dìng zhuān jiā bù yī shì chǎng jià zhí ér shì yī zhǔ guān jià zhí píng dìng dōng xi děng jí de xíng wéi yán zhòng rǎo luàn le shì chǎng zhì xù","Hành vi của một số chuyên gia giám định vô lương tâm không theo giá trị thị trường mà theo giá trị chủ quan để định cấp đồ vật đã làm rối loạn nghiêm trọng trật tự thị trường."],["依我看，你在这件事的处理上有失公允。","yī wǒ kàn nǐ zài zhè jiàn shì de chǔ lǐ shàng yǒu shī gōng yǔn","Theo tôi thấy, anh xử lý việc này có phần thiếu công bằng."]]},{"n":22,"c":["词类","连词","连接分句或句子"],"z":"鉴于²、况且、免得、若、倘若、以防","t":"Liên từ 鉴于, 况且, 免得, 若, 倘若, 以防","d":"鉴于 = xét thấy (đầu câu); 况且 = huống hồ, hơn nữa; 免得 = để khỏi, kẻo; 若/倘若 = nếu (văn viết); 以防 = để phòng, đề phòng.","e":[["鉴于近期设备故障频发，技术部门决定对相关设备进行全面维护。","jiàn yú jìn qī shè bèi gù zhàng pín fā jì shù bù mén jué dìng duì xiāng guān shè bèi jìn xíng quán miàn wéi hù","Xét thấy gần đây thiết bị thường xuyên hỏng hóc, bộ phận kỹ thuật quyết định bảo dưỡng toàn diện các thiết bị liên quan."],["鉴于被告人严某主动上缴违法所得，认罪态度良好，可酌情从轻处罚。","jiàn yú bèi gào rén yán mǒu zhǔ dòng shàng jiǎo wéi fǎ suǒ dé rèn zuì tài dù liáng hǎo kě zhuó qíng cóng qīng chǔ fá","Xét thấy bị cáo Nghiêm chủ động nộp lại số tiền thu lợi bất chính, thái độ nhận tội tốt, có thể cân nhắc xử phạt nhẹ hơn."],["你们的方案非常详细，况且已经得到了业内专家的肯定，相信实施起来不会有什么问题。","nǐ men de fāng àn fēi cháng xiáng xì kuàng qiě yǐ jīng dé dào le yè nèi zhuān jiā de kěn dìng xiāng xìn shí shī qǐ lái bú huì yǒu shén me wèn tí","Phương án của các bạn rất chi tiết, hơn nữa đã được các chuyên gia trong ngành công nhận, tin rằng khi thực hiện sẽ không có vấn đề gì."],["要告别近二十年的舞台生涯，她真的十分不舍，况且，隔行如隔山，不跳舞她又能改行做些什么呢？","yào gào bié jìn èr shí nián de wǔ tái shēng yá tā zhēn de shí fēn bù shě kuàng qiě gé háng rú gé shān bú tiào wǔ tā yòu néng gǎi háng zuò xiē shén me ne","Từ biệt gần hai mươi năm sự nghiệp sân khấu, cô ấy thật sự rất lưu luyến, huống hồ khác nghề như cách núi, không múa nữa thì cô ấy có thể chuyển sang làm gì?"],["有缘无缘不可强求，免得徒增烦恼。","yǒu yuán wú yuán bù kě qiǎng qiú miǎn de tú zēng fán nǎo","Có duyên hay không không thể cưỡng cầu, kẻo chỉ thêm phiền não."],["去往一个陌生的国家或地区，须了解当地的治安环境、文化禁忌，免得招来麻烦。","qù wǎng yí gè mò shēng de guó jiā huò dì qū xū liǎo jiě dāng dì de zhì ān huán jìng wén huà jìn jì miǎn de zhāo lái má fan","Đến một quốc gia hay khu vực xa lạ, cần tìm hiểu tình hình an ninh, những điều cấm kỵ văn hóa ở đó, kẻo chuốc lấy phiền phức."],["事情要是能顺利解决最好，若不行，就得另寻其他门路了。","shì qing yào shi néng shùn lì jiě jué zuì hǎo ruò bù xíng jiù děi lìng xún qí tā mén lù le","Việc này giải quyết suôn sẻ được là tốt nhất, nếu không được thì phải tìm con đường khác."],["若是购买的产品有任何质量问题，消费者可在七天之内无理由退换。","ruò shì gòu mǎi de chǎn pǐn yǒu rèn hé zhì liàng wèn tí xiāo fèi zhě kě zài qī tiān zhī nèi wú lǐ yóu tuì huàn","Nếu sản phẩm mua về có bất kỳ vấn đề chất lượng nào, người tiêu dùng có thể đổi trả không cần lý do trong vòng bảy ngày."],["倘若一开始她就懂得精打细算，日子也不会过得这么捉襟见肘了。","tǎng ruò yì kāi shǐ tā jiù dǒng de jīng dǎ xì suàn rì zi yě bú huì guò de zhè me zhuō jīn jiàn zhǒu le","Nếu ngay từ đầu cô ấy biết tính toán chi li thì cuộc sống cũng không đến nỗi túng thiếu như vậy."],["我现在已经不想再听你说什么豪言壮语了。倘若五年后你能混出点名堂，就当我今日有眼不识泰山。","wǒ xiàn zài yǐ jīng bù xiǎng zài tīng nǐ shuō shén me háo yán zhuàng yǔ le tǎng ruò wǔ nián hòu nǐ néng hùn chū diǎn míng táng jiù dàng wǒ jīn rì yǒu yǎn bù shí tài shān","Bây giờ tôi không muốn nghe anh nói những lời hùng hồn gì nữa. Nếu năm năm sau anh làm nên trò trống gì, thì coi như hôm nay tôi có mắt mà không thấy núi Thái Sơn."],["切莫轻易向陌生人转账汇款，以防上当受骗。","qiè mò qīng yì xiàng mò shēng rén zhuǎn zhàng huì kuǎn yǐ fáng shàng dàng shòu piàn","Chớ dễ dàng chuyển khoản cho người lạ, để đề phòng bị lừa."],["这次安全事故造成的惨烈后果，希望各位引以为戒，以防类似的悲剧再度发生。","zhè cì ān quán shì gù zào chéng de cǎn liè hòu guǒ xī wàng gè wèi yǐn yǐ wéi jiè yǐ fáng lèi sì de bēi jù zài dù fā shēng","Hậu quả thảm khốc do sự cố an toàn lần này gây ra, mong mọi người lấy đó làm bài học, để phòng bi kịch tương tự tái diễn."]]},{"n":23,"c":["词类","连词","连接词或词组以及分句或句子"],"z":"加之、乃至、且","t":"Liên từ 加之, 乃至, 且","d":"加之 = thêm vào đó, cộng thêm; 乃至 = thậm chí, cho đến cả; 且 = và, hơn nữa (văn viết).","e":[["空气湿闷，加之窗外嘈杂不已，使得她彻夜未眠。","kōng qì shī mēn jiā zhī chuāng wài cáo zá bù yǐ shǐ de tā chè yè wèi mián","Không khí ẩm thấp ngột ngạt, thêm vào đó ngoài cửa sổ ồn ào không ngớt, khiến cô ấy thức trắng cả đêm."],["他出众的能力加之丰富的工作经验是他职位迅速晋升的关键所在。","tā chū zhòng de néng lì jiā zhī fēng fù de gōng zuò jīng yàn shì tā zhí wèi xùn sù jìn shēng de guān jiàn suǒ zài","Năng lực xuất chúng cộng thêm kinh nghiệm làm việc phong phú là điểm then chốt giúp anh ấy thăng chức nhanh chóng."],["这件衣服的刺绣工艺异常复杂，单是绣一朵花就需要花费数月乃至一年的时间。","zhè jiàn yī fu de cì xiù gōng yì yì cháng fù zá dān shì xiù yì duǒ huā jiù xū yào huā fèi shù yuè nǎi zhì yì nián de shí jiān","Kỹ thuật thêu của bộ quần áo này phức tạp lạ thường, riêng thêu một bông hoa đã mất mấy tháng thậm chí một năm."],["我被他对文学的热爱和执着深深地打动了，乃至我回去之后还不能平静。","wǒ bèi tā duì wén xué de rè ài hé zhí zhuó shēn shēn de dǎ dòng le nǎi zhì wǒ huí qù zhī hòu hái bù néng píng jìng","Tôi bị tình yêu và sự kiên trì của anh ấy với văn học làm cho cảm động sâu sắc, đến nỗi về rồi mà lòng vẫn chưa thể bình tĩnh."],["受欢迎且传播力强的文章，在选题策划方面一定高出一筹。","shòu huān yíng qiě chuán bō lì qiáng de wén zhāng zài xuǎn tí cè huà fāng miàn yí dìng gāo chū yì chóu","Những bài viết được yêu thích và lan tỏa mạnh, ở khâu chọn đề tài lên ý tưởng nhất định cao tay hơn một bậc."],["醉酒驾车造成他人死亡的驾驶员被当场吊销驾照，且终身不予重新申请。","zuì jiǔ jià chē zào chéng tā rén sǐ wáng de jià shǐ yuán bèi dāng chǎng diào xiāo jià zhào qiě zhōng shēn bù yǔ chóng xīn shēn qǐng","Tài xế say rượu lái xe gây chết người bị tước bằng lái ngay tại chỗ, và cả đời không được xin cấp lại."]]},{"n":24,"c":["词类","助词","语气助词"],"z":"罢了、也罢、矣","t":"Trợ từ ngữ khí 罢了, 也罢, 矣","d":"罢了 = …mà thôi; 也罢 = cũng được, thôi cũng được (A也罢，B也罢 = dù A hay B); 矣 = rồi (văn cổ, giống 了).","e":[["他很谦虚地将自己的成功归结为运气好罢了。","tā hěn qiān xū de jiāng zì jǐ de chéng gōng guī jié wèi yùn qì hǎo bà le","Anh ấy rất khiêm tốn quy thành công của mình cho may mắn mà thôi."],["那些我们一度以为难以承受的挫折，终将会变成人生宝贵的经历，只是时间的问题罢了。","nà xiē wǒ men yí dù yǐ wéi nán yǐ chéng shòu de cuò zhé zhōng jiāng huì biàn chéng rén shēng bǎo guì de jīng lì zhǐ shì shí jiān de wèn tí bà le","Những thất bại mà ta từng nghĩ khó chịu đựng nổi, cuối cùng sẽ trở thành trải nghiệm quý giá của cuộc đời, chỉ là vấn đề thời gian mà thôi."],["这件事你答应也好，不答应也罢，我都铁了心要去做。","zhè jiàn shì nǐ dā ying yě hǎo bù dā ying yě bà wǒ dōu tiě le xīn yào qù zuò","Việc này anh đồng ý cũng được, không đồng ý cũng xong, tôi đều quyết tâm làm."],["那些为迎合市场而推出的快餐读物，不看也罢。","nà xiē wèi yíng hé shì chǎng ér tuī chū de kuài cān dú wù bú kàn yě bà","Những ấn phẩm ăn liền tung ra để chiều theo thị trường, không đọc cũng được."],["朋友在精不在多，人生得一知己足矣。","péng you zài jīng bú zài duō rén shēng de yì zhī jǐ zú yǐ","Bạn quý ở chất chứ không ở lượng, đời người có được một tri kỷ là đủ rồi."],["作为一个摄影爱好者，我对这位国际知名的摄影大师仰慕久矣。","zuò wéi yí gè shè yǐng ài hào zhě wǒ duì zhè wèi guó jì zhī míng de shè yǐng dà shī yǎng mù jiǔ yǐ","Là người yêu nhiếp ảnh, tôi đã ngưỡng mộ bậc thầy nhiếp ảnh nổi tiếng quốc tế này từ lâu rồi."]]},{"n":25,"c":["短语","固定短语","四字格"],"z":"爱A不A","t":"Cấu trúc bốn chữ 爱A不A","d":"= …thì…, không thì thôi (thái độ thờ ơ, mặc kệ): 爱买不买 = mua thì mua không thì thôi.","e":[["团购的产品价格十分优惠，可商家对待使用团购券的客人却很不热情，总摆出一副爱吃不吃、爱住不住、爱买不买的姿态。","tuán gòu de chǎn pǐn jià gé shí fēn yōu huì kě shāng jiā duì dài shǐ yòng tuán gòu quàn de kè rén què hěn bú rè qíng zǒng bǎi chū yí fù ài chī bu chī ài zhù bu zhù ài mǎi bu mǎi de zī tài","Giá sản phẩm mua theo nhóm rất ưu đãi, nhưng người bán lại rất lạnh nhạt với khách dùng phiếu mua nhóm, luôn tỏ thái độ ăn thì ăn không ăn thì thôi, ở thì ở không ở thì thôi, mua thì mua không mua thì thôi."],["他这个人干什么都我行我素，穿衣打扮更是特立独行，一副“你爱看不看，反正我的事你管不着”的态度。","tā zhè ge rén gàn shén me dōu wǒ xíng wǒ sù chuān yī dǎ ban gèng shì tè lì dú xíng yí fù nǐ ài kàn bu kàn fǎn zhèng wǒ de shì nǐ guǎn bu zháo de tài dù","Anh ta làm gì cũng theo ý mình, ăn mặc lại càng khác người, một thái độ \"anh thích nhìn thì nhìn, không thì thôi, việc của tôi anh không quản được\"."]]},{"n":26,"c":["短语","固定短语","四字格"],"z":"半A半B","t":"Cấu trúc bốn chữ 半A半B","d":"= nửa…nửa…: 半睡半醒 = nửa tỉnh nửa mê; 半真半假 = nửa thật nửa giả.","e":[["我这两天工作压力比较大，晚上一直半睡半醒，第二天精神很差。","wǒ zhè liǎng tiān gōng zuò yā lì bǐ jiào dà wǎn shang yì zhí bàn shuì bàn xǐng dì èr tiān jīng shén hěn chà","Mấy hôm nay áp lực công việc khá lớn, buổi tối tôi cứ nửa tỉnh nửa mê, hôm sau tinh thần rất kém."],["他提供的信息半真半假，我们不能完全信任他。","tā tí gōng de xìn xī bàn zhēn bàn jiǎ wǒ men bù néng wán quán xìn rèn tā","Thông tin anh ta cung cấp nửa thật nửa giả, chúng ta không thể hoàn toàn tin anh ta."]]},{"n":27,"c":["短语","固定短语","四字格"],"z":"不A不B","t":"Cấu trúc bốn chữ 不A不B","d":"① A, B trái nghĩa: vừa phải (不好不坏 = không tốt không xấu); ② A, B gần nghĩa: hoàn toàn không (不吃不喝 = không ăn không uống).","e":[["我开服装店到今天正好一个月，生意不好不坏。","wǒ kāi fú zhuāng diàn dào jīn tiān zhèng hǎo yí gè yuè shēng yì bù hǎo bú huài","Tôi mở cửa hàng quần áo đến hôm nay vừa đúng một tháng, làm ăn không tốt cũng không tệ."],["1000万，对绝大多数人来说是一个天文数字。如果一个人年入10万，他需要不吃不喝100年才能攒够1000万。","wàn duì jué dà duō shù rén lái shuō shì yí gè tiān wén shù zì rú guǒ yí gè rén nián rù wàn tā xū yào bù chī bù hē nián cái néng zǎn gòu wàn","10 triệu tệ với đại đa số mọi người là một con số thiên văn. Nếu một người thu nhập 100 nghìn một năm, người đó phải nhịn ăn nhịn uống 100 năm mới dành dụm đủ 10 triệu."]]},{"n":28,"c":["短语","固定短语","四字格"],"z":"不A而B","t":"Cấu trúc bốn chữ 不A而B","d":"= không…mà (vẫn)…: 不辞而别 = không từ biệt mà đi; 不治而愈 = không chữa mà khỏi.","e":[["这名教授在职称晋升后，不顾尚未履行完毕的人事合同，连招呼都不打，直接不辞而别。","zhè míng jiào shòu zài zhí chēng jìn shēng hòu bú gù shàng wèi lǚ xíng wán bì de rén shì hé tong lián zhāo hu dōu bù dǎ zhí jiē bù cí ér bié","Vị giáo sư này sau khi được thăng chức danh, bất chấp hợp đồng nhân sự chưa thực hiện xong, đến chào hỏi cũng không, cứ thế bỏ đi không một lời từ biệt."],["有研究表明，长期坚持有氧运动的人心肺功能会得到明显提升，一些疾病也会不治而愈。","yǒu yán jiū biǎo míng cháng qī jiān chí yǒu yǎng yùn dòng de rén xīn fèi gōng néng huì dé dào míng xiǎn tí shēng yì xiē jí bìng yě huì bú zhì ér yù","Có nghiên cứu cho thấy, người kiên trì tập aerobic lâu dài thì chức năng tim phổi được cải thiện rõ rệt, một số bệnh còn không chữa mà khỏi."]]},{"n":29,"c":["短语","固定短语","四字格"],"z":"东A西B","t":"Cấu trúc bốn chữ 东A西B","d":"= …chỗ này…chỗ kia, khắp nơi: 东奔西走 = chạy đông chạy tây; 东拼西凑 = chắp vá chỗ này chỗ kia (gom góp).","e":[["这几个月我不停地东奔西走，几乎参访了集团下面所有的分公司，足以说明我一直关注集团的发展。","zhè jǐ gè yuè wǒ bù tíng de dōng bēn xī zǒu jī hū cān fǎng le jí tuán xià miàn suǒ yǒu de fēn gōng sī zú yǐ shuō míng wǒ yì zhí guān zhù jí tuán de fā zhǎn","Mấy tháng nay tôi không ngừng bôn ba khắp nơi, gần như đã đi thăm tất cả các công ty con của tập đoàn, đủ chứng tỏ tôi luôn quan tâm đến sự phát triển của tập đoàn."],["她东拼西凑了万多元钱，但是离治病所需的高额费用还是远远不够的。","tā dōng pīn xī còu le wàn duō yuán qián dàn shì lí zhì bìng suǒ xū de gāo é fèi yòng hái shì yuǎn yuǎn bú gòu de","Cô ấy chạy vạy gom góp được hơn 30 nghìn tệ, nhưng vẫn còn xa mới đủ chi phí chữa bệnh khổng lồ."]]},{"n":30,"c":["短语","固定短语","四字格"],"z":"非A非B","t":"Cấu trúc bốn chữ 非A非B","d":"= chẳng phải…cũng chẳng phải…: 非亲非故 = chẳng họ hàng chẳng quen biết; 非真非假 = chẳng thật chẳng giả.","e":[["我跟他非亲非故，但是他却为了我的事四处奔波，感动得我不知说什么好。","wǒ gēn tā fēi qīn fēi gù dàn shì tā què wèi le wǒ de shì sì chù bēn bō gǎn dòng de wǒ bù zhī shuō shén me hǎo","Tôi và anh ấy chẳng họ hàng chẳng quen biết, nhưng anh ấy lại vì việc của tôi mà chạy ngược chạy xuôi, làm tôi cảm động không biết nói gì."],["这些非真非假的传说故事，吊足了一众游客的胃口，也给第二天的行程增添了几分神秘色彩。","zhè xiē fēi zhēn fēi jiǎ de chuán shuō gù shì diào zú le yí zhòng yóu kè de wèi kǒu yě gěi dì èr tiān de xíng chéng zēng tiān le jǐ fēn shén mì sè cǎi","Những truyền thuyết thực hư lẫn lộn này đã khơi dậy sự tò mò của đông đảo du khách, cũng thêm vài phần màu sắc huyền bí cho hành trình ngày hôm sau."]]},{"n":31,"c":["短语","固定短语","四字格"],"z":"忽A忽B","t":"Cấu trúc bốn chữ 忽A忽B","d":"= lúc…lúc… (thay đổi nhanh, liên tục): 忽上忽下 = lúc lên lúc xuống; 忽隐忽现 = lúc ẩn lúc hiện.","e":[["那条盘山公路很险，一个接一个的急转弯。汽车开着像是扭秧歌，忽上忽下，忽左忽右。","nà tiáo pán shān gōng lù hěn xiǎn yí gè jiē yí gè de jí zhuǎn wān qì chē kāi zhe xiàng shì niǔ yāng gē hū shàng hū xià hū zuǒ hū yòu","Con đường đèo đó rất hiểm trở, khúc cua gấp nối tiếp nhau. Ô tô chạy như múa ương ca, lúc lên lúc xuống, lúc trái lúc phải."],["羊群在草丛中忽隐忽现。一只细长的牧羊犬忙不迭地穿梭其中。","yáng qún zài cǎo cóng zhōng hū yǐn hū xiàn yì zhī xì cháng de mù yáng quǎn máng bù dié de chuān suō qí zhōng","Đàn cừu lúc ẩn lúc hiện trong đám cỏ. Một con chó chăn cừu thon dài tất bật chạy qua chạy lại giữa đàn."]]},{"n":32,"c":["短语","固定短语","四字格"],"z":"或A或B","t":"Cấu trúc bốn chữ 或A或B","d":"= hoặc…hoặc…, người thì…người thì…: 或坐或立 = người ngồi người đứng.","e":[["酒吧里的客人手里端着酒杯，或坐或立，姿态各异。","jiǔ bā lǐ de kè rén shǒu lǐ duān zhe jiǔ bēi huò zuò huò lì zī tài gè yì","Khách trong quán bar tay cầm ly rượu, người ngồi người đứng, mỗi người một tư thế."],["夜深了，可她或躺或坐，一直难以入睡。她生平第一次有这种牵肠挂肚的感觉。","yè shēn le kě tā huò tǎng huò zuò yì zhí nán yǐ rù shuì tā shēng píng dì yī cì yǒu zhè zhǒng qiān cháng guà dù de gǎn jué","Đêm đã khuya, cô ấy lúc nằm lúc ngồi, mãi không ngủ được. Lần đầu tiên trong đời cô có cảm giác bồn chồn lo lắng như thế."],["她做的豆腐，或炖或炒，总是色白味醇。乡亲们头一次吃到这么好的豆腐，都夸她手艺好。","tā zuò de dòu fu huò dùn huò chǎo zǒng shì sè bái wèi chún xiāng qīn men tóu yí cì chī dào zhè me hǎo de dòu fu dōu kuā tā shǒu yì hǎo","Đậu phụ cô ấy làm, dù hầm hay xào, đều trắng và vị đậm đà. Bà con lần đầu được ăn đậu phụ ngon như vậy, ai cũng khen cô khéo tay."]]},{"n":33,"c":["短语","固定短语","四字格"],"z":"可A可B","t":"Cấu trúc bốn chữ 可A可B","d":"= có thể…cũng có thể… / vừa…vừa…: 可长可短 = dài ngắn đều được; 可敬可亲 = vừa đáng kính vừa đáng mến.","e":[["小婉对这位天才同事，没有半点嫉妒，而是一开始就由衷地欣赏她，并真心地关爱她，完全像一位可敬可亲大姐姐。","xiǎo wǎn duì zhè wèi tiān cái tóng shì méi yǒu bàn diǎn jí dù ér shì yì kāi shǐ jiù yóu zhōng de xīn shǎng tā bìng zhēn xīn de guān ài tā wán quán xiàng yí wèi kě jìng kě qīn dà jiě jie","Tiểu Uyển không chút đố kỵ với cô đồng nghiệp thiên tài này, mà ngay từ đầu đã thật lòng ngưỡng mộ và quan tâm cô ấy, hoàn toàn như một người chị vừa đáng kính vừa thân thương."],["读书笔记要精炼，要根据实际的阅读进度，总结概括，并体现所思所想。篇幅可长可短，决不写空话、假话、应付的话。","dú shū bǐ jì yào jīng liàn yào gēn jù shí jì de yuè dú jìn dù zǒng jié gài kuò bìng tǐ xiàn suǒ sī suǒ xiǎng piān fú kě cháng kě duǎn jué bù xiě kōng huà jiǎ huà yìng fù de huà","Ghi chép đọc sách phải cô đọng, tổng kết khái quát theo tiến độ đọc thực tế, và thể hiện điều mình suy nghĩ. Độ dài ngắn đều được, tuyệt đối không viết lời sáo rỗng, giả dối, đối phó."]]},{"n":34,"c":["短语","固定短语","四字格"],"z":"连A带B","t":"Cấu trúc bốn chữ 连A带B","d":"= vừa…vừa… (连说带笑 = vừa nói vừa cười) / cả…lẫn… (连人带车 = cả người lẫn xe).","e":[["一群年轻人连说带笑地迎面走来，整个街道顿时充满了欢声笑语。","yì qún nián qīng rén lián shuō dài xiào de yíng miàn zǒu lái zhěng gè jiē dào dùn shí chōng mǎn le huān shēng xiào yǔ","Một nhóm thanh niên vừa nói vừa cười đi tới, cả con phố bỗng tràn ngập tiếng cười nói."],["昨晚有人在江边骑行，结果连人带车落入江中，至今生死不明。","zuó wǎn yǒu rén zài jiāng biān qí xíng jié guǒ lián rén dài chē luò rù jiāng zhōng zhì jīn shēng sǐ bù míng","Tối qua có người đạp xe ven sông, kết quả cả người lẫn xe rơi xuống sông, đến nay vẫn chưa rõ sống chết."]]},{"n":35,"c":["短语","固定短语","四字格"],"z":"七A八B","t":"Cấu trúc bốn chữ 七A八B","d":"= lộn xộn, nhiều và rối: 七拐八绕 = rẽ ngang rẽ dọc; 七零八落 = tan tác, tơi tả.","e":[["司机对这里的道路不太熟悉，竟七拐八绕地把车开到了海边，现在陷在烂泥里出不来了。","sī jī duì zhè lǐ de dào lù bú tài shú xī jìng qī guǎi bā rào de bǎ chē kāi dào le hǎi biān xiàn zài xiàn zài làn ní lǐ chū bù lái le","Tài xế không quen đường ở đây, vậy mà rẽ ngang rẽ dọc lái xe ra tận bờ biển, giờ bị sa lầy trong bùn không ra được."],["乐乐是个十足的捣蛋鬼，常常把家里的玩具拆得七零八落的，用画笔把墙上涂得乱七八糟。","lè lè shì gè shí zú de dǎo dàn guǐ cháng cháng bǎ jiā lǐ de wán jù chāi de qī líng bā luò de yòng huà bǐ bǎ qiáng shàng tú de luàn qī bā zāo","Lạc Lạc là đứa nghịch ngợm chính hiệu, thường tháo đồ chơi trong nhà ra tơi tả, lấy bút vẽ bôi lên tường lung tung."]]},{"n":36,"c":["短语","固定短语","四字格"],"z":"时A时B","t":"Cấu trúc bốn chữ 时A时B","d":"= lúc…lúc…: 时好时坏 = lúc tốt lúc xấu; 时隐时现 = lúc ẩn lúc hiện.","e":[["他最近身体时好时坏，但只要他还撑得住，他一定会来参加我们的婚礼的。","tā zuì jìn shēn tǐ shí hǎo shí huài dàn zhǐ yào tā hái chēng de zhù tā yí dìng huì lái cān jiā wǒ men de hūn lǐ de","Dạo này sức khỏe ông ấy lúc tốt lúc xấu, nhưng chỉ cần còn gắng gượng được, ông nhất định sẽ đến dự đám cưới của chúng tôi."],["雨停了，天上的云渐渐散了，天边有道彩虹时隐时现。","yǔ tíng le tiān shàng de yún jiàn jiàn sàn le tiān biān yǒu dào cǎi hóng shí yǐn shí xiàn","Mưa tạnh, mây trên trời dần tan, phía chân trời có một cầu vồng lúc ẩn lúc hiện."]]},{"n":37,"c":["短语","固定短语","四字格"],"z":"无A不B","t":"Cấu trúc bốn chữ 无A不B","d":"Phủ định kép = khẳng định tuyệt đối: 无话不谈 = chuyện gì cũng nói; 无人不知 = không ai không biết.","e":[["短短几天，我们就成了无话不谈的好友，一想到就要分开了，不免觉得伤感。","duǎn duǎn jǐ tiān wǒ men jiù chéng le wú huà bù tán de hǎo yǒu yì xiǎng dào jiù yào fēn kāi le bù miǎn jué de shāng gǎn","Chỉ trong vài ngày ngắn ngủi, chúng tôi đã trở thành bạn thân chuyện gì cũng kể cho nhau, nghĩ đến sắp phải chia tay, không khỏi thấy buồn."],["这所无人不知的重点初中的家长可谓卧虎藏龙，基本上都是知名学者、政府高官、企业高管等有着较高社会地位的人。","zhè suǒ wú rén bù zhī de zhòng diǎn chū zhōng de jiā zhǎng kě wèi wò hǔ cáng lóng jī běn shàng dōu shì zhī míng xué zhě zhèng fǔ gāo guān qǐ yè gāo guǎn děng yǒu zhe jiào gāo shè huì dì wèi de rén","Phụ huynh của trường cấp hai trọng điểm ai cũng biết này có thể nói là ngọa hổ tàng long, hầu hết đều là học giả nổi tiếng, quan chức cao cấp, lãnh đạo doanh nghiệp… có địa vị xã hội cao."]]},{"n":38,"c":["短语","固定短语","四字格"],"z":"无A可B","t":"Cấu trúc bốn chữ 无A可B","d":"= không có…để…: 无处可去 = không có chỗ nào để đi; 无事可做 = không có việc gì để làm.","e":[["工作地点离城里很远，休息时无处可去，他只得靠钓鱼聊以解闷。","gōng zuò dì diǎn lí chéng lǐ hěn yuǎn xiū xi shí wú chù kě qù tā zhǐ de kào diào yú liáo yǐ jiě mèn","Nơi làm việc cách thành phố rất xa, lúc nghỉ không có chỗ nào để đi, anh ấy đành câu cá cho đỡ buồn."],["到了淡季，公司业务很少，大部员工无事可做，只能拿底薪。","dào le dàn jì gōng sī yè wù hěn shǎo dà bù yuán gōng wú shì kě zuò zhǐ néng ná dǐ xīn","Đến mùa thấp điểm, công ty rất ít việc, phần lớn nhân viên không có việc gì làm, chỉ có thể lĩnh lương cơ bản."]]},{"n":39,"c":["短语","固定短语","四字格"],"z":"自A自B","t":"Cấu trúc bốn chữ 自A自B","d":"= tự…tự… (một mình làm cả): 自编自导 = tự viết kịch bản tự đạo diễn; 自称自赞 = tự khen mình.","e":[["这位导演，早年在外国留过学，编剧功底了得，今天这戏，就是他自编自导的。","zhè wèi dǎo yǎn zǎo nián zài wài guó liú guò xué biān jù gōng dǐ liǎo de jīn tiān zhè xì jiù shì tā zì biān zì dǎo de","Vị đạo diễn này hồi trẻ từng du học nước ngoài, viết kịch bản rất giỏi, vở kịch hôm nay chính là do ông ấy tự viết tự đạo diễn."],["他开心极了，直夸我干得好，并自称自赞，说自己眼光独到。","tā kāi xīn jí le zhí kuā wǒ gàn de hǎo bìng zì chēng zì zàn shuō zì jǐ yǎn guāng dú dào","Ông ấy vui cực kỳ, khen tôi làm tốt mãi, rồi lại tự khen mình, nói mình có con mắt tinh tường."]]},{"n":40,"c":["短语","固定短语","其他（话语标记）"],"z":"不瞒你说","t":"Từ đánh dấu diễn ngôn 不瞒你说","d":"= Nói thật với bạn, không giấu gì bạn.","e":[["你这一番言论真令我醍醐灌顶，不瞒你说，我虽虚长你几岁，见解却远不如你。","nǐ zhè yì fān yán lùn zhēn lìng wǒ tí hú guàn dǐng bù mán nǐ shuō wǒ suī xū zhǎng nǐ jǐ suì jiàn jiě què yuǎn bù rú nǐ","Những lời của bạn khiến tôi bừng tỉnh, nói thật với bạn, tôi tuy lớn hơn bạn vài tuổi nhưng hiểu biết lại kém xa bạn."],["老刘，不瞒你说，那次去你家吃饭，我到得早，你不在屋子里，桌上放着白菜炖五花肉，我就恨不得先吃两块解解馋。","lǎo liú bù mán nǐ shuō nà cì qù nǐ jiā chī fàn wǒ dào de zǎo nǐ bú zài wū zi lǐ zhuō shàng fàng zhe bái cài dùn wǔ huā ròu wǒ jiù hèn bù de xiān chī liǎng kuài jiě jiě chán","Lão Lưu này, nói thật với anh, lần đến nhà anh ăn cơm ấy, tôi đến sớm, anh không có trong nhà, trên bàn để món cải thảo hầm thịt ba chỉ, tôi chỉ mong được ăn trước hai miếng cho đỡ thèm."]]},{"n":41,"c":["短语","固定短语","其他（话语标记）"],"z":"不是","t":"Từ đánh dấu diễn ngôn 不是","d":"不是，… ở đầu câu trả lời = Không phải chứ, khoan đã… (phản bác, ngạc nhiên).","e":[["你们俩有话好好说，别斤斤计较，各自让一步，这事儿不就过去了？","nǐ men liǎ yǒu huà hǎo hǎo shuō bié jīn jīn jì jiào gè zì ràng yí bù zhè shì r bú jiù guò qù le","Hai người có gì từ từ nói, đừng tính toán chi li, mỗi người nhường một bước, chuyện này chẳng phải qua rồi sao?"],["——不是，我俩吵架你瞎掺和什么？","bú shì wǒ liǎ chǎo jià nǐ xiā chān huo shén me","— Không phải chứ, bọn tôi cãi nhau thì anh xen vào làm gì?"],["我们现在去吃自助餐怎么样？","wǒ men xiàn zài qù chī zì zhù cān zěn me yàng","Bây giờ chúng ta đi ăn buffet thế nào?"],["——不是，你下午两点才吃过饭，现在还不到三个小时，这么快就又饿了？","bú shì nǐ xià wǔ liǎng diǎn cái chī guò fàn xiàn zài hái bú dào sān gè xiǎo shí zhè me kuài jiù yòu è le","— Khoan đã, hai giờ chiều cậu mới ăn, giờ còn chưa đến ba tiếng, sao đói nhanh thế?"]]},{"n":42,"c":["短语","固定短语","其他（话语标记）"],"z":"不是我说你","t":"Từ đánh dấu diễn ngôn 不是我说你","d":"= Không phải tôi trách bạn đâu, nhưng… (mở đầu lời phê bình thẳng thắn).","e":[["不是我说你，你真是一点儿事都不懂。你既然求他帮忙，为什么姿态不放低点儿？","bú shì wǒ shuō nǐ nǐ zhēn shì yì diǎn r shì dōu bù dǒng nǐ jì rán qiú tā bāng máng wèi shén me zī tài bú fàng dī diǎn r","Không phải tôi nói bạn đâu, bạn thật chẳng hiểu chuyện gì cả. Đã nhờ anh ấy giúp thì sao không hạ mình xuống một chút?"],["哥们儿，不是我说你，你还是社会经验不够啊。这件事搞成这样，说明你和上司的关系实在不怎么样。","gē men r bú shì wǒ shuō nǐ nǐ hái shì shè huì jīng yàn bú gòu a zhè jiàn shì gǎo chéng zhè yàng shuō míng nǐ hé shàng sī de guān xi shí zài bù zěn me yàng","Người anh em này, không phải tôi trách cậu, cậu vẫn còn thiếu kinh nghiệm xã hội lắm. Việc này ra nông nỗi này chứng tỏ quan hệ giữa cậu và cấp trên thật chẳng ra sao."]]},{"n":43,"c":["短语","固定短语","其他（话语标记）"],"z":"反过来（说）","t":"Từ đánh dấu diễn ngôn 反过来(说)","d":"= Ngược lại (mà nói).","e":[["人的素质是人进行社会实践的产物，反过来，人的素质同样也会影响社会实践。","rén de sù zhì shì rén jìn xíng shè huì shí jiàn de chǎn wù fǎn guò lái rén de sù zhì tóng yàng yě huì yǐng xiǎng shè huì shí jiàn","Tố chất con người là sản phẩm của thực tiễn xã hội, ngược lại, tố chất con người cũng ảnh hưởng đến thực tiễn xã hội."],["一个国家的教育发展水平取决于其经济、政治的发展程度；反过来说，它的经济和政治的发展程度，同样受到教育发展水平的深刻影响。","yí gè guó jiā de jiào yù fā zhǎn shuǐ píng qǔ jué yú qí jīng jì zhèng zhì de fā zhǎn chéng dù fǎn guò lái shuō tā de jīng jì hé zhèng zhì de fā zhǎn chéng dù tóng yàng shòu dào jiào yù fā zhǎn shuǐ píng de shēn kè yǐng xiǎng","Trình độ phát triển giáo dục của một quốc gia phụ thuộc vào mức độ phát triển kinh tế, chính trị; ngược lại, mức độ phát triển kinh tế và chính trị cũng chịu ảnh hưởng sâu sắc từ trình độ phát triển giáo dục."]]},{"n":44,"c":["短语","固定短语","其他（话语标记）"],"z":"概括来说","t":"Từ đánh dấu diễn ngôn 概括来说","d":"= Nói một cách khái quát, tóm lại.","e":[["我看过陈刚写的诗，概括来说，给我留下了这样两点印象：第一，他的诗可谓大气磅礴；第二，他古典诗词方面的修养非常高。","wǒ kàn guò chén gāng xiě de shī gài kuò lái shuō gěi wǒ liú xià le zhè yàng liǎng diǎn yìn xiàng dì yī tā de shī kě wèi dà qì páng bó dì èr tā gǔ diǎn shī cí fāng miàn de xiū yǎng fēi cháng gāo","Tôi đã đọc thơ Trần Cương viết, nói khái quát, để lại cho tôi hai ấn tượng: thứ nhất, thơ anh ấy có thể nói là khí thế hào hùng; thứ hai, anh ấy có tu dưỡng rất cao về thơ từ cổ điển."],["《体育课程标准》为体育课堂提供了课程评价的相关要求。概括来说，相关要求涵盖对学生的学习、教师的教学和课程的建设等多个方面。","tǐ yù kè chéng biāo zhǔn wèi tǐ yù kè táng tí gōng le kè chéng píng jià de xiāng guān yāo qiú gài kuò lái shuō xiāng guān yāo qiú hán gài duì xué shēng de xué xí jiào shī de jiào xué hé kè chéng de jiàn shè děng duō gè fāng miàn","\"Tiêu chuẩn chương trình thể dục\" đưa ra các yêu cầu đánh giá chương trình cho giờ học thể dục. Nói khái quát, các yêu cầu bao gồm nhiều mặt như việc học của học sinh, việc dạy của giáo viên và xây dựng chương trình."]]},{"n":45,"c":["短语","固定短语","其他（话语标记）"],"z":"归根到底","t":"Từ đánh dấu diễn ngôn 归根到底","d":"= Suy cho cùng, nói cho cùng.","e":[["我所做的一切，归根到底，不还是为了你吗？","wǒ suǒ zuò de yí qiè guī gēn dào dǐ bù hái shì wèi le nǐ ma","Tất cả những gì tôi làm, suy cho cùng, chẳng phải đều vì em sao?"],["企业竞争，是技术、产品的竞争，归根到底是人才的竞争。","qǐ yè jìng zhēng shì jì shù chǎn pǐn de jìng zhēng guī gēn dào dǐ shì rén cái de jìng zhēng","Cạnh tranh doanh nghiệp là cạnh tranh về công nghệ, sản phẩm, suy cho cùng là cạnh tranh về nhân tài."]]},{"n":46,"c":["短语","固定短语","其他（话语标记）"],"z":"话是这么说","t":"Từ đánh dấu diễn ngôn 话是这么说","d":"= Nói thì nói vậy (nhưng…).","e":[["他问同事怕不怕，他们总是说：“这有什么好怕的？”话是这么说，但他依然有些恐惧。但怕也没有用，因为活是要干的，你怕不怕都得干！","tā wèn tóng shì pà bu pà tā men zǒng shì shuō zhè yǒu shén me hǎo pà de huà shì zhè me shuō dàn tā yī rán yǒu xiē kǒng jù dàn pà yě méi yǒu yòng yīn wèi huó shì yào gàn de nǐ pà bu pà dōu děi gàn","Anh ấy hỏi đồng nghiệp có sợ không, họ luôn nói: \"Có gì mà sợ?\" Nói thì nói vậy, nhưng anh ấy vẫn hơi sợ. Nhưng sợ cũng vô ích, vì việc thì vẫn phải làm, sợ hay không cũng phải làm!"],["如果一个人的事业能够被社会所认可，那么这种感受是超越物质的。话是这么说，但谁不想拥有好的物质条件呢？","rú guǒ yí gè rén de shì yè néng gòu bèi shè huì suǒ rèn kě nà me zhè zhǒng gǎn shòu shì chāo yuè wù zhì de huà shì zhè me shuō dàn shuí bù xiǎng yōng yǒu hǎo de wù zhì tiáo jiàn ne","Nếu sự nghiệp của một người được xã hội công nhận, thì cảm giác ấy vượt lên trên vật chất. Nói thì nói vậy, nhưng ai mà không muốn có điều kiện vật chất tốt chứ?"]]},{"n":47,"c":["短语","固定短语","其他（话语标记）"],"z":"话（又）说回来","t":"Từ đánh dấu diễn ngôn 话(又)说回来","d":"= Nhưng nói đi cũng phải nói lại.","e":[["现在很多公交车驾驶座旁安装了包围门，保证司机专注开车。话说回来，司机安全驾驶，乘客才能安全到站。","xiàn zài hěn duō gōng jiāo chē jià shǐ zuò páng ān zhuāng le bāo wéi mén bǎo zhèng sī jī zhuān zhù kāi chē huà shuō huí lái sī jī ān quán jià shǐ chéng kè cái néng ān quán dào zhàn","Hiện nay nhiều xe buýt lắp cửa bảo vệ cạnh ghế lái để tài xế tập trung lái xe. Nói đi cũng phải nói lại, tài xế lái xe an toàn thì hành khách mới đến nơi an toàn."],["我一定得去问问，她这本书是在哪淘来的？不过话又说回来了，打听出来了又怎么样？反正已经被她买走了。","wǒ yí dìng de qù wèn wèn tā zhè běn shū shì zài nǎ táo lái de bú guò huà yòu shuō huí lái le dǎ tīng chū lái le yòu zěn me yàng fǎn zhèng yǐ jīng bèi tā mǎi zǒu le","Tôi nhất định phải đi hỏi xem cuốn sách này cô ấy săn được ở đâu? Nhưng nói đi cũng phải nói lại, hỏi ra rồi thì sao? Đằng nào cũng bị cô ấy mua mất rồi."]]},{"n":48,"c":["短语","固定短语","其他（话语标记）"],"z":"换句话说","t":"Từ đánh dấu diễn ngôn 换句话说","d":"= Nói cách khác.","e":[["喀什绝大多数人口是维吾尔族，汉族仅占10%。换句话说，10个人里只有一个是汉族人。","kā shí jué dà duō shù rén kǒu shì wéi wú ěr zú hàn zú jǐn zhàn huàn jù huà shuō gè rén lǐ zhǐ yǒu yí gè shì hàn zú rén","Đại đa số dân số Kashgar là người Duy Ngô Nhĩ, người Hán chỉ chiếm 10%. Nói cách khác, 10 người thì chỉ có một người Hán."],["读书固然范围要广博，但是也要有所选择，不能什么都读。换句话说，不仅要多读书，还要读好书。","dú shū gù rán fàn wéi yào guǎng bó dàn shì yě yào yǒu suǒ xuǎn zé bù néng shén me dōu dú huàn jù huà shuō bù jǐn yào duō dú shū hái yào dú hǎo shū","Đọc sách tất nhiên phải rộng, nhưng cũng phải có chọn lọc, không thể cái gì cũng đọc. Nói cách khác, không chỉ phải đọc nhiều mà còn phải đọc sách hay."]]},{"n":49,"c":["短语","固定短语","其他（话语标记）"],"z":"简（而）言之","t":"Từ đánh dấu diễn ngôn 简(而)言之","d":"= Nói ngắn gọn, tóm lại.","e":[["你要问我过年的感受，简言之：热热闹闹、忙忙碌碌、吃吃喝喝、嘻嘻哈哈罢了。","nǐ yào wèn wǒ guò nián de gǎn shòu jiǎn yán zhī rè rè nao nào máng máng lù lù chī chī hē hē xī xī hā hā bà le","Bạn hỏi tôi cảm nhận về Tết à, nói ngắn gọn thì: nhộn nhịp, bận rộn, ăn uống, cười đùa mà thôi."],["电影艺术的教育作用，在于将人物的境遇、所作的斗争以及内心活动、思想感情传递给观众并为其所理解，从而激起共情。简而言之，就是能否动之以情。","diàn yǐng yì shù de jiào yù zuò yòng zài yú jiāng rén wù de jìng yù suǒ zuò de dòu zhēng yǐ jí nèi xīn huó dòng sī xiǎng gǎn qíng chuán dì gěi guān zhòng bìng wéi qí suǒ lǐ jiě cóng ér jī qǐ gòng qíng jiǎn ér yán zhī jiù shì néng fǒu dòng zhī yǐ qíng","Tác dụng giáo dục của nghệ thuật điện ảnh nằm ở chỗ truyền tải hoàn cảnh, cuộc đấu tranh cùng diễn biến nội tâm, tư tưởng tình cảm của nhân vật đến khán giả và được họ thấu hiểu, từ đó khơi dậy sự đồng cảm. Nói ngắn gọn, là có lay động được lòng người hay không."]]},{"n":50,"c":["短语","固定短语","其他（话语标记）"],"z":"可不（是嘛）","t":"Từ đánh dấu diễn ngôn 可不(是嘛)","d":"= Chứ còn gì nữa! Đúng thế! (đồng tình mạnh, khẩu ngữ).","e":[["“北京的雪总是静悄悄地飘下来，不会有一点声音。只有第二天早上睡醒了去开门，才知道昨天晚上下雪了。”一个道地的北京口音回应说：“可不，北京连雪也文明。”","běi jīng de xuě zǒng shì jìng qiāo qiāo de piāo xià lái bú huì yǒu yì diǎn shēng yīn zhǐ yǒu dì èr tiān zǎo shang shuì xǐng le qù kāi mén cái zhī dao zuó tiān wǎn shang xià xuě le yí gè dào de de běi jīng kǒu yīn huí yìng shuō kě bù běi jīng lián xuě yě wén míng","\"Tuyết Bắc Kinh lúc nào cũng rơi lặng lẽ, không một tiếng động. Chỉ khi sáng hôm sau ngủ dậy mở cửa mới biết đêm qua tuyết rơi.\" Một giọng Bắc Kinh chính gốc đáp: \"Đúng thế, ở Bắc Kinh đến tuyết cũng văn minh.\""],["刘全指着铁子说：“要不是蔬菜大棚，铁子还是贫困户哩！”铁子不好意思地笑了：“可不是嘛！”","liú quán zhǐ zhe tiě zi shuō yào bú shì shū cài dà péng tiě zi hái shì pín kùn hù lī tiě zi bù hǎo yì si de xiào le kě bú shì ma","Lưu Toàn chỉ Thiết Tử nói: \"Nếu không có nhà kính trồng rau, Thiết Tử vẫn còn là hộ nghèo đấy!\" Thiết Tử ngượng ngùng cười: \"Chứ còn gì nữa!\""]]},{"n":51,"c":["短语","固定短语","其他（话语标记）"],"z":"老实说","t":"Từ đánh dấu diễn ngôn 老实说","d":"= Nói thật (lòng).","e":[["老实说，我对你太失望了。","lǎo shí shuō wǒ duì nǐ tài shī wàng le","Nói thật, tôi quá thất vọng về anh."],["我和我老公现在的状态是，只要我不主动和他说话，他也绝不会找我说话，老实说，有时候我觉得这样也挺好的，默契就行。","wǒ hé wǒ lǎo gōng xiàn zài de zhuàng tài shì zhǐ yào wǒ bù zhǔ dòng hé tā shuō huà tā yě jué bú huì zhǎo wǒ shuō huà lǎo shí shuō yǒu shí hou wǒ jué de zhè yàng yě tǐng hǎo de mò qì jiù xíng","Tình trạng của tôi và chồng bây giờ là, chỉ cần tôi không chủ động nói chuyện thì anh ấy cũng tuyệt đối không tìm tôi nói chuyện, nói thật, đôi khi tôi thấy thế cũng khá ổn, ăn ý là được."]]},{"n":52,"c":["短语","固定短语","其他（话语标记）"],"z":"（你）还别说","t":"Từ đánh dấu diễn ngôn (你)还别说","d":"= Đừng nói chứ, phải công nhận là… (thừa nhận điều bất ngờ là đúng).","e":[["我的朋友给我介绍了一位知名造型师。还别说，经他这么一打扮，我感觉整个人年轻了10岁。","wǒ de péng you gěi wǒ jiè shào le yí wèi zhī míng zào xíng shī hái bié shuō jīng tā zhè me yì dǎ ban wǒ gǎn jué zhěng gè rén nián qīng le suì","Bạn tôi giới thiệu cho tôi một nhà tạo mẫu nổi tiếng. Phải công nhận, được anh ấy trang điểm cho một cái, tôi thấy cả người trẻ ra 10 tuổi."],["我当年一咬牙，花了三个月的工资买了这台洗衣机，你还别说，贵有贵的道理，这么多年它没出现过一次质量问题。","wǒ dāng nián yì yǎo yá huā le sān gè yuè de gōng zī mǎi le zhè tái xǐ yī jī nǐ hái bié shuō guì yǒu guì de dào lǐ zhè me duō nián tā méi chū xiàn guò yí cì zhì liàng wèn tí","Năm đó tôi nghiến răng bỏ ba tháng lương ra mua cái máy giặt này, phải công nhận là đắt xắt ra miếng, bao nhiêu năm nay nó chưa hỏng lần nào."]]},{"n":53,"c":["短语","固定短语","其他（话语标记）"],"z":"你看你","t":"Từ đánh dấu diễn ngôn 你看你","d":"= Xem bạn kìa (trách móc, hoặc quan tâm).","e":[["孩子考试不及格，千万别这样训斥孩子：“你看你，就考这么点分。你看那谁谁谁，人家怎么就能考那么高的分呢？”","hái zi kǎo shì bù jí gé qiān wàn bié zhè yàng xùn chì hái zi nǐ kàn nǐ jiù kǎo zhè me diǎn fēn nǐ kàn nà shuí shuí shuí rén jiā zěn me jiù néng kǎo nà me gāo de fēn ne","Con thi trượt, tuyệt đối đừng mắng con thế này: \"Xem con kìa, thi được có tí điểm. Con xem đứa nọ đứa kia, sao người ta thi được điểm cao thế?\""],["小娟啊！别人减肥，你可不能减啊！你看你，本来就瘦，再减的话都没人形了！","xiǎo juān a bié rén jiǎn féi nǐ kě bù néng jiǎn a nǐ kàn nǐ běn lái jiù shòu zài jiǎn de huà dōu méi rén xíng le","Tiểu Quyên à! Người khác giảm cân chứ cháu thì không được giảm đâu! Xem cháu kìa, vốn đã gầy, giảm nữa thì chẳng ra hình người mất!"]]},{"n":54,"c":["短语","固定短语","其他（话语标记）"],"z":"说到哪儿去了","t":"Từ đánh dấu diễn ngôn 说到哪儿去了","d":"= Nói gì kỳ vậy, đâu có chuyện đó (phủ nhận lời đối phương một cách nhẹ nhàng).","e":[["你说到哪儿去了，我才不会对他产生任何好感！","nǐ shuō dào nǎ r qù le wǒ cái bú huì duì tā chǎn shēng rèn hé hǎo gǎn","Cậu nói gì kỳ vậy, tớ mới không có chút cảm tình nào với anh ta!"],["姐姐，看你说到哪儿去了，这么见外，我们是一家人，我怎么会不尽全力帮你呢？","jiě jie kàn nǐ shuō dào nǎ r qù le zhè me jiàn wài wǒ men shì yì jiā rén wǒ zěn me huì bú jìn quán lì bāng nǐ ne","Chị ơi, chị nói gì vậy, khách sáo thế, chúng ta là người một nhà, sao em lại không dốc hết sức giúp chị chứ?"]]},{"n":55,"c":["短语","固定短语","其他（话语标记）"],"z":"说真的","t":"Từ đánh dấu diễn ngôn 说真的","d":"= Nói thật đấy.","e":[["说真的，老张，我真怕他！不但我怕，别人也都怕他。他要是来了，我可是一句话都说不出来。","shuō zhēn de lǎo zhāng wǒ zhēn pà tā bú dàn wǒ pà bié rén yě dōu pà tā tā yào shi lái le wǒ kě shì yí jù huà dōu shuō bù chū lái","Nói thật nhé, lão Trương, tôi rất sợ ông ấy! Không chỉ tôi sợ, người khác cũng sợ. Ông ấy mà đến thì tôi một câu cũng không nói ra được."],["娜娜心平气和地说：“说真的，晓东，你过得好还是不好，对我已经无所谓了。我现在看到你，心里完全没有波澜。你放心吧，我不恨你，你不用抱歉。”","nà nà xīn píng qì hé de shuō shuō zhēn de xiǎo dōng nǐ guò de hǎo hái shì bù hǎo duì wǒ yǐ jīng wú suǒ wèi le wǒ xiàn zài kàn dào nǐ xīn lǐ wán quán méi yǒu bō lán nǐ fàng xīn ba wǒ bú hèn nǐ nǐ bú yòng bào qiàn","Na Na bình thản nói: \"Nói thật, Hiểu Đông, anh sống tốt hay không với em đã chẳng còn quan trọng. Giờ em nhìn thấy anh, lòng không chút gợn sóng. Anh yên tâm, em không hận anh, anh không cần áy náy.\""]]},{"n":56,"c":["短语","固定短语","其他（话语标记）"],"z":"退一步说","t":"Từ đánh dấu diễn ngôn 退一步说","d":"= Lùi một bước mà nói, cứ cho là….","e":[["向一个根本不喜欢数学的人解释为何迷上数学，这几乎不可能。退一步说，他甚至不能向自己解释清楚。","xiàng yí gè gēn běn bù xǐ huan shù xué de rén jiě shì wèi hé mí shàng shù xué zhè jī hū bù kě néng tuì yí bù shuō tā shèn zhì bù néng xiàng zì jǐ jiě shì qīng chu","Giải thích cho một người hoàn toàn không thích toán vì sao mình mê toán, gần như là không thể. Lùi một bước mà nói, anh ta thậm chí còn không thể tự giải thích rõ cho chính mình."],["且不说在近几年内，本省电力紧缺的局面不可能有根本性的改观，退一步说，即使电力紧缺得到基本缓解，小火电仍然有其不可替代之处。","qiě bù shuō zài jìn jǐ nián nèi běn shěng diàn lì jǐn quē de jú miàn bù kě néng yǒu gēn běn xìng de gǎi guān tuì yí bù shuō jí shǐ diàn lì jǐn quē dé dào jī běn huǎn jiě xiǎo huǒ diàn réng rán yǒu qí bù kě tì dài zhī chù","Chưa nói đến việc trong vài năm tới tình trạng thiếu điện của tỉnh không thể thay đổi căn bản, lùi một bước mà nói, cho dù tình trạng thiếu điện được giải quyết cơ bản, các nhà máy nhiệt điện nhỏ vẫn có chỗ không thể thay thế."]]},{"n":57,"c":["短语","固定短语","其他（话语标记）"],"z":"无论如何","t":"Từ đánh dấu diễn ngôn 无论如何","d":"= Dù thế nào đi nữa, bằng mọi giá.","e":[["无论如何，我得去打听打听，她这衣服到底从哪买的？","wú lùn rú hé wǒ děi qù dǎ tīng dǎ tīng tā zhè yī fu dào dǐ cóng nǎ mǎi de","Dù thế nào tôi cũng phải đi hỏi thăm xem, rốt cuộc bộ quần áo của cô ấy mua ở đâu?"],["追逐梦想的过程必然是艰辛的，但无论如何，你都要坚持下去。","zhuī zhú mèng xiǎng de guò chéng bì rán shì jiān xīn de dàn wú lùn rú hé nǐ dōu yào jiān chí xià qù","Quá trình theo đuổi ước mơ chắc chắn gian khổ, nhưng dù thế nào đi nữa, bạn cũng phải kiên trì."]]},{"n":58,"c":["短语","固定短语","其他（话语标记）"],"z":"要（让）我说","t":"Từ đánh dấu diễn ngôn 要(让)我说","d":"= Nếu để tôi nói thì, theo tôi.","e":[["你不能只看别人对你热不热情，先得想想自己应该怎么做。要我说呀，你还老觉得自己是个知识分子，身份与众不同。","nǐ bù néng zhǐ kàn bié rén duì nǐ rè bu rè qíng xiān děi xiǎng xiǎng zì jǐ yīng gāi zěn me zuò yào wǒ shuō ya nǐ hái lǎo jué de zì jǐ shì gè zhī shi fēn zǐ shēn fèn yǔ zhòng bù tóng","Bạn không thể chỉ xem người khác có nhiệt tình với bạn không, trước hết phải nghĩ xem mình nên làm thế nào. Theo tôi nhé, bạn vẫn cứ nghĩ mình là trí thức, thân phận khác người."],["我是没看出来他的书法好在哪里，妙在哪里。要让我说，不同就不同在他是个作家，而不是普通人。","wǒ shì méi kàn chū lái tā de shū fǎ hǎo zài nǎ lǐ miào zài nǎ lǐ yào ràng wǒ shuō bù tóng jiù bù tóng zài tā shì gè zuò jiā ér bú shì pǔ tōng rén","Tôi chẳng nhìn ra thư pháp của ông ấy hay ở đâu, đẹp ở đâu. Nếu để tôi nói, khác là khác ở chỗ ông ấy là nhà văn chứ không phải người bình thường."]]},{"n":59,"c":["短语","固定短语","其他（话语标记）"],"z":"这不","t":"Từ đánh dấu diễn ngôn 这不","d":"= Đấy, thấy chưa (đưa ra ví dụ minh họa ngay trước mắt).","e":[["那些小伙子经常过来帮我在院子里干活，遇着墙坏了就重新垒。这不，院子的东墙就是他们不久前新垒的。","nà xiē xiǎo huǒ zi jīng cháng guò lái bāng wǒ zài yuàn zi lǐ gàn huó yù zhe qiáng huài le jiù chóng xīn lěi zhè bù yuàn zi de dōng qiáng jiù shì tā men bù jiǔ qián xīn lěi de","Mấy cậu thanh niên đó thường qua giúp tôi làm việc trong sân, gặp tường hỏng là xây lại. Đấy, bức tường phía đông của sân chính là họ mới xây lại không lâu."],["节日到了，我想给他们改善改善伙食。他俩是滕州的，这不，我准备了大葱、煎饼，还有一大盘肉。","jié rì dào le wǒ xiǎng gěi tā men gǎi shàn gǎi shàn huǒ shí tā liǎ shì téng zhōu de zhè bù wǒ zhǔn bèi le dà cōng jiān bǐng hái yǒu yí dà pán ròu","Lễ đến rồi, tôi muốn cải thiện bữa ăn cho họ. Hai người họ quê Đằng Châu, đấy, tôi đã chuẩn bị hành boa-rô, bánh tráng chiên, còn có một đĩa thịt to."]]},{"n":60,"c":["短语","固定短语","其他（话语标记）"],"z":"这样一来","t":"Từ đánh dấu diễn ngôn 这样一来","d":"= Như vậy thì, làm như thế thì.","e":[["他在屋后的空地上饲养了一群小鸡。这样一来，等小鸡长大后，他就有鸡蛋和鸡肉可吃了。","tā zài wū hòu de kòng dì shàng sì yǎng le yì qún xiǎo jī zhè yàng yì lái děng xiǎo jī zhǎng dà hòu tā jiù yǒu jī dàn hé jī ròu kě chī le","Anh ấy nuôi một đàn gà con trên khoảng đất trống sau nhà. Như vậy thì, đợi gà lớn lên, anh ấy sẽ có trứng và thịt gà để ăn."],["这些猎犬虽然个个经验丰富、身手矫健，但是对主人却不够信任。这样一来，整个队伍在捕猎时的战斗力并不高。","zhè xiē liè quǎn suī rán gè gè jīng yàn fēng fù shēn shǒu jiǎo jiàn dàn shì duì zhǔ rén què bú gòu xìn rèn zhè yàng yì lái zhěng gè duì wu zài bǔ liè shí de zhàn dòu lì bìng bù gāo","Những con chó săn này tuy con nào cũng giàu kinh nghiệm, nhanh nhẹn, nhưng lại không đủ tin tưởng chủ. Như vậy thì sức chiến đấu của cả đàn khi đi săn không cao."]]},{"n":61,"c":["短语","固定短语","其他（话语标记）"],"z":"真是的","t":"Từ đánh dấu diễn ngôn 真是的","d":"= Thật là! (phàn nàn, bực bội).","e":[["他在我睡熟的时候偷偷跑了。真是的，我怎么会一点儿动静都没听到，睡得这么沉呢？","tā zài wǒ shuì shú de shí hou tōu tōu pǎo le zhēn shì de wǒ zěn me huì yì diǎn r dòng jìng dōu méi tīng dào shuì de zhè me chén ne","Anh ấy lén đi mất lúc tôi đang ngủ say. Thật là, sao tôi lại chẳng nghe thấy động tĩnh gì, ngủ say thế không biết?"],["这点儿小事你竟然能唠叨两个多小时，真是的！","zhè diǎn r xiǎo shì nǐ jìng rán néng láo dao liǎng gè duō xiǎo shí zhēn shì de","Chuyện cỏn con thế này mà anh có thể lải nhải hơn hai tiếng, thật là!"]]},{"n":62,"c":["短语","固定短语","其他（话语标记）"],"z":"综上所述","t":"Từ đánh dấu diễn ngôn 综上所述","d":"= Tổng hợp những điều nêu trên, tóm lại (kết luận bài viết, bài nói).","e":[["在这两天的赛场上，对面实力强大，调兵遣将游刃有余，相比起来，我们在女子项目上可与之匹敌，男双也有机会，但男单相对处于弱势。综上所述，赢下对方的困难不小，可他们碰见我们，心里未必就不发怵。","zài zhè liǎng tiān de sài chǎng shàng duì miàn shí lì qiáng dà diào bīng qiǎn jiàng yóu rèn yǒu yú xiāng bǐ qǐ lái wǒ men zài nǚ zǐ xiàng mù shàng kě yǔ zhī pǐ dí nán shuāng yě yǒu jī huì dàn nán dān xiāng duì chǔ yú ruò shì zōng shàng suǒ shù yíng xià duì fāng de kùn nán bù xiǎo kě tā men pèng jiàn wǒ men xīn lǐ wèi bì jiù bù fā chù","Trên sân đấu hai ngày qua, đối phương thực lực mạnh, điều binh khiển tướng thành thạo; so ra, ở nội dung nữ chúng ta có thể ngang ngửa, đôi nam cũng có cơ hội, nhưng đơn nam tương đối yếu thế. Tổng hợp những điều trên, đánh bại đối phương không dễ, nhưng gặp chúng ta, trong lòng họ chưa chắc đã không chột dạ."],["综上所述，创造经济效益、增强地区的竞争力与可持续发展密不可分。","zōng shàng suǒ shù chuàng zào jīng jì xiào yì zēng qiáng dì qū de jìng zhēng lì yǔ kě chí xù fā zhǎn mì bù kě fēn","Tóm lại, tạo ra hiệu quả kinh tế, tăng cường sức cạnh tranh của địa phương không thể tách rời phát triển bền vững."]]},{"n":63,"c":["短语","固定短语","其他（话语标记）"],"z":"总的来说","t":"Từ đánh dấu diễn ngôn 总的来说","d":"= Nói chung, nhìn chung.","e":[["法制组调查组赴广东省多地，对招商引资工作进行了深入调研。总的来说，工作取得了不小的成就，但也暴露出了若干具体问题。","fǎ zhì zǔ diào chá zǔ fù guǎng dōng shěng duō dì duì zhāo shāng yǐn zī gōng zuò jìn xíng le shēn rù diào yán zǒng de lái shuō gōng zuò qǔ dé le bù xiǎo de chéng jiù dàn yě bào lù chū le ruò gān jù tǐ wèn tí","Tổ điều tra pháp chế đã đến nhiều nơi ở tỉnh Quảng Đông khảo sát sâu công tác thu hút đầu tư. Nhìn chung, công tác đạt được thành tựu không nhỏ, nhưng cũng bộc lộ một số vấn đề cụ thể."],["他虽然性子急，有时说话有点儿伤人，但总的来说，他是个善良、真诚的人，关键时刻，总能给予我最及时的帮助。","tā suī rán xìng zi jí yǒu shí shuō huà yǒu diǎn r shāng rén dàn zǒng de lái shuō tā shì gè shàn liáng zhēn chéng de rén guān jiàn shí kè zǒng néng jǐ yǔ wǒ zuì jí shí de bāng zhù","Anh ấy tuy nóng tính, có lúc nói hơi làm tổn thương người khác, nhưng nhìn chung, anh ấy là người lương thiện, chân thành, lúc then chốt luôn giúp tôi kịp thời nhất."]]},{"n":64,"c":["短语","固定短语","其他（话语标记）"],"z":"总而言之","t":"Từ đánh dấu diễn ngôn 总而言之","d":"= Tóm lại, nói tóm lại.","e":[["一个有志于学习的人，总而言之，肯定能够找到适合自己的学习之路。","yí gè yǒu zhì yú xué xí de rén zǒng ér yán zhī kěn dìng néng gòu zhǎo dào shì hé zì jǐ de xué xí zhī lù","Tóm lại, một người có chí học tập chắc chắn sẽ tìm được con đường học tập phù hợp với mình."],["鲁迅早就主张用“拿来主义”对待他国的科学文化。他主张“拿来”以后，再区别好坏，或用或弃，总而言之，为我所用。","lǔ xùn zǎo jiù zhǔ zhāng yòng ná lái zhǔ yì duì dài tā guó de kē xué wén huà tā zhǔ zhāng ná lái yǐ hòu zài qū bié hǎo huài huò yòng huò qì zǒng ér yán zhī wèi wǒ suǒ yòng","Lỗ Tấn từ lâu đã chủ trương dùng \"chủ nghĩa lấy về\" để đối đãi với khoa học văn hóa nước khác. Ông chủ trương \"lấy về\" rồi mới phân biệt tốt xấu, hoặc dùng hoặc bỏ, tóm lại là để phục vụ cho mình."]]},{"n":65,"c":["固定格式","",""],"z":"X到这个地步/份上","t":"Cấu trúc X到这个地步/份上","d":"= …đến mức này, đến nông nỗi này.","e":[["他的出发点是好的，只是没想到事情会闹到这个地步。","tā de chū fā diǎn shì hǎo de zhǐ shì méi xiǎng dào shì qing huì nào dào zhè ge dì bù","Xuất phát điểm của anh ấy là tốt, chỉ là không ngờ chuyện lại ầm ĩ đến mức này."],["她是铁了心要走，话说到这个份上了，再挽留也就没什么意思。","tā shì tiě le xīn yào zǒu huà shuō dào zhè ge fèn shàng le zài wǎn liú yě jiù méi shén me yì si","Cô ấy đã quyết tâm ra đi, lời đã nói đến nước này rồi, níu kéo nữa cũng chẳng có ý nghĩa gì."]]},{"n":66,"c":["固定格式","",""],"z":"X得要命/要死","t":"Cấu trúc X得要命/要死","d":"= …muốn chết, …kinh khủng (mức độ cực cao, khẩu ngữ).","e":[["他对他那一对双胞胎儿女，喜欢得要命。","tā duì tā nà yí duì shuāng bāo tāi ér nǚ xǐ huan de yào mìng","Ông ấy cưng cặp con trai con gái sinh đôi của mình hết mực."],["今年福州破天荒下起了雪，天气冷得要死。幸亏家里提前装了地暖。","jīn nián fú zhōu pò tiān huāng xià qǐ le xuě tiān qì lěng de yào sǐ xìng kuī jiā lǐ tí qián zhuāng le dì nuǎn","Năm nay Phúc Châu lần đầu tiên có tuyết rơi, trời lạnh muốn chết. May mà nhà đã lắp sưởi sàn từ trước."]]},{"n":67,"c":["固定格式","",""],"z":"X都不/没X","t":"Cấu trúc X都不/没X","d":"(连) + động từ + 都不/没 + động từ = đến…cũng không… (nhấn mạnh phủ định).","e":[["儿子再次打来电话，可他连听都不听就直接把电话挂掉，然后把话筒放在一边，这样他儿子就再也打不进来了。","ér zi zài cì dǎ lái diàn huà kě tā lián tīng dōu bù tīng jiù zhí jiē bǎ diàn huà guà diào rán hòu bǎ huà tǒng fàng zài yì biān zhè yàng tā ér zi jiù zài yě dǎ bú jìn lái le","Con trai lại gọi điện đến, nhưng ông ấy đến nghe cũng không nghe đã cúp máy, rồi để ống nghe sang một bên, như vậy con trai không gọi vào được nữa."],["我敢断定，你托他办的这件事，他在老板面前提都没提过。","wǒ gǎn duàn dìng nǐ tuō tā bàn de zhè jiàn shì tā zài lǎo bǎn miàn qián tí dōu méi tí guò","Tôi dám chắc, việc bạn nhờ anh ta, anh ta đến nhắc cũng chưa từng nhắc trước mặt ông chủ."]]},{"n":68,"c":["固定格式","",""],"z":"X就X个Y","t":"Cấu trúc X就X个Y","d":"= Đã…thì…cho…(trọn vẹn): 玩就玩个痛快 = đã chơi thì chơi cho đã.","e":[["玩就玩个痛快，反正明天还是假期。","wán jiù wán gè tòng kuài fǎn zhèng míng tiān hái shì jià qī","Đã chơi thì chơi cho đã, đằng nào mai vẫn được nghỉ."],["今天我请客，你不用心疼钱，咱去就去个好点儿的饭店。","jīn tiān wǒ qǐng kè nǐ bú yòng xīn téng qián zán qù jiù qù gè hǎo diǎn r de fàn diàn","Hôm nay tôi mời, cậu đừng tiếc tiền, đã đi thì đi nhà hàng nào tử tế một chút."]]},{"n":69,"c":["固定格式","",""],"z":"X了Y，Y了X","t":"Cấu trúc X了Y，Y了X","d":"= …rồi lại…, …rồi lại… (lặp đi lặp lại): 吃了吐，吐了吃 = ăn rồi nôn, nôn rồi ăn.","e":[["在海上生活可不是件简单的事。这几天，我们晕船晕得吃了吐，吐了吃，一点儿胃口都没有。","zài hǎi shàng shēng huó kě bú shì jiàn jiǎn dān de shì zhè jǐ tiān wǒ men yùn chuán yūn de chī le tǔ tǔ le chī yì diǎn r wèi kǒu dōu méi yǒu","Sống trên biển đâu phải chuyện đơn giản. Mấy ngày nay chúng tôi say sóng, ăn vào lại nôn ra, nôn ra lại ăn, chẳng chút ngon miệng."],["昨天晚上我睡了醒，醒了睡，心里十分烦躁，总觉得我们的秘密被泄露了。","zuó tiān wǎn shang wǒ shuì le xǐng xǐng le shuì xīn lǐ shí fēn fán zào zǒng jué de wǒ men de mì mì bèi xiè lòu le","Đêm qua tôi ngủ rồi lại tỉnh, tỉnh rồi lại ngủ, trong lòng rất bứt rứt, cứ cảm thấy bí mật của chúng tôi đã bị lộ."]]},{"n":70,"c":["固定格式","",""],"z":"X也好，Y也罢","t":"Cấu trúc X也好，Y也罢","d":"= Dù…hay…(cũng vậy).","e":[["你相信也好，不相信也罢，反正我没有在背后说过你的坏话。","nǐ xiāng xìn yě hǎo bù xiāng xìn yě bà fǎn zhèng wǒ méi yǒu zài bèi hòu shuō guò nǐ de huài huà","Bạn tin cũng được, không tin cũng chẳng sao, dù sao tôi chưa từng nói xấu bạn sau lưng."],["不论别人说我幼稚也好，不成熟也罢，我都会坚持自己的原则。","bú lùn bié rén shuō wǒ yòu zhì yě hǎo bù chéng shú yě bà wǒ dōu huì jiān chí zì jǐ de yuán zé","Bất kể người khác nói tôi ấu trĩ hay chưa chín chắn, tôi đều sẽ giữ vững nguyên tắc của mình."]]},{"n":71,"c":["固定格式","",""],"z":"别提（有）多+形容词+了","t":"Cấu trúc 别提(有)多 + tính từ + 了","d":"= …khỏi phải nói, …không kể xiết.","e":[["她这次考试没考好，整整哭了一天，别提多伤心了。","tā zhè cì kǎo shì méi kǎo hǎo zhěng zhěng kū le yì tiān bié tí duō shāng xīn le","Lần thi này cô ấy làm không tốt, khóc suốt cả ngày, buồn khỏi phải nói."],["我和爸爸昨天第一次坐了过山车，那种体验，别提有多奇妙了。","wǒ hé bà ba zuó tiān dì yī cì zuò le guò shān chē nà zhǒng tǐ yàn bié tí yǒu duō qí miào le","Hôm qua tôi và bố lần đầu đi tàu lượn siêu tốc, cảm giác đó thì kỳ diệu khỏi phải nói."]]},{"n":72,"c":["固定格式","",""],"z":"不亚于……","t":"Cấu trúc 不亚于……","d":"= Không thua kém…, chẳng kém gì….","e":[["站在慕田峪长城的高处看去，只见长城宛如一条曲折蜿蜒的巨龙，气势丝毫不亚于八达岭长城。","zhàn zài mù tián yù cháng chéng de gāo chù kàn qù zhǐ jiàn cháng chéng wǎn rú yì tiáo qū zhé wān yán de jù lóng qì shì sī háo bú yà yú bā dá lǐng cháng chéng","Đứng trên cao nhìn Trường Thành Mộ Điền Dục, chỉ thấy Trường Thành như một con rồng khổng lồ uốn lượn quanh co, khí thế không hề thua kém Trường Thành Bát Đạt Lĩnh."],["她一说起家乡便打开了话匣子，那骄傲的神情透出对家乡无比的热爱。她对每一处名胜的了解程度不亚于一个专业导游。","tā yì shuō qǐ jiā xiāng biàn dǎ kāi le huà xiá zi nà jiāo ào de shén qíng tòu chū duì jiā xiāng wú bǐ de rè ài tā duì měi yí chù míng shèng de liǎo jiě chéng dù bú yà yú yí gè zhuān yè dǎo yóu","Hễ nhắc đến quê hương là cô ấy nói không ngớt, vẻ tự hào toát lên tình yêu vô hạn với quê nhà. Mức độ hiểu biết của cô về từng danh thắng chẳng kém gì một hướng dẫn viên chuyên nghiệp."]]},{"n":73,"c":["固定格式","",""],"z":"不知X是/才好","t":"Cấu trúc 不知X是/才好","d":"= Không biết…thế nào mới phải: 不知如何是好 = không biết làm sao cho phải.","e":[["很多年轻人工作上有闯劲，但比较毛躁，遭遇挫折时，总不知如何是好。","hěn duō nián qīng rén gōng zuò shàng yǒu chuǎng jìn dàn bǐ jiào máo zào zāo yù cuò zhé shí zǒng bù zhī rú hé shì hǎo","Nhiều người trẻ có tinh thần xông pha trong công việc nhưng khá nóng vội, khi gặp thất bại thường không biết phải làm sao."],["她告诉我她和男友分手了，很痛苦。可我真的不知怎么办才好，只能不停地安慰她。","tā gào su wǒ tā hé nán yǒu fēn shǒu le hěn tòng kǔ kě wǒ zhēn de bù zhī zěn me bàn cái hǎo zhǐ néng bù tíng de ān wèi tā","Cô ấy kể với tôi đã chia tay bạn trai, rất đau khổ. Nhưng tôi thật không biết làm thế nào cho phải, chỉ có thể an ủi cô ấy mãi."]]},{"n":74,"c":["固定格式","",""],"z":"动不动就……","t":"Cấu trúc 动不动就……","d":"= Hơi một tí là…, động một chút là….","e":[["那姑娘动不动就给他打电话，弄得别人都以为他们是恋爱关系。","nà gū niang dòng bu dòng jiù gěi tā dǎ diàn huà nòng de bié rén dōu yǐ wéi tā men shì liàn ài guān xi","Cô gái đó hơi tí là gọi điện cho anh ấy, làm người khác ai cũng tưởng họ đang yêu nhau."],["“我根本没有说过那些话！”王静的脸沉了下来，“你怎么动不动就歪曲我？”","wǒ gēn běn méi yǒu shuō guò nà xiē huà wáng jìng de liǎn chén le xià lái nǐ zěn me dòng bu dòng jiù wāi qū wǒ","\"Tôi hoàn toàn không nói những lời đó!\" Mặt Vương Tĩnh sa sầm, \"Sao anh hơi một tí là xuyên tạc lời tôi?\""]]},{"n":75,"c":["固定格式","",""],"z":"动词+得个……","t":"Cấu trúc động từ + 得个……","d":"= rốt cuộc chuốc lấy… (kết quả xấu): 落得个 = rơi vào cảnh…; 闹得个 = rốt cuộc thành ra….","e":[["小黄怎么也不会想到，这份就业协议把自己送上了法庭，赔了万元“违约金”不说，还落得个“没有诚信”的名声。","xiǎo huáng zěn me yě bú huì xiǎng dào zhè fèn jiù yè xié yì bǎ zì jǐ sòng shàng le fǎ tíng péi le wàn yuán wéi yuē jīn bù shuō hái luò de gè méi yǒu chéng xìn de míng shēng","Tiểu Hoàng có nghĩ thế nào cũng không ngờ bản thỏa thuận việc làm này đưa mình ra tòa, bồi thường 20 nghìn \"tiền vi phạm hợp đồng\" chưa nói, còn chuốc lấy tiếng \"không có chữ tín\"."],["他也曾在股市搏杀，企图大赚一笔，结果闹得个血本无归，连房子都卖了。","tā yě céng zài gǔ shì bó shā qǐ tú dà zhuàn yì bǐ jié guǒ nào de gè xuè běn wú guī lián fáng zi dōu mài le","Anh ấy cũng từng lăn lộn trên thị trường chứng khoán, mong kiếm một món hời, kết quả mất trắng cả vốn lẫn lãi, đến nhà cũng phải bán."]]},{"n":76,"c":["固定格式","",""],"z":"动词+个X","t":"Cấu trúc động từ + 个X","d":"Động từ + 个 + bổ ngữ = …cho thỏa, cho đã (喝个痛快 = uống cho đã); …个什么劲儿 = …làm gì mà hăng thế.","e":[["你来我家，我一定用珍藏多年的好酒招待你，让你喝个痛快。","nǐ lái wǒ jiā wǒ yí dìng yòng zhēn cáng duō nián de hǎo jiǔ zhāo dài nǐ ràng nǐ hē gè tòng kuài","Bạn đến nhà tôi, tôi nhất định đãi bạn rượu ngon cất giữ nhiều năm, cho bạn uống thỏa thích."],["你下班之后就回家不行吗？天天在外面玩个什么劲儿？","nǐ xià bān zhī hòu jiù huí jiā bù xíng ma tiān tiān zài wài miàn wán gè shén me jìn r","Tan làm về nhà luôn không được à? Ngày nào cũng ở ngoài chơi làm gì mà hăng thế?"]]},{"n":77,"c":["固定格式","",""],"z":"该X（就）X，该Y（就）Y","t":"Cấu trúc 该X(就)X，该Y(就)Y","d":"= Đến lúc…thì…, đến lúc…thì… (cứ sống bình thường, việc nào ra việc nấy).","e":[["遇事别多想，该吃吃，该喝喝，天塌不下来。","yù shì bié duō xiǎng gāi chī chī gāi hē hē tiān tā bú xià lái","Gặp chuyện đừng nghĩ nhiều, đến bữa thì ăn, khát thì uống, trời không sập được đâu."],["到了高三下学期，就该放下所有负担，调整好心态，该学就学，该玩就玩。","dào le gāo sān xià xué qī jiù gāi fàng xià suǒ yǒu fù dān tiáo zhěng hǎo xīn tài gāi xué jiù xué gāi wán jiù wán","Đến học kỳ hai lớp 12 thì nên bỏ hết gánh nặng, điều chỉnh tâm lý tốt, lúc học thì học, lúc chơi thì chơi."]]},{"n":78,"c":["固定格式","",""],"z":"何至于……","t":"Cấu trúc 何至于……","d":"= Đâu đến nỗi…, sao lại đến mức….","e":[["要是我能想到别的办法，何至于来叨扰您呢？","yào shi wǒ néng xiǎng dào bié de bàn fǎ hé zhì yú lái tāo rǎo nín ne","Nếu tôi nghĩ ra được cách khác thì đâu đến nỗi phải đến làm phiền ông?"],["我后悔没有听从他的忠告——要不然，事情何至于变得如此不可收拾！","wǒ hòu huǐ méi yǒu tīng cóng tā de zhōng gào yào bù rán shì qing hé zhì yú biàn de rú cǐ bù kě shōu shi","Tôi hối hận vì đã không nghe lời khuyên của anh ấy — nếu không, sự việc đâu đến mức không thể cứu vãn như thế này!"]]},{"n":79,"c":["固定格式","",""],"z":"仅次于X","t":"Cấu trúc 仅次于X","d":"= Chỉ đứng sau X.","e":[["在这家私营企业中，他的地位仅次于董事长。","zài zhè jiā sī yíng qǐ yè zhōng tā de dì wèi jǐn cì yú dǒng shì zhǎng","Trong doanh nghiệp tư nhân này, địa vị của anh ấy chỉ đứng sau chủ tịch hội đồng quản trị."],["水稻是世界上分布最广泛的粮食作物之一，其种植面积仅次于小麦。","shuǐ dào shì shì jiè shàng fēn bù zuì guǎng fàn de liáng shí zuò wù zhī yī qí zhòng zhí miàn jī jǐn cì yú xiǎo mài","Lúa nước là một trong những cây lương thực phân bố rộng rãi nhất thế giới, diện tích gieo trồng chỉ đứng sau lúa mì."]]},{"n":80,"c":["固定格式","",""],"z":"看在X的面子上","t":"Cấu trúc 看在X的面子上","d":"= Nể mặt X, vì nể X.","e":[["我今天之所以放他一马，完全是看在你的面子上。","wǒ jīn tiān zhī suǒ yǐ fàng tā yì mǎ wán quán shì kàn zài nǐ de miàn zi shàng","Hôm nay tôi sở dĩ tha cho hắn một lần, hoàn toàn là nể mặt anh."],["你别那么固执了，看在孩子的面子上，就来一趟吧。","nǐ bié nà me gù zhí le kàn zài hái zi de miàn zi shàng jiù lái yí tàng ba","Bạn đừng cố chấp thế nữa, nể mặt con, đến một chuyến đi."]]},{"n":81,"c":["固定格式","",""],"z":"没什么+动词+头儿","t":"Cấu trúc 没什么 + động từ + 头儿","d":"= Chẳng có gì đáng để…: 没什么吃头儿 = chẳng có gì đáng ăn; 没什么看头儿 = chẳng có gì đáng xem.","e":[["我觉得高档饭店的菜真没什么吃头儿，还是路边地道的土菜馆吃着过瘾。","wǒ jué de gāo dàng fàn diàn de cài zhēn méi shén me chī tou r hái shì lù biān dì dào de tǔ cài guǎn chī zhe guò yǐn","Tôi thấy món ăn ở nhà hàng cao cấp thật chẳng có gì đáng ăn, vẫn là quán ăn dân dã ven đường ăn mới đã."],["春晚小品少了原来那些老面孔，还真是没什么看头儿。","chūn wǎn xiǎo pǐn shǎo le yuán lái nà xiē lǎo miàn kǒng hái zhēn shì méi shén me kàn tou r","Tiểu phẩm Gala Xuân thiếu những gương mặt quen thuộc trước đây, thật chẳng có gì đáng xem."]]},{"n":82,"c":["固定格式","",""],"z":"没什么好+动词+的","t":"Cấu trúc 没什么好 + động từ + 的","d":"= Chẳng có gì để…, chẳng có gì đáng….","e":[["你别再解释了，我跟你没什么好说的。","nǐ bié zài jiě shì le wǒ gēn nǐ méi shén me hǎo shuō de","Anh đừng giải thích nữa, tôi với anh chẳng có gì để nói cả."],["这事儿已经过去了，没什么好纠结的，人得往前看。","zhè shì r yǐ jīng guò qù le méi shén me hǎo jiū jié de rén de wǎng qián kàn","Chuyện này qua rồi, chẳng có gì phải day dứt, con người phải nhìn về phía trước."]]},{"n":83,"c":["固定格式","",""],"z":"莫过于……","t":"Cấu trúc 莫过于……","d":"= Không gì bằng…, …nhất chính là….","e":[["登山的游客可以欣赏到众多书画名家留下的石刻题词。石刻题词最密集地方，莫过于我们现在看到的这处崖壁了。","dēng shān de yóu kè kě yǐ xīn shǎng dào zhòng duō shū huà míng jiā liú xià de shí kè tí cí shí kè tí cí zuì mì jí dì fang mò guò yú wǒ men xiàn zài kàn dào de zhè chù yá bì le","Du khách leo núi có thể ngắm những khắc đá đề từ của nhiều danh gia thư họa để lại. Nơi khắc đá dày đặc nhất không đâu bằng vách đá chúng ta đang thấy đây."],["近些年，在全球范围内引发最多关注的火山，莫过于2010年3月20日开始大规模喷发的冰岛南部的埃亚菲亚德拉火山了。","jìn xiē nián zài quán qiú fàn wéi nèi yǐn fā zuì duō guān zhù de huǒ shān mò guò yú nián yuè rì kāi shǐ dà guī mó pēn fā de bīng dǎo nán bù de āi yà fēi yà dé lā huǒ shān le","Những năm gần đây, ngọn núi lửa gây chú ý nhất trên toàn cầu không gì bằng núi lửa Eyjafjallajökull ở miền nam Iceland, phun trào quy mô lớn từ ngày 20 tháng 3 năm 2010."]]},{"n":84,"c":["固定格式","",""],"z":"你说你一个X，……","t":"Cấu trúc 你说你一个X，……","d":"= Bạn xem, bạn là một…mà… (trách: không xứng với thân phận).","e":[["你说你一个20多岁的成年人，又不是小孩子，怎么连话都说不清楚呢？","nǐ shuō nǐ yí gè duō suì de chéng nián rén yòu bú shì xiǎo hái zi zěn me lián huà dōu shuō bù qīng chu ne","Bạn xem, bạn là người lớn hơn hai mươi tuổi rồi, có phải trẻ con đâu, sao đến nói cũng không rõ ràng?"],["你说你一个弱女子，一个人跑到这儿来干什么？人生地不熟的。","nǐ shuō nǐ yí gè ruò nǚ zǐ yí gè rén pǎo dào zhè r lái gàn shén me rén shēng dì bù shú de","Cô xem, cô là phận gái yếu đuối, một mình chạy đến đây làm gì? Lạ nước lạ cái."]]},{"n":85,"c":["固定格式","",""],"z":"什么A的B的","t":"Cấu trúc 什么A的B的","d":"= …với…gì chứ (gạt đi, không quan trọng).","e":[["你知道我的难言之隐，我不能和任何人说明我们的关系。所以什么好的坏的我都要憋在心里，默默承受。","nǐ zhī dao wǒ de nán yán zhī yǐn wǒ bù néng hé rèn hé rén shuō míng wǒ men de guān xi suǒ yǐ shén me hǎo de huài de wǒ dōu yào biē zài xīn lǐ mò mò chéng shòu","Anh biết nỗi khổ khó nói của em, em không thể nói rõ quan hệ của chúng ta với ai. Nên tốt hay xấu gì em cũng phải giữ trong lòng, lặng lẽ chịu đựng."],["听说小林和小王要结婚了，是真的吗？","tīng shuō xiǎo lín hé xiǎo wáng yào jié hūn le shì zhēn de ma","Nghe nói Tiểu Lâm và Tiểu Vương sắp cưới, thật không?"],["——什么真的假的？！他俩结婚的日子早就定了，请帖也都发出去了。","shén me zhēn de jiǎ de tā liǎ jié hūn de rì zi zǎo jiù dìng le qǐng tiē yě dōu fā chū qù le","— Thật với giả gì chứ?! Ngày cưới của hai người họ định từ lâu rồi, thiệp cũng gửi đi cả rồi."]]},{"n":86,"c":["固定格式","",""],"z":"视……而定","t":"Cấu trúc 视……而定","d":"= Tùy theo…mà quyết định.","e":[["这项低保补助金，是为低收入家庭发放的。补助金额每家从500到3500元不等，视家庭收入而定。","zhè xiàng dī bǎo bǔ zhù jīn shì wèi dī shōu rù jiā tíng fā fàng de bǔ zhù jīn é měi jiā cóng dào yuán bù děng shì jiā tíng shōu rù ér dìng","Khoản trợ cấp mức sống tối thiểu này cấp cho các gia đình thu nhập thấp. Mức trợ cấp mỗi nhà từ 500 đến 3500 tệ, tùy theo thu nhập gia đình mà định."],["领导进行调研的方式有多种，可以明察，可以暗访，可以召开小型座谈会，还可以针对性地个别谈话。该用什么方式，应视情况而定。","lǐng dǎo jìn xíng diào yán de fāng shì yǒu duō zhǒng kě yǐ míng chá kě yǐ àn fǎng kě yǐ zhào kāi xiǎo xíng zuò tán huì hái kě yǐ zhēn duì xìng de gè bié tán huà gāi yòng shén me fāng shì yìng shì qíng kuàng ér dìng","Lãnh đạo khảo sát có nhiều cách: có thể công khai, có thể bí mật, có thể mở tọa đàm nhỏ, còn có thể nói chuyện riêng có trọng tâm. Nên dùng cách nào thì tùy tình hình mà định."]]},{"n":87,"c":["固定格式","",""],"z":"谈何……","t":"Cấu trúc 谈何……","d":"= Nói gì đến…, …đâu có dễ (phản vấn: hoàn toàn không thể).","e":[["十几年前，该县共有20余所小学，其中多半学校的校舍残破，教学设施老旧。这种情况下，谈何“素质教育”？","shí jǐ nián qián gāi xiàn gòng yǒu yú suǒ xiǎo xué qí zhōng duō bàn xué xiào de xiào shè cán pò jiào xué shè shī lǎo jiù zhè zhǒng qíng kuàng xià tán hé sù zhì jiào yù","Hơn mười năm trước, huyện này có hơn 20 trường tiểu học, quá nửa trong số đó trường lớp xập xệ, thiết bị dạy học cũ kỹ. Trong tình hình đó, nói gì đến \"giáo dục toàn diện\"?"],["消费能力不足，工业产品就卖不出去。产品市场惨淡，工业谈何兴旺！","xiāo fèi néng lì bù zú gōng yè chǎn pǐn jiù mài bù chū qù chǎn pǐn shì chǎng cǎn dàn gōng yè tán hé xīng wàng","Sức tiêu dùng không đủ thì sản phẩm công nghiệp không bán được. Thị trường sản phẩm ảm đạm thì nói gì đến công nghiệp hưng thịnh!"]]},{"n":88,"c":["固定格式","",""],"z":"无非/不过/只是……罢了/而已","t":"Cấu trúc 无非/不过/只是……罢了/而已","d":"= Chẳng qua chỉ là…mà thôi.","e":[["他无非有些小聪明罢了，离天才还差得远呢！","tā wú fēi yǒu xiē xiǎo cōng ming bà le lí tiān cái hái chà de yuǎn ne","Cậu ta chẳng qua có chút khôn vặt mà thôi, còn kém thiên tài xa lắm!"],["这里的海鲜大餐物美价廉，人均花费不过二百多港币而已。","zhè lǐ de hǎi xiān dà cān wù měi jià lián rén jūn huā fèi bú guò èr bǎi duō gǎng bì ér yǐ","Bữa hải sản ở đây ngon mà rẻ, mỗi người chi chẳng qua hơn hai trăm đô la Hồng Kông mà thôi."],["我从来不觉得自己胖，我只是不瘦而已。","wǒ cóng lái bù jué de zì jǐ pàng wǒ zhǐ shì bú shòu ér yǐ","Tôi chưa bao giờ thấy mình béo, tôi chỉ là không gầy mà thôi."]]},{"n":89,"c":["固定格式","",""],"z":"想X之所想，急X之所急","t":"Cấu trúc 想X之所想，急X之所急","d":"= Nghĩ điều X nghĩ, lo điều X lo (đặt mình vào vị trí người khác).","e":[["领导干部不能有私心杂念，要全心全意为人民服务，想人民之所想，急人民之所急。","lǐng dǎo gàn bù bù néng yǒu sī xīn zá niàn yào quán xīn quán yì wèi rén mín fú wù xiǎng rén mín zhī suǒ xiǎng jí rén mín zhī suǒ jí","Cán bộ lãnh đạo không được có tư tâm tạp niệm, phải toàn tâm toàn ý phục vụ nhân dân, nghĩ điều dân nghĩ, lo điều dân lo."],["创业指导专家服务团成立一年来，想创业者之所想，急创业者之所急，是创业者的最佳智囊团。","chuàng yè zhǐ dǎo zhuān jiā fú wù tuán chéng lì yì nián lái xiǎng chuàng yè zhě zhī suǒ xiǎng jí chuàng yè zhě zhī suǒ jí shì chuàng yè zhě de zuì jiā zhì náng tuán","Đoàn chuyên gia hướng dẫn khởi nghiệp từ khi thành lập một năm nay luôn nghĩ điều người khởi nghiệp nghĩ, lo điều người khởi nghiệp lo, là nhóm cố vấn tốt nhất của người khởi nghiệp."]]},{"n":90,"c":["固定格式","",""],"z":"向……致以……","t":"Cấu trúc 向……致以……","d":"= Xin gửi tới…lời… (trang trọng: 致以问候/祝福/谢意).","e":[["我们谨此向广大读者致以最诚挚的问候，感谢大家在过去的一年里对本刊的支持、鼓励和批评。","wǒ men jǐn cǐ xiàng guǎng dà dú zhě zhì yǐ zuì chéng zhì de wèn hòu gǎn xiè dà jiā zài guò qù de yì nián lǐ duì běn kān de zhī chí gǔ lì hé pī píng","Nhân đây chúng tôi xin gửi tới đông đảo bạn đọc lời thăm hỏi chân thành nhất, cảm ơn mọi người đã ủng hộ, động viên và góp ý cho tạp chí trong năm qua."],["我满怀喜悦，用中文向留学生们致以节日的祝福。","wǒ mǎn huái xǐ yuè yòng zhōng wén xiàng liú xué shēng men zhì yǐ jié rì de zhù fú","Tôi tràn đầy niềm vui, dùng tiếng Trung gửi tới các lưu học sinh lời chúc mừng ngày lễ."]]},{"n":91,"c":["固定格式","",""],"z":"要X有/没X，要Y有/没Y","t":"Cấu trúc 要X有/没X，要Y有/没Y","d":"= Muốn X thì có/không có X, muốn Y thì có/không có Y (có đủ hết / chẳng có gì).","e":[["我要长相没长相，要身材没身材，怎么可能当明星？","wǒ yào zhǎng xiàng méi zhǎng xiàng yào shēn cái méi shēn cái zěn me kě néng dāng míng xīng","Tôi nhan sắc chẳng có, dáng người cũng không, làm sao làm ngôi sao được?"],["我们返回的时候要机票没机票，要火车票没火车票，只好跟人拼车回来。","wǒ men fǎn huí de shí hou yào jī piào méi jī piào yào huǒ chē piào méi huǒ chē piào zhǐ hǎo gēn rén pīn chē huí lái","Lúc chúng tôi quay về, vé máy bay không có, vé tàu cũng không, đành phải đi xe ghép với người ta về."],["老张要能力有能力，要资历有资历，早就应该当经理了。","lǎo zhāng yào néng lì yǒu néng lì yào zī lì yǒu zī lì zǎo jiù yīng gāi dāng jīng lǐ le","Lão Trương năng lực có năng lực, thâm niên có thâm niên, lẽ ra phải làm giám đốc từ lâu rồi."],["你的部队一定要坚守阵地，把敌人反击下去，要援兵有援兵，要弹药有弹药。","nǐ de bù duì yí dìng yào jiān shǒu zhèn dì bǎ dí rén fǎn jī xià qù yào yuán bīng yǒu yuán bīng yào dàn yào yǒu dàn yào","Đơn vị của các anh nhất định phải giữ vững trận địa, đánh lui quân địch, cần viện binh có viện binh, cần đạn dược có đạn dược."]]},{"n":92,"c":["固定格式","",""],"z":"因……而……","t":"Cấu trúc 因……而……","d":"= Vì…mà…: 因人而异 = tùy người mà khác.","e":[["看到其他人的结局，俞经理十分庆幸自己没有因一时冲动而犯下大错。","kàn dào qí tā rén de jié jú yú jīng lǐ shí fēn qìng xìng zì jǐ méi yǒu yīn yì shí chōng dòng ér fàn xià dà cuò","Nhìn kết cục của người khác, giám đốc Du rất mừng vì mình không vì nhất thời bốc đồng mà phạm sai lầm lớn."],["教师为每个学生制定的学习计划应因人而异。","jiào shī wèi měi gè xué shēng zhì dìng de xué xí jì huà yìng yīn rén ér yì","Kế hoạch học tập giáo viên lập cho mỗi học sinh nên tùy từng người mà khác nhau."]]},{"n":93,"c":["固定格式","",""],"z":"有何X","t":"Cấu trúc 有何X","d":"= Có gì… (văn viết của 有什么): 有何不可 = có gì không được.","e":[["政府若仅靠当地力量不能让群众脱贫致富，引入外部资源有何不可？","zhèng fǔ ruò jǐn kào dāng dì lì liàng bù néng ràng qún zhòng tuō pín zhì fù yǐn rù wài bù zī yuán yǒu hé bù kě","Nếu chính quyền chỉ dựa vào sức địa phương không giúp người dân thoát nghèo làm giàu được, thì thu hút nguồn lực bên ngoài có gì không được?"],["我是真不明白，你这样只知道拼命赚钱，生活究竟有何乐趣？","wǒ shì zhēn bù míng bai nǐ zhè yàng zhǐ zhī dao pīn mìng zhuàn qián shēng huó jiū jìng yǒu hé lè qù","Tôi thật không hiểu, anh chỉ biết liều mạng kiếm tiền như vậy, rốt cuộc cuộc sống có niềm vui gì?"]]},{"n":94,"c":["固定格式","",""],"z":"有什么+动词+头儿","t":"Cấu trúc 有什么 + động từ + 头儿","d":"= Có gì đáng để… (phản vấn: chẳng đáng).","e":[["这不就是一场校际篮球联赛吗，有什么看头？","zhè bú jiù shì yì chǎng xiào jì lán qiú lián sài ma yǒu shén me kàn tou","Chẳng phải chỉ là giải bóng rổ liên trường thôi sao, có gì đáng xem?"],["我是不明白，这些垃圾食品，油腻至极，有什么吃头？","wǒ shì bù míng bai zhè xiē lā jī shí pǐn yóu nì zhì jí yǒu shén me chī tou","Tôi không hiểu, mấy thứ đồ ăn vặt vô bổ này, ngấy hết mức, có gì đáng ăn?"]]},{"n":95,"c":["固定格式","",""],"z":"（在）……之余","t":"Cấu trúc (在)……之余","d":"= Ngoài lúc…, sau khi… (thời gian rảnh ngoài việc chính).","e":[["他职位提升后，工作日益繁忙，只能在工作之余发表一些作品。","tā zhí wèi tí shēng hòu gōng zuò rì yì fán máng zhǐ néng zài gōng zuò zhī yú fā biǎo yì xiē zuò pǐn","Sau khi được thăng chức, công việc ngày càng bận rộn, anh ấy chỉ có thể đăng một số tác phẩm lúc rảnh rỗi ngoài công việc."],["这本书收录了很多幽默、滑稽的故事，不过倘若能在捧腹大笑之余回味一番，便可发现这些故事背后也蕴含着深刻的哲理。","zhè běn shū shōu lù le hěn duō yōu mò huá jī de gù shì bú guò tǎng ruò néng zài pěng fù dà xiào zhī yú huí wèi yì fān biàn kě fā xiàn zhè xiē gù shì bèi hòu yě yùn hán zhe shēn kè de zhé lǐ","Cuốn sách này tập hợp nhiều câu chuyện hài hước, khôi hài, nhưng nếu sau khi cười ôm bụng mà ngẫm nghĩ lại, sẽ thấy đằng sau chúng cũng chứa đựng triết lý sâu sắc."]]},{"n":96,"c":["固定格式","",""],"z":"值此……之际，……","t":"Cấu trúc 值此……之际，……","d":"= Nhân dịp…, … (lời chúc, cảm ơn trang trọng).","e":[["值此新春佳节之际，衷心感谢您对本公司一直以来的关心和支持！","zhí cǐ xīn chūn jiā jié zhī jì zhōng xīn gǎn xiè nín duì běn gōng sī yì zhí yǐ lái de guān xīn hé zhī chí","Nhân dịp Tết đến xuân về, xin chân thành cảm ơn quý khách đã luôn quan tâm và ủng hộ công ty chúng tôi!"],["值此教师节来临之际，祝我校全体老师身体健康，阖家幸福！","zhí cǐ jiào shī jié lái lín zhī jì zhù wǒ xiào quán tǐ lǎo shī shēn tǐ jiàn kāng hé jiā xìng fú","Nhân dịp Ngày Nhà giáo sắp đến, kính chúc toàn thể thầy cô giáo trường ta sức khỏe dồi dào, gia đình hạnh phúc!"]]},{"n":97,"c":["句子的类型","特殊句型","比较句5"],"z":"A+形容词+于/过+B","t":"Câu so sánh: A + tính từ + 于/过 + B","d":"= A…hơn B (văn viết): 优于 = tốt hơn; 胜于 = hơn; 高过 = cao hơn; 强过 = giỏi hơn.","e":[["新型钛合金门窗不仅美观大方，而且在使用寿命方面也远远优于铁窗和铝合金门窗。","xīn xíng tài hé jīn mén chuāng bù jǐn měi guān dà fāng ér qiě zài shǐ yòng shòu mìng fāng miàn yě yuǎn yuǎn yōu yú tiě chuāng hé lǚ hé jīn mén chuāng","Cửa hợp kim titan kiểu mới không chỉ đẹp mà tuổi thọ sử dụng cũng vượt xa cửa sắt và cửa hợp kim nhôm."],["对她这种锦衣玉食的富家小姐而言，面子往往胜于一切。","duì tā zhè zhǒng jǐn yī yù shí de fù jiā xiǎo jiě ér yán miàn zi wǎng wǎng shèng yú yí qiè","Đối với tiểu thư nhà giàu ăn sung mặc sướng như cô ta, thể diện thường hơn tất cả."],["我可不相信这世界上还有厨艺高过您的人。","wǒ kě bù xiāng xìn zhè shì jiè shàng hái yǒu chú yì gāo guò nín de rén","Tôi không tin trên đời này còn người nấu ăn giỏi hơn bà."],["你争气点，强过你的两个哥哥，不要让那些没安好心的人笑话了。","nǐ zhēng qì diǎn qiáng guò nǐ de liǎng gè gē ge bú yào ràng nà xiē méi ān hǎo xīn de rén xiào huà le","Con cố gắng lên, giỏi hơn hai anh của con, đừng để những kẻ không có ý tốt chê cười."]]},{"n":98,"c":["句子的类型","简单复句","并列复句"],"z":"一来……，二来……，三来……","t":"Câu phức đẳng lập: 一来……，二来……，三来……","d":"= Một là…, hai là…, ba là… (liệt kê lý do).","e":[["他虽然在犹豫，但现在还不会和她说分手，一来于心不忍，二来谈了这么多年多少也习惯了，三来怕别人议论。","tā suī rán zài yóu yù dàn xiàn zài hái bú huì hé tā shuō fēn shǒu yì lái yú xīn bù rěn èr lái tán le zhè me duō nián duō shǎo yě xí guàn le sān lái pà bié rén yì lùn","Anh ấy tuy đang do dự nhưng giờ vẫn chưa nói chia tay với cô ấy, một là không nỡ, hai là yêu nhau bao năm cũng ít nhiều quen rồi, ba là sợ người khác bàn tán."],["他对王经理有相当的敬意，一来因为是自己的顶头上司，二来因为经理对于相关业务确实是烂熟于心，三来因为经理虽沉默寡言但又善于处理人际关系。","tā duì wáng jīng lǐ yǒu xiāng dāng de jìng yì yì lái yīn wèi shì zì jǐ de dǐng tóu shàng si èr lái yīn wèi jīng lǐ duì yú xiāng guān yè wù què shí shì làn shú yú xīn sān lái yīn wèi jīng lǐ suī chén mò guǎ yán dàn yòu shàn yú chǔ lǐ rén jì guān xi","Anh ấy khá kính trọng giám đốc Vương, một là vì đó là cấp trên trực tiếp, hai là vì giám đốc thực sự nắm nghiệp vụ liên quan rất kỹ, ba là vì giám đốc tuy ít nói nhưng giỏi xử lý quan hệ."]]},{"n":99,"c":["句子的类型","简单复句","并列复句"],"z":"一则……，二则……，三则……","t":"Câu phức đẳng lập: 一则……，二则……，三则……","d":"= Một là…, hai là…, ba là… (văn viết).","e":[["这种药品一则价格高昂，二则产量较少，三则副作用明显，因此难以推广。","zhè zhǒng yào pǐn yì zé jià gé gāo áng èr zé chǎn liàng jiào shǎo sān zé fù zuò yòng míng xiǎn yīn cǐ nán yǐ tuī guǎng","Loại thuốc này một là giá cao, hai là sản lượng ít, ba là tác dụng phụ rõ rệt, vì vậy khó phổ biến."],["排练时需要的演员比实际演出的时候要多一些，一则考察演员的表现，不合适的话就换掉；二则可以相互提出意见，完善表演；三则不上场的演员也可以做一些剧务工作。","pái liàn shí xū yào de yǎn yuán bǐ shí jì yǎn chū de shí hou yào duō yì xiē yì zé kǎo chá yǎn yuán de biǎo xiàn bù hé shì de huà jiù huàn diào èr zé kě yǐ xiāng hù tí chū yì jiàn wán shàn biǎo yǎn sān zé bú shàng chǎng de yǎn yuán yě kě yǐ zuò yì xiē jù wù gōng zuò","Khi tập cần nhiều diễn viên hơn lúc diễn thật, một là để xem xét biểu hiện của diễn viên, không hợp thì thay; hai là có thể góp ý cho nhau, hoàn thiện màn diễn; ba là diễn viên không lên sân khấu cũng có thể làm một số việc hậu đài."]]},{"n":100,"c":["句子的类型","简单复句","解说复句"],"z":"所谓……，就是……","t":"Câu phức giải thích: 所谓……，就是……","d":"= Cái gọi là…, chính là… (định nghĩa).","e":[["所谓绒面涂料，就是视觉效果一流，又不会引发眩晕，触感柔软而有弹性的新型装饰材料。","suǒ wèi róng miàn tú liào jiù shì shì jué xiào guǒ yì liú yòu bú huì yǐn fā xuàn yùn chù gǎn róu ruǎn ér yǒu tán xìng de xīn xíng zhuāng shì cái liào","Cái gọi là sơn hiệu ứng nhung, chính là loại vật liệu trang trí mới có hiệu ứng thị giác hàng đầu, không gây chói mắt, sờ vào mềm mại và có độ đàn hồi."],["企业管理者要为企业的发展提供催化剂。所谓催化剂，就是能为企业发展提供助力的一切行为，包括设立清晰目标、调动员工自主性和创造性，以及提供充分的资源等。","qǐ yè guǎn lǐ zhě yào wèi qǐ yè de fā zhǎn tí gōng cuī huà jì suǒ wèi cuī huà jì jiù shì néng wèi qǐ yè fā zhǎn tí gōng zhù lì de yí qiè xíng wéi bāo kuò shè lì qīng xī mù biāo diào dòng yuán gōng zì zhǔ xìng hé chuàng zào xìng yǐ jí tí gōng chōng fèn de zī yuán děng","Nhà quản lý doanh nghiệp phải tạo chất xúc tác cho sự phát triển của doanh nghiệp. Cái gọi là chất xúc tác, chính là mọi hành động có thể hỗ trợ doanh nghiệp phát triển, bao gồm đặt mục tiêu rõ ràng, phát huy tính tự chủ và sáng tạo của nhân viên, cung cấp đủ nguồn lực…"]]},{"n":101,"c":["句子的类型","简单复句","选择复句"],"z":"或……，或……","t":"Câu phức lựa chọn: 或……，或……","d":"= Hoặc…, hoặc… (văn viết).","e":[["这一辈子，或饱经挫折，或一帆风顺。受挫折的，心性会得到磨炼，总是处于顺境的，往往思想单纯。","zhè yí bèi zi huò bǎo jīng cuò zhé huò yì fān fēng shùn shòu cuò zhé de xīn xìng huì dé dào mó liàn zǒng shì chǔ yú shùn jìng de wǎng wǎng sī xiǎng dān chún","Một đời người, hoặc trải qua nhiều thất bại, hoặc thuận buồm xuôi gió. Người gặp thất bại thì tâm tính được tôi luyện, người luôn thuận lợi thì suy nghĩ thường đơn giản."],["那个工人，或是生病了，或是家里头有事，反正今天来不了了。","nà gè gōng rén huò shì shēng bìng le huò shì jiā lǐ tou yǒu shì fǎn zhèng jīn tiān lái bù liǎo le","Người công nhân đó hoặc là bị ốm, hoặc là nhà có việc, dù sao hôm nay cũng không đến được."]]},{"n":102,"c":["句子的类型","简单复句","选择复句"],"z":"宁可/宁愿……，也不……","t":"Câu phức lựa chọn: 宁可/宁愿……，也不……","d":"= Thà…chứ không….","e":[["今年上半年，门店营业额有二百五十万元之多，但利润仅一万多元，公司经理说：“我们宁可利润少一些，也不能忘掉服务消费者的宗旨。”","jīn nián shàng bàn nián mén diàn yíng yè é yǒu èr bǎi wǔ shí wàn yuán zhī duō dàn lì rùn jǐn yí wàn duō yuán gōng sī jīng lǐ shuō wǒ men nìng kě lì rùn shǎo yì xiē yě bù néng wàng diào fú wù xiāo fèi zhě de zōng zhǐ","Nửa đầu năm nay doanh thu cửa hàng lên tới 2,5 triệu tệ, nhưng lợi nhuận chỉ hơn 10 nghìn, giám đốc công ty nói: \"Chúng tôi thà lợi nhuận ít một chút, chứ không thể quên tôn chỉ phục vụ người tiêu dùng.\""],["这批有志于交响乐艺术的音乐家始终以发展中国高水平的交响乐为己任。他们宁愿生活艰苦些，也不愿放弃自己热爱的事业。","zhè pī yǒu zhì yú jiāo xiǎng yuè yì shù de yīn yuè jiā shǐ zhōng yǐ fā zhǎn zhōng guó gāo shuǐ píng de jiāo xiǎng yuè wèi jǐ rèn tā men nìng yuàn shēng huó jiān kǔ xiē yě bú yuàn fàng qì zì jǐ rè ài de shì yè","Những nhạc sĩ tâm huyết với nghệ thuật giao hưởng này luôn coi việc phát triển nhạc giao hưởng Trung Quốc trình độ cao là trách nhiệm của mình. Họ thà sống khổ một chút chứ không muốn từ bỏ sự nghiệp mình yêu."]]},{"n":103,"c":["句子的类型","简单复句","选择复句"],"z":"与其……，宁愿/宁可……","t":"Câu phức lựa chọn: 与其……，宁愿/宁可……","d":"= Thay vì…, thà… còn hơn.","e":[["与其在这里胡思乱想，我宁愿当面去问个清楚。","yǔ qí zài zhè lǐ hú sī luàn xiǎng wǒ nìng yuàn dāng miàn qù wèn gè qīng chu","Thay vì ngồi đây nghĩ ngợi lung tung, tôi thà đến hỏi trực tiếp cho rõ."],["与其跟这些毫无责任心的人一组，我宁可一个人做这个小组作业。","yǔ qí gēn zhè xiē háo wú zé rèn xīn de rén yì zǔ wǒ nìng kě yí gè rén zuò zhè ge xiǎo zǔ zuò yè","Thay vì chung nhóm với những người chẳng có chút trách nhiệm này, tôi thà một mình làm bài tập nhóm này."]]},{"n":104,"c":["句子的类型","简单复句","转折复句"],"z":"X（倒）是X（了），……","t":"Câu phức chuyển ngoặt: X(倒)是X(了)，……","d":"= …thì có…(rồi), nhưng… (thừa nhận một phần rồi chuyển ý).","e":[["重庆火锅好吃是好吃，不过对于吃不惯麻辣味的人来说，恐怕会难以入口。","chóng qìng huǒ guō hǎo chī shì hǎo chī bú guò duì yú chī bú guàn má là wèi de rén lái shuō kǒng pà huì nán yǐ rù kǒu","Lẩu Trùng Khánh ngon thì có ngon, nhưng với người không quen vị cay tê, e là khó nuốt."],["上周的大型相亲会，他迫于父母的压力，去倒是去了，但若是让他在相亲会上勇敢地表达自己，追求心上人，确实是难为他了。","shàng zhōu de dà xíng xiāng qīn huì tā pò yú fù mǔ de yā lì qù dào shì qù le dàn ruò shì ràng tā zài xiāng qīn huì shàng yǒng gǎn de biǎo dá zì jǐ zhuī qiú xīn shàng rén què shí shì nán wéi tā le","Buổi xem mắt quy mô lớn tuần trước, vì áp lực của bố mẹ, đi thì anh ấy cũng đi rồi, nhưng nếu bắt anh ấy mạnh dạn bày tỏ bản thân, theo đuổi người trong mộng ở đó thì quả thật là làm khó anh ấy."]]},{"n":105,"c":["句子的类型","简单复句","转折复句"],"z":"别看……，……","t":"Câu phức chuyển ngoặt: 别看……，……","d":"= Đừng thấy…mà…, tuy…nhưng thực ra….","e":[["别看年龄小，他的志向可很大呢！","bié kàn nián líng xiǎo tā de zhì xiàng kě hěn dà ne","Đừng thấy tuổi còn nhỏ, chí hướng của cậu bé lớn lắm đấy!"],["别看小王一天到晚看上去什么都不在乎的样子，其实他是个特别在意别人看法的人。","bié kàn xiǎo wáng yì tiān dào wǎn kàn shàng qù shén me dōu bú zài hu de yàng zi qí shí tā shì gè tè bié zài yì bié rén kàn fǎ de rén","Đừng thấy Tiểu Vương suốt ngày trông như chẳng bận tâm gì, thực ra cậu ấy là người cực kỳ để ý cách nhìn của người khác."]]},{"n":106,"c":["句子的类型","简单复句","转折复句"],"z":"虽说……，但/可……","t":"Câu phức chuyển ngoặt: 虽说……，但/可……","d":"= Tuy nói là…nhưng… (khẩu ngữ của 虽然).","e":[["虽说我的身体不好，但我并不会放弃一直以来的理想。","suī shuō wǒ de shēn tǐ bù hǎo dàn wǒ bìng bú huì fàng qì yì zhí yǐ lái de lǐ xiǎng","Tuy sức khỏe tôi không tốt, nhưng tôi sẽ không từ bỏ lý tưởng bấy lâu nay."],["虽说这位著名画家的一幅画就可赚上百万，可仍然架不住儿子这样挥霍。","suī shuō zhè wèi zhù míng huà jiā de yì fú huà jiù kě zhuàn shàng bǎi wàn kě réng rán jià bú zhù ér zi zhè yàng huī huò","Tuy một bức tranh của danh họa này có thể kiếm cả triệu, nhưng vẫn không chịu nổi sự phung phí như vậy của cậu con trai."]]},{"n":107,"c":["句子的类型","简单复句","条件复句"],"z":"无论……与否，都……","t":"Câu phức điều kiện: 无论……与否，都……","d":"= Bất kể có…hay không, đều….","e":[["无论你同意与否，他都会按自己的计划去处理这件事的。","wú lùn nǐ tóng yì yǔ fǒu tā dōu huì àn zì jǐ de jì huà qù chǔ lǐ zhè jiàn shì de","Bất kể bạn có đồng ý hay không, anh ấy đều sẽ xử lý việc này theo kế hoạch của mình."],["所有的工作人员，无论工作成绩优异与否，都是能领到高额奖金的。","suǒ yǒu de gōng zuò rén yuán wú lùn gōng zuò chéng jì yōu yì yǔ fǒu dōu shì néng lǐng dào gāo é jiǎng jīn de","Toàn bộ nhân viên, bất kể thành tích công việc có xuất sắc hay không, đều được nhận thưởng cao."]]},{"n":108,"c":["句子的类型","简单复句","条件复句"],"z":"凡……（者），均（可）……","t":"Câu phức điều kiện: 凡……(者)，均(可)……","d":"= Phàm là…(người nào) đều (có thể)… (văn bản quy định).","e":[["此次比赛设有一、二、三等奖及优秀奖。凡获奖者均颁发荣誉证书。","cǐ cì bǐ sài shè yǒu yī èr sān děng jiǎng jí yōu xiù jiǎng fán huò jiǎng zhě jūn bān fā róng yù zhèng shū","Cuộc thi lần này có giải nhất, nhì, ba và giải khuyến khích. Phàm là người đoạt giải đều được trao giấy chứng nhận."],["凡来我市进行技术合作的单位，均可根据自身的资金、设备、专长等条件，进行多领域、多层次的合作。","fán lái wǒ shì jìn xíng jì shù hé zuò de dān wèi jūn kě gēn jù zì shēn de zī jīn shè bèi zhuān cháng děng tiáo jiàn jìn xíng duō lǐng yù duō céng cì de hé zuò","Phàm là đơn vị đến thành phố ta hợp tác kỹ thuật, đều có thể tùy theo điều kiện vốn, thiết bị, chuyên môn của mình để hợp tác ở nhiều lĩnh vực, nhiều cấp độ."]]},{"n":109,"c":["句子的类型","简单复句","假设复句"],"z":"假若/假使……，……","t":"Câu phức giả thiết: 假若/假使……，……","d":"= Giả như, nếu như… (văn viết).","e":[["假若你不愿待在家里，你可以到湖边散散步，或在公园喝喝茶、下下棋。","jiǎ ruò nǐ bú yuàn dài zài jiā lǐ nǐ kě yǐ dào hú biān sàn sàn bù huò zài gōng yuán hē hē chá xià xià qí","Nếu bạn không muốn ở nhà, bạn có thể ra bờ hồ đi dạo, hoặc vào công viên uống trà, chơi cờ."],["我从来都不会后悔之前的决定，假使一切再从头来，结果也还是一样的。","wǒ cóng lái dōu bú huì hòu huǐ zhī qián de jué dìng jiǎ shǐ yí qiè zài cóng tóu lái jié guǒ yě hái shì yí yàng de","Tôi chưa bao giờ hối hận về quyết định trước đây, giả sử mọi thứ làm lại từ đầu, kết quả vẫn sẽ như vậy."]]},{"n":110,"c":["句子的类型","简单复句","假设复句"],"z":"幸亏/幸好……，不然/否则……","t":"Câu phức giả thiết: 幸亏/幸好……，不然/否则……","d":"= May mà…, nếu không thì….","e":[["幸好你今天中午替我打了饭，不然我就只有挨饿的份了。","xìng hǎo nǐ jīn tiān zhōng wǔ tì wǒ dǎ le fàn bù rán wǒ jiù zhǐ yǒu ái è de fèn le","May mà trưa nay bạn lấy cơm giúp tôi, nếu không tôi chỉ có nước nhịn đói."],["幸亏老张告诉了我哥哥的电话号码，否则我就真没法跟哥哥联系了。","xìng kuī lǎo zhāng gào su le wǒ gē ge de diàn huà hào mǎ fǒu zé wǒ jiù zhēn méi fǎ gēn gē ge lián xì le","May mà lão Trương cho tôi số điện thoại của anh trai, nếu không tôi thật không cách nào liên lạc được với anh ấy."]]},{"n":111,"c":["句子的类型","简单复句","假设复句"],"z":"纵然/纵使……，也……","t":"Câu phức nhượng bộ: 纵然/纵使……，也……","d":"= Dẫu cho, cho dù…cũng… (văn viết).","e":[["纵然无人为他加油喝彩，他最终也还是夺取了本站比赛的冠军。","zòng rán wú rén wèi tā jiā yóu hè cǎi tā zuì zhōng yě hái shì duó qǔ le běn zhàn bǐ sài de guàn jūn","Dẫu cho không ai cổ vũ cho anh ấy, cuối cùng anh ấy vẫn giành chức vô địch chặng đua này."],["纵使出于好心，你也要注意沟通的方式，说话不要那么直接。","zòng shǐ chū yú hǎo xīn nǐ yě yào zhù yì gōu tōng de fāng shì shuō huà bú yào nà me zhí jiē","Cho dù xuất phát từ ý tốt, bạn cũng phải chú ý cách trao đổi, nói đừng thẳng quá."]]},{"n":112,"c":["句子的类型","简单复句","因果复句"],"z":"（因）……，故……","t":"Câu phức nhân quả: (因)……，故……","d":"= (Vì)…, nên… (văn viết).","e":[["富有智慧者看得透，故不争；胸襟豁达者想得开，故不斗。","fù yǒu zhì huì zhě kàn de tòu gù bù zhēng xiōng jīn huò dá zhě xiǎng de kāi gù bú dòu","Người có trí tuệ nhìn thấu nên không tranh, người có lòng rộng mở nghĩ thoáng nên không đấu."],["肺肉瘤样癌是一种罕见的肺癌，因其症状、体征缺乏特异性，常需术后活检才能确诊，故明确诊断较难。","fèi ròu liú yàng ái shì yì zhǒng hǎn jiàn de fèi ái yīn qí zhèng zhuàng tǐ zhēng quē fá tè yì xìng cháng xū shù hòu huó jiǎn cái néng què zhěn gù míng què zhěn duàn jiào nán","Ung thư phổi dạng sarcoma là một loại ung thư phổi hiếm gặp, vì triệu chứng và dấu hiệu thiếu tính đặc trưng, thường phải sinh thiết sau phẫu thuật mới xác định được, nên việc chẩn đoán chính xác khá khó."]]},{"n":113,"c":["句子的类型","简单复句","因果复句"],"z":"……，以至（于）……","t":"Câu phức nhân quả: ……，以至(于)……","d":"= …, đến nỗi/đến mức….","e":[["自从这种靶向药物问世之后，它的治疗癌症的功能被推崇到了极点，以至它在黑市上的价格被炒到了百万以上。","zì cóng zhè zhǒng bǎ xiàng yào wù wèn shì zhī hòu tā de zhì liáo ái zhèng de gōng néng bèi tuī chóng dào le jí diǎn yǐ zhì tā zài hēi shì shàng de jià gé bèi chǎo dào le bǎi wàn yǐ shàng","Kể từ khi loại thuốc nhắm trúng đích này ra đời, công dụng điều trị ung thư của nó được tung hô đến cực điểm, đến nỗi giá chợ đen bị đẩy lên hơn một triệu."],["当下的素质教育实践呈现出明显的形式化特征，以至于一些学校将活动课的数量作为衡量素质教育实施的指标，反而加重了学生负担。","dāng xià de sù zhì jiào yù shí jiàn chéng xiàn chū míng xiǎn de xíng shì huà tè zhēng yǐ zhì yú yì xiē xué xiào jiāng huó dòng kè de shù liàng zuò wéi héng liáng sù zhì jiào yù shí shī de zhǐ biāo fǎn ér jiā zhòng le xué shēng fù dān","Thực tiễn giáo dục toàn diện hiện nay mang đặc điểm hình thức rõ rệt, đến mức một số trường lấy số lượng tiết hoạt động làm chỉ tiêu đánh giá việc thực hiện giáo dục toàn diện, ngược lại còn tăng gánh nặng cho học sinh."]]},{"n":114,"c":["句子的类型","简单复句","递进复句"],"z":"别说……，都/也……","t":"Câu phức tăng tiến: 别说……，都/也……","d":"= Đừng nói là…, ngay cả…cũng….","e":[["这本书别说本科生了，研究生读起来都费劲。","zhè běn shū bié shuō běn kē shēng le yán jiū shēng dú qǐ lái dōu fèi jìn","Quyển sách này đừng nói sinh viên, đến nghiên cứu sinh đọc cũng vất vả."],["他现在没有收入来源，别说10万，就是一万块现在也拿不出。","tā xiàn zài méi yǒu shōu rù lái yuán bié shuō wàn jiù shì yí wàn kuài xiàn zài yě ná bù chū","Giờ anh ấy không có nguồn thu nhập, đừng nói 100 nghìn, đến 10 nghìn bây giờ cũng không có."]]},{"n":115,"c":["句子的类型","简单复句","递进复句"],"z":"……不说，还……","t":"Câu phức tăng tiến: ……不说，还……","d":"= …đã đành, lại còn….","e":[["你们在我家住着白吃白喝不说，还给我添乱。","nǐ men zài wǒ jiā zhù zhe bái chī bái hē bù shuō huán gěi wǒ tiān luàn","Các người ở nhà tôi ăn chực uống chực đã đành, lại còn gây thêm rắc rối cho tôi."],["消费者最怕的就是上当受骗，买到假冒伪劣商品，钱花了不说，还弄了一肚子气。","xiāo fèi zhě zuì pà de jiù shì shàng dàng shòu piàn mǎi dào jiǎ mào wěi liè shāng pǐn qián huā le bù shuō hái nòng le yí dù zi qì","Người tiêu dùng sợ nhất là bị lừa, mua phải hàng giả hàng kém chất lượng, tốn tiền đã đành, lại còn tức anh ách."]]},{"n":116,"c":["句子的类型","简单复句","递进复句"],"z":"连……都……，更不用说……了","t":"Câu phức tăng tiến: 连……都……，更不用说……了","d":"= Ngay cả…cũng…, càng khỏi phải nói đến….","e":[["这道题的解法连老师都得想半天，更不用说学生了。","zhè dào tí de jiě fǎ lián lǎo shī dōu děi xiǎng bàn tiān gèng bú yòng shuō xué shēng le","Cách giải bài này ngay cả thầy cô cũng phải nghĩ mãi, càng khỏi nói đến học sinh."],["他连简单的道歉都不肯，更不用说做出什么补偿了。","tā lián jiǎn dān de dào qiàn dōu bù kěn gèng bú yòng shuō zuò chū shén me bǔ cháng le","Anh ta đến một lời xin lỗi đơn giản cũng không chịu, càng khỏi nói đến bồi thường gì."]]},{"n":117,"c":["句子的类型","简单复句","递进复句"],"z":"……尚且……，（更）何况……","t":"Câu phức tăng tiến: ……尚且……，(更)何况……","d":"= …còn…, huống hồ là….","e":[["这样的影视作品，成人尚且不宜观看，何况是涉世未深的孩子。","zhè yàng de yǐng shì zuò pǐn chéng rén shàng qiě bù yí guān kàn hé kuàng shì shè shì wèi shēn de hái zi","Tác phẩm điện ảnh như vậy người lớn còn không nên xem, huống hồ là trẻ con chưa trải sự đời."],["高海拔地区土壤贫瘠、气候恶劣，野草生长尚且困难，更何况发展大规模农业？","gāo hǎi bá dì qū tǔ rǎng pín jí qì hòu è liè yě cǎo shēng zhǎng shàng qiě kùn nán gèng hé kuàng fā zhǎn dà guī mó nóng yè","Vùng núi cao đất đai cằn cỗi, khí hậu khắc nghiệt, cỏ dại mọc còn khó, huống hồ là phát triển nông nghiệp quy mô lớn?"]]},{"n":118,"c":["句子的类型","简单复句","递进复句"],"z":"……，更不用说……了","t":"Câu phức tăng tiến: ……，更不用说……了","d":"= …, càng không cần phải nói đến….","e":[["听音乐如果音量过大，对成人的听力都会造成损伤，更不用说对婴幼儿了。所以，让婴幼儿听音乐时，音量要控制适当。","tīng yīn yuè rú guǒ yīn liàng guò dà duì chéng rén de tīng lì dōu huì zào chéng sǔn shāng gèng bú yòng shuō duì yīng yòu ér le suǒ yǐ ràng yīng yòu ér tīng yīn yuè shí yīn liàng yào kòng zhì shì dàng","Nghe nhạc nếu âm lượng quá lớn, đến thính lực người lớn cũng bị tổn thương, càng không cần nói đến trẻ nhỏ. Vì vậy, khi cho trẻ nghe nhạc, âm lượng phải điều chỉnh vừa phải."],["虽说“豪华型”大客车带有卧铺，但路况不好，一路颠簸。坐在这种车上，想打个盹常常都不容易，更不用说睡个安稳觉了。","suī shuō háo huá xíng dà kè chē dài yǒu wò pù dàn lù kuàng bù hǎo yí lù diān bǒ zuò zài zhè zhǒng chē shàng xiǎng dǎ gè dǔn cháng cháng dōu bù róng yì gèng bú yòng shuō shuì gè ān wěn jiào le","Tuy xe khách \"hạng sang\" có giường nằm, nhưng đường xá xấu, xóc suốt dọc đường. Ngồi trên xe như vậy, muốn chợp mắt một lát thường còn khó, càng không nói đến ngủ một giấc yên ổn."]]},{"n":119,"c":["句子的类型","简单复句","目的复句"],"z":"为（了）……起见，……","t":"Câu phức mục đích: 为(了)……起见，……","d":"= Vì muốn…, để cho…(an toàn, chắc chắn).","e":[["超强台风将在浦东登陆，为安全起见，长三角地区部分列车会临时停运。","chāo qiáng tái fēng jiāng zài pǔ dōng dēng lù wèi ān quán qǐ jiàn cháng sān jiǎo dì qū bù fen liè chē huì lín shí tíng yùn","Siêu bão sắp đổ bộ vào Phố Đông, để đảm bảo an toàn, một số chuyến tàu ở khu vực đồng bằng Trường Giang sẽ tạm ngừng chạy."],["医生说他手术恢复得很好，但为了保险起见，还是需要留院观察一段时间。","yī shēng shuō tā shǒu shù huī fù de hěn hǎo dàn wèi le bǎo xiǎn qǐ jiàn hái shì xū yào liú yuàn guān chá yí duàn shí jiān","Bác sĩ nói anh ấy hồi phục sau phẫu thuật rất tốt, nhưng để cho chắc chắn, vẫn cần ở lại viện theo dõi một thời gian."]]},{"n":120,"c":["句子的类型","简单复句","目的复句"],"z":"……，以……","t":"Câu phức mục đích: ……，以……","d":"= …, để…/nhằm… (văn viết).","e":[["在广泛听取各方意见之后，工信部决定实施宽带提速计划，以实现上网速度与国际平均水平接轨。","zài guǎng fàn tīng qǔ gè fāng yì jiàn zhī hòu gōng xìn bù jué dìng shí shī kuān dài tí sù jì huà yǐ shí xiàn shàng wǎng sù dù yǔ guó jì píng jūn shuǐ píng jiē guǐ","Sau khi lắng nghe rộng rãi ý kiến các bên, Bộ Công nghiệp và Thông tin quyết định triển khai kế hoạch tăng tốc băng thông rộng, nhằm đưa tốc độ mạng bắt kịp mức trung bình quốc tế."],["世界卫生组织呼吁成员国加强合作，完善监督机制，保证有充裕的资金，以帮助广大发展中国家。","shì jiè wèi shēng zǔ zhī hū yù chéng yuán guó jiā qiáng hé zuò wán shàn jiān dū jī zhì bǎo zhèng yǒu chōng yù de zī jīn yǐ bāng zhù guǎng dà fā zhǎn zhōng guó jiā","Tổ chức Y tế Thế giới kêu gọi các nước thành viên tăng cường hợp tác, hoàn thiện cơ chế giám sát, đảm bảo nguồn vốn dồi dào để giúp đỡ các nước đang phát triển."]]},{"n":121,"c":["句子的类型","简单复句","紧缩复句"],"z":"非得……才……","t":"Câu rút gọn: 非得……才……","d":"= Nhất định phải…mới….","e":[["为什么我事先对你百般劝说都没有用，非得酿成大错你才肯反思？","wèi shén me wǒ shì xiān duì nǐ bǎi bān quàn shuō dōu méi yǒu yòng fēi děi niàng chéng dà cuò nǐ cái kěn fǎn sī","Tại sao trước đó tôi khuyên bạn đủ đường đều vô ích, nhất định phải gây ra sai lầm lớn bạn mới chịu tự xét lại?"],["若是家长不给买玩具，“小皇帝”便会大哭大闹，非得把玩具弄到手才罢休。","ruò shì jiā zhǎng bù gěi mǎi wán jù xiǎo huáng dì biàn huì dà kū dà nào fēi děi bǎ wán jù nòng dào shǒu cái bà xiū","Nếu bố mẹ không mua đồ chơi, \"tiểu hoàng đế\" sẽ khóc lóc ầm ĩ, nhất định phải có được đồ chơi mới thôi."]]},{"n":122,"c":["句子的类型","简单复句","紧缩复句"],"z":"任……也……","t":"Câu rút gọn: 任……也……","d":"= Mặc cho/bất kể…cũng…: 任谁也 = bất kể ai cũng.","e":[["他的小女儿要是哭起来，任谁也哄不好。","tā de xiǎo nǚ ér yào shi kū qǐ lái rèn shuí yě hǒng bù hǎo","Con gái út của anh ấy mà khóc thì bất kể ai cũng không dỗ được."],["他的心情低落到了极点，似乎任什么事也不能让他开心一点。","tā de xīn qíng dī luò dào le jí diǎn sì hū rèn shén me shì yě bù néng ràng tā kāi xīn yì diǎn","Tâm trạng anh ấy xuống đến tận cùng, dường như bất kể chuyện gì cũng không làm anh ấy vui lên được chút nào."]]},{"n":123,"c":["句子的类型","多重复句",""],"z":"多重并列复句","t":"Câu phức nhiều tầng: đẳng lập","d":"Câu có nhiều vế, các vế lớn quan hệ đẳng lập, trong mỗi vế lại có quan hệ nhỏ hơn.","e":[["我8岁开始学拉二胡，现已达到第七级了；11岁开始学弹钢琴，现已通过第八级的考试。","wǒ suì kāi shǐ xué lā èr hú xiàn yǐ dá dào dì qī jí le suì kāi shǐ xué tán gāng qín xiàn yǐ tōng guò dì bā jí de kǎo shì","Tôi bắt đầu học đàn nhị từ năm 8 tuổi, giờ đã đạt cấp bảy; bắt đầu học piano từ năm 11 tuổi, giờ đã thi qua cấp tám."],["我在孩子的成长过程中，给予他充分的自由。我不逼他学奥数，除非他自己愿意学；不逼他音乐考级，只求培养些许乐感；不逼他学外语，只为他提供开口讲外语的机会。","wǒ zài hái zi de chéng zhǎng guò chéng zhōng jǐ yǔ tā chōng fèn de zì yóu wǒ bù bī tā xué ào shù chú fēi tā zì jǐ yuàn yì xué bù bī tā yīn yuè kǎo jí zhǐ qiú péi yǎng xiē xǔ yuè gǎn bù bī tā xué wài yǔ zhǐ wèi tā tí gōng kāi kǒu jiǎng wài yǔ de jī huì","Trong quá trình con trưởng thành, tôi cho con đầy đủ tự do. Tôi không ép con học toán Olympic, trừ khi con tự muốn học; không ép con thi chứng chỉ âm nhạc, chỉ mong bồi dưỡng chút cảm thụ âm nhạc; không ép con học ngoại ngữ, chỉ tạo cho con cơ hội nói ngoại ngữ."]]},{"n":124,"c":["句子的类型","多重复句",""],"z":"多重转折复句","t":"Câu phức nhiều tầng: chuyển ngoặt","d":"Quan hệ chuyển ngoặt ở tầng ngoài cùng, bên trong có thể là nhân quả, tăng tiến….","e":[["今年虽然因为气温低，西瓜上市的时间推迟了，但总产量同比增长了近二成。","jīn nián suī rán yīn wèi qì wēn dī xī guā shàng shì de shí jiān tuī chí le dàn zǒng chǎn liàng tóng bǐ zēng zhǎng le jìn èr chéng","Năm nay tuy vì nhiệt độ thấp nên thời gian dưa hấu ra thị trường bị lùi lại, nhưng tổng sản lượng tăng gần 20% so với cùng kỳ."],["我清楚地记得那天她戴的是一枚钻戒，虽然她后来坚决否认，说她戴的只不过是枚普通金戒指，而且她发给我的照片也证实了这一点，可我还是不愿意承认我记错了。","wǒ qīng chu de jì de nà tiān tā dài de shì yì méi zuàn jiè suī rán tā hòu lái jiān jué fǒu rèn shuō tā dài de zhǐ bú guò shì méi pǔ tōng jīn jiè zhǐ ér qiě tā fā gěi wǒ de zhào piàn yě zhèng shí le zhè yì diǎn kě wǒ hái shì bú yuàn yì chéng rèn wǒ jì cuò le","Tôi nhớ rõ hôm đó cô ấy đeo một chiếc nhẫn kim cương, tuy sau này cô ấy kiên quyết phủ nhận, nói chỉ đeo một chiếc nhẫn vàng bình thường, hơn nữa ảnh cô ấy gửi tôi cũng chứng minh điều đó, nhưng tôi vẫn không muốn thừa nhận mình nhớ nhầm."]]},{"n":125,"c":["句子的类型","多重复句",""],"z":"多重假设复句","t":"Câu phức nhiều tầng: giả thiết","d":"Tầng ngoài là giả thiết (如果/要是…就…), bên trong có tăng tiến, nhân quả….","e":[["如果你足够努力，而且有一定的天赋，再加上一点点好运气，就一定能通过这次考试。","rú guǒ nǐ zú gòu nǔ lì ér qiě yǒu yí dìng de tiān fù zài jiā shàng yì diǎn diǎn hǎo yùn qì jiù yí dìng néng tōng guò zhè cì kǎo shì","Nếu bạn đủ nỗ lực, lại có năng khiếu nhất định, cộng thêm một chút may mắn, thì nhất định sẽ qua được kỳ thi này."],["要是房子没有其他问题，只是因为租金高而迟迟租不出去，你就要考虑降一部分租金试试了。","yào shi fáng zi méi yǒu qí tā wèn tí zhǐ shì yīn wèi zū jīn gāo ér chí chí zū bù chū qù nǐ jiù yào kǎo lǜ jiàng yí bù fen zū jīn shì shì le","Nếu căn nhà không có vấn đề gì khác, chỉ vì tiền thuê cao mà mãi không cho thuê được, thì bạn nên cân nhắc giảm bớt tiền thuê thử xem."]]},{"n":126,"c":["句子的类型","多重复句",""],"z":"多重因果复句","t":"Câu phức nhiều tầng: nhân quả","d":"Quan hệ nhân quả ở tầng ngoài, các vế nhỏ bên trong có thể là tăng tiến, nối tiếp….","e":[["由于奥运会足球比赛一开始只面向准业余选手，所以它的水平不能与世界杯相比。于是在1930年乌拉圭举办第一届世界杯后，奥运会足球比赛就退居到次要位置。","yóu yú ào yùn huì zú qiú bǐ sài yì kāi shǐ zhǐ miàn xiàng zhǔn yè yú xuǎn shǒu suǒ yǐ tā de shuǐ píng bù néng yǔ shì jiè bēi xiāng bǐ yú shì zài nián wū lā guī jǔ bàn dì yī jiè shì jiè bēi hòu ào yùn huì zú qiú bǐ sài jiù tuì jū dào cì yào wèi zhì","Vì bóng đá Olympic ban đầu chỉ dành cho cầu thủ bán chuyên nên trình độ không thể so với World Cup. Thế là sau khi Uruguay tổ chức World Cup đầu tiên năm 1930, bóng đá Olympic lùi xuống vị trí thứ yếu."],["他非常热衷于人体研究，因为在研究中不但可以获得新知识，而且还能对自己的身体状况有更深入的了解。","tā fēi cháng rè zhōng yú rén tǐ yán jiū yīn wèi zài yán jiū zhōng bú dàn kě yǐ huò dé xīn zhī shi ér qiě hái néng duì zì jǐ de shēn tǐ zhuàng kuàng yǒu gèng shēn rù de liǎo jiě","Anh ấy rất say mê nghiên cứu cơ thể người, vì trong nghiên cứu không những có được kiến thức mới mà còn hiểu sâu hơn về tình trạng cơ thể mình."]]},{"n":127,"c":["句子的类型","多重复句",""],"z":"多重递进复句","t":"Câu phức nhiều tầng: tăng tiến","d":"Nhiều vế tăng tiến nối tiếp: 不但…而且…甚至…; 既…又…而且….","e":[["他不但会吹笛子，而且吹得还挺好，甚至还会做笛子呢！","tā bú dàn huì chuī dí zi ér qiě chuī de hái tǐng hǎo shèn zhì hái huì zuò dí zi ne","Anh ấy không những biết thổi sáo mà còn thổi khá hay, thậm chí còn biết làm sáo nữa đấy!"],["这个项目不如交给小张负责，这样既能考验小张的能力，又能满足董事长的要求，而且还可以不得罪总经理。","zhè ge xiàng mù bù rú jiāo gěi xiǎo zhāng fù zé zhè yàng jì néng kǎo yàn xiǎo zhāng de néng lì yòu néng mǎn zú dǒng shì zhǎng de yāo qiú ér qiě hái kě yǐ bù dé zuì zǒng jīng lǐ","Dự án này chi bằng giao cho Tiểu Trương phụ trách, như vậy vừa thử thách được năng lực của Tiểu Trương, vừa đáp ứng yêu cầu của chủ tịch, hơn nữa còn không làm mất lòng tổng giám đốc."]]},{"n":128,"c":["语段（句群）","",""],"z":"时间顺序","t":"Đoạn văn: trình tự thời gian","d":"Các câu sắp xếp theo thứ tự trước sau của sự việc (先, 再, 然后, 经过…以后…).","e":[["豆腐皮包肉的制作程序如下：取豆腐皮一袋用温水泡软，切成两个饺子皮大小的方块备用。将肉末用姜末、葱花、盐、味精、鸡蛋和好，再将几只冬菇泡软、切碎，放入肉末中拌匀。","dòu fu pí bāo ròu de zhì zuò chéng xù rú xià qǔ dòu fu pí yí dài yòng wēn shuǐ pào ruǎn qiē chéng liǎng gè jiǎo zi pí dà xiǎo de fāng kuài bèi yòng jiāng ròu mò yòng jiāng mò cōng huā yán wèi jīng jī dàn hé hǎo zài jiāng jǐ zhī dōng gū pào ruǎn qiē suì fàng rù ròu mò zhōng bàn yún","Cách làm váng đậu cuộn thịt như sau: lấy một túi váng đậu ngâm nước ấm cho mềm, cắt thành miếng vuông cỡ hai vỏ sủi cảo để riêng. Trộn thịt băm với gừng băm, hành hoa, muối, bột ngọt, trứng gà, rồi ngâm mềm vài cái nấm hương, băm nhỏ, cho vào thịt băm trộn đều."],["在广泛调研的基础上，有关部门合并了一些高度类似的企业，停办一些消耗高、污染重、利润低的企业。经过调整以后，不少厂很快扭亏为盈。","zài guǎng fàn diào yán de jī chǔ shàng yǒu guān bù mén hé bìng le yì xiē gāo dù lèi sì de qǐ yè tíng bàn yì xiē xiāo hào gāo wū rǎn zhòng lì rùn dī de qǐ yè jīng guò tiáo zhěng yǐ hòu bù shǎo chǎng hěn kuài niǔ kuī wéi yíng","Trên cơ sở khảo sát rộng rãi, các cơ quan liên quan đã sáp nhập một số doanh nghiệp rất giống nhau, cho dừng một số doanh nghiệp tiêu hao cao, ô nhiễm nặng, lợi nhuận thấp. Sau khi điều chỉnh, nhiều nhà máy nhanh chóng chuyển lỗ thành lãi."]]},{"n":129,"c":["语段（句群）","",""],"z":"空间顺序","t":"Đoạn văn: trình tự không gian","d":"Miêu tả theo vị trí: trái – phải, đông – tây, trước – sau, xa – gần.","e":[["20年前的长江中堡岛已不复存在。现在，在它的左边，大坝已矗立在波涛之中，左岸厂房坝、电厂、泄洪坝等已相继建成。在它的右边，三期工程的主体项目——右岸电厂正夜以继日地工作着。","nián qián de cháng jiāng zhōng bǎo dǎo yǐ bú fù cún zài xiàn zài zài tā de zuǒ biān dà bà yǐ chù lì zài bō tāo zhī zhōng zuǒ àn chǎng fáng bà diàn chǎng xiè hóng bà děng yǐ xiāng jì jiàn chéng zài tā de yòu biān sān qī gōng chéng de zhǔ tǐ xiàng mù yòu àn diàn chǎng zhèng yè yǐ jì rì de gōng zuò zhe","Đảo Trung Bảo trên sông Trường Giang 20 năm trước đã không còn nữa. Giờ đây, bên trái nó, con đập đã sừng sững giữa sóng nước, đập nhà máy bờ trái, nhà máy điện, đập xả lũ đã lần lượt hoàn thành. Bên phải nó, hạng mục chính của giai đoạn ba — nhà máy điện bờ phải — đang làm việc ngày đêm."],["站在广场的中心位置，向东望去，1号展馆坐落于馆区主轴线上。其南北分别为2、3号展馆。三个展馆从远处看排成一条线，十分整齐。绕过三馆，背后是4、5号展馆，分别位于2、3号馆的东侧，两馆皆为东西走向，共同构成环湖之势。","zhàn zài guǎng chǎng de zhōng xīn wèi zhì xiàng dōng wàng qù hào zhǎn guǎn zuò luò yú guǎn qū zhǔ zhóu xiàn shàng qí nán běi fēn bié wèi hào zhǎn guǎn sān gè zhǎn guǎn cóng yuǎn chù kàn pái chéng yì tiáo xiàn shí fēn zhěng qí rào guò sān guǎn bèi hòu shì hào zhǎn guǎn fēn bié wèi yú hào guǎn de dōng cè liǎng guǎn jiē wèi dōng xī zǒu xiàng gòng tóng gòu chéng huán hú zhī shì","Đứng ở trung tâm quảng trường nhìn về phía đông, nhà triển lãm số 1 nằm trên trục chính khu triển lãm. Phía nam và bắc là nhà số 2 và số 3. Ba nhà nhìn từ xa xếp thành một hàng rất ngay ngắn. Vòng qua ba nhà đó, phía sau là nhà số 4 và 5, lần lượt nằm phía đông nhà số 2 và 3, cả hai đều chạy theo hướng đông – tây, cùng tạo thế bao quanh hồ."]]},{"n":130,"c":["语段（句群）","",""],"z":"逻辑顺序","t":"Đoạn văn: trình tự logic","d":"Sắp xếp theo quan hệ logic: nguyên nhân – kết quả, một mặt – mặt khác, ưu điểm – nhược điểm.","e":[["全球变暖是自然因素和人为因素共同作用的结果。一方面，近年来超强的厄尔尼诺现象显著升高了海水温度，使得大洋上空温度偏高。另一方面，人类活动，如大规模的工业排放和森林采伐，是更主要的原因。","quán qiú biàn nuǎn shì zì rán yīn sù hé rén wéi yīn sù gòng tóng zuò yòng de jié guǒ yì fāng miàn jìn nián lái chāo qiáng de è ěr ní nuò xiàn xiàng xiǎn zhù shēng gāo le hǎi shuǐ wēn dù shǐ de dà yáng shàng kōng wēn dù piān gāo lìng yì fāng miàn rén lèi huó dòng rú dà guī mó de gōng yè pái fàng hé sēn lín cǎi fá shì gèng zhǔ yào de yuán yīn","Trái đất nóng lên là kết quả tác động chung của yếu tố tự nhiên và yếu tố con người. Một mặt, hiện tượng El Niño cực mạnh những năm gần đây đã làm nhiệt độ nước biển tăng đáng kể, khiến nhiệt độ trên các đại dương cao hơn. Mặt khác, hoạt động của con người như xả thải công nghiệp quy mô lớn và chặt phá rừng là nguyên nhân chủ yếu hơn."],["该体制的优点是灾害响应速度快，处理突发情况效率高；缺点是不利于整合地方力量，也不利于平日村民自救意识的提高。","gāi tǐ zhì de yōu diǎn shì zāi hài xiǎng yìng sù dù kuài chǔ lǐ tū fā qíng kuàng xiào lǜ gāo quē diǎn shì bú lì yú zhěng hé dì fāng lì liàng yě bú lì yú píng rì cūn mín zì jiù yì shí de tí gāo","Ưu điểm của cơ chế này là phản ứng với thiên tai nhanh, xử lý tình huống bất ngờ hiệu quả; nhược điểm là không có lợi cho việc tập hợp lực lượng địa phương, cũng không có lợi cho việc nâng cao ý thức tự cứu của người dân thường ngày."]]},{"n":131,"c":["语段（句群）","",""],"z":"话题延伸","t":"Đoạn văn: mở rộng chủ đề","d":"Cùng một chủ đề được nói tiếp ở các câu sau, chủ ngữ lặp lại hoặc được lược bỏ.","e":[["甘草在中国北部、蒙古、俄罗斯西伯利亚地区、哈萨克斯坦、巴基斯坦等地都有分布，在中国具体分布于东北、华北、西北等地。甘草喜光照充足、干燥少雨、冬夏分明以及昼夜温差大的环境，具有喜光、耐旱、耐热、耐寒及耐盐碱等特性。","gān cǎo zài zhōng guó běi bù měng gǔ é luó sī xī bó lì yà dì qū hā sà kè sī tǎn bā jī sī tǎn děng dì dōu yǒu fēn bù zài zhōng guó jù tǐ fēn bù yú dōng běi huá běi xī běi děng dì gān cǎo xǐ guāng zhào chōng zú gān zào shǎo yǔ dōng xià fēn míng yǐ jí zhòu yè wēn chā dà de huán jìng jù yǒu xǐ guāng nài hàn nài rè nài hán jí nài yán jiǎn děng tè xìng","Cam thảo phân bố ở miền bắc Trung Quốc, Mông Cổ, vùng Siberia của Nga, Kazakhstan, Pakistan…, ở Trung Quốc cụ thể phân bố ở Đông Bắc, Hoa Bắc, Tây Bắc. Cam thảo ưa môi trường nhiều nắng, khô ít mưa, đông hè rõ rệt và chênh lệch nhiệt độ ngày đêm lớn, có đặc tính ưa sáng, chịu hạn, chịu nóng, chịu rét và chịu mặn kiềm."],["人工智能是新一轮科技革命和产业变革的重要驱动力量，是研究、开发用于模拟、延伸和扩展人的智能的理论、方法、技术及应用系统的一门新的技术科学。","rén gōng zhì néng shì xīn yì lún kē jì gé mìng hé chǎn yè biàn gé de zhòng yào qū dòng lì liàng shì yán jiū kāi fā yòng yú mó nǐ yán shēn hé kuò zhǎn rén de zhì néng de lǐ lùn fāng fǎ jì shù jí yìng yòng xì tǒng de yì mén xīn de jì shù kē xué","Trí tuệ nhân tạo là động lực quan trọng của cuộc cách mạng khoa học công nghệ và chuyển đổi công nghiệp mới, là một ngành khoa học kỹ thuật mới nghiên cứu, phát triển lý thuyết, phương pháp, kỹ thuật và hệ thống ứng dụng dùng để mô phỏng, kéo dài và mở rộng trí tuệ con người."]]},{"n":132,"c":["语段（句群）","",""],"z":"话题转换","t":"Đoạn văn: chuyển chủ đề","d":"Dùng 至于 (còn về), 另外… để chuyển sang chủ đề khác.","e":[["我在创作这幅作品时，是希望能够依靠背影去反映出人物的情绪和精神状态。至于这件作品的展出位置，在规划展厅布局时，就做了特别的安排。","wǒ zài chuàng zuò zhè fú zuò pǐn shí shì xī wàng néng gòu yī kào bèi yǐng qù fǎn yìng chū rén wù de qíng xù hé jīng shén zhuàng tài zhì yú zhè jiàn zuò pǐn de zhǎn chū wèi zhì zài guī huà zhǎn tīng bù jú shí jiù zuò le tè bié de ān pái","Khi sáng tác tác phẩm này, tôi mong có thể dựa vào bóng lưng để phản ánh cảm xúc và trạng thái tinh thần của nhân vật. Còn về vị trí trưng bày tác phẩm, khi quy hoạch bố cục phòng triển lãm đã có sắp xếp đặc biệt."],["我刻录光盘的速度都是软件默认的，如果自己去调高速度的话光盘容易报废。（至于）价钱嘛，买的比较多的话就一元一张盘。","wǒ kè lù guāng pán de sù dù dōu shì ruǎn jiàn mò rèn de rú guǒ zì jǐ qù tiáo gāo sù dù de huà guāng pán róng yì bào fèi zhì yú jià qián ma mǎi de bǐ jiào duō de huà jiù yì yuán yì zhāng pán","Tốc độ ghi đĩa của tôi đều để mặc định của phần mềm, nếu tự tăng tốc độ thì đĩa dễ bị hỏng. (Còn về) giá ấy à, mua nhiều thì một tệ một đĩa."]]},{"n":133,"c":["语段（句群）","",""],"z":"承前省略","t":"Đoạn văn: lược bỏ theo phía trước","d":"Chủ ngữ đã nêu ở câu/vế trước thì các vế sau lược bỏ (chỗ ＿ là chủ ngữ bị lược).","e":[["我奶奶虽然没有文化，＿做事却十分干脆，＿听了这话便找出存折，＿抱着我便径直走出家门去银行取钱。","wǒ nǎi nai suī rán méi yǒu wén huà zuò shì què shí fēn gān cuì tīng le zhè huà biàn zhǎo chū cún zhé bào zhe wǒ biàn jìng zhí zǒu chū jiā mén qù yín háng qǔ qián","Bà tôi tuy không có học, nhưng (bà) làm việc rất dứt khoát, (bà) nghe câu đó liền tìm sổ tiết kiệm, (bà) bế tôi đi thẳng ra khỏi nhà đến ngân hàng rút tiền."],["中国政府秉承“以人为本”的精神，＿根据被援助国要求和国际社会的呼吁，＿及时提供了救灾物资、救援队和医疗队。","zhōng guó zhèng fǔ bǐng chéng yǐ rén wéi běn de jīng shén gēn jù bèi yuán zhù guó yāo qiú hé guó jì shè huì de hū yù jí shí tí gōng le jiù zāi wù zī jiù yuán duì hé yī liáo duì","Chính phủ Trung Quốc giữ vững tinh thần \"lấy con người làm gốc\", (chính phủ) căn cứ yêu cầu của nước được viện trợ và lời kêu gọi của cộng đồng quốc tế, (chính phủ) đã kịp thời cung cấp vật tư cứu trợ, đội cứu hộ và đội y tế."]]},{"n":134,"c":["语段（句群）","",""],"z":"蒙后省略","t":"Đoạn văn: lược bỏ theo phía sau","d":"Chủ ngữ xuất hiện ở vế SAU, các vế trước lược bỏ (chỗ ＿).","e":[["虽然＿没有得到为国家献身的机会，但也一直做好了准备；如果到了那一天，汪昌绪绝对丝毫不会犹豫。","suī rán méi yǒu dé dào wèi guó jiā xiàn shēn de jī huì dàn yě yì zhí zuò hǎo le zhǔn bèi rú guǒ dào le nà yì tiān wāng chāng xù jué duì sī háo bú huì yóu yù","Tuy (ông) chưa có cơ hội hiến thân cho đất nước, nhưng cũng luôn sẵn sàng; nếu ngày đó đến, Uông Xương Tự tuyệt đối không chút do dự."],["无论＿平时工作多忙，＿回家多晚，王和平都会非常认真地检查孩子的作业。","wú lùn píng shí gōng zuò duō máng huí jiā duō wǎn wáng hé píng dōu huì fēi cháng rèn zhēn de jiǎn chá hái zi de zuò yè","Bất kể (anh) ngày thường bận đến đâu, (anh) về nhà muộn thế nào, Vương Hòa Bình đều kiểm tra bài tập của con rất cẩn thận."]]}]};
